-- #####################################################################################
-- ####################### SECTION 0 -- THE PRE-DDL LIVE PROBES ########################
-- #####################################################################################
-- One probe = one named failure mode with a remedy in its text. Negative probes guard a
-- partial/duplicate re-apply; positive anchor probes reconfirm -- against pg_class /
-- pg_constraint / pg_proc / information_schema, never against the design's prose -- every
-- prior object this file's FKs, splices, calls and censuses depend on. Runs BEFORE
-- `set role clara_fn_owner`.

-- #####################################################################################
-- ### SECTION 0 (D-b2 SLICE) -- THE SHARED SQL-LEXICAL STRIPPER (deploy-time only) ####
-- #####################################################################################
-- [R12 FIX 2026-08-04 -- confirming round, Codex CXR3, DEPLOY-BLOCKER] TWO INSTRUMENTS IN THIS FILE JUDGE
-- WHETHER A LIVE BODY CONTAINS A CALL: probe 11 below, and SECTION S5's S5.8-b2 prestate. They
-- must agree, because probe 11 admitting an apply that S5.8-b2 then refuses is a migration that
-- fails in the middle. Round 11 made them agree by stripping comments with a regexp pair. That is
-- not a lexer, and the confirming round measured both directions of the gap:
--   * A LAWFUL HOTFIX IS REFUSED. A body re-created with identical executable SQL plus
--     `raise notice $msg$see clara._adj_on_approve(p_entry)$msg$` counts the marker inside a
--     STRING as executable, and 0045 then refuses to deploy onto a database where nothing was
--     applied ("already applied", of a splice nobody made).
--   * A REAL CALL CAN BE ERASED. `v := 'see /* here'; perform clara._adj_on_approve(p_entry);
--     v := 'and */ there';` -- the block-comment regexp spans from inside the first string to
--     inside the second and deletes the executable line between them. MEASURED on the round-11
--     expression: the count dropped to ZERO, which is the idempotency claim reading "already
--     applied" on a body nothing has touched.
-- THE ANSWER IS TO TOKENISE. This body walks the source once and BLANKS -- replaces every
-- character except the newline with a space -- each comment (line and block, block comments
-- NESTING as Postgres nests them) and each string literal (single-quoted with '' doubling and
-- E'' backslash escapes; dollar-quoted with tagged or untagged delimiters). Executable code is
-- passed through untouched.
--
-- BLANKING RATHER THAN DELETING IS THE PROPERTY THAT MAKES IT AUDITABLE: the result is the SAME
-- LENGTH as the input and carries the same line structure, so a position measured on the code is
-- a position in the source -- and an instrument can ASSERT that invariant rather than trust it
-- (probe 11 does, on every call).
--
-- IT USES NOTHING NEWER THAN `position`/`substr`/`regexp_replace`, deliberately: a deploy-time
-- instrument that needs a recent server function is an instrument that fails on the one database
-- nobody tested against.
--
-- THE INSTRUMENT'S GRAMMAR IS A NAMED SUBSET, AND EVERYTHING OUTSIDE IT IS LOUD OR LISTED
-- [R15 FIX 2026-08-04 -- third re-confirming round]. Three rounds have now found the same shape of defect
-- three times: a construct Postgres understands, this body does not, and the disagreement is
-- SILENT -- a real call read as absent, which is a second call spliced in beside the first. The
-- rule that replaces "we think we have them all" is:
--   * what this body DOES handle is the grammar written below, and every clause of it was settled
--     by RUNNING the construct on this server rather than by reading a manual page about it;
--   * a construct that could make this body MISJUDGE, and that it cannot resolve, REFUSES LOUDLY
--     with a diagnosis naming the construct -- never a guess, never a silent blank;
--   * a construct that is genuinely INVISIBLE BY DESIGN, or that POSTGRES ITSELF refuses to store,
--     is listed here with the reason it is safe to leave alone.
--
-- WHAT IT DOES NOT HANDLE, RE-AUDITED UNDER THAT LAW:
--   * A CALL BUILT AND RUN AS A STRING (`execute 'select clara._adj_on_approve(...)'`) is
--     INVISIBLE BY DESIGN and settled: the text is a literal, the literal is blanked, and no
--     lexical instrument can know what a runtime string will contain. These instruments' question
--     is "does this body's CODE call the hook", and a dynamic call is a different question that a
--     catalog census cannot answer.
--   * A `U&"..."` IDENTIFIER THIS BODY CANNOT RESOLVE IS REFUSED LOUDLY: one that is never closed,
--     one whose content carries a BACKSLASH (a unicode escape in that spelling, so `U&"\0063lara"`
--     IS clara), and any of them at all in a subject that mentions UESCAPE. The last arm is the
--     one that is not obvious, and it was MEASURED rather than reasoned: `U&'z0063lara' UESCAPE
--     'z'` is `clara`, a LETTER is a legal escape character, and a body running
--     `pg_temp.U&"z005ft4callee" UESCAPE 'z'(...)` reached its callee while an instrument that
--     folded the content verbatim reported the call absent. So an escaped identifier's content can
--     look exactly like a plain lowercase name and denote something else. The UESCAPE test is
--     WHOLE-BODY and deliberately over-broad because it cannot be made local -- measured, a
--     comment may sit between the identifier and its UESCAPE clause, so a lookahead over
--     whitespace would be provably incomplete -- and because over-refusing is the direction this
--     file has chosen at every other one of these forks. WHAT OVER-BROAD COSTS, STATED HERE IN
--     FULL SO NO OTHER SITE HAS TO: the refusal does not only convert silent misjudges. A body
--     carrying a lawful, resolvable U& identifier that is NOT A CALL, together with the word
--     UESCAPE anywhere -- a comment, a literal, an unrelated clause -- is refused, and on that
--     body round 14's answer of 0 was correct. Measured, both halves required: the U& identifier
--     alone does not refuse, the word alone does not refuse. The intersection is empty in this
--     schema today (one body carries a U& prefix, none mentions UESCAPE), the refusal names its
--     own cause, and the alternative is implementing the escape decoder -- which is the fix to
--     make if this ever bites, not a loosened test.
--   * A `U&'...'` STRING NEEDS NO SUCH RULE AND DOES NOT GET ONE. Its content is a LITERAL and is
--     blanked whatever the escapes decode to, so no decoder could change the answer; the two
--     prefix characters are consumed into the excision so they cannot be read as code. A UESCAPE
--     clause after such a string is ordinary code and stays.
--   * AN UNTERMINATED DOLLAR-QUOTE TAG is REFUSED LOUDLY. Round 13 blanked it to the end of the
--     body and called that fail-safe; it is only fail-safe if the region really is a literal, and
--     (3) below is the measurement showing this body can open a tag region that is not one.
--     AND THAT REFUSAL'S SCOPE IS THE WHOLE SCHEMA, WHICH IS WIDER THAN THE BODIES ANY ONE
--     INSTRUMENT JUDGES, so it is named here rather than left to be rediscovered: the raise
--     happens inside this stripper, and tails 1(b) and 1(c) lex EVERY clara body, so from this
--     wave onward ONE malformed body anywhere in the schema stops the migration mid-apply where
--     round 13 blanked it and carried on. That is the direction this file's own law demands --
--     silence is the one answer the instrument may not give -- and it is an accepted trade rather
--     than an oversight: reachability was measured at 0 of 1,214 subjects across every non-system
--     schema, on both subject shapes, and the only known road to such a body is a deliberate
--     insertion under check_function_bodies off, which Postgres will not compile at its first call
--     anyway.
--   * THE OTHER THREE UNTERMINATED OPENERS -- a block comment, a single-quoted string and a
--     double-quoted identifier -- are still blanked SILENTLY to the end of the body; only the
--     dollar tag refuses. That asymmetry is deliberate and belongs on this list rather than in the
--     loud arm. The tag is the one opener THIS BODY CAN OPEN WHERE THE SOURCE HAS NONE, which is
--     what makes blanking it a guess; the other three can only be reached by a subject Postgres
--     would not store, because an unterminated literal or comment is a parse error at CREATE.
--     Measured on the shipped instrument: the three answer 0 with no refusal, the tag is LOUD.
--   * A NUMERIC LITERAL IMMEDIATELY BEFORE A TAG (`1$q$x$q$`) is the one place the left-boundary
--     rule below is NARROWER than Postgres's own lexer, and it is listed rather than fixed because
--     Postgres will not store it WITH check_function_bodies AT ITS DEFAULT: measured, a function
--     body containing that text is a syntax error at CREATE time, and so is the same text inside a
--     branch that never runs, because plpgsql parses every statement when the function is created.
--     THE QUALIFIER IS LOAD-BEARING AND WAS ADDED BECAUSE THE UNQUALIFIED SENTENCE WAS FALSE: with
--     check_function_bodies OFF the same body DOES store, measured. It changes nothing that
--     matters -- plpgsql compiles on first call and throws the same syntax error there -- so such
--     a body can never execute, and the divergence can only ever mislead an instrument about a
--     body that does not run.
--   * THE U& ADJACENCY GUARD'S CHARACTER CLASS IS ASCII-ONLY WHERE THE TAG BOUNDARY'S IS
--     UNICODE-AWARE, and the two therefore disagree about exactly one input: a NON-ASCII
--     identifier character immediately before `u&`. Postgres reads that as an identifier, the
--     bitwise-and operator and a quoted name; this body reads a U& prefix. MEASURED DEAD AT THE
--     MATCHER rather than argued dead: the matcher's gap class admits whitespace and the comment
--     sentinel, and on this server [[:space:]] matches NO non-ASCII character (checked for U+00A0,
--     U+2000, U+2028, U+3000, U+00E9 and U+FEFF), so the leftover character sits in code position
--     and blocks the match from the left -- which is the same verdict Postgres gives. The mirror
--     case, a DIGIT before `u&`, cannot be written at all: the parser rejects it as trailing junk
--     after a numeric literal.
--   * THE SHARED CALL MATCHER'S LEFT LOOKBEHIND IS ALSO ASCII-ONLY AND ALSO OMITS `$`, in a round
--     whose whole subject is that `$` is legal inside an identifier. `a$clara._adj_on_approve(` is
--     ONE identifier to Postgres and reads as a call here -- an OVER-count, and every consumer of
--     that count refuses loudly on it (probe 10 wants exactly four callers, probe 11 wants zero,
--     and S5.8-b2's prestate raises on any count it did not want), so the direction is a refused
--     deploy and never a silent double. Pre-existing on both builds, reach 0 of 603 bodies, and
--     listed rather than swept up with the other two `$` sites because widening that lookbehind
--     changes what all six instruments count, and a comment-only round is not where that is done.
--   * THE E-STRING DETECTOR HAS THE SAME `$` GAP AND ITS DIRECTION IS THE SILENT ONE, and it is
--     DELIBERATELY NOT CLOSED. In `a$E'ab\'` the identifier is `a$E` and the string is an ordinary
--     one that ends at its second quote, but this body reads an E-string and blanks past the
--     escaped quote. Both ends of the trade were measured. Against closing it: the construct is
--     not executable SQL -- `ident$E'...'` is the typename-literal form and needs a type actually
--     named that -- and reach is 0 of 603 bodies. Against closing it more strongly: adding `$` to
--     that class would BREAK the lawful direction, because in `$q$tag$q$E'...'` the character
--     before the `E` is `$` and there the E-string reading is the one that matches Postgres. The
--     narrower class is the better of the two, so it stays and this line exists instead.
--   * A SUBJECT CARRYING chr(1)/chr(2)/chr(3) is REFUSED LOUDLY, and that is an accepted,
--     documented trade rather than an oversight [N14-4/CXR14-2, third round]: the refusal names
--     the exact cause and the remedy, reachability was measured at 0 of 603 clara bodies and 0
--     across all schemas, and a sentinel byte can never reach code position because the guard
--     rejects the whole subject before any excision. The alternative -- trusting the property --
--     is the round-13 defect this replaced. Do not weaken it.
--   * A SESSION RUNNING WITH standard_conforming_strings OFF is not handled and is listed rather
--     than guarded: it would only ever mis-place a boundary INSIDE text that is blanked either
--     way, and no deploy path in this product turns it off.
create or replace function pg_temp._wdb_sql_code(p_src text) returns text
  language plpgsql immutable as $lex$
declare
  v_out   text := '';
  v_rest  text;
  v_i     int := 1;
  v_n     int;
  v_hit   int;
  v_k     int;
  v_len   int;
  v_depth int;
  v_tag   text;
  v_esc   boolean;
  v_p     int;
  v_a     int;
  v_b     int;
  v_q     int;
  v_bs    int;
  v_fill  text;
  v_closed boolean;
  -- [R15 FIX 2026-08-04] `U&` seen immediately before this opener, the quoted part's content, and a
  -- WHOLE-BODY flag: does this subject mention UESCAPE anywhere at all.
  v_uamp  boolean;
  v_id    text;
  v_uesc  boolean;
  -- [R14 FIX 2026-08-04] chr(1) marks an excised COMMENT (whitespace to Postgres, so the matcher admits
  -- it in a token gap); chr(2) marks an excised TOKEN -- a string literal, or a quoted identifier
  -- that is not the bare name -- which the matcher never admits in a gap.
  v_cmt   text := chr(1);
  v_tok   text := chr(2);
begin
  if p_src is null then return null; end if;
  -- [R14 FIX 2026-08-04 -- second re-confirming round, N13-4/CXR13-2] THE SENTINELS ARE CONTROL BYTES, AND
  -- A SUBJECT THAT ALREADY CONTAINS ONE IS REFUSED RATHER THAN MISJUDGED. Round 13 used `~` and
  -- `#`, and argued in this file's own comment that neither "can appear between a function name
  -- and its parenthesis in any executable text". That was FALSE and was refuted by a running
  -- counter-example: with `clara` a table alias and `_adj_on_approve` its column,
  -- `where clara._adj_on_approve ~ ('^x')` is the regex-match OPERATOR between the name and a
  -- parenthesis -- executable, not a call -- and the matcher counted it because `~` was in the gap
  -- class. The lesson is not "pick a rarer printable character": it is that a sentinel drawn from
  -- the subject's own alphabet can always be forged. chr(1)/chr(2)/chr(3) cannot appear in SQL
  -- source text, and this guard is what makes that a CHECKED property instead of an assumption.
  if p_src ~ ('[' || chr(1) || chr(2) || chr(3) || ']') then
    raise exception '0042 D-b2 SQL-lexical stripper: the body being lexed contains one of the control bytes chr(1)/chr(2)/chr(3), which this instrument uses to mark excised comments, excised tokens and the call-offset it substitutes -- every judgement made on the result would be reading its own marks. Investigate the body; do not weaken the instrument.';
  end if;
  -- [R15 FIX 2026-08-04 -- third re-confirming round, N14-1/CXR14-1] ONE WHOLE-BODY QUESTION, ASKED ONCE:
  -- does this subject mention UESCAPE at all. A `U&"..."` identifier is only resolvable by an
  -- instrument that does not decode escapes when nothing can have redefined the escape character,
  -- and that CANNOT be decided locally -- measured, a comment may sit between the identifier and
  -- its UESCAPE clause, so a lookahead over whitespace would be provably incomplete. This test is
  -- over-broad on purpose: it costs one regexp per subject, and it fires only where a U&
  -- identifier and the word actually MEET -- both halves are required, and both were measured.
  -- WHAT IT DOES NOT DO IS ONLY EVER CONVERT A SILENT MISJUDGE, and the sentence that used to say
  -- so was measured false: on a body whose U& identifier is lawful, resolvable and NOT A CALL at
  -- all, with the word sitting in an unrelated comment, round 14 answered 0 and was RIGHT, and
  -- this refuses instead. That is the over-broad trade, it is stated in full in the
  -- does-not-handle list one screen up, and it is not softened here.
  v_uesc := p_src ~* '(?<![A-Za-z0-9_$])uescape(?![A-Za-z0-9_$])';
  v_n := length(p_src);
  while v_i <= v_n loop
    v_rest := substr(p_src, v_i);
    -- The next lexically interesting position: the earliest of the four openers.
    v_hit := 0;
    foreach v_p in array array[position('--' in v_rest), position('/*' in v_rest),
                               position('''' in v_rest), position('$' in v_rest),
                               position('"' in v_rest)] loop
      if v_p > 0 and (v_hit = 0 or v_p < v_hit) then v_hit := v_p; end if;
    end loop;
    if v_hit = 0 then
      v_out := v_out || v_rest;                       -- plain code all the way to the end
      exit;
    end if;
    v_out := v_out || substr(v_rest, 1, v_hit - 1);   -- the plain run before the opener
    v_i := v_i + v_hit - 1;
    v_rest := substr(p_src, v_i);

    if substr(v_rest, 1, 2) = '--' then
      -- LINE COMMENT -- to the end of the line. The newline is code structure and stays.
      v_k := position(E'\n' in v_rest);
      v_len := case when v_k = 0 then length(v_rest) else v_k - 1 end;
      v_fill := v_cmt;   -- [R13 FIX 2026-08-04] a comment IS whitespace to Postgres; see the fill note below

    elsif substr(v_rest, 1, 2) = '/*' then
      -- BLOCK COMMENT -- nesting, as Postgres nests them. Scanned by jumps rather than
      -- character by character so a long comment cannot make this body quadratic.
      v_depth := 1; v_k := 3;
      loop
        v_a := position('*/' in substr(v_rest, v_k));
        exit when v_a = 0;                            -- unterminated
        v_b := position('/*' in substr(v_rest, v_k));
        if v_b > 0 and v_b < v_a then
          v_depth := v_depth + 1; v_k := v_k + v_b + 1;
        else
          v_depth := v_depth - 1; v_k := v_k + v_a + 1;
          exit when v_depth = 0;
        end if;
      end loop;
      -- An unterminated comment blanks to the end, which is the fail-safe direction: nothing
      -- after it can then be read as an executable call.
      v_len := case when v_depth > 0 then length(v_rest) else v_k - 1 end;
      v_fill := v_cmt;   -- [R13 FIX 2026-08-04] a comment IS whitespace to Postgres

    elsif substr(v_rest, 1, 1) = '''' then
      -- SINGLE-QUOTED STRING. '' is an embedded quote; a backslash escapes the next character
      -- ONLY in an E'' literal, which is decided by the token immediately before the quote.
      -- [R15 FIX 2026-08-04 -- third re-confirming round, N14-1] ...AND `U&'...'` IS THE SAME CLASS. The
      -- prefix is two characters of CODE sitting in front of a literal; left there it would be
      -- read as a token in its own right. It is consumed into the excision, two characters in and
      -- two sentinels out, so the length and every offset behind it survive. NO ESCAPE QUESTION
      -- ARISES HERE and none is asked: the content is a literal and is blanked whatever it decodes
      -- to. A U& string does NOT take backslash-escaped quotes the way E'' does (the backslash is
      -- a UNICODE escape there, not a quote escape), so v_esc stays false, which is what the
      -- E-test below already yields when the preceding character is `&`. THE PREFIX MUST BE
      -- ADJACENT, and that was measured in both directions: `U& "x"`, `U&<newline>"x"` and
      -- `U&/*c*/"x"` are all the bitwise-and operator between an identifier and a quoted name.
      v_fill := v_tok;   -- [R13 FIX 2026-08-04] a literal is a TOKEN, not whitespace
      v_uamp := (v_i > 2 and substr(p_src, v_i - 2, 2) ~* '^u&$'
                 and (v_i = 3 or substr(p_src, v_i - 3, 1) !~ '[A-Za-z0-9_$]'));
      if v_uamp then
        v_out := left(v_out, length(v_out) - 2) || v_tok || v_tok;
      end if;
      v_esc := (v_i > 1 and upper(substr(p_src, v_i - 1, 1)) = 'E'
                and (v_i = 2 or substr(p_src, v_i - 2, 1) !~ '[A-Za-z0-9_]'));
      v_k := 2; v_len := length(v_rest);
      loop
        v_a := position('''' in substr(v_rest, v_k));
        exit when v_a = 0;                            -- unterminated: blank to the end
        v_q := v_k + v_a - 1;                         -- this quote's index inside v_rest
        if v_esc then
          -- an ODD run of backslashes immediately before the quote escapes it
          v_bs := 0;
          while v_q - 1 - v_bs >= 2 and substr(v_rest, v_q - 1 - v_bs, 1) = chr(92) loop
            v_bs := v_bs + 1;
          end loop;
          if (v_bs % 2) = 1 then v_k := v_q + 1; continue; end if;
        end if;
        if substr(v_rest, v_q + 1, 1) = '''' then v_k := v_q + 2; continue; end if;
        v_len := v_q; exit;
      end loop;

    elsif substr(v_rest, 1, 1) = '"' then
      -- DOUBLE-QUOTED IDENTIFIER [R14 FIX 2026-08-04 -- second re-confirming round, N13-3 + N13-6 /
      -- CXR13-1, DEPLOY-BLOCKER, the silent-double direction]. Round 13 had no token class for
      -- `"` at all, and the cost was measured in both directions on planted frontiers:
      --   * `perform "clara"."_adj_on_approve"(p_entry);` IS the call -- quoting an
      --     already-lower-case name changes nothing about which function runs -- and every
      --     instrument read it as ABSENT. The pre-fix build APPLIED CLEAN onto a body that already
      --     had the hook and left TWO independent executable calls in it.
      --   * `declare "don't" text;` was read as an APOSTROPHE opening a string literal, so the
      --     executable lines up to the next apostrophe were blanked -- a real call, hidden by a
      --     lawful variable name.
      -- SO A QUOTED PART IS A TOKEN, AND THE ONLY QUESTION IS WHICH TOKEN. If the quoted content
      -- is a valid identifier that is ALREADY LOWER CASE, quoting it is a no-op in Postgres and
      -- the part FOLDS to the bare name -- the delimiters become the comment sentinel, which the
      -- matcher already admits in a token gap, so the fold costs no length and no offset. Any
      -- OTHER quoted content ("CLARA", "Clara", "don't", `a""b`) is a DIFFERENT identifier from
      -- the bare one, so it becomes one OPAQUE token: it can never match the roster, and -- the
      -- half that closes the apostrophe defect -- it can never open a string either.
      -- [R15 FIX 2026-08-04 -- third re-confirming round, N14-1/CXR14-1, MONEY] ...AND `U&"..."` IS THE
      -- SAME IDENTIFIER, WRITTEN THE OTHER LAWFUL WAY. MEASURED: `U&"clara".U&"_adj_on_approve"`
      -- resolves to exactly the function the bare spelling resolves to, a plpgsql body reaches
      -- clara through it, and W-R14's fold left the two-character `U&` sitting in CODE position
      -- between the dot and the next name -- so the matcher's gap class stopped dead there and
      -- every instrument read a RUNNING call as absent. End to end on a planted frontier: the
      -- migration APPLIED CLEAN and the body ended with TWO executable invocations per approval,
      -- which is RC3's silent double reached through a spelling nobody had enumerated.
      -- THE PREFIX IS PART OF THE TOKEN. Two characters in, two sentinels out -- the comment
      -- sentinel when the part folds (so the matcher walks over it exactly as it walks over the
      -- delimiters), the token sentinel when it does not.
      v_uamp := (v_i > 2 and substr(p_src, v_i - 2, 2) ~* '^u&$'
                 and (v_i = 3 or substr(p_src, v_i - 3, 1) !~ '[A-Za-z0-9_$]'));
      v_k := 2; v_len := length(v_rest); v_closed := false;
      loop
        v_a := position('"' in substr(v_rest, v_k));
        exit when v_a = 0;                            -- unterminated: opaque to the end
        v_q := v_k + v_a - 1;
        if substr(v_rest, v_q + 1, 1) = '"' then v_k := v_q + 2; continue; end if;
        v_len := v_q; v_closed := true; exit;
      end loop;
      v_id := case when v_closed and v_len > 2 then substr(v_rest, 2, v_len - 2) else null end;
      -- A U& PART THIS BODY CANNOT RESOLVE IS REFUSED, NOT GUESSED [R15 FIX 2026-08-04]. Three ways it
      -- can be unresolvable, and only the first is obvious. (a) A BACKSLASH is a unicode escape in
      -- this spelling, so `U&"\0063lara"` IS clara and folding the content verbatim would rename a
      -- running call to something no roster carries. (b) A UESCAPE CLAUSE redefines the escape
      -- character to almost anything -- MEASURED, `U&'z0063lara' UESCAPE 'z'` is clara -- so under
      -- one, a content that looks like a plain lowercase identifier can denote something else
      -- entirely; the flag is whole-body because a comment may sit between the identifier and its
      -- clause. (c) An unterminated or empty quoted part names nothing at all. The bare `"..."`
      -- spelling is untouched by all three: there, a backslash is simply a character in the name.
      if v_uamp and (v_id is null or position(chr(92) in v_id) > 0 or v_uesc) then
        raise exception '0042 D-b2 SQL-lexical stripper: a U&"..." identifier this instrument cannot resolve (%) -- %. It does not decode unicode escapes and does not implement UESCAPE, so it cannot say which identifier this names, and a call it cannot resolve must never be reported as absent: that is the silent double this file exists to close. Rewrite the identifier in its plain spelling, or extend the stripper.',
          coalesce('"' || v_id || '"', 'unterminated or empty'),
          case when not v_closed then 'the quoted part is never closed'
               when v_id is null then 'the quoted part is empty'
               when position(chr(92) in v_id) > 0 then 'its content carries a backslash, which is a UNICODE ESCAPE in this spelling'
               else 'this body mentions UESCAPE, which can redefine the escape character to a character that leaves the content looking like a plain identifier' end;
      end if;
      if v_id is not null and v_id ~ '^[a-z_][a-z0-9_$]*$' then
        -- FOLDED. Same length in as out: (two prefix sentinels when U&,) one sentinel, the
        -- content, one sentinel.
        if v_uamp then
          v_out := left(v_out, length(v_out) - 2) || v_cmt || v_cmt;
        end if;
        v_out := v_out || v_cmt || v_id || v_cmt;
        v_i := v_i + v_len;
        continue;
      end if;
      if v_uamp then
        v_out := left(v_out, length(v_out) - 2) || v_tok || v_tok;
      end if;
      v_fill := v_tok;

    else
      -- A '$'. It opens a dollar-quoted string only if it is a well-formed delimiter; `$1` and a
      -- bare `$` are ordinary code and pass through one character at a time.
      -- [R14 FIX 2026-08-04 -- second re-confirming round, N13-5/CXR13-4] THE TAG RULE IS POSTGRES'S,
      -- NOT ASCII'S. A dollar-quote tag follows the identifier rules, and those admit non-ASCII
      -- letters; the round-13 class stopped at [A-Za-z_], so `$<e-acute>$ ... $<e-acute>$` was not
      -- recognised as a delimiter at all and its CONTENTS were passed through as executable code.
      -- MEASURED on this rig (server_encoding UTF8, lc_ctype C -- where [[:alpha:]] is ASCII-only
      -- and would NOT have fixed it): the explicit range below recognises the accented tag, a CJK
      -- tag and an astral-plane tag, still recognises `$q$` and `$$`, and still correctly REFUSES
      -- `$1` and a digit-first tag. The upper bound is the last Unicode code point, so there is no
      -- plane left over.
      -- [R15 FIX 2026-08-04 -- third re-confirming round, CXR14-3, MEASURED BEFORE FIXING] A TAG CAN ONLY
      -- OPEN AT A TOKEN BOUNDARY. `$` is legal in a non-first identifier position, so `x$t$` is ONE
      -- identifier -- confirmed by running it, not by reading the grammar. Without this test the
      -- body reads that `$t$` as a tag opener, scans to the next `$t$` and blanks everything
      -- between: MEASURED on a function Postgres executes, with the call sitting between two
      -- `$`-bearing identifiers, the matcher read ZERO while the call ran. Same silent-miss class
      -- as the U& defect above, through a different door. The test is on the last EMITTED
      -- character, not the last source character, which is the right question: a `$` that follows
      -- an excised region follows a sentinel, and a sentinel is not identifier text -- which is
      -- also correct for the source, because a comment or a quoted part ENDS the identifier that
      -- preceded it and Postgres opens a tag there too.
      if v_out <> '' and right(v_out, 1) ~ '[A-Za-z0-9_$\u0080-\U0010FFFF]' then
        v_out := v_out || '$';
        v_i := v_i + 1;
        continue;
      end if;
      v_tag := substring(v_rest from '^\$[A-Za-z_\u0080-\U0010FFFF][A-Za-z0-9_\u0080-\U0010FFFF]*\$|^\$\$');
      if v_tag is null then
        v_out := v_out || '$';
        v_i := v_i + 1;
        continue;
      end if;
      v_a := position(v_tag in substr(v_rest, length(v_tag) + 1));
      -- AN UNTERMINATED TAG REGION IS REFUSED, NOT BLANKED [R15 FIX 2026-08-04]. Round 13 blanked to the
      -- end of the body and argued that was the fail-safe direction. It is -- but only if the
      -- region really is a literal, and the measurement above is a body where this code opens a
      -- region that is not one. Blanking to end would then hide every call after it, silently.
      if v_a = 0 then
        raise exception '0042 D-b2 SQL-lexical stripper: a dollar-quote tag (%) opens a region that is never closed in this body -- a complete function body cannot contain one, so either the subject is truncated or this instrument opened a tag where the source has none; blanking to the end of the body would hide every call after it', v_tag;
      end if;
      v_len := length(v_tag) + v_a - 1 + length(v_tag);
      v_fill := v_tok;   -- [R13 FIX 2026-08-04] a literal is a TOKEN, not whitespace
    end if;

    -- BLANKED, NOT DELETED: same length, same lines.
    -- ...AND BLANKED TO A SENTINEL, NOT TO A SPACE [R13 FIX 2026-08-04 -- re-confirming round, Codex RC3,
    -- DEPLOY-BLOCKER]. Round 12 wrote spaces, and spaces threw away the one fact the consumers
    -- needed: a comment between two tokens is WHITESPACE to Postgres (so
    -- `clara._adj_on_approve/*x*/(p_entry)` is a real call), and a string literal between them is
    -- a TOKEN (so `clara._adj_on_approve'x'(p_entry)` is not). Blanked to spaces both look the
    -- same, and every exact-substring consumer read the comment-spliced call as ABSENT -- on a
    -- database that already had it, which is a second call spliced in beside the first.
    -- chr(1) MARKS A COMMENT and chr(2) MARKS A TOKEN (a literal, or a quoted identifier that is
    -- not the bare name), and pg_temp._wdb_call_rx admits chr(1) in a token gap and refuses chr(2).
    -- [R14 FIX 2026-08-04 -- second re-confirming round, N13-4/CXR13-2] THE CHARACTERS USED TO BE `~` AND
    -- `#`, AND THE SENTENCE HERE CLAIMED NEITHER "can appear between a function name and its
    -- parenthesis in any executable text". That was measured FALSE with a body that runs:
    -- `select count(*) from t as clara(_adj_on_approve) where clara._adj_on_approve ~ ('^x')` --
    -- an alias, a column and the regex-match OPERATOR, no call anywhere, and the matcher counted
    -- one because `~` sat in the gap class. A sentinel taken from the subject's own alphabet can
    -- always be forged, so the marks are now control bytes that cannot occur in SQL source at all,
    -- and the stripper REFUSES a body that contains one rather than trusting the property.
    -- LENGTH IS STILL PRESERVED, WHICH IS THE INVARIANT THE POSITIONAL CLAIMS REST ON: one
    -- character out, one character in, newlines kept -- so an offset measured on the code is an
    -- offset in the source, and probe 11 and S5.8-b2 assert exactly that on every run.
    v_out := v_out || regexp_replace(substr(v_rest, 1, v_len), '[^' || E'\n' || ']', v_fill, 'g');
    v_i := v_i + v_len;
  end loop;
  return v_out;
end $lex$;

-- #####################################################################################
-- ### SECTION 0 (D-b2 SLICE) -- THE SHARED CALL MATCHER (deploy-time only) ############
-- #####################################################################################
-- [R13 FIX 2026-08-04 -- re-confirming round, Codex RC3+RC4, DEPLOY-BLOCKER] FOUR INSTRUMENTS IN THIS
-- FILE JUDGE WHETHER A LIVE BODY CALLS A HOOK: SECTION 0's probe 11, SECTION S5's S5.8-b2
-- prestate and postcheck, tail 1(c) and tail 3(1). Round 12 made them share a LEXER. They still
-- did not share a QUESTION, and the re-confirming round measured both halves of that gap:
--   * A COMMENT-SPLICED CALL WAS INVISIBLE. Postgres treats a comment as whitespace, so
--     `perform clara._adj_on_approve/*hotfix*/(p_entry);` IS a call -- but the stripper blanked
--     the comment to SPACES and every consumer matched an exact substring, so all four read the
--     hook as ABSENT on a database that already had it. The splice then added a SECOND canonical
--     call and the postcheck, counting one spelling, passed. A silent double materialisation of
--     every occurrence, shipped by a migration that reported success.
--   * A NAMED-NOTATION CALL SPLIT THE INSTRUMENTS. `clara._adj_on_approve(p_entry => p_entry)`
--     is the same call; probe 11 (which asked for `...(p_entry)`) read it as absent and admitted
--     the apply, and the S5.8-b2 prestate (which asked the argument-blind `...(`) refused it one
--     section later -- a migration that dies in the middle of itself.
-- SO THE QUESTION IS ASKED ONCE, HERE, AND THE FOUR CONSUMERS ASK IT. A call is matched by its
-- QUALIFIED NAME up to the opening paren and nothing else:
--   * ARGUMENT-BLIND. The argument list is not part of the question. Positional, named,
--     defaulted, a different variable spelling -- all of them are the same call, and the thing
--     every one of these instruments actually wants to know is whether the hook runs.
--   * TOKEN-AWARE. Whitespace AND excised regions are legal between `clara`, `.`, the name and
--     the `(`, because Postgres allows both there. `~` is the stripper's COMMENT sentinel and is
--     admitted in the gap; `#`, its STRING-LITERAL sentinel, is NOT -- a literal is a token, not
--     whitespace, so `clara._adj_on_approve'x'(p_entry)` is not a call and this matcher does not
--     pretend it is. That distinction is the whole reason the two sentinels are different
--     characters.
--   * CASE-BLIND. Unquoted SQL identifiers are case-insensitive, so `PERFORM CLARA._ADJ_ON_APPROVE(`
--     is the same call. Two of the four consumers already lower-cased their input and two did
--     not; leaving that asymmetry would ship RC4's defect under a different spelling.
--   * BOUNDED ON THE LEFT. The lookbehind stops `xclara._adj_on_approve(` from matching, and the
--     `(` stops `clara._adj_on_approve_twin(` from matching -- so the roster cannot collide with
--     a longer sibling name of the same family.
--   * QUOTED-PART AWARE [R14 FIX 2026-08-04 -- N13-3/N13-6/CXR13-1]. The stripper FOLDS a quoted part
--     whose content is an already-lower-case identifier down to the bare name, wrapping it in the
--     comment sentinel -- so `"clara"."_adj_on_approve"(` reaches this matcher as the bare tokens
--     with sentinel gaps and MATCHES, which is right, because that is the same call. A quoted part
--     that is anything else ("CLARA", "Clara", "don't") is one opaque token and can never match --
--     also right: `"CLARA"."_adj_on_approve"` names a DIFFERENT function.
--   * REACHABILITY, MEASURED AND OFFERED AS CONTEXT RATHER THAN AS COMFORT: across the 2,141 call
--     sites in this schema today, ZERO are written with a quoted identifier and ZERO are written
--     unqualified. That is why the defect was latent and not live -- it is mitigation, not
--     immunity, and the instrument is fixed rather than the census being trusted to stay at zero.
create or replace function pg_temp._wdb_call_rx(p_qname text) returns text
  language sql immutable as $rx$
  select '(?i)(?<![A-Za-z0-9_])'
      || replace(p_qname, '.', '[[:space:]' || chr(1) || ']*[.][[:space:]' || chr(1) || ']*')
      || '[[:space:]' || chr(1) || ']*[(]' $rx$;

-- HOW MANY TIMES DOES THIS CODE CALL THAT FUNCTION. `regexp_matches` rather than `regexp_count`
-- on purpose: the same rule the stripper states one screen up -- a deploy-time instrument that
-- needs a recent server function is an instrument that fails on the one database nobody tested
-- against (regexp_count is PostgreSQL 15+).
create or replace function pg_temp._wdb_call_count(p_code text, p_qname text) returns int
  language sql immutable as $cc$
  select count(*)::int from regexp_matches(p_code, pg_temp._wdb_call_rx(p_qname), 'g') $cc$;

-- WHERE IS THE FIRST ONE. Returns 0 when there is none, which is the convention every ordering
-- claim in this file is already written against ("a bare position(a) < position(b) reads a
-- MISSING marker as correctly ordered", so each of them asserts both endpoints are non-zero).
-- THE OFFSET IS TAKEN BY SUBSTITUTION, NOT BY SEARCHING FOR THE MATCHED TEXT: `position(match in
-- code)` would find an EARLIER identical substring that the lookbehind had (correctly) refused,
-- and report a position where there is no call. Replacing the first match with a character that
-- cannot occur in SQL source gives the true offset with nothing but regexp_replace and position.
-- The guard is not ceremony: if the marker byte ever WERE in the text, this body would silently
-- return somebody else's offset, and an ordering claim built on it would be decoration.
-- [R14 FIX 2026-08-04] THE MARKER IS chr(3) NOW, because chr(1) became the stripper's comment sentinel
-- and therefore appears legitimately in every lexed body that carries a comment. The guard moves
-- with it and stays a guard.
create or replace function pg_temp._wdb_call_pos(p_code text, p_qname text) returns int
  language plpgsql immutable as $cp$
declare v_x text;
begin
  if position(chr(3) in p_code) > 0 then
    raise exception '0042 D-b2 call matcher: the text being measured already contains chr(3), the offset marker this body substitutes the first match with -- the position it returned would be that character''s, not the call''s';
  end if;
  v_x := regexp_replace(p_code, pg_temp._wdb_call_rx(p_qname), chr(3), '');
  return position(chr(3) in v_x);
end $cp$;


do $probe$
declare
  v_n int; v_names text; v_def text; v_code text; v_ver int; r record;
begin
  -- PROBE 1 -- FRONTIER ASSERT.
  -- [SPLIT D-b2 2026-08-04] THE FRONTIER IS D-b3, NOT 0041 AND NOT D-b0/D-b1. The whole unit pinned
  -- 0041_wave_d_a_fa_register because it was the applied predecessor of the ONE file; this
  -- slice's predecessor is the slice before it in the ship order, and the dependency on ALL
  -- THREE predecessors is a REAL CALL GRAPH (the SHIP ORDER paragraph in this file's header
  -- names each edge). Applied out of order, SECTION S2 would `create or replace`
  -- clara._wdb_rerun_breach onto NOTHING (E9: create-or-replace on an absent body creates it
  -- silently, so the FA arms D-b0 owns would simply vanish), and every cross-slice call in the
  -- template family, the hook and the pair machine would raise `undefined_function` at its
  -- first real use -- in the middle of somebody's approval. 0041, 0042 and 0043 are not
  -- re-asserted here: each slice's own frontier probe pinned its predecessor, and
  -- clara.schema_migrations is append-only, so 0044 present implies all three.
  select count(*)::int into v_n from clara.schema_migrations
    where version = '0044_wave_d_b3_af2_composite';
  if v_n <> 1 then
    raise exception '0042 D-b2 probe 1: migration 0044_wave_d_b3_af2_composite is not recorded as applied -- the D-b slices ship in the order D-b0 -> D-b1 -> D-b3 -> D-b2 and SECTION S2 of this one RE-CREATES a D-b0 body and CALLS D-b0, D-b1 and D-b3 bodies; apply in order';
  end if;

  -- PROBE 2 -- PRE-STATE SAFETY: none of the three relations this file creates already exist.
  -- [SPLIT D-b2 2026-08-04] NARROWED TO THIS SLICE'S OWN THREE. The whole-unit probe 2 lists seven;
  -- clara.staff_advance_accounts, clara.staff_advances, clara.staff_advance_applications and
  -- clara.ea1955_policy all shipped in D-b1 and EXIST now, so the whole-unit predicate would
  -- refuse this migration on a correctly-ordered database. That is the exact shape of error a
  -- copied-unchanged negative probe produces, and it is why every one of them has to be cut to
  -- the objects its OWN slice creates (D-b3's probe 3 recorded the same lesson).
  -- FINAL FORM: the whole-unit probe 2, reassembled across D-b1 and here.
  select count(*)::int, string_agg(t.relname, ', ' order by t.relname) into v_n, v_names
  from pg_class t join pg_namespace n on n.oid = t.relnamespace
  where n.nspname = 'clara' and t.relname in
    ('adjustment_templates', 'adjustment_runs', 'adjustment_pair_reversals');
  if v_n <> 0 then
    raise exception '0042 D-b2 probe 2: % relation(s) already exist in schema clara that this migration is about to create (%) -- this looks like a partial or duplicate re-apply, not a fresh deploy', v_n, v_names;
  end if;

  -- [SPLIT D-b2 2026-08-04] PROBE 3 HAS NO D-b2 FORM, AND IT IS RECORDED RATHER THAN SILENTLY DROPPED.
  -- The whole-unit probe 3 names three columns and NOT ONE of them is this slice's:
  -- clara.journal_entries.auto_reversal_of shipped in D-b0 (SS1.10, census sect.4 Option A --
  -- the deliberate DDL-forward that let clara._wdb_reversal_blocked exist from D-b1) and the two
  -- clara.bank_matches park columns shipped in D-b3. THIS SLICE ADDS NO COLUMN TO ANY TABLE.
  -- FINAL FORM: the whole-unit probe 3, reassembled across D-b0 and D-b3.

  -- PROBE 4 -- PRE-STATE SAFETY: none of the three indexes this file creates exist yet -- the
  -- two hot-loop partials (ABI SSC) and the pair-receipt correction lookup (SS1.11).
  -- [SPLIT D-b2 2026-08-04] NARROWED FROM FOUR TO THREE: uq_je_auto_reversal_of is D-b0's and EXISTS,
  -- so probing it absent would refuse a correctly-ordered deploy. The other three are created
  -- with a PLAIN `create index` / `create unique index`, so each is additionally self-detecting
  -- at the CREATE -- this probe exists to name the failure before Postgres names it.
  -- FINAL FORM: the whole-unit probe 4, reassembled across D-b0 and here.
  select count(*)::int, string_agg(c.relname, ', ' order by c.relname) into v_n, v_names
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'clara' and c.relkind = 'i'
    and c.relname in ('ix_je_adj_draft', 'ix_je_adj_occurrence', 'ix_adj_pair_corrections');
  if v_n <> 0 then
    raise exception '0042 D-b2 probe 4: % index(es) already exist (%) -- partial or duplicate re-apply', v_n, v_names;
  end if;

  -- PROBE 5 -- PRE-STATE SAFETY: the new event name is not registered yet (ABI SSG).
  -- [SPLIT D-b2 2026-08-04] NARROWED TO ONE NAME: bank.line_exception_reopened is D-b3's and IS
  -- registered now. Census sect.4 adjudicates the SECTION EVENTS split by name ("the CTE + local
  -- postcheck duplicate cleanly"), and this probe follows the same cut.
  -- FINAL FORM: the whole-unit probe 5, reassembled across D-b3 and here.
  select count(*)::int, string_agg(name, ', ' order by name) into v_n, v_names
    from clara.event_types
    where name in ('adjustment.posted');
  if v_n <> 0 then
    raise exception '0042 D-b2 probe 5: % event type(s) already registered that this migration adds (%) -- partial or duplicate re-apply', v_n, v_names;
  end if;

  -- PROBE 6 -- PRE-STATE SAFETY: no verb or internal this file creates already exists (a
  -- duplicate re-apply would otherwise CREATE OR REPLACE over a live body silently).
  -- [SPLIT D-b2 2026-08-04] NARROWED TO THE NAMES **THIS SLICE** CREATES, which is the only cut that
  -- can be right: the whole-unit list enumerates every name the ONE file created, and 45 of
  -- those bodies now EXIST (D-b0's six s2 fragments, D-b1's advance family and its four SS1
  -- trigger functions, D-b3's two suggestion helpers, its composite and its SS1.8 guard). A
  -- copied-unchanged list would refuse this migration on a correctly-ordered database.
  -- clara._wdb_rerun_breach is DELIBERATELY ABSENT FROM THIS LIST and that is the single most
  -- important line in this probe: D-b0 created it in FA-arm form and SECTION S2 below RE-CREATES
  -- it whole with `create or replace`, so it MUST already exist -- probe 7 asserts exactly that,
  -- under the [SPLIT-CREATED] class errata E9 defines. Probing it absent here would refuse every
  -- lawful deploy.
  -- RECORDED, NOT REPAIRED (D-b0's finding E3, D-b1's E11, D-b3's E14/E15 -- the same class, one
  -- slice later, and the last chance anybody has to notice it): the whole-unit probe 6 does NOT
  -- in fact enumerate every name the unit creates. SIX are missing, and FIVE of them are THIS
  -- slice's: clara._adj_template_json, clara._adj_run_json, clara.list_adjustment_templates,
  -- clara.list_adjustment_runs and clara.get_adjustment_run (all SECTION S2.8), plus
  -- clara._assert_due_read_ctx, which is D-b0's (errata E4). They are NOT added here. The scope
  -- law for this extraction is faithful extraction, never invention, and D-b3's errata E14 set
  -- the precedent one slice ago for exactly this shape of omission. Recorded as errata E19 with
  -- the measurement, so the reassembled whole-unit list can be repaired once, deliberately,
  -- rather than six times by accident. Note that E4's own direction ("fix at D-b2's final form")
  -- is unhonourable AS WRITTEN for clara._assert_due_read_ctx: it is D-b0's body, it EXISTS by
  -- the time this file runs, and a negative probe naming it would refuse a correct deploy --
  -- the same measured shape as D-b3's E13.
  -- FINAL FORM: the whole-unit probe 6 list, reassembled across the four slices (and repaired
  -- by six names when it is).
  select count(*)::int, string_agg(p.proname, ', ' order by p.proname) into v_n, v_names
  from pg_proc p where p.pronamespace = 'clara'::regnamespace
    and p.proname in (
      -- SS2, the adjustment family (verbs, core, hook, pair machine + private helpers), MINUS
      -- the six s2 fragments census sect.2 Class A/D moved forward to D-b0 and D-b3
      -- (clara._acct_role_reserved, clara._adj_line_eligibility_breach,
      -- clara._wdb_correction_posting_date, clara._wdb_iso_date_supported,
      -- clara._wdb_period_stamps, clara._wdb_suggestion_lines / clara._wdb_suggestion_rule_hit),
      -- MINUS clara._wdb_reversal_blocked (D-b1's, census sect.8's D-b1 map), and MINUS
      -- clara._wdb_rerun_breach (D-b0's FA-arm shell, re-created below -- see the paragraph
      -- above).
      '_adj_canon_lines', '_adj_correction_door',
      '_adj_occurrence_outstanding', '_adj_oldest_unmet_period', '_adj_on_approve',
      '_adj_period_end', '_adj_period_label',
      '_adj_period_start',
      '_adj_run_occurrence_core', '_adj_template_hash', '_pair_reverse_core',
      '_wdb_correction_admission',
      '_wdb_entry_shape',
      '_wdb_line_shape', '_wdb_overlapping_siblings',
      '_wdb_shape_overlap',
      '_wdb_iso_day',                        -- [R12 FIX 2026-08-04] the period-stamp grammar
      '_wdb_period_overlap_advisory',        -- [R12 FIX 2026-08-04] the propose/sign period advisory
      '_wdb_replaced_generation_standing',   -- [R11 FIX 2026-08-04] the period-keyed lineage authority
      '_wdb_template_ancestry',
      '_wdb_template_standing_charges',
      'propose_adjustment_template', 'sign_adjustment_template', 'retire_adjustment_template',
      'run_adjustment_occurrence', 'run_adjustment_manual', 'adjustment_run_due',
      'reverse_adjustment_pair', 'approve_pair_reversal', 'cancel_pair_reversal',
      -- SS1, the trigger functions of THIS slice's three relations
      '_tf_adjustment_pair_reversal_no_commit_approving',
      '_tf_adjustment_pair_reversal_transition', '_tf_adjustment_run_immutable',
      '_tf_adjustment_template_lineage_root',  -- [R13 FIX 2026-08-04] the declared-root constraint belt
      '_tf_adjustment_template_transition');
  if v_n <> 0 then
    raise exception '0042 D-b2 probe 6: % D-b function name(s) already exist (%) -- partial or duplicate re-apply', v_n, v_names;
  end if;

  -- PROBE 7 -- ANCHOR: every live body SECTION S5 splices, and every body outside this slice
  -- that SECTION S2 calls or replaces, is present at its EXACT signature. A missing one here is
  -- a far better error than a regprocedure cast failing mid-splice -- or, worse, than nothing at
  -- all until the first real call.
  -- [SPLIT D-b2 2026-08-04] NARROWED TO THIS SLICE'S FOUR SPLICE SUBJECTS + the three op/hash
  -- primitives its verbs use + clara._approve_entry_core (the hook's arm (2) mirror flip), AND
  -- WIDENED by ELEVEN [SPLIT-CREATED] ANCHORS. The widening is a DEVIATION FROM THE CANONICAL
  -- ARRAY, named rather than smuggled, and its precedent is errata E9 (D-b1's probe 7 was
  -- widened by four such anchors; D-b3's by five): these are dependencies the SPLIT invented and
  -- the whole unit could not have carried, because in ONE file each of these bodies was created
  -- a few thousand lines above its use. TWO DISTINCT FAILURE MODES ARE COVERED, and neither is
  -- caught by anything else:
  --   * clara._wdb_rerun_breach is a `create or replace` TARGET. On an absent body that
  --     statement CREATES it silently -- the inverse of what probe 6 exists to catch -- and the
  --     FA arms D-b0 owns would vanish with no error anywhere.
  --   * the other ten are CALL dependencies, and plpgsql resolves a call at EXECUTION. Nothing
  --     at CREATE time notices their absence; the failure surfaces months later, inside
  --     somebody's approval.
  -- The whole unit's other nineteen entries are the settle/allocate/match/bank subjects of
  -- SECTION S4 (D-b3's, shipped) and the FA/K-door subjects of SECTION S5's pure blocks
  -- (D-b0's, shipped); this slice splices none of them and does not re-assert them.
  -- FINAL FORM: the whole-unit 27-entry array, reassembled across the four slices.
  foreach v_names in array array[
      -- this slice's own SECTION S5 splice subjects
      'clara._subledger_on_approve(uuid)',
      'clara.revise_entry(uuid,jsonb,jsonb,jsonb,uuid,text,jsonb,jsonb)',
      'clara.withdraw_draft(uuid,text,uuid,text)',
      'clara.set_client_fy_end(uuid,integer,integer,text)',
      -- the core the hook's arm (2) re-enters through, and the op/hash primitives every verb
      -- in SECTION S2 reserves and finishes with
      'clara._approve_entry_core(jsonb,uuid,uuid,text,text)',
      'clara._reserve_op(uuid,text,text,bytea)',
      'clara._finish_op(uuid,text,text,jsonb)',
      'clara._hash(jsonb)',
      -- [SPLIT-CREATED] the `create or replace` TARGET: D-b0's FA-arm form of the ONE re-run
      -- gate. SECTION S2 restores its adjustment arm; on an absent body the same statement
      -- would CREATE a body with no FA arms at all and D-b0's two callers
      -- (clara._fa_oldest_unmet_period, clara._fa_run_period_core) would silently lose their
      -- gate. This is the anchor errata E9 exists for.
      'clara._wdb_rerun_breach(uuid,text,text[],date,date)',
      -- [SPLIT-CREATED] the FIVE D-b0 bodies SECTION S2 CALLS (census sect.2 Class A/D moved
      -- each of them forward out of the adjustment section)
      'clara._assert_due_read_ctx(uuid)',
      'clara._wdb_period_stamps()',
      'clara._wdb_correction_posting_date(uuid,date)',
      'clara._wdb_iso_date_supported(date)',
      'clara._adj_line_eligibility_breach(uuid,jsonb)',
      -- [SPLIT-CREATED] the THREE D-b1 bodies SECTION S2's correction-door / admission
      -- authority CALL, plus the hook line S5.8-b2 anchors its splice on
      'clara._wdb_reversal_blocked(uuid)',
      'clara._adv_reversal_admission(uuid,text,uuid,date,timestamptz,uuid)',
      'clara._adv_on_approve(uuid)',
      -- [SPLIT-CREATED] the TWO D-b3 bodies clara._adj_on_approve's arm (3) re-derives through.
      -- The whole point of the approve-time re-validation is that the checker approves what the
      -- rule says TODAY, and a second derivation here would only prove that two pieces of code
      -- agree with themselves -- so this slice CALLS D-b3's and never re-creates them.
      'clara._wdb_suggestion_rule_hit(uuid,uuid)',
      'clara._wdb_suggestion_lines(uuid,uuid,uuid)'] loop
    if to_regprocedure(v_names) is null then
      raise exception '0042 D-b2 probe 7: % is not present at that exact signature -- SECTION S2/S5 cannot splice, replace or call it', v_names;
    end if;
  end loop;

  -- PROBE 8 -- ANCHOR: exactly one ACTIVE taxonomy version exists and the new row will attach
  -- to it (the 0041:978-996 CTE cross-joins clara.taxonomy_active).
  -- [SPLIT D-b2 2026-08-04] KEPT WHOLE AND IT IS THIS SLICE'S OWN CLAIM: SECTION EVENTS below registers
  -- adjustment.posted by cross-joining clara.taxonomy_active, so a second active version would
  -- silently write a second taxonomy row and tail 14's exact count would be the first thing to
  -- notice. D-b0 and D-b1 kept this probe as an anchor while registering nothing; here, as in
  -- D-b3, it is load-bearing.
  select count(*)::int into v_n from clara.taxonomy_active;
  if v_n <> 1 then
    raise exception '0042 probe 8: clara.taxonomy_active must hold exactly one row (found %)', v_n;
  end if;
  select version into v_ver from clara.taxonomy_active;
  if v_ver is null then
    raise exception '0042 probe 8b: clara.taxonomy_active carries no version';
  end if;

  -- PROBE 9 -- ANCHOR: the tenancy anchor this file's composite FKs target.
  -- [SPLIT D-b2 2026-08-04] NARROWED TO 9, WITHOUT 9b. All three relations SS1.1-SS1.3 creates carry
  -- the (client_id, firm_id) composite FK against clara.clients' uq_clients_id_firm, so probe 9
  -- is exactly this slice's. Probe 9b (clara.coa_accounts' (client_id, account_code) unique) is
  -- named in the canonical source as "the ENROLMENT FK anchor" -- clara.staff_advance_accounts'
  -- -- and that relation is D-b1's, shipped. Asserting it here would be asserting somebody
  -- else's anchor.
  -- FINAL FORM: the whole-unit probe 9 pair, reassembled across D-b1 and here.
  if not exists (select 1 from pg_constraint
                 where conrelid = 'clara.clients'::regclass and conname = 'uq_clients_id_firm') then
    raise exception '0042 probe 9: clara.clients is missing uq_clients_id_firm -- the (client_id, firm_id) FK anchor';
  end if;

  -- PROBE 10 -- ANCHOR: the four approve paths still funnel through _subledger_on_approve at
  -- the count the 0037 tail pinned and the 0041 tail re-pinned. The 0042 tail RE-PINS this
  -- at the SAME number after the SS2.6/SS3.3 hook splices -- every D-b approval routes
  -- through _approve_entry_core, so the census must NOT move. Measuring it here first makes
  -- the tail's claim a delta, not a guess.
  -- [R14 FIX 2026-08-04 -- second re-confirming round, N13-1/CXR13-3, DEPLOY-BLOCKER] ...AND IT IS ASKED
  -- ON THE SHARED INSTRUMENT, because this probe was the FIFTH judge of "who calls this hook" and
  -- the only one still reading raw, case-sensitive, comment-blind text. Both directions were
  -- MEASURED on a planted 0044 frontier:
  --   * a caller that respells the call in UPPER CASE -- lawful, since unquoted identifiers are
  --     case-insensitive, and behaviourally identical -- made this probe read THREE and refuse a
  --     correct deploy;
  --   * an unrelated body carrying a COMMENT that names the hook -- no call at all -- made it read
  --     FIVE and refuse a correct deploy.
  -- Both are E37 deploy blockers, and both disappear when the question is the shared one.
  select count(*)::int into v_n from pg_proc p
    where p.pronamespace = 'clara'::regnamespace
      and pg_temp._wdb_call_count(pg_temp._wdb_sql_code(coalesce(p.prosrc, '')),
                                  'clara._subledger_on_approve') > 0;
  if v_n <> 4 then
    raise exception '0042 probe 10: expected exactly 4 callers of clara._subledger_on_approve, found % -- the 0037:3779-3846 four-caller census drifted', v_n;
  end if;

  -- PROBE 11 -- ANCHOR: the hook splice subject still carries the _fa_on_approve marker
  -- exactly once, at the position SS2.6 splices AFTER. A drifted count means the D-a splice
  -- moved and SECTION S5's positional splice has no anchor.
  -- [SPLIT D-b2 2026-08-04] WIDENED BY ONE MARKER, AND THE WIDENING IS THE ERRATA-E8 ANCHOR. The whole
  -- unit measured only clara._fa_on_approve(p_entry) because in ONE file the body it splices was
  -- 0041's. This slice splices a body D-b1 ALREADY EDITED, so the prestate it must measure is the
  -- body AS D-b1 LEFT IT: the FA marker at 1 (the position D-b1 anchored on) AND
  -- clara._adv_on_approve(p_entry) at 1 (the line S5.8-b2 splices ABOVE). Both counts were
  -- HARVESTED with pg_get_functiondef from a rig with 0042+0043+0044 applied, never read off the
  -- 0041 or the whole-unit file text. The adjustment marker is asserted at ZERO on the SAME
  -- instrument -- which is the idempotency claim.
  -- [R11 FIX 2026-08-04 -- confirming-round Codex finding 6] AND IT IS NO LONGER MADE ON PROSE. E8's
  -- device worked by making a COMMENT SPELLING load-bearing across two migrations: D-b1 omitted
  -- the open paren so this raw-text probe would read zero. A lawful hotfix that re-created
  -- _subledger_on_approve with IDENTICAL executable SQL and one extra comment naming the hook
  -- would then have refused a correct deploy as "already applied". So this census measures the
  -- CODE, and E8's comment-spelling dependency is retired rather than merely honoured.
  -- [R12 FIX 2026-08-04 -- confirming round, Codex CXR3] ...AND THE JUDGEMENT IS NOW LEXICAL, ON THE
  -- SHARED STRIPPER, FOR ALL THREE ROWS. Round 11 used a regexp pair, which cannot tell a marker
  -- inside a STRING from an executable call (a lawful hotfix carrying the hook's name in a
  -- dollar-quoted message was REFUSED) and can span a block-comment match from inside one string
  -- literal to inside another (erasing the executable line between them). It also left an
  -- INSTRUMENT MISMATCH: this probe stripped all three rows while S5.8-b2 stripped only the
  -- absence row, so a comment naming the FA or the advance hook made this probe pass and that
  -- prestate refuse -- an apply that dies in the middle. Both now ask pg_temp._wdb_sql_code, for
  -- all three hook markers, on the same body text.
  -- THE LENGTH ASSERT IS THE INSTRUMENT'S OWN SELF-CHECK: the stripper BLANKS rather than
  -- deletes, so the code is always exactly as long as the source. A stripper that silently lost
  -- text would UNDER-count, which is the direction that admits a double apply.
  -- [R13 FIX 2026-08-04 -- re-confirming round, Codex RC3+RC4, DEPLOY-BLOCKER] ...AND THE COUNT IS NOW
  -- THE SHARED CALL MATCHER'S, ARGUMENT-BLIND AND TOKEN-AWARE, THE SAME ONE ALL FOUR INSTRUMENTS
  -- ASK. Round 12 counted an exact substring on lexed text, which was wrong in both directions:
  -- `clara._adj_on_approve/*hotfix*/(p_entry)` -- a real call, because a comment is whitespace --
  -- read ZERO here and the splice landed a second call beside it; and
  -- `clara._adj_on_approve(p_entry => p_entry)` -- the same call in named notation -- also read
  -- ZERO here while the S5.8-b2 prestate's argument-blind row read ONE, so this probe admitted an
  -- apply that prestate then refused. The roster below is the qualified NAME, without arguments,
  -- because the question is "does this body call the hook", and pg_temp._wdb_call_count is where
  -- that question is answered for every consumer in this file.
  select p.prosrc into v_def from pg_proc p
    where p.oid = 'clara._subledger_on_approve(uuid)'::regprocedure;
  v_code := pg_temp._wdb_sql_code(v_def);
  if length(v_code) <> length(v_def) then
    raise exception '0042 D-b2 probe 11: the SQL-lexical stripper returned % character(s) for a % character body -- it must BLANK comments and string literals, never delete them; a shortened result would under-count the calls below', length(v_code), length(v_def);
  end if;
  for r in select * from (values
      ('clara._fa_on_approve', 1),
      ('clara._adv_on_approve', 1),
      ('clara._adj_on_approve', 0)) as t(marker, want) loop
    v_n := pg_temp._wdb_call_count(v_code, r.marker);
    if v_n <> r.want then
      raise exception '0042 D-b2 probe 11: expected % call(s) to % in the CODE of _subledger_on_approve (comments and string literals blanked lexically; the call matched by qualified name, blind to its arguments), found % -- the SS2.6 splice anchor drifted, or D-b1 was not applied, or D-b2 has already been applied to this database', r.want, r.marker, v_n;
    end if;
  end loop;

  -- PROBE 12 IS NOT IN THIS SLICE AND IS RECORDED RATHER THAN SILENTLY DROPPED: the
  -- clara.fixed_assets NULL cost_cents prestate is D-b0's, and already SPENT -- D-b0 set that
  -- column NOT NULL, so the same query is now trivially zero and the probe could not fail. Its
  -- post-state is tail 16, D-b0's. PROBE 13 (clara.bank_line_exceptions' five resolution
  -- columns) is D-b3's, for the SS4 reopen arm this slice does not carry.

  -- [R13 FIX 2026-08-04 -- re-confirming round, Codex RC5] TEN, NOT NINE, AND THE CONVENTION IS THE ONE
  -- THE SHIPPED SLICES USE: the number after the slash is how many probes the SECTION 0 block
  -- runs (D-b0, D-b1 and D-b3 all say 0/6 and all run six). This block runs TEN -- 1, 2, 4, 5, 6,
  -- 7, 8, 9, 10, 11 -- because probe 3 and probes 12/13 are recorded as having no D-b2 form
  -- rather than silently dropped, and the recorded ones are not run. It has said nine since round
  -- 11. Counted on the file.
  raise notice '0042 D-b2 SECTION 0 probe OK (0/10): 0044_wave_d_b3_af2_composite is the applied frontier; none of the 3 adjustment relations, 3 pre-existing-table indexes, adjustment.posted event or 35 function names pre-exist; the 19 splice/call/replace subjects (including the ELEVEN the split itself created), the taxonomy singleton, the clara.clients tenancy anchor, the four-caller census and the two hook markers S5.8-b2 splices between are all present in their expected shape.';
end
$probe$;

-- #####################################################################################
-- ### SECTION S1 (D-b2 SLICE) -- DDL: 3 ADJUSTMENT RELATIONS + 3 PRE-EXISTING-TABLE INDEXES ###
-- #####################################################################################
-- [SPLIT D-b2 2026-08-04] THIS SLICE CARRIES FIVE OF SECTION S1's ELEVEN DDL BLOCKS, each at its
-- existing SS1.x boundary (census sect.4: "split s1 at its existing SS1.x boundaries -- already
-- clean"), plus the adjustment.posted HALF of SECTION EVENTS:
--   SS1.1-SS1.3 (adjustment_templates / adjustment_runs / adjustment_pair_reversals
--                and their triggers, policies and grants)      -> HERE
--   SS1.4-SS1.6 (staff_advance_accounts / staff_advances /
--                staff_advance_applications)                   -> ALREADY SHIPPED, D-b1
--   SS1.7       (ea1955_policy + its three-row EA 1955 seed)    -> ALREADY SHIPPED, D-b1
--   SS1.8       (the clara.bank_matches ALTERs + the set-once trigger) -> ALREADY SHIPPED, D-b3
--   SS1.9       (ix_je_adj_draft, ix_je_adj_occurrence)         -> HERE
--   [R12 2026-08-04] THE COUNT IN THE HEADING IS THE PRE-EXISTING-TABLE ONE, and it is named as such
--   because the two categories are easy to read as a contradiction. THREE indexes land on tables
--   that already existed (SS1.9's two hot-loop partials on clara.journal_entries and SS1.11's
--   pair-correction lookup) -- those are the three SECTION 0's probe 4 proves absent. The indexes
--   on THIS section's own three new relations are not counted there and never were: they arrive
--   with the `create table` statements that make probe 2 true, and the fix waves added two of
--   them (uq_adjustment_templates_one_successor, uq_adjustment_templates_one_live_leaf).
--   SS1.10      (auto_reversal_of + uq_je_auto_reversal_of)     -> ALREADY SHIPPED, D-b0
--   SS1.11      (ix_adj_pair_corrections)                       -> HERE
--   SECTION EVENTS -- SPLIT BY NAME: bank.line_exception_reopened shipped with D-b3,
--                adjustment.posted -> HERE. Census sect.4: "the CTE + local postcheck duplicate
--                cleanly."
--
-- SS1.9 AND SS1.11 ARE THIS SLICE'S EVEN THOUGH TWO OF THEIR THREE INDEXES SIT ON A LIVE,
-- POPULATED TABLE. ix_je_adj_draft and ix_je_adj_occurrence are PARTIAL indexes on
-- clara.journal_entries whose predicates key on `flags ? 'recurring_adjustment'` (census sect.4:
-- "SS1.9 -> D-b2, predicates key on flags ? 'recurring_adjustment'"), so before this slice they
-- would index nothing and after it they are the hot-loop the poster and the hook lean on. Both
-- are built with a plain `create index` on a table that is large but not locked for long by a
-- partial-predicate build, and neither carries a NOT NULL or a rewrite. ix_adj_pair_corrections
-- sits on this file's OWN clara.adjustment_pair_reversals, which is empty at creation.
--
-- SS1.10 IS EMPHATICALLY NOT RE-MADE HERE, AND THIS IS WHERE THAT WOULD BE EASY TO GET WRONG.
-- clara.journal_entries.auto_reversal_of is the pair-linkage column, and it is written for the
-- first time by THIS slice's clara._adj_on_approve arm (2) -- but it was CREATED by D-b0 three
-- slices ago, deliberately, because clara._wdb_reversal_blocked reads only that column and
-- shipping it early is what let D-b1 create that body (census sect.4 Option A: one dormant
-- nullable column three slices early resolves six of the twenty-two order violations). The
-- column arrives dormant and leaves this slice live; nothing in this file's DDL touches it.
--
-- ROLE SCOPING IS THIS FILE'S OWN (census hazard sect.7.4): the probe runs as the plain
-- migration role, the tables/triggers/policies/grants and the three indexes inside an explicit
-- `set role clara_fn_owner` scope this file opens and closes, and SECTION EVENTS then runs as
-- the PLAIN MIGRATION ROLE -- the same 0038:8413-8423 / 0040:2769-2776 / 0041:963-968 precedent
-- the canonical section states, kept rather than flattened.

-- #####################################################################################
-- ################## SS1.0 (D-b2 SLICE) -- THE PRE-DDL LIVE PROBE #####################
-- #####################################################################################
-- [SPLIT D-b2 2026-08-04] ONE OF SS1.0's EIGHT PROBES IS THIS SLICE'S: probe 8, the POSITIVE ANCHOR on
-- the generic guard function the three new tables' TRUNCATE triggers reuse. It is NARROWED to
-- clara._tf_no_truncate: the canonical probe asserts BOTH generic guards are present because the
-- whole unit's seven tables use both, but clara._tf_append_only is the guard
-- clara.staff_advance_applications' pure-append-only trigger binds -- D-b1's table, D-b1's
-- probe, shipped. Measured against this slice's own three tables: SS1.1, SS1.2 and SS1.3 bind
-- clara._tf_no_truncate three times and clara._tf_append_only not at all (their row guards are
-- their own named transition/immutability functions).
-- Its probes 1 (frontier), 2 (the relations), 4 (the hot-loop indexes) and 5 (the event name)
-- are made once, in SECTION 0 above -- a slice has no reason to ask the same negative question
-- twice, and D-b1 and D-b3 set that precedent. Its probes 3 (the clara.bank_matches columns),
-- 6 (that table's status CHECK) and 7 (clara.bank_line_exceptions' primary key) are about
-- objects and FK targets of D-b3's SS1.8.
-- FINAL FORM: the whole-unit SS1.0 block, reassembled across the four slices.

do $s1_probe$
declare
  v_anchor int;
begin
  -- PROBE 8 -- ANCHOR PROBE, positive: the generic guard function this section's triggers
  -- reuse is present (clara._tf_no_truncate on all three tables).
  select count(*)::int into v_anchor
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'clara' and p.proname = '_tf_no_truncate';
  if v_anchor <> 1 then
    raise exception '0042 D-b2 SS1 probe 8: clara._tf_no_truncate is not present -- the generic TRUNCATE guard this section''s three tables reuse is missing';
  end if;

  raise notice '0042 D-b2 SS1 probe OK (0/1): clara._tf_no_truncate is present. (The three new relations, the three new indexes and the new event name were probed absent in SECTION 0 probes 2, 4 and 5 above.)';
end
$s1_probe$;

set role clara_fn_owner;

-- =====================================================================================
-- SS1.1 -- clara.adjustment_templates (design SS2.1; WDB-G1/G2/G3/G4/G13). Clones
-- clara.fa_depreciation_authorities (0041:614-686) column-for-column on the propose/sign/
-- retire shape: the same three-state lifecycle, the same signed/retired PAIR checks, the
-- same transition trigger idiom (mutable-set subtraction; lawful edges proposed->live,
-- proposed->retired, live->retired; DELETE always raises). content_hash is the propose-
-- time dedup key (ABI SSA: `_hash({name, cadence, start_date, end_date, auto_reverse,
-- lines, memo_template})`, hex-encoded -- the same shape clara.bank_rules.content_hash
-- (0040:627) and every other content_hash column in this schema carries, restated here
-- rather than left as ABI's bare "content_hash text NOT NULL" so a malformed hash cannot
-- squat the partial-unique slot).
--
-- CADENCE ADMITS MONTHLY + ANNUAL ONLY (WDB-G3); start_date/end_date are period boundaries,
-- not arbitrary dates -- validated at propose/sign (S2/S3 lane, not this DDL). lines is a
-- jsonb ARRAY (ABI SSC: `[{account_code, debit_cents, credit_cents, description?}]`, >=2
-- rows, balanced to the sen) -- only the STRUCTURAL jsonb-array shape is asserted here
-- (matching the clara.fa_depreciation_runs.skipped precedent, 0041:709-710); the row-count
-- and balance laws are propose-time VERB validation, per design SS2.1 ("validated at
-- propose; re-derived at every occurrence AND at approve").
-- =====================================================================================
create table clara.adjustment_templates (
  id               uuid        primary key default gen_random_uuid(),
  firm_id          uuid        not null,
  client_id        uuid        not null,
  status           text        not null check (status in ('proposed', 'live', 'retired')),
  name             text        not null check (btrim(name) <> ''),
  cadence          text        not null check (cadence in ('monthly', 'annual')),
  start_date       date        not null,
  end_date         date,
  auto_reverse     boolean     not null,
  lines            jsonb       not null check (jsonb_typeof(lines) = 'array'),
  memo_template    text        not null,
  content_hash     text        not null check (content_hash ~ '^[0-9a-f]{64}$'),
  -- WHAT THIS TEMPLATE REPLACES, RECORDED RATHER THAN INFERRED [round 10, lane P1; the OWNER's
  -- option (b), ruled 2026-08-04 as an ADDITIVE [WDB-G13] amendment]. G13's template
  -- immutability and its retire-and-re-propose idiom are UNCHANGED -- an "edit" is still a new
  -- row -- and this column merely lets the replacement SAY which row it replaces.
  --
  -- WHY IT EXISTS AT ALL, in money. Rounds 8-10 tried three times to answer "is the standing
  -- charge in the way the generation this template replaces?" from state the schema does not
  -- hold. Round 9 read the standing writer's STATUS as the answer and was measured wrong in
  -- BOTH directions (a retired SIBLING whose only offered act erased RM6,000 of a legitimate
  -- audit accrual; the propose-then-retire click ORDER, where the status reads `live` and the
  -- doubling instruction printed anyway -- RM18,000 against an RM6,000 intention). Round 10
  -- (lane O1) deleted the inference and shipped an honest MEASURED caution, which is correct and
  -- still leaves the double reachable to a professional who reads it and re-cuts anyway. Only a
  -- RECORDED fact closes it: with this column the gate KNOWS, and the refusal can finally assert
  -- and forbid instead of cautioning. The full measurement is at clara._wdb_overlapping_siblings
  -- and clara._wdb_template_ancestry in SECTION S2.
  --
  -- SAME FIRM AND SAME CLIENT ARE STRUCTURAL, NOT A VERB'S PROMISE. The FK is the COMPOSITE one
  -- against uq_adjustment_templates_id_firm_client, the idiom clara.adjustment_runs and
  -- clara.adjustment_pair_reversals already use two screens down: a cross-client (or cross-firm)
  -- lineage claim is impossible at the storage layer, so no reader of this column has to re-check
  -- the tenancy it was written under. MATCH SIMPLE is what makes the NULL case free -- firm_id
  -- and client_id are NOT NULL, so the constraint is simply not enforced when the pointer is
  -- absent, which is the ordinary case (a first-generation template replaces nothing).
  --
  -- NOT ITSELF, AND THEREFORE NEVER A CYCLE. The CHECK is load-bearing rather than decorative: a
  -- self-referencing FK is satisfied by the row's own key, so without it `replaces_template_id =
  -- id` would INSERT cleanly. With it, plus (a) the FK's requirement that the target already
  -- exist at INSERT time and (b) the transition trigger's immutability (this column is NOT in the
  -- trigger's mutable set, so it can never be UPDATEd), the lineage graph is a DAG BY
  -- CONSTRUCTION -- every edge points at a row that was already there and no edge is ever
  -- repointed. The in-body hop cap at clara._wdb_template_ancestry is therefore a belt against a
  -- FORGED or restored graph, not against anything these verbs can build.
  --
  -- NO INDEX. MEASURED, not assumed: the only read is the gate's UPWARD walk, which follows
  -- `replaces_template_id` to `id` -- a PRIMARY KEY lookup per hop (EXPLAIN on the lane rig: Index
  -- Scan using adjustment_templates_pkey, one row). Nothing in this migration walks DOWNWARD
  -- (children of a generation), so a partial index on the column would be an index nobody probes.
  replaces_template_id uuid,
  -- WHICH LINEAGE THIS ROW BELONGS TO [R12 FIX 2026-08-04 -- confirming round, Codex CXR2].
  --
  -- NULL MEANS "I AM MY OWN ROOT", and that spelling is deliberate rather than a shortcut. A
  -- first-generation template replaces nothing, so making it point at itself would need its own
  -- id before the INSERT -- a mint this verb does not otherwise do -- and would put a
  -- self-reference on every row to say something the absence of a pointer already says. The
  -- effective root is therefore `coalesce(lineage_root_id, id)` everywhere it is asked, and the
  -- partial unique below is built on exactly that expression so the storage layer and the door
  -- can never disagree about which lineage a row is in.
  --
  -- SET AT PROPOSE, FROM THE PREDECESSOR, AND NEVER AGAIN. clara.propose_adjustment_template
  -- writes coalesce(predecessor.lineage_root_id, p_replaces) under the same 203005004 rung that
  -- validates the declaration, so a chain's whole descent carries ONE root id from its first
  -- edge onward. The column is not in the transition trigger's mutable set, so -- like
  -- replaces_template_id beside it -- it is immutable from the moment of INSERT: a root that
  -- could be repointed after the fact would be a fact the storage layer asserts on and a
  -- professional can rewrite.
  --
  -- THE FK IS THE COMPOSITE ONE, for the same reason the lineage pointer's is: a cross-client or
  -- cross-firm root is impossible at the storage layer, so no reader of this column re-checks the
  -- tenancy it was written under. MATCH SIMPLE makes the NULL case free.
  --
  -- IT IS NOT PROJECTED, MEASURED RATHER THAN ASSUMED. clara._adj_template_json carries
  -- replaces_template_id because the gate ASSERTS on that column and a professional must be able
  -- to check the claim; the root is a DERIVED grouping of the same edges and no surface acts on
  -- it. The refusal that uses it (template_lineage_root_occupied) names the live template by id
  -- in its own detail, which is the fact a reader needs.
  lineage_root_id  uuid,
  proposed_by      uuid        not null references clara.users(id),
  proposed_op_key  text        not null,
  signed_by        uuid        references clara.users(id),
  signed_at        timestamptz,
  signed_op_key    text,
  retired_by       uuid        references clara.users(id),
  retired_at       timestamptz,
  retired_reason   text,
  retired_op_key   text,
  created_at       timestamptz not null default now(),
  constraint fk_adjustment_templates_client foreign key (client_id, firm_id)
    references clara.clients(id, firm_id),
  constraint uq_adjustment_templates_id_firm_client unique (id, firm_id, client_id),
  constraint ck_adjustment_templates_end_date check (end_date is null or end_date >= start_date),
  -- The FA-authority signed/retired PAIR checks (0041:633-639), restated for templates.
  constraint ck_adjustment_templates_signed check (
    (status = 'proposed' and signed_by is null and signed_at is null)
    or (status in ('live', 'retired') and signed_by is not null and signed_at is not null)),
  constraint ck_adjustment_templates_retired check (
    (status <> 'retired' and retired_by is null and retired_at is null and retired_reason is null)
    or (status = 'retired' and retired_by is not null and retired_at is not null
        and retired_reason is not null and btrim(retired_reason) <> '')),
  -- [round 10, lane P1] The lineage pointer's two structural laws, argued at the column.
  constraint fk_adjustment_templates_replaces
    foreign key (replaces_template_id, firm_id, client_id)
    references clara.adjustment_templates(id, firm_id, client_id),
  constraint ck_adjustment_templates_replaces_not_self
    check (replaces_template_id is null or replaces_template_id <> id),
  -- [R12 FIX 2026-08-04] The root pointer's tenancy law, the same composite shape as the edge's above.
  -- There is deliberately NO not-self CHECK here: a row IS allowed to name itself as its own
  -- root (the FK is satisfied by the row's own key), which is simply the explicit spelling of
  -- the NULL default -- and forbidding it would forbid a restore that wrote roots out in full.
  constraint fk_adjustment_templates_lineage_root
    foreign key (lineage_root_id, firm_id, client_id)
    references clara.adjustment_templates(id, firm_id, client_id)
);
-- ABI SSD.1: partial unique (client_id, content_hash) WHERE status IN ('proposed','live')
-- -- the propose-time dedup slot; a retired template's content_hash is free to be reused.
create unique index uq_adjustment_templates_content
  on clara.adjustment_templates (client_id, content_hash) where status in ('proposed', 'live');
create index ix_adjustment_templates_client on clara.adjustment_templates (client_id, status);
-- [R11 FIX 2026-08-04 -- Codex round-11 finding 4, "chain multiplicity is not enforced"] ONE PREDECESSOR
-- MAY HAVE AT MOST ONE UNRETIRED SUCCESSOR, AND THE STORAGE LAYER IS WHERE THAT IS SAID.
-- MEASURED (Codex r11, two concurrent sessions): session B waited correctly behind session A's
-- 203005004 client rung and then ALSO succeeded; both children were signed; the predecessor
-- finished with TWO LIVE DIRECT SUCCESSORS. That is a lineage FORK, not a chain -- and every
-- consumer of clara._wdb_template_ancestry is written for a chain: the walk returns "the
-- ancestors" as an ordered list, propose's cap counts "generations", and the gate's prohibition
-- says "the generation this template replaces" in the singular. A fork makes each of those
-- sentences true of one branch and silent about the other, which is exactly the class of
-- half-true assertion the round-9/round-10/round-11 repairs keep deleting.
-- WHY 'proposed' IS IN THE PREDICATE AND 'retired' IS NOT. The transition trigger admits
-- proposed->live, so a rule that policed only `live` would admit two PROPOSED successors and
-- then let both sign -- the wall must stand at the door that CREATES the state (propose), which
-- is the same root-fix argument the chain-depth refusal already makes one screen down. `retired`
-- is excluded because a superseded successor is a historical fact: a professional who declares a
-- replacement, retires it, and declares another has stated two true things in sequence, and
-- forbidding that would forbid correcting a mis-declaration through the one act this file offers
-- for it (retire and re-propose -- the recovery clause the gate's own prohibition names).
-- IT IS A BELT, NOT THE DOOR. clara.propose_adjustment_template refuses this state BY NAME
-- (template_replaces_already_succeeded) under the client rung, so a human never meets this
-- index; what the index catches is the writer the rung cannot serialise -- a restored register, a
-- hand-written row, or a future door that forgets to ask. The propose body discriminates the two
-- unique_violations by CONSTRAINT NAME rather than assuming, because this table now has two.
create unique index uq_adjustment_templates_one_successor
  on clara.adjustment_templates (replaces_template_id)
  where replaces_template_id is not null and status in ('proposed', 'live');
-- [R12 FIX 2026-08-04 -- confirming round, Codex CXR2, MONEY] ...AND ONE LINEAGE HAS AT MOST ONE
-- UNRETIRED LEAF, WHICH IS THE LAW THE INDEX ABOVE ONLY APPROXIMATES.
-- MEASURED (the confirming round's P/A/B/C walk): P retired, A replaces P, A retired, B replaces
-- A and goes live, C replaces P and goes live. Every direct-child test passes -- P's only direct
-- successor A is retired -- and the lineage ends with TWO LIVE LEAVES. E30's recorded intent is
-- ONE ACTIVE CONTINUATION per lineage, and "one child per parent" cannot express it: the fork can
-- always be moved one generation up. Keyed on the ROOT it is one predicate.
-- THE KEY IS `coalesce(lineage_root_id, id)` -- the row's own id when it is its own root -- so
-- the root itself is IN this index while it is unretired. That is not an accident: a live
-- predecessor with a live successor is the same "two active continuations" state one hop down,
-- and the propose door refuses it separately (template_replaces_not_retired) for the same reason.
-- NO client_id IN THE KEY, and it is not an omission: the composite FK above forces a root to
-- belong to the row's own client, and a root id is a primary key, so the expression is already
-- globally unique per lineage. A (client_id, expr) key would be strictly WEAKER.
-- IT DOES NOT REPLACE THE INDEX ABOVE. A hand-written or restored row can carry a replaces_ edge
-- with a wrong (or absent) root, which this index would not see and that one still refuses. Two
-- belts, two different forgeries; the propose body discriminates all three unique_violations on
-- this table by CONSTRAINT NAME rather than assuming which one bit.
create unique index uq_adjustment_templates_one_live_leaf
  on clara.adjustment_templates ((coalesce(lineage_root_id, id)))
  where status in ('proposed', 'live');

-- THE TRANSITION TRIGGER -- the 0041:649-663 `_tf_fa_authority_transition` idiom, cloned
-- verbatim onto the template shape (mutable-set subtraction; the frozen set is exactly the
-- eight lifecycle-stamp columns; every other column -- name, cadence, start_date, end_date,
-- auto_reverse, lines, memo_template, content_hash, replaces_template_id, proposed_by/op_key,
-- firm/client/id, created_at -- is immutable from the moment of INSERT). THE SUBTRACTION IS WHY
-- THE ALLOWSET NEEDED NO EDIT WHEN THE LINEAGE COLUMN ARRIVED [round 10, lane P1], and that is
-- the point of spelling immutability as "everything except this named set" rather than as a
-- per-column comparison: a column added to this table is immutable BY DEFAULT, and an author who
-- wants it mutable has to say so out loud in v_frozen. replaces_template_id is deliberately left
-- OUT of that set -- a recorded lineage that could be repointed after the fact would be a fact
-- the gate asserts on and a professional can rewrite, which is worse than no fact at all.
-- Lawful edges: proposed->live,
-- proposed->retired, live->retired (WDB-G1..G4's whole propose/sign/retire lifecycle);
-- anything else, including a same-status no-op UPDATE, raises. DELETE always raises,
-- folded into this one function (the FA precedent's own shape).
create function clara._tf_adjustment_template_transition() returns trigger
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare v_frozen text[] := array['status', 'signed_by', 'signed_at', 'signed_op_key',
  'retired_by', 'retired_at', 'retired_reason', 'retired_op_key'];
begin
  if tg_op = 'DELETE' then
    raise exception 'an adjustment template is retired, never deleted'
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'adjustment_template_never_deleted', 'template_id', old.id)::text;
  end if;
  if (to_jsonb(new) - v_frozen) is distinct from (to_jsonb(old) - v_frozen) then
    raise exception 'an adjustment template is immutable outside its sign/retire transitions'
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'adjustment_template_immutable', 'template_id', old.id)::text;
  end if;
  if (old.status = 'proposed' and new.status in ('live', 'retired'))
     or (old.status = 'live' and new.status = 'retired') then
    return new;
  end if;
  raise exception 'adjustment template transition % -> % is not lawful', old.status, new.status
    using errcode = 'CLR38',
      detail = jsonb_build_object('reason', 'adjustment_template_transition_illegal',
        'template_id', old.id, 'from_status', old.status, 'to_status', new.status)::text;
end $$;
revoke all on function clara._tf_adjustment_template_transition() from public;
create trigger t_adjustment_templates_transition before delete or update
  on clara.adjustment_templates
  for each row execute function clara._tf_adjustment_template_transition();
create trigger t_adjustment_templates_no_truncate before truncate
  on clara.adjustment_templates for each statement execute function clara._tf_no_truncate();

-- =====================================================================================
-- ...AND THE ROOT A ROW CLAIMS IS PROVEN, NOT TRUSTED [R13 FIX 2026-08-04 -- re-confirming round,
-- Codex RC1, MONEY].
-- =====================================================================================
-- THE INDEX ABOVE IS ONLY AS TRUE AS THE COLUMN IT IS KEYED ON, and until this trigger nothing
-- made the column true. clara.propose_adjustment_template writes the inherited root correctly --
-- and the propose door is not the writer either lineage belt exists for. Its own comment says so:
-- "what the index catches is the writer the rung cannot serialise -- a restored register, a
-- hand-written row, or a future door that forgets to ask". THAT writer may put ANY value in
-- lineage_root_id, and a row which declares a predecessor while carrying a false root -- or no
-- root at all -- is keyed into a DIFFERENT bucket of uq_adjustment_templates_one_live_leaf. The
-- lineage then has two unretired leaves again, which is CXR2's measured double restored through
-- the very belt that closed it.
--
-- THE LAW, IN FULL, AND IT IS THE ONE THE COLUMN'S OWN COMMENT ALREADY STATES:
--   * a row that DECLARES A PREDECESSOR inherits that predecessor's effective root, and nothing
--     else: lineage_root_id = coalesce(parent.lineage_root_id, parent.id);
--   * a row that declares NO predecessor is its own root, spelled either as NULL (the canonical
--     spelling, and the only one the door writes) or as its own id (the explicit spelling a
--     restore that wrote roots out in full would carry -- which the composite FK deliberately
--     admits, and which this trigger therefore must too). Any OTHER value names a lineage this
--     row has no edge into.
--
-- WHY A CONSTRAINT TRIGGER AND NOT A CHECK OR A FOREIGN KEY. A CHECK may not read another row,
-- and this law is an equality between two rows. The composite FK already proves the root EXISTS
-- and belongs to this client -- it cannot prove it is the RIGHT one. A constraint trigger is the
-- only structure in Postgres that states "this row's column equals a value derived from another
-- row".
-- IT IS DEFERRABLE INITIALLY IMMEDIATE, AND THE REASON GIVEN HERE USED TO BE FALSE [R14 FIX 2026-08-04 --
-- second re-confirming round, N13-7]. The sentence claimed the deferrability lets "a restore load
-- a whole lineage inside one transaction and be checked at its end rather than row by row". It
-- cannot: MEASURED on the rig, ALL SIX foreign keys on this table report condeferrable = false
-- (the schema has 344 FKs and exactly six deferrable ones, none of them here), so a restore must
-- insert every parent before its child no matter what this trigger does -- the out-of-order load
-- the sentence described is refused one constraint earlier. What deferrability actually buys is
-- HEADROOM: a future maintenance transaction that has a reason to reorder these rows can ask for
-- it explicitly, and asking costs nothing today. The half of the old sentence that WAS measured
-- true is kept, because it is the half that matters: deferring never SKIPS the check.
--
-- IT SAYS NOTHING WHEN THE PARENT ROW IS NOT THERE, and that is deliberate rather than a hole.
-- Existence is the composite FK's job. The one shape that reaches this body with a missing parent
-- is a partial restore that dropped the FK (the shape x42.r11f stages), and for that row there IS
-- no parent root to inherit -- the honest verdict is clara._wdb_template_ancestry's `truncated`,
-- which the propose door already refuses to extend. Inventing a refusal here would refuse the
-- forensic state instead of the forgery.
--
-- SECURITY DEFINER FOR THE LOOKUP, NOT FOR THE WRITE. clara.adjustment_templates carries FORCE
-- RLS, so the parent read must run as an owner or a writer in another role would see no parent
-- row and this belt would pass by blindness -- the fail-OPEN direction, in a body whose whole
-- job is to fail closed.
create function clara._tf_adjustment_template_lineage_root() returns trigger
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare v_want uuid;
begin
  if new.replaces_template_id is null then
    if new.lineage_root_id is not null and new.lineage_root_id <> new.id then
      raise exception 'this template declares no predecessor, so it is its own lineage root -- lineage_root_id may be null or its own id, and it names % instead', new.lineage_root_id
        using errcode = 'CLR38',
          detail = jsonb_build_object('reason', 'adjustment_template_lineage_root_false',
            'axis', 'parentless', 'template_id', new.id,
            'lineage_root_id', new.lineage_root_id, 'expected_lineage_root_id', new.id)::text;
    end if;
    return null;
  end if;
  select coalesce(t.lineage_root_id, t.id) into v_want
    from clara.adjustment_templates t where t.id = new.replaces_template_id;
  if not found then
    return null;
  end if;
  if new.lineage_root_id is distinct from v_want then
    raise exception 'this template declares % as its predecessor, so its lineage root is % -- it carries % instead, which would put it in a different lineage from the generation it claims to continue', new.replaces_template_id, v_want, coalesce(new.lineage_root_id::text, 'no root at all')
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'adjustment_template_lineage_root_false',
          'axis', 'inherited', 'template_id', new.id,
          'replaces_template_id', new.replaces_template_id,
          'lineage_root_id', new.lineage_root_id, 'expected_lineage_root_id', v_want)::text;
  end if;
  return null;
end $$;
revoke all on function clara._tf_adjustment_template_lineage_root() from public;
create constraint trigger t_adjustment_templates_lineage_root
  after insert or update on clara.adjustment_templates
  deferrable initially immediate
  for each row execute function clara._tf_adjustment_template_lineage_root();

alter table clara.adjustment_templates enable row level security;
alter table clara.adjustment_templates force row level security;
create policy p_adjustment_templates_owner on clara.adjustment_templates
  for all to clara_fn_owner using (true) with check (true);
create policy p_adjustment_templates_human on clara.adjustment_templates
  for select to clara_authenticated using (firm_id = clara.jwt_firm());
grant select on clara.adjustment_templates to clara_authenticated;

-- =====================================================================================
-- SS1.2 -- clara.adjustment_runs (design SS2.5; ABI SSD.2). RECEIPTS, MINTED AT APPROVE,
-- the clara.fa_depreciation_runs (0041:699-757) shape restated for the occurrence poster:
-- FULLY immutable (no mutable-column carve-out at all -- contrast the templates' transition
-- trigger above), one receipt per entry, no-delete, no-truncate.
--
-- DELIBERATELY NO (template_id, period) UNIQUENESS (design SS2.5, matching the FA runs
-- table's own comment at 0041:692-693 almost verbatim): a corrected re-run after a pair
-- reversal or a solo `reverse_entry` lawfully mints a SECOND receipt for the same period,
-- and a uniqueness index here would deadlock the ramp-reset sweep against its own
-- correction door.
-- =====================================================================================
create table clara.adjustment_runs (
  id                uuid        primary key default gen_random_uuid(),
  firm_id           uuid        not null,
  client_id         uuid        not null,
  template_id       uuid        not null,
  period_start      date        not null,
  period_end        date        not null,
  mode              text        not null check (mode in ('post', 'draft')),
  entry_id          uuid        not null,
  reversal_entry_id uuid,
  amount_cents      bigint      not null check (amount_cents > 0),
  op_key            text        not null,
  created_at        timestamptz not null default now(),
  constraint fk_adjustment_runs_client foreign key (client_id, firm_id)
    references clara.clients(id, firm_id),
  constraint fk_adjustment_runs_template foreign key (template_id, firm_id, client_id)
    references clara.adjustment_templates(id, firm_id, client_id),
  constraint fk_adjustment_runs_entry foreign key (entry_id, firm_id, client_id)
    references clara.journal_entries(id, firm_id, client_id),
  constraint fk_adjustment_runs_reversal_entry foreign key (reversal_entry_id, firm_id, client_id)
    references clara.journal_entries(id, firm_id, client_id),
  constraint uq_adjustment_runs_id_firm_client unique (id, firm_id, client_id),
  constraint ck_adjustment_runs_period check (period_start <= period_end)
);
-- ONE RECEIPT PER ENTRY (the 0041:724 1:1 precedent).
create unique index uq_adjustment_runs_entry on clara.adjustment_runs (entry_id);
-- The issuer's op key is the receipt's second identity (0041:725-726); a replay cannot
-- mint a twin.
create unique index uq_adjustment_runs_op_key on clara.adjustment_runs (firm_id, op_key);
create index ix_adjustment_runs_client on clara.adjustment_runs (client_id, period_end desc);
create index ix_adjustment_runs_template on clara.adjustment_runs (template_id, period_end desc);

create function clara._tf_adjustment_run_immutable() returns trigger
  language plpgsql security definer set search_path = clara, pg_temp as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'an adjustment run receipt is never deleted (reverse its entry)'
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'adjustment_run_never_deleted', 'run_id', old.id)::text;
  end if;
  raise exception 'an adjustment run receipt is immutable (reverse its entry and re-run)'
    using errcode = 'CLR38',
      detail = jsonb_build_object('reason', 'adjustment_run_immutable', 'run_id', old.id)::text;
end $$;
revoke all on function clara._tf_adjustment_run_immutable() from public;
create trigger t_adjustment_runs_immutable before delete or update on clara.adjustment_runs
  for each row execute function clara._tf_adjustment_run_immutable();
create trigger t_adjustment_runs_no_truncate before truncate
  on clara.adjustment_runs for each statement execute function clara._tf_no_truncate();

alter table clara.adjustment_runs enable row level security;
alter table clara.adjustment_runs force row level security;
create policy p_adjustment_runs_owner on clara.adjustment_runs
  for all to clara_fn_owner using (true) with check (true);
create policy p_adjustment_runs_human on clara.adjustment_runs
  for select to clara_authenticated using (firm_id = clara.jwt_firm());
grant select on clara.adjustment_runs to clara_authenticated;

-- =====================================================================================
-- SS1.3 -- clara.adjustment_pair_reversals (design SS2.4; ABI SSD.3; WDB-G1/G2). The
-- sanctioned machine for correcting an auto-reverse occurrence/mirror PAIR: both
-- correction mirrors are born together (occurrence_correction_id, mirror_correction_id
-- both NOT NULL from INSERT -- the receipt is inserted `pending` with both ids AFTER
-- `_pair_reverse_core` births the drafts, per design SS2.4), then the receipt is the
-- AUTHORIZATION CHANNEL a defense-in-depth hook arm and `revise_entry`/`withdraw_draft`
-- both consult before letting either half move.
--
-- TWO INDEPENDENT GUARD MECHANISMS, matching the design's split between an ORDINARY
-- transition (immediate, mutable-set subtraction, the 0041:649-663 idiom) and a DEFERRED
-- constraint that polices what the transaction is allowed to COMMIT (the 0038:~3255
-- re-query-by-id idiom): a same-transaction pending->approving->completed run is lawful and
-- must not be refused by a naive NEW-tuple read of a queued-but-superseded snapshot.
-- =====================================================================================
create table clara.adjustment_pair_reversals (
  id                        uuid        primary key default gen_random_uuid(),
  firm_id                   uuid        not null,
  client_id                 uuid        not null,
  template_id               uuid        not null,
  occurrence_id             uuid        not null,
  mirror_id                 uuid        not null,
  occurrence_correction_id  uuid        not null,
  mirror_correction_id      uuid        not null,
  maker                     uuid        not null references clara.users(id),
  status                    text        not null check (status in ('pending', 'approving', 'completed', 'cancelled')),
  completed_at              timestamptz,
  op_key                    text        not null,
  created_at                timestamptz not null default now(),
  constraint fk_adjustment_pair_reversals_client foreign key (client_id, firm_id)
    references clara.clients(id, firm_id),
  constraint fk_adjustment_pair_reversals_template foreign key (template_id, firm_id, client_id)
    references clara.adjustment_templates(id, firm_id, client_id),
  constraint fk_adjustment_pair_reversals_occurrence foreign key (occurrence_id, firm_id, client_id)
    references clara.journal_entries(id, firm_id, client_id),
  constraint fk_adjustment_pair_reversals_mirror foreign key (mirror_id, firm_id, client_id)
    references clara.journal_entries(id, firm_id, client_id),
  constraint fk_adjustment_pair_reversals_occurrence_correction
    foreign key (occurrence_correction_id, firm_id, client_id)
    references clara.journal_entries(id, firm_id, client_id),
  constraint fk_adjustment_pair_reversals_mirror_correction
    foreign key (mirror_correction_id, firm_id, client_id)
    references clara.journal_entries(id, firm_id, client_id),
  constraint uq_adjustment_pair_reversals_id_firm_client unique (id, firm_id, client_id),
  -- completed_at is stamped EXACTLY on the approving->completed edge (design SS2.4: "the
  -- ramp clock's timestamp"); every other status carries it null.
  constraint ck_adjustment_pair_reversals_completed
    check ((status = 'completed') = (completed_at is not null))
);
-- ONE ACTIVE PAIR PER OCCURRENCE (ABI SSD.3). Historical completed/cancelled rows for the
-- same occurrence accumulate freely -- a cancelled attempt can be retried, and a completed
-- correction's history is never pruned.
create unique index uq_adjustment_pair_reversals_occurrence_active
  on clara.adjustment_pair_reversals (occurrence_id) where status in ('pending', 'approving');
create index ix_adjustment_pair_reversals_client on clara.adjustment_pair_reversals (client_id, status);
create index ix_adjustment_pair_reversals_template on clara.adjustment_pair_reversals (template_id, created_at);

-- THE IMMEDIATE TRANSITION TRIGGER. Mutable set = {status, completed_at} ONLY (ABI SSD.3);
-- every other column -- template_id, occurrence_id, mirror_id, both correction ids, maker,
-- op_key, firm/client/id, created_at -- is immutable from INSERT. Lawful edges:
-- pending->approving, approving->completed, pending->cancelled; DELETE always raises.
create function clara._tf_adjustment_pair_reversal_transition() returns trigger
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare v_mutable text[] := array['status', 'completed_at'];
begin
  if tg_op = 'DELETE' then
    raise exception 'an adjustment pair reversal receipt is never deleted'
      using errcode = 'CLR39',
        detail = jsonb_build_object('reason', 'adjustment_pair_reversal_never_deleted', 'pair_id', old.id)::text;
  end if;
  if (to_jsonb(new) - v_mutable) is distinct from (to_jsonb(old) - v_mutable) then
    raise exception 'an adjustment pair reversal receipt is immutable outside its status/completed_at transitions'
      using errcode = 'CLR39',
        detail = jsonb_build_object('reason', 'adjustment_pair_reversal_immutable', 'pair_id', old.id)::text;
  end if;
  if (old.status = 'pending' and new.status = 'approving')
     or (old.status = 'approving' and new.status = 'completed')
     or (old.status = 'pending' and new.status = 'cancelled') then
    return new;
  end if;
  raise exception 'adjustment pair reversal transition % -> % is not lawful', old.status, new.status
    using errcode = 'CLR39',
      detail = jsonb_build_object('reason', 'adjustment_pair_reversal_transition_illegal',
        'pair_id', old.id, 'from_status', old.status, 'to_status', new.status)::text;
end $$;
revoke all on function clara._tf_adjustment_pair_reversal_transition() from public;
create trigger t_adjustment_pair_reversals_transition before delete or update
  on clara.adjustment_pair_reversals
  for each row execute function clara._tf_adjustment_pair_reversal_transition();

-- THE DEFERRED, RE-QUERY-BY-ID CONSTRAINT TRIGGER (the 0038:~3255 idiom, restated: "the
-- NEW tuple is a snapshot of the row as it was when the trigger was QUEUED; a LATER
-- statement in the SAME transaction may have already moved it"). Reading NEW.status here
-- would refuse every lawful pending->approving->completed run that lands inside one
-- transaction (the exact low-stakes `reverse_adjustment_pair` shape design SS2.4
-- describes), because the completing UPDATE queues its own copy of this trigger AFTER the
-- approving UPDATE's copy already fired. Only a row RE-QUERIED at commit tells the truth:
-- 'approving' is a transient in-transaction waypoint (the high-stakes park, awaiting
-- `approve_pair_reversal`/`cancel_pair_reversal` in a LATER transaction) and must never be
-- the state a transaction actually COMMITS.
create function clara._tf_adjustment_pair_reversal_no_commit_approving() returns trigger
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare v_status text;
begin
  select p.status into v_status from clara.adjustment_pair_reversals p where p.id = new.id;
  if v_status is null then return null; end if;
  if v_status = 'approving' then
    raise exception 'adjustment pair reversal % committed in the approving state -- approving is a transient in-transaction waypoint, never a resting one', new.id
      using errcode = 'CLR39',
        detail = jsonb_build_object('reason', 'adjustment_pair_reversal_approving_uncommitted', 'pair_id', new.id)::text;
  end if;
  return null;
end $$;
revoke all on function clara._tf_adjustment_pair_reversal_no_commit_approving() from public;
create constraint trigger t_adjustment_pair_reversals_no_commit_approving
  after insert or update on clara.adjustment_pair_reversals
  deferrable initially deferred
  for each row execute function clara._tf_adjustment_pair_reversal_no_commit_approving();

create trigger t_adjustment_pair_reversals_no_truncate before truncate
  on clara.adjustment_pair_reversals for each statement execute function clara._tf_no_truncate();

alter table clara.adjustment_pair_reversals enable row level security;
alter table clara.adjustment_pair_reversals force row level security;
create policy p_adjustment_pair_reversals_owner on clara.adjustment_pair_reversals
  for all to clara_fn_owner using (true) with check (true);
create policy p_adjustment_pair_reversals_human on clara.adjustment_pair_reversals
  for select to clara_authenticated using (firm_id = clara.jwt_firm());
grant select on clara.adjustment_pair_reversals to clara_authenticated;

-- =====================================================================================

-- [SPLIT D-b2 2026-08-04] SS1.4-SS1.8 STAND HERE IN THE WHOLE UNIT AND ARE NOT IN THIS SLICE: the four
-- staff-advance / EA-1955 blocks shipped with D-b1 and the clara.bank_matches ALTERs with D-b3.
-- What follows is SS1.9, at its own boundary, unedited.
-- =====================================================================================
-- SS1.9 -- THE TWO HOT-LOOP PARTIAL INDEXES (ABI SSC, byte-exact; the D-a F10 measured
-- law -- 0041:781-787's ix_journal_entries_fa_disposal_draft restated for the occurrence
-- poster's own per-client hot loop, both the outstanding-draft predicate
-- (`_adj_occurrence_outstanding`) and the ramp's per-(template,period) lookup).
-- =====================================================================================
create index ix_je_adj_draft on clara.journal_entries (client_id)
  where status = 'draft' and flags ? 'recurring_adjustment';
create index ix_je_adj_occurrence on clara.journal_entries (
    (flags -> 'recurring_adjustment' ->> 'template_id'),
    (flags -> 'recurring_adjustment' ->> 'period_start'))
  where flags ? 'recurring_adjustment';


-- [SPLIT D-b2 2026-08-04] SS1.10 STANDS HERE IN THE WHOLE UNIT AND IS NOT IN THIS SLICE:
-- clara.journal_entries.auto_reversal_of and uq_je_auto_reversal_of shipped with D-b0 (census
-- sect.4 Option A). This slice is the one that finally WRITES that column -- SECTION S2's hook
-- arm (2) stamps it on the auto-reversal mirror -- but it does not create it. What follows is
-- SS1.11, at its own boundary, unedited.
-- SS1.11 -- the pair-receipt correction-id lookup index (SECTION S2's hook arm (1) probes
-- clara.adjustment_pair_reversals by occurrence_correction_id OR mirror_correction_id on
-- EVERY reversal approval; ABI SSD.3 specifies only the partial unique on occurrence_id,
-- so without this the defense arm sequential-scans the receipt table on every reversal
-- approval in the system -- the same D-a F10 class of miss the two indexes above close).
create index ix_adj_pair_corrections on clara.adjustment_pair_reversals
  (occurrence_correction_id, mirror_correction_id);

reset role;

-- #####################################################################################
-- ############ SECTION EVENTS (D-b2 SLICE) -- adjustment.posted ######################
-- #####################################################################################
-- [SPLIT D-b2 2026-08-04] THE adjustment.posted HALF. The canonical block registers TWO names in one
-- CTE; census sect.4 adjudicates the split ("the CTE + local postcheck duplicate cleanly") and
-- this file carries the ADJUSTMENT name only -- bank.line_exception_reopened is the AF-2 reopen
-- arm's fact and shipped with its emitter, in D-b3. The CTE's SHAPE is unchanged (the same
-- values/insert/insert-select/cross-join clara.taxonomy_active chain, the 0041:978-996 idiom);
-- what is narrowed is its VALUES list, and with it the postcheck's three counts, from 2 to 1.
-- A copied-unchanged block would try to insert a name that already exists and die on a naked
-- unique violation, which is precisely what SECTION 0's probe 5 was narrowed to keep readable.
-- FINAL FORM: the whole-unit SECTION EVENTS block, reassembled across D-b3 and here.
-- ROLE NOTE (0038:8413-8423 / 0040:2769-2776 / 0041:963-968 precedent): clara.event_types
-- and clara.trigger_taxonomy are migration-owned; this section runs as the PLAIN MIGRATION
-- ROLE, between SS1's clara_fn_owner close (above) and whatever later section next needs
-- `set role clara_fn_owner` re-opened for its own DDL/splices.
--
-- TWO NAMES (contrast 0040/0041's larger batches): adjustment.posted is the one new
-- occurrence-poster fact (design SS2.5; ABI SSG) and bank.line_exception_reopened is the
-- AF-2 post-flip-unmatch fact (design SS4). Both CLIENT-SCOPED, both decision 'ignore' --
-- /rules and /bank read the underlying tables directly, the same 0040/0041 bank/asset-kind
-- reasoning restated. Payloads carry IDENTIFIERS + the receipt's already-public totals ONLY
-- (ABI SSG); the payload-key allowlist scan against these two names is a SECTION TAIL
-- deliverable, not this section's.

with added(name, client_scoped, description, decision, note) as (values
  ('adjustment.posted', true,
    'A recurring/reversing adjustment template occurrence was materialised at entry approval',
    'ignore', null::text)
), inserted_types as (
  insert into clara.event_types(name, client_scoped, description)
  select name, client_scoped, description from added returning name
)
insert into clara.trigger_taxonomy(version, event_type, decision, note)
select a.version, x.name, x.decision, x.note
from added x
join inserted_types i on i.name = x.name
cross join clara.taxonomy_active a;

-- LOCAL POSTCHECK (the 0040 SS3-probe-6 style, reproduced downstream of the write instead
-- of upstream of it, since THIS section is the registrar rather than a later consumer of
-- someone else's prior registration). Confirms only that THIS section's own INSERT landed
-- in the shape it claims -- both names in event_types, exactly one active-taxonomy row
-- apiece, decision 'ignore'. SECTION TAIL re-asserts this against the WHOLE migration's
-- emission sites (the poster + the reopen arm, sections this lane cannot see); this probe
-- is narrower on purpose.
-- [SPLIT D-b2 2026-08-04] NARROWED WITH THE CTE ABOVE: one name, so all three counts drop from 2
-- to 1. The comment above says "both names ... exactly one active-taxonomy row apiece", which is
-- the WHOLE UNIT's claim; this slice registers the second of the two and says so rather than
-- leaving a count that quietly passes for the wrong reason. Tail 14 below makes the reassembled
-- claim about BOTH names, because by then both exist.
do $s1_events_check$
declare v_types int; v_rows int; v_bad int;
begin
  select count(*)::int into v_types from clara.event_types
    where name = 'adjustment.posted';
  if v_types <> 1 then
    raise exception '0042 SS1 events postcheck (D-b2 slice): the new event type did not land in clara.event_types'
      using errcode = 'CLR10';
  end if;
  select count(*)::int into v_rows from clara.trigger_taxonomy tt
    join clara.taxonomy_active a on a.version = tt.version
    where tt.event_type = 'adjustment.posted';
  if v_rows <> 1 then
    raise exception '0042 SS1 events postcheck (D-b2 slice): expected exactly 1 active trigger_taxonomy row for the new event type, found %', v_rows
      using errcode = 'CLR10';
  end if;
  select count(*)::int into v_bad from clara.trigger_taxonomy tt
    join clara.taxonomy_active a on a.version = tt.version
    where tt.event_type = 'adjustment.posted'
      and tt.decision <> 'ignore';
  if v_bad <> 0 then
    raise exception '0042 SS1 events postcheck (D-b2 slice): the new event type landed with a decision other than ''ignore'''
      using errcode = 'CLR10';
  end if;
  raise notice '0042 SS1 events OK (D-b2 slice): adjustment.posted registered in event_types and active-taxonomy at decision ''ignore''; bank.line_exception_reopened was D-b3''s half of this block.';
end
$s1_events_check$;

-- SS1 END. Role is the plain migration role on exit (matching 0041's own exit posture at
-- its SECTION EVENTS boundary) -- the next section, if it needs clara_fn_owner, opens its
-- own `set role clara_fn_owner;` scope, exactly the 0041 SS1/SS2 precedent.

-- #####################################################################################
-- ###### SECTION S2 (D-b2 SLICE) -- THE ADJUSTMENT FAMILY, THE REMAINDER #############
-- #####################################################################################
-- [SPLIT D-b2 2026-08-04] THIRTY-FIVE OF SECTION S2's FORTY-TWO NEW BODIES LAND HERE, plus the
-- FULL-FORM RE-CREATE of a thirty-sixth. Census sect.8's D-b2 bullet: "s2 REMAINDER (42 fns
-- minus the 6 fragments lifted above)" + "Full-form re-create of clara._wdb_rerun_breach
-- (adjustment arm restored)". What was lifted OUT of this section, and where each went, in the
-- order the canonical file creates them:
--   * clara._acct_role_reserved            (s2 L45-94)      -> D-b0 (FA-only shell), COMPLETED
--                                                              by D-b1 with its advance arms
--                                                              (census sect.2 Class B)
--   * clara._assert_due_read_ctx           (s2 L96-164)     -> D-b0 (Class A: zero deps)
--   * clara._wdb_period_stamps +
--     clara._wdb_correction_posting_date   (s2 L166-298)    -> D-b0 (Class A)
--   * clara._wdb_iso_date_supported        (s2 L300-332)    -> D-b0 (Class A)
--   * clara._adj_line_eligibility_breach   (s2 L420-476)    -> D-b0 (Class A)
--   * clara._wdb_suggestion_rule_hit +
--     clara._wdb_suggestion_lines          (s2 L3417-3482)  -> D-b3 (Class A: their real family)
--   * clara._wdb_reversal_blocked          (s2 L4367-4455)  -> D-b1 (census sect.8's D-b1 map;
--                                                              it reads only
--                                                              journal_entries.auto_reversal_of,
--                                                              which D-b0 shipped early)
-- ALL SEVEN ARE CALLED FROM THIS FILE AND NONE IS RE-CREATED HERE. That is the point of the
-- misfiling repair: one body per question, reached by every family's door, rather than three
-- copies that can drift. SECTION 0's probe 7 pins every one of them as a [SPLIT-CREATED] anchor
-- (errata E9) precisely because plpgsql resolves these calls at EXECUTION and nothing at CREATE
-- time would notice an absence.
--
-- clara._wdb_rerun_breach IS THE ONE BODY THIS SLICE RE-CREATES RATHER THAN CREATES, and the
-- reason is census sect.2 Class D. D-b0 needed the ONE re-run gate for its own two callers
-- (clara._fa_oldest_unmet_period at S5.15c and clara._fa_run_period_core at S5.15d), and both
-- pass only p_stamp='depreciation_charges' -- so D-b0 shipped the body with its TWO FIXED-ASSET
-- ARMS byte-exact and, in place of the adjustment arm, the same "registered stamp with no books
-- arm" refusal any unclaimed stamp takes: narrowed, never weakened, failing CLOSED. The
-- adjustment arm reads clara.journal_entries under the recurring_adjustment stamp and
-- clara.adjustment_templates for its remedy, and calls clara._wdb_entry_shape,
-- clara._wdb_shape_overlap, clara._adj_correction_door, clara._wdb_overlapping_siblings and
-- clara._wdb_template_ancestry -- six D-b2 objects. This file restores it by re-creating the
-- WHOLE body in its canonical form, so the two FA arms are once again the canonical text rather
-- than a copy of it, and the gate every re-run in both lanes passes is one body again.
--
-- ONE STATEMENT THIS SECTION SHIPS HAS NO CANONICAL SITE, and it is the confirming round's, not
-- the census's: S2.9-b3 below grants clara.accept_bank_rule_suggestion to clara_authenticated.
-- In the whole unit that grant is part of SECTION S4's own ACL loop and lands with the verb at
-- D-b3; the confirming round measured that the verb's SECOND account-role door
-- (clara._adj_on_approve arm (3), a body THIS file creates) does not exist at the 0044 frontier
-- and that a reachable producer there mints a PHANTOM STAFF ADVANCE every instrument ties over.
-- So D-b3 creates, revokes-from-public and owns the verb, and the grant waits for the wall.
-- See S2.9-b3's own header for the probed sequence; the four-slice ACL end state is unchanged.
--
-- WHAT THIS FILE DOES NOT DO: it does not build the round-11 fix list. Those findings
-- (ladder-r11-record.md) are recorded against this family and belong to D-b2's OWN hold-ladder;
-- the canonical sections predate them, so a faithful extraction leaves them out by construction.
-- Nothing below has been "improved".
--
-- ROLE SCOPING IS THIS FILE'S OWN (census hazard sect.7.4). In the whole unit this section
-- opened `set role clara_fn_owner` at its L39 and NEVER reset -- SECTION S3 then relied on that
-- role for its first 2,650 lines, and the closing comment at the section's end says so in as
-- many words. This slice opens the same scope at the same place and CLOSES it at the end of the
-- file (see that comment's own site below), so nothing downstream inherits a role by accident.

-- #####################################################################################
-- ############ SECTION S2 -- THE ADJUSTMENT FAMILY (design SS2, WD-R8/R9) #############
-- #####################################################################################
-- FUNCTIONS ONLY. The seven relations, their belts, the two hot-loop partial indexes and
-- the event/taxonomy registrations are SECTION S1 / SECTION EVENTS; this section is the
-- behaviour that rides them and it names every table by its ABI SSD name.
--
-- WHAT LIVES HERE, IN FILE ORDER:
--   S2.0  the shared account-role reservation reader (SS2.1) + the small period/hash/line
--         primitives every verb below shares, including clara._wdb_iso_date_supported --
--         the ONE statement of which dates the period-stamp grammar can carry (round 8).
--   S2.1  clara._adj_occurrence_outstanding -- blocked(template), the 0041:1301 shape.
--   S2.1a the account line-shape (clara._wdb_line_shape / clara._wdb_entry_shape), the
--         COLLISION test over two of them (clara._wdb_shape_overlap, round 8) and the ONE
--         correction-door authority the gate's remedy and the run receipt's `correctable`
--         both read (clara._adj_correction_door, round 8).
--   S2.1b clara._wdb_rerun_breach -- the ONE re-run gate, both lanes (rounds 5-8).
--   S2.2  the template family: propose -> sign -> retire (SS2.2; WD-R8/R9).
--   S2.3  the poster: clara._adj_run_occurrence_core + the two twins (SS2.3).
--   S2.4  the due oracle clara.adjustment_run_due (SS2.3).
--   S2.5  the approve-time hook clara._adj_on_approve -- arms (0)(1)(2)(3) (SS2.6, SS5).
--   S2.6  the auto-reversal PAIR machine (SS2.4).
--   S2.7  clara._wdb_reversal_blocked -- reverse_entry's 7th splice body (SS2.4, SS3.3).
--   S2.8  the READ RPCs behind the /rules panel (SS2.8): list_adjustment_templates,
--         list_adjustment_runs, get_adjustment_run + their two shared projections.
--   S2.9  grants / revokes.
--
-- THE ONE MATERIALISATION MOMENT [WDB-G1, SS2.3/SS2.6]. The poster writes a DRAFT carrying
-- a flags PROPOSAL and nothing else -- no receipt, no mirror, no event. Every durable
-- consequence is minted by clara._adj_on_approve inside the approving transaction, which is
-- why a draft that is withdrawn, revised away or simply abandoned leaves the register, the
-- receipts table and the event log exactly as it found them.
--
-- THE DIRECT INSERT IS THE RATIFIED SHAPE (SS9.5; the 0037 allocate_receipt / 0041 poster
-- precedent). clara._draft_entry_core carries no flags column and is NEVER widened: proposal
-- authenticity in this product is structural (origin + a durable op-receipt whose request
-- hash re-derives from the client, template and period), not conventional.

set role clara_fn_owner;

-- =====================================================================================
-- S2.0 -- THE SHARED READER + THE SMALL PRIMITIVES.
-- =====================================================================================


-- [SPLIT D-b2 2026-08-04] THE FIVE S2.0 PRIMITIVES CENSUS SECT.2 CLASS A MOVED TO D-b0 STAND HERE IN
-- THE WHOLE UNIT AND ARE NOT RE-CREATED: clara._acct_role_reserved (the shared reservation
-- reader -- shipped FA-only by D-b0 and COMPLETED with its advance arms by D-b1, which is the
-- form this file's doors see), clara._assert_due_read_ctx, clara._wdb_period_stamps,
-- clara._wdb_correction_posting_date and clara._wdb_iso_date_supported. THE CADENCE PERIOD
-- ALGEBRA AND THE HASH/CANON PRIMITIVES BELOW ARE THIS SLICE'S and follow, unedited.
-- THE CADENCE PERIOD ALGEBRA (design SS2.3; ABI SSC). D-a already owns the month and
-- financial-year primitives and they are the SAME algebra a template cadence needs -- a
-- second implementation would be a second place for the FY-end fallback to drift. Monthly is
-- calendar-month; annual is the CLIENT's financial year (clara.clients.fy_end_month/day, with
-- the surfaced Dec-31 fallback), which is why both take the client.
create function clara._adj_period_start(p_client uuid, p_cadence text, p_d date) returns date
  language sql stable security definer set search_path = clara, pg_temp as $$
  select case when p_cadence = 'monthly' then clara._fa_month_start(p_d)
              else clara._fa_fy_open_for(p_client, p_d) end $$;
revoke all on function clara._adj_period_start(uuid, text, date) from public;

create function clara._adj_period_end(p_client uuid, p_cadence text, p_d date) returns date
  language sql stable security definer set search_path = clara, pg_temp as $$
  select case when p_cadence = 'monthly' then clara._fa_month_end(p_d)
              else clara._fa_fy_end_for(p_client, p_d) end $$;
revoke all on function clara._adj_period_end(uuid, text, date) from public;

-- THE CANONICAL PERIOD LABEL (ABI SSC). RENDER-ONLY: receipts, events and hashes carry
-- period_start + period_end as DATES; the label exists so the memo and the surfaces read like
-- an accountant wrote them. Monthly 'Jul 2026'; annual 'FY2026'.
-- STABLE, not IMMUTABLE: to_char over a timestamp is catalogued stable (lc_time / DateStyle).
create function clara._adj_period_label(p_cadence text, p_period_end date) returns text
  language sql stable as $$
  select case when p_cadence = 'monthly' then to_char(p_period_end, 'Mon YYYY')
              else 'FY' || to_char(p_period_end, 'YYYY') end $$;
revoke all on function clara._adj_period_label(text, date) from public;

-- THE CANONICAL LINE SET (ABI SSC). ONE normalisation, used by the content hash, by the
-- poster's line writer and by hook arm (2)'s byte-equality axis -- so "the template's lines"
-- means exactly one thing in all three places. Key order is jsonb's own (it normalises
-- object keys), array order is the caller's (line_no derives from position), and a blank or
-- absent description normalises to JSON null so a template written with '' and an entry line
-- stored as NULL compare EQUAL rather than drifting the staleness axis on whitespace.
--
-- THE ABSENT MONEY SIDE NORMALISES TO 0, NOT NULL (as-built ladder fix 2026-08-02). ABI SSC's
-- line shape is {account_code, debit_cents, credit_cents, description?} and the propose
-- validator ACCEPTS the zero side OMITTED -- it reads both legs through
-- `coalesce((x ->> '...')::bigint, 0)` -- as does the poster's clara.journal_lines writer
-- below. This body was the only one of the THREE that did not, and it is the body that both
-- STORES adjustment_templates.lines and computes arm (2d)'s `v_want`. clara.journal_lines
-- carries NOT NULL money columns, so an omitted-zero template stored `credit_cents: null`
-- while its own occurrence stored 0 -- `v_want IS DISTINCT FROM v_have` on every occurrence,
-- and the template was bricked for life at approve with CLR39 adjustment_stale /
-- lines_changed when NOTHING had changed. A template proposed in the ABI's own natural
-- spelling could never post, the ramp could never be earned, and the due oracle reported it
-- merely `all_blocked`. The battery missed it because every fixture wrote explicit zeros.
--
-- IT ALSO REPAIRS THE HASH. With one side normalising to null, the two spellings of the SAME
-- template produced two DIFFERENT content hashes, so the partial unique index AND the
-- friendly template_duplicate precheck both walked straight past a genuine twin. Coalescing
-- is hash-STABLE for the explicit-zero spelling (0 canonicalises to 0), so no already-stored
-- hash moves -- the two spellings simply collide, which is the ABI SSC intent.
--
-- STABLE, not IMMUTABLE: jsonb_build_object is catalogued stable.
create function clara._adj_canon_lines(p_lines jsonb) returns jsonb
  language sql stable as $$
  select coalesce((
    select jsonb_agg(jsonb_build_object(
             'account_code', x.value ->> 'account_code',
             'debit_cents', coalesce((x.value ->> 'debit_cents')::bigint, 0),
             'credit_cents', coalesce((x.value ->> 'credit_cents')::bigint, 0),
             'description', nullif(btrim(coalesce(x.value ->> 'description', '')), ''))
           order by x.ord)
    from jsonb_array_elements(p_lines) with ordinality as x(value, ord)), '[]'::jsonb) $$;
revoke all on function clara._adj_canon_lines(jsonb) from public;

-- THE TEMPLATE CONTENT HASH (design SS2.1; ABI SSD). Exactly the seven fields the design
-- names -- {name, cadence, start_date, end_date, auto_reverse, lines, memo_template} -- over
-- the CANONICAL lines, so two proposals that differ only in a blank description are the same
-- template and the partial unique (client_id, content_hash) WHERE status IN
-- ('proposed','live') refuses the second by name.
--
-- Dates ride as dates: Postgres' JSON output for a DATE is ISO 8601 regardless of DateStyle,
-- so the serialisation is deterministic without a to_char dance (the 0041 fa_disposal
-- proposal hash carries dates the same way). Stored hex like clara.coding_rules /
-- clara.bank_rules do.
create function clara._adj_template_hash(p_name text, p_cadence text, p_start date,
    p_end date, p_auto boolean, p_lines jsonb, p_memo text) returns text
  language sql stable as $$
  select encode(clara._hash(jsonb_build_object(
    'name', p_name, 'cadence', p_cadence, 'start_date', p_start, 'end_date', p_end,
    'auto_reverse', p_auto, 'lines', clara._adj_canon_lines(p_lines),
    'memo_template', p_memo)), 'hex') $$;
revoke all on function clara._adj_template_hash(text, text, date, date, boolean, jsonb, text)
  from public;

-- [SPLIT D-b2 2026-08-04] clara._adj_line_eligibility_breach STANDS HERE IN THE WHOLE UNIT AND IS NOT
-- IN THIS SLICE: census sect.2 Class A moved it to D-b0 alongside the reservation union, because
-- D-b3's clara.accept_bank_rule_suggestion calls it and a D-b3 that shipped before it would
-- carry an unresolvable forward reference. Three bodies in THIS file call it (propose, the
-- poster and the hook), all as plpgsql calls resolved at execution, and SECTION 0's probe 7 pins
-- it as a [SPLIT-CREATED] anchor.

-- =====================================================================================
-- S2.1 -- blocked(template): IS AN OCCURRENCE DRAFT OUTSTANDING? (design SS2.3)
-- =====================================================================================
-- The 0041:1301 clara._fa_disposal_draft_outstanding shape, template-keyed: an EXISTS over
-- DRAFT entries carrying the recurring_adjustment key, backed by the ABI SSC partial index
--   ix_je_adj_draft (client_id) WHERE status='draft' AND flags ? 'recurring_adjustment'
-- so the sweep's per-client hot loop never sequentially scans clara.journal_entries (the D-a
-- F10 measured law: 0.884 ms / 291 buffers per unindexed call on a 5,847-entry database).
--
-- DELIBERATELY NOT ROLE-FILTERED. A mirror draft cannot exist as committed state -- the
-- mirror is born and approved inside the SAME statement as its occurrence's approval, and any
-- mirror-side refusal aborts that whole statement -- so "any recurring_adjustment draft" and
-- "any occurrence draft" are the same set. Asking the broader question costs nothing and
-- fails SAFE if a future writer ever leaves one behind.
create function clara._adj_occurrence_outstanding(p_client uuid, p_template uuid)
  returns boolean
  language sql stable security definer set search_path = clara, pg_temp as $$
  select exists (
    select 1 from clara.journal_entries je
    where je.client_id = p_client and je.status = 'draft'
      and je.flags ? 'recurring_adjustment'
      and (je.flags -> 'recurring_adjustment' ->> 'template_id') = p_template::text) $$;
revoke all on function clara._adj_occurrence_outstanding(uuid, uuid) from public;

-- =====================================================================================
-- S2.1a -- THE ACCOUNT LINE-SHAPE: THE BOOKS' OWN IDENTITY FOR A PERIODIC POSTING
-- (as-built ladder round 6).
--
-- The sorted multiset of (account_code, side) an entry moves money on. AMOUNTS ARE
-- DELIBERATELY OUT OF IT, and that omission is the entire fix. The round-5 gate was keyed on
-- template_id, and the design's OWN edit idiom [WDB-G13] -- "editing" a template is retire +
-- propose again -- mints a NEW template_id, so the gate was bypassed by the most ordinary user
-- story there is. MEASURED, from the round-6 probe: an accrual of 50,000.00 is running; the
-- figure was wrong; the template is retired and re-proposed at the corrected 60,000.00; the due
-- oracle re-advertises every period the retired generation had already met, and the month ends
-- up carrying 110,000.00 against a 60,000.00 intention. Keying on the CANONICAL LINES (which
-- carry the amounts) would have walked straight past that -- 50,000.00 and 60,000.00 are
-- different lines. The books cannot tell two accruals of the same accounts in the same month
-- apart, and neither may this gate.
--
-- ONE DERIVATION FOR BOTH SIDES. clara._wdb_line_shape reads a TEMPLATE's lines (through
-- clara._adj_canon_lines, so an omitted zero side normalises exactly as it does everywhere
-- else); clara._wdb_entry_shape reads a STORED entry's clara.journal_lines. They must agree, so
-- both spell the element the same way and both sort -- line ORDER is a template's business, not
-- the books'.
--
-- IT IS A SET, NOT A MULTISET, AND THE `distinct` IS THE WHOLE OF ROUND 7's FIX HERE. The law
-- three paragraphs up is an ACCOUNT-SET rule -- "the books cannot tell two accruals of the same
-- accounts in the same month apart" -- but round 6 shipped it as a per-LINE multiset, and the
-- gate of the day compared the two arrays with exact array equality, so {400:C, 900:D} never
-- matched {400:C, 900:D, 900:D}. (That comparison is itself history now -- round 8 replaced the
-- equality with an INTERSECTION, four paragraphs down -- but the `distinct` remains load-bearing
-- for the reason this paragraph gives.) MEASURED (probes L2R7/p7, p9, p10), not inferred: a
-- [WDB-G13] edit that
-- merely ITEMISES one debit leg across two lines on the SAME account -- "audit fee, statutory"
-- and "audit fee, tax" -- keeps the accounting identical to the sen, changes the key, and
-- restores the round-6 doubling IN FULL: six consecutive months re-accrued through the machine's
-- own due ladder, `blocked: []` on every one of them, unattended. A gate keyed on anything a
-- template author can vary without changing the books is not a gate; the number of LINES a
-- posting is written on is exactly such a thing, and the sen the books move is not.
--
-- THAT CRITERION WAS NECESSARY AND NOT SUFFICIENT, AND ROUND 8 IS ITS RECORD. The set key stayed
-- author-variable BY CHANGING THE BOOKS: move ONE SEN of the credit into a second accrual code --
-- the product's own named remedy -- and the set changes, the gate goes blind, and four standing
-- months re-accrue (probe r8x1/p2 arm A; three of the four auto-posted). Adding an accrual leg
-- does the same for six (r8x1/p1). So the shape stayed the KEY and the COMPARISON stopped being
-- identity: the gate now asks whether two shapes INTERSECT (clara._wdb_shape_overlap), which is
-- a question no edit can vary without actually moving the charge off the account it collided on.
--
-- IT STAYS AMOUNT-FREE AND NAME-FREE, which is settled law and is deliberately a REFUSAL the
-- product owes an explanation for: two genuinely different accruals written on one pair of
-- accounts (audit fees and legal fees, both Dr expense / Cr accrual) collide here and the
-- second is refused. That is the designed grain -- ONE template per (client, period, account
-- line-shape set) -- because the books themselves cannot tell those two accruals apart and
-- neither can any reader of them. The professional's remedy is a distinct accrual account per
-- liability class, and the refusal at clara._adj_run_occurrence_core says so in those words.
--
-- NO ELEMENT MAY BE NULL, and the coalesce around the account code is what guarantees it. An
-- array holding a NULL compares to another array as NULL, not as false -- so a single missing
-- code would make the gate's own filter fall through and answer "sound" for a period it has not
-- actually looked at. That is a fail-OPEN in the one body whose whole job is to fail closed. It
-- is unreachable through any door today (clara.journal_lines.account_code is NOT NULL, and
-- clara._adj_line_eligibility_breach refuses an unknown code at propose and again at every
-- occurrence), which is exactly why it is worth spending one function call on: a guard that
-- depends on three other guards staying correct is not a guard.
create function clara._wdb_line_shape(p_lines jsonb) returns text[]
  language sql stable security definer set search_path = clara, pg_temp as $$
  select coalesce((
    select array_agg(distinct q.s order by q.s)
      from (select coalesce(x.value ->> 'account_code', '')
                   || case when coalesce((x.value ->> 'debit_cents')::bigint, 0) > 0
                           then ':D' else ':C' end as s
              from jsonb_array_elements(clara._adj_canon_lines(p_lines)) x) q),
    '{}'::text[]) $$;
revoke all on function clara._wdb_line_shape(jsonb) from public;

create function clara._wdb_entry_shape(p_entry uuid) returns text[]
  language sql stable security definer set search_path = clara, pg_temp as $$
  select coalesce((
    select array_agg(distinct q.s order by q.s)
      from (select coalesce(l.account_code, '')
                   || case when coalesce(l.debit_cents, 0) > 0 then ':D' else ':C' end as s
              from clara.journal_lines l where l.entry_id = p_entry) q),
    '{}'::text[]) $$;
revoke all on function clara._wdb_entry_shape(uuid) from public;

-- =====================================================================================
-- S2.1a-2 -- THE GATE ASKS COLLISION, NOT IDENTITY (as-built ladder round 8).
--
-- THE ROUND-7 GATE COMPARED THE TWO SHAPES WITH EXACT ARRAY EQUALITY, and equality is an
-- IDENTITY test on a key the template author still controls. Round 7 closed "vary the number
-- of LINES"; round 8 measured the two edits it did not close, both of them the [WDB-G13]
-- retire-and-re-propose story an accountant actually performs:
--   * ADD A LEG. "Also accrue the legal fee." {900:D, 400:C} becomes {900:D, 901:D, 400:C};
--     the sets are not equal, so the gate cannot see the six standing months. MEASURED
--     (probe r8x1/p1) on this rig: six consecutive months re-posted through the machine's own
--     due ladder with `blocked: []` on every one, 900-D42 carrying RM6,000.00 against an
--     RM3,000.00 intention.
--   * MOVE ONE SEN. Reclass 1 sen of the credit into a second accrual code -- which is the
--     product's OWN named remedy for a shape collision. {900:D, 400:C} becomes
--     {900:D, 400:C, 401:C}. MEASURED (probe r8x1/p2 arm A): four months doubled, three of
--     the four auto-posted, on a book change of ONE SEN.
-- The round-7 criterion three paragraphs up -- "a gate keyed on anything a template author can
-- vary without changing the books is not a gate" -- was necessary and not sufficient: the
-- author CAN change the books, by one sen, and buy the whole doubling with it.
--
-- SO THE LAW IS AN INTERSECTION. At most one machine-posted charge may be standing on ANY ONE
-- (account, side) over any stretch of a client's calendar. Two postings collide when their
-- shapes share ANY element; they are independent only when the sets are FULLY DISJOINT. That
-- is not a widening of convenience, it is the only predicate the remedy can honestly promise:
-- the refusal has told the professional to "give this template distinct account codes" since
-- round 6, and under an equality key that sentence was a lie -- distinct codes on the DEBIT
-- side alone still shared the accrual, and the books still carried two charges nobody could
-- attribute. Under intersection the promise is exact: make the sets disjoint and the second
-- template runs in the same period, which cell x42.r8m1c proves.
--
-- WHAT IT COSTS, WRITTEN DOWN RATHER THAN DISCOVERED LATER. Two live templates that share one
-- accrual account -- an audit-fee accrual and a legal-fee accrual both crediting 400 -- now
-- collide in overlapping periods and the second is refused. That IS the designed grain, one
-- element wider than round 7's: the books record two charges on 400 and no reader, human or
-- machine, can say which accrual each belongs to. The remedy is a distinct accrual code per
-- liability class, it is named in the refusal, and it is now actually sufficient.
--
-- IT RETURNS THE COLLIDING ELEMENTS, NOT A BOOLEAN, because a refusal that says "these
-- collide" without saying WHERE is a remedy the reader cannot follow: with 3-line templates
-- there are up to three candidate codes to re-cut and the human has no way to pick. The
-- payload carries `colliding_elements` and the sentence names them.
--
-- NULL IN, NULL OUT -- "no opinion" -- so the gate's own `p_shape is null` arm ("every shape")
-- stays exactly where it was rather than being re-expressed here.
--
-- AN EMPTY SET COLLIDES WITH EVERYTHING, and that is the same fail-CLOSED argument the
-- coalesce in clara._wdb_entry_shape and the malformed-period-key arm of the gate both carry.
-- A stored entry with no lines cannot exist (clara._assert_balanced runs on every writer) and
-- a template needs two lines to be proposed -- so this arm is unreachable today, which is
-- exactly why it is written: an unreachable arm that fails closed costs one cardinality test,
-- and `'{}' && anything` = false would have made a shapeless posting invisible to the one body
-- whose whole job is to fail closed.
create function clara._wdb_shape_overlap(p_a text[], p_b text[]) returns text[]
  language sql immutable as $$
  select case
    when p_a is null or p_b is null then null
    when cardinality(p_a) = 0 or cardinality(p_b) = 0 then '{}'::text[]
    else (select array_agg(x order by x) from unnest(p_a) x where x = any (p_b))
  end $$;
revoke all on function clara._wdb_shape_overlap(text[], text[]) from public;

-- =====================================================================================
-- S2.1a-2b -- WOULD THAT VERB ADMIT THIS CORRECTION TODAY? THE ONE ADMISSION AUTHORITY
-- (round 10, WDB-R1 + WDB-R2; Codex r10 finding 1, HIGH).
--
-- THE DEFECT THIS BODY EXISTS FOR, AND IT IS THE SEVENTH CONSECUTIVE ROUND OF ONE CLASS.
-- clara._adj_correction_door (S2.1a-3, just below) ROUTES: it reads clara._wdb_reversal_
-- blocked's refusal token and turns `adjustment_pair_locked` into "the verb is
-- clara.reverse_adjustment_pair", or SILENCE into "the verb is clara.reverse_entry". Round 10
-- measured that ROUTING IS NOT ADMISSION -- in BOTH branches, on the same root:
--
--   * THE PAIR BRANCH (Codex's own public recipe; probe o3/p1-door-composition.mjs, re-run on
--     this rig). An auto-reverse template accrues onto an ASSET code; the pair is born, so the
--     code's net balance is ZERO; the template is RETIRED (an ordinary act); an admin then
--     lawfully enrols that now-clean code as a STAFF-ADVANCE account (another ordinary act, on
--     another family's door, admitted in full). MEASURED: the door answered
--     {verb: clara.reverse_adjustment_pair, correctable: true} and clara.get_adjustment_run
--     exported the same; clara._adv_reversal_admission said admitted=false /
--     advance_movement_unregistered / unregistered_mirror about BOTH halves; and calling the
--     advertised verb refused CLR40 with that exact token, rolling back with zero pair rows and
--     zero correction entries. Fail-CLOSED for the money -- and a lie to the professional.
--   * THE SOLO BRANCH IS THE SAME BUG (probe o3/p2-solo-branch.mjs, this lane's own
--     off-path measurement, which Codex's finding did not reach). clara._wdb_reversal_blocked
--     raises ONLY the CARRIED half of the advance envelope (through
--     clara._adv_reversal_blocked, S3.0, whose header states exactly that); the DATED half --
--     the enrolment window, the date ordering, and round 9's fifth wall -- is an ANSWER, never
--     a raise, at clara.reverse_entry. So the door's SILENCE branch is silent about it too.
--     MEASURED on a SOLO prepayment occurrence over the same enrolled code: door
--     {verb: clara.reverse_entry, wall: null, correctable: true}, admission
--     {admitted: false, carried.admitted: TRUE, dated.axis: unregistered_mirror}, and
--     clara.reverse_entry refused CLR40 unregistered_mirror. A fix aimed at the pair branch
--     alone would have been the point-fix WDB-R1 forbids, and round 11's lens would have found
--     the other half.
--
-- SO THE CURE IS THE ONE WDB-R2 NAMES: the body that PROMISES a verb and the body that IS that
-- verb consult ONE authority. This body is it. It answers exactly one question --
--
--     "if `p_verb` were called on this entry (and, for the pair verb, this mirror) right now,
--      would it be admitted, and if not, by which wall?"
--
-- -- and it answers it by ASKING THE VERBS' OWN WALLS, never by re-deriving one. Every arm below
-- is a call into the body that already owns that rule.
--
-- THE DISPATCH IS EXHAUSTIVE AND FAILS CLOSED, the clara._wdb_rerun_breach p_stamp idiom: an
-- unregistered verb RAISES rather than answering "admitted". A third correction door (and one
-- already exists in the catalog -- clara.approve_wrong_client_correction, which takes
-- caller-named entry ids and is granted to bookkeepers) has to be ADJUDICATED into this body
-- before anything may advertise it, rather than silently inheriting a "yes".
--
-- THE ENVELOPE HAS TWO HALVES, AND THE SPLIT IS THE SAME ONE clara._adv_reversal_admission
-- ALREADY DRAWS between `carried` and `dated` -- for the same reason, one layer up:
--
--   * `at_verb`    -- the walls the verb RAISES ITSELF, at the moment it is called, before it
--                     mints anything. True whenever they are asked, so a caller may raise them.
--                     clara._pair_reverse_core does exactly that (S2.6), which is what makes
--                     the courtesy and the authority ONE derivation rather than two copies.
--   * `at_approve` -- the advance-side admission of every half, which the verb's own APPROVE
--                     path enforces (clara._adv_on_approve GUARD III) and which must NOT be
--                     raised at the first moment: at or above the firm's high-stakes floor the
--                     correction PARKS as a draft and a checker may lawfully re-enrol the
--                     account before approving it. Raising early would wall in the caller whose
--                     checker was going to fix it first -- the corridor, not the cure (S3.0's
--                     own ruling, quoted rather than re-decided). It is REPORTED here and
--                     nothing raises it early.
-- `first` is at_verb THEN at_approve -- the enforcing order, so the refusal a caller actually
-- meets is the one this body names first.
--
-- WHAT IS DELIBERATELY NOT HERE: THE PAIR-STATE WALLS. clara._pair_reverse_core re-derives
-- status / reversal_of / reversed_by / pair_already_active / template-stamp UNDER ITS OWN ROW
-- LOCKS ("RE-READ UNDER THE LOCKS. Every refusal below reads locked truth."), and this body is
-- STABLE and lock-free by the SS2.1 doctrine -- the lock belongs to the caller that is about to
-- write. Moving those into a lock-free body would weaken the verb to make the courtesy tidier,
-- which is the wrong trade. The door asks them itself, in its own branch, with its own tokens
-- (pair_already_active / pair_half_not_approved / pair_half_already_reversed) -- that is round
-- 8's work and it stands. The two `not_an_auto_pair` arms the door does not mirror
-- (a half that is ITSELF a reversal, and a missing template stamp) are VACUOUS by construction:
-- section 6 tail 6(a) pins the stamp's writer set at exactly the poster (role='occurrence',
-- reversal_of NULL, stamp always written) and the hook (role='reversal'), so no pair half can
-- carry reversal_of or lack a template_id. Named here rather than left to be re-discovered.
--
-- STABLE, SECURITY DEFINER, LOCK-FREE. It is VOLATILE-BY-DEPENDENCY in the same sense
-- clara._wdb_reversal_blocked already is (that body is declared STABLE and reaches
-- clara._adv_reversal_admission, which samples clock_timestamp() inside the enrolment band):
-- this adds no new smell, it inherits the one the shipped catalog already carries, and it is
-- named here so the next reader does not have to re-derive it.
--
-- COST, MEASURED NOT ASSUMED -- AND IT IS NOT FREE. A/B on this rig against a throwaway twin
-- of the pre-round-10 door (500 warm calls each, two-line adjustment entries on a client with
-- no advance enrolments at all):
--     PAIR occurrence   0.052 ms/call  ->  0.931 ms/call
--     SOLO occurrence   0.372 ms/call  ->  1.142 ms/call
-- Components, same rig: clara._fa_reversal_blocked 0.171 ms, clara._adv_reversal_admission
-- 0.113 ms, and the rest is the two plpgsql exception blocks' subtransactions. The pair arm was
-- so cheap before precisely BECAUSE it was wrong -- clara._wdb_reversal_blocked arm (a) raises
-- on the first row read and nothing downstream was ever asked.
--
-- WHY THAT IS THE RIGHT TRADE HERE, stated rather than assumed. Neither
-- clara.list_adjustment_runs nor clara.get_adjustment_run is on the sweep's hot path (the D-a
-- F10 law, which this file's own S2.8 header already records), and clara._wdb_rerun_breach
-- reaches the door at most ONCE per gate call and only on the REFUSAL path -- so the sweep's
-- per-template T x E is untouched. The visible cost is a receipt LIST: ~0.9 ms per row, i.e.
-- ~22 ms on a 24-receipt client, on a page that is already per-client and firm-scoped.
--
-- at_verb DELIBERATELY RE-ASKS clara._wdb_reversal_blocked rather than trusting the routing
-- answer the door already computed. That is the third of the three admission evaluations on
-- the solo arm and it could be saved -- but this body must be complete for a caller that did
-- NOT route first, and a body that answers correctly only when its caller pre-computed half of
-- it is the composition seam this whole ladder keeps finding.
create function clara._wdb_correction_admission(p_verb text, p_entry uuid,
    p_mirror uuid default null) returns jsonb
  language plpgsql stable security definer set search_path = clara, pg_temp as $$
declare
  v_halves uuid[]; v_h uuid; v_pair boolean;
  v_at_verb jsonb := jsonb_build_object('admitted', true);
  v_at_approve jsonb := jsonb_build_object('admitted', true);
  v_first jsonb; v_radm jsonb;
  v_code text; v_msg text; v_det text;
begin
  -- FAIL CLOSED ON AN UNREGISTERED VERB (the clara._wdb_rerun_breach p_stamp idiom).
  if p_verb is null
     or not (p_verb = any (array['clara.reverse_entry', 'clara.reverse_adjustment_pair'])) then
    raise exception 'clara._wdb_correction_admission was asked about the correction verb "%", which has no arm in this body -- a door that advertises a verb this body cannot speak for is the walled corridor this ladder has found in seven consecutive rounds', coalesce(p_verb, '<null>')
      using errcode = 'CLR10', detail = '{"reason":"correction_verb_unregistered"}';
  end if;
  v_pair := p_verb = 'clara.reverse_adjustment_pair';
  if v_pair and p_mirror is null then
    raise exception 'clara._wdb_correction_admission was asked about clara.reverse_adjustment_pair with no mirror -- the pair verb corrects BOTH halves and an admission that saw only one of them would be exactly the half-answer this body exists to replace'
      using errcode = 'CLR10', detail = '{"reason":"correction_mirror_required"}';
  end if;
  if not v_pair and p_mirror is not null then
    raise exception 'clara._wdb_correction_admission was handed a mirror for clara.reverse_entry, which corrects ONE entry -- a caller that has a mirror in hand is asking about the pair verb'
      using errcode = 'CLR10', detail = '{"reason":"correction_mirror_not_taken"}';
  end if;
  v_halves := case when v_pair then array[p_entry, p_mirror] else array[p_entry] end;

  -- ---------------------------------------------------------------------------------
  -- at_verb -- WALL BY WALL, ACROSS THE HALVES, IN THE VERBS' OWN SHARED ORDER.
  -- MEASURED from the live catalog rather than assumed: clara.reverse_entry asks
  -- clara._subledger_allocated_items_present, then clara._bank_live_match_present, then
  -- clara._fa_reversal_blocked, then clara._wdb_reversal_blocked; clara._pair_reverse_core
  -- asks the first three (each over BOTH halves, `or`-joined for the first two and per-half
  -- for the FA wall) and deliberately NOT the fourth -- clara._wdb_reversal_blocked arm (a)
  -- refuses either half of an auto pair BY NAME and its sanctioned remedy IS the pair verb, so
  -- a pair arm that asked it would make the pair machine refuse its own remedy [L3/6].
  --
  -- THE MESSAGES ARE THE VERBS' OWN, VERBATIM. The two subledger/bank walls read differently
  -- for the two verbs ("this entry" vs "this adjustment pair"), so the sentence is composed per
  -- verb here rather than flattened -- clara._pair_reverse_core raises straight out of this
  -- envelope and its refusal must stay byte-identical to the inline one it replaced.
  -- `detail` is carried as TEXT, not as a jsonb object, so what a caller raises is exactly the
  -- literal the wall shipped (a jsonb round-trip re-spaces it, and a cell that pins a detail
  -- string would then fail on a change that moved no rule).
  -- ---------------------------------------------------------------------------------
  if clara._subledger_allocated_items_present(p_entry)
     or (v_pair and clara._subledger_allocated_items_present(p_mirror)) then
    v_at_verb := jsonb_build_object('admitted', false, 'errcode', 'CLR10',
      'reason', 'allocated_items_present',
      'message', case when v_pair
        then 'open items on this adjustment pair carry allocations; unallocate them first'
        else 'open items on this entry carry allocations; unallocate them first' end,
      'detail', '{"reason":"allocated_items_present"}');
  elsif clara._bank_live_match_present(p_entry)
     or (v_pair and clara._bank_live_match_present(p_mirror)) then
    v_at_verb := jsonb_build_object('admitted', false, 'errcode', 'CLR10',
      'reason', 'live_bank_match_present',
      'message', case when v_pair
        then 'a half of this adjustment pair is matched to a bank statement line; unmatch the bank match first'
        else 'this entry is matched to a bank statement line; unmatch the bank match first' end,
      'detail', '{"reason":"live_bank_match_present"}');
  end if;

  -- THE TWO RAISING WALLS ARE ASKED THROUGH AN EXCEPTION BLOCK AND READ WITH A REGEX, NOT A
  -- CAST -- the same argument clara._adj_correction_door's own detail reader carries: a failed
  -- cast inside a diagnosis turns the diagnosis into an error, and this body must survive ANY
  -- refusal shape a delegate ever raises. The captured sqlstate/message/detail are re-emitted
  -- unchanged, so a caller that raises from this envelope is indistinguishable from the wall.
  foreach v_h in array v_halves loop
    exit when not (v_at_verb ->> 'admitted')::boolean;
    begin
      perform clara._fa_reversal_blocked(v_h);
    exception when others then
      get stacked diagnostics v_code = returned_sqlstate, v_msg = message_text,
                              v_det = pg_exception_detail;
      v_at_verb := jsonb_build_object('admitted', false, 'errcode', v_code,
        'reason', coalesce(substring(coalesce(v_det, '') from '"reason"[[:space:]]*:[[:space:]]*"([a-z0-9_]+)"'),
                           'fa_reversal_blocked'),
        'message', v_msg, 'detail', v_det, 'half', v_h);
    end;
  end loop;
  if (v_at_verb ->> 'admitted')::boolean and not v_pair then
    begin
      perform clara._wdb_reversal_blocked(p_entry);
    exception when others then
      get stacked diagnostics v_code = returned_sqlstate, v_msg = message_text,
                              v_det = pg_exception_detail;
      v_at_verb := jsonb_build_object('admitted', false, 'errcode', v_code,
        'reason', coalesce(substring(coalesce(v_det, '') from '"reason"[[:space:]]*:[[:space:]]*"([a-z0-9_]+)"'),
                           'reversal_blocked'),
        'message', v_msg, 'detail', v_det, 'half', p_entry);
    end;
  end if;

  -- ---------------------------------------------------------------------------------
  -- at_approve -- THE ADVANCE-SIDE ADMISSION OF EVERY HALF, from the ONE body that owns all
  -- FIVE advance-side reversal walls (clara._adv_reversal_admission, S3.0). BOTH halves,
  -- because the pair verb mints a correction for EACH and each correction's approval runs
  -- clara._adv_on_approve GUARD III against ITS OWN original -- which is precisely the
  -- composition Codex measured: the occurrence's own admission and the mirror's are two
  -- different questions and the door was asking neither.
  --
  -- THE FULL ENVELOPE, not just the dated half: the pair verb never calls
  -- clara._wdb_reversal_blocked at all, so for THAT verb even the `carried` walls are enforced
  -- nowhere earlier than the approve. Asking `admitted` covers both halves for both verbs, and
  -- re-asking the carried half on the solo arm is free of consequence (same body, same answer).
  -- ---------------------------------------------------------------------------------
  foreach v_h in array v_halves loop
    exit when not (v_at_approve ->> 'admitted')::boolean;
    v_radm := clara._adv_reversal_admission(v_h);
    if not (v_radm ->> 'admitted')::boolean then
      v_at_approve := jsonb_build_object('admitted', false,
        'errcode', v_radm -> 'first' ->> 'errcode',
        'reason', v_radm ->> 'blocked_by',
        'axis', v_radm -> 'first' ->> 'axis',
        'message', v_radm -> 'first' ->> 'message',
        'detail', v_radm -> 'first' ->> 'detail', 'half', v_h);
    end if;
  end loop;

  v_first := case when not (v_at_verb ->> 'admitted')::boolean then v_at_verb
                  when not (v_at_approve ->> 'admitted')::boolean then v_at_approve end;
  return jsonb_build_object('verb', p_verb, 'entry', p_entry, 'mirror', p_mirror,
    'admitted', v_first is null, 'blocked_by', v_first ->> 'reason',
    'first', v_first, 'at_verb', v_at_verb, 'at_approve', v_at_approve);
end $$;
revoke all on function clara._wdb_correction_admission(text, uuid, uuid) from public;

-- =====================================================================================
-- S2.1a-3 -- WHICH DOOR CORRECTS THIS ENTRY TODAY? THE ONE AUTHORITY (round 8, WDB-R2).
--
-- Two bodies promise an outcome about a correction of one entry and they must not be able to
-- disagree: clara._wdb_rerun_breach's shape_already_met payload, which tells a human WHICH
-- VERB to call on WHICH ENTRY, and clara._adj_run_json's `correctable`, which decides whether
-- the run-receipt card offers the act at all. Round 7 built the first as an inline probe of
-- clara._wdb_reversal_blocked; round 8's surface work needed the same answer, and a second
-- inline copy is precisely the drift WDB-R2 forbids. So the derivation lives here once.
--
-- IT ASKS THE WALLS, IT DOES NOT RE-DERIVE THEM. clara._wdb_reversal_blocked IS
-- clara.reverse_entry's own 7th-splice wall, so its silence is that verb's own admission
-- answer rather than this body's opinion of it -- but SILENCE FROM ONE SPLICE IS NOT
-- ADMISSION, and round 10 measured that in both branches. The status and double-reverse
-- checks are asserted here directly, above, because a card must not offer an act on a draft
-- or on an entry that is already corrected; EVERY OTHER wall of the verb this body is about
-- to name is asked of clara._wdb_correction_admission (S2.1a-2b) after routing -- the FA
-- wall this comment used to claim was "asserted here directly" and never was, the two
-- subledger/bank walls, and the whole advance-side envelope whose DATED half no splice
-- raises at all. The detail is read with a regex rather than a jsonb cast so this body
-- survives ANY refusal shape a delegate ever raises: a failed cast inside a diagnosis turns
-- the diagnosis into an error.
--
-- ROUTING IS NOT ADMISSION [round 10, WDB-R1/WDB-R2; Codex r10 finding 1 + this lane's own
-- solo-branch measurement]. This body's job has two steps and they were fused into one until
-- round 10: (1) WHICH verb is the shape's door -- the wall token answers that, and that half
-- was right; (2) WOULD that verb admit this entry today -- which nothing asked. The full
-- measurement, both branches, is at clara._wdb_correction_admission's header; the consequence
-- here is that every `correctable: true` return below is now issued only AFTER the routed
-- verb's own complete admission has been consulted, and a refusal carries THAT WALL'S OWN
-- token in `wall` (never the routing token, which would say "adjustment_pair_locked" about a
-- run whose real obstacle is an advance register) plus the wall's own sentence in
-- `wall_advice`, so a consumer composing a remedy names something the reader can follow.
--
-- AND WHEN THE WALL SAYS adjustment_pair_locked IT READS THE PAIR MACHINE'S OWN STATE, never a
-- second opinion of its admission logic. "Active" is not this body's word: the schema itself
-- defines it, at the partial unique index uq_adjustment_pair_reversals_occurrence_active
-- (status in ('pending','approving')), which is the same predicate clara._pair_reverse_core's
-- pair_already_active arm refuses on. Round 7 named clara.reverse_adjustment_pair
-- UNCONDITIONALLY whenever the wall said adjustment_pair_locked -- so a period whose standing
-- occurrence already had a correction PARKED for a checker was handed a verb that refuses
-- CLR10 pair_already_active. That is the walled corridor this ladder has now found in seven
-- consecutive rounds, in the very repair that closed the sixth; here it is closed by asking.
--
-- THE MIRROR'S OWN STATE IS READ TOO. clara._pair_reverse_core refuses when EITHER half is
-- already reversed, and a mirror can be reversed alone through a door this migration does not
-- own (clara.approve_wrong_client_correction takes caller-named entry ids), which is exactly
-- the pair_half_uncorrected fact the gate's own mixed arm exists for.
--
-- SHAPE OF THE ANSWER (never null; EVERY return carries EVERY key, so a consumer never has to
-- ask whether one is present):
--   verb                text|null  the verb that admits this entry today, or null
--   entry               uuid       the entry THAT VERB takes (the pair verb takes the
--                                  OCCURRENCE, so a mirror resolves to it)
--   correctable         boolean    verb is not null
--   wall                text|null  the reason token that closed the door, when one did
--   active_pair_id      uuid|null  the in-flight pair over this occurrence, if any
--   active_pair_status  text|null  its status ('pending' | 'approving')
--   wall_advice         text|null  [round 10] the closing wall's OWN sentence, when the wall
--                                  came from a body that composes one. A remedy that names a
--                                  wall token and nothing else is not followable by the role
--                                  reading it; this is the sentence that makes it followable,
--                                  carried rather than re-composed so it can only ever say
--                                  what the wall's owning body actually says.
create function clara._adj_correction_door(p_entry uuid) returns jsonb
  language plpgsql stable security definer set search_path = clara, pg_temp as $$
declare e record; pr record; v_detail text; v_wall text; v_occ uuid; v_mirror record;
        v_adm jsonb; v_detail_message text;
begin
  select * into e from clara.journal_entries where id = p_entry;
  if not found then
    return jsonb_build_object('verb', null::text, 'entry', p_entry, 'correctable', false,
      'wall', 'entry_not_found', 'active_pair_id', null::uuid,
      'active_pair_status', null::text, 'wall_advice', null::text);
  end if;
  -- THE PAIR VERB TAKES THE OCCURRENCE. Resolve first, so every key below -- including the
  -- active-pair lookup, which is keyed on occurrence_id -- speaks about the same act.
  v_occ := coalesce(e.auto_reversal_of, p_entry);
  select r.id, r.status into pr from clara.adjustment_pair_reversals r
    where r.occurrence_id = v_occ and r.status in ('pending', 'approving') limit 1;

  if e.status <> 'approved' then
    return jsonb_build_object('verb', null::text, 'entry', v_occ, 'correctable', false,
      'wall', 'entry_not_approved', 'active_pair_id', pr.id,
      'active_pair_status', pr.status, 'wall_advice', null::text);
  end if;
  if e.reversed_by is not null then
    -- [R11 FIX 2026-08-04 -- Codex round-11 finding 5] THE ALIAS IS STATED, NOT LEFT TO BE DISCOVERED.
    -- For an already-corrected PAIR the door says `entry_already_reversed` and the verb raises
    -- `pair_half_already_reversed`: both refuse correctly, so it is not an admission or money
    -- error, but it is not token parity either. The token itself may not move -- the run-receipt
    -- card keys the COMPLETED state on this exact spelling (cell x42.r10o2.f4a pins it as "the
    -- exact shape correctionPhase's wall-based fallback consumes"), so aligning the DB word would
    -- trade a naming mismatch for a broken completed render. The sentence carries the parity
    -- instead, and only where it is true: this arm fires for solo occurrences too, and there is no
    -- pair verb to alias for those.
    return jsonb_build_object('verb', null::text, 'entry', v_occ, 'correctable', false,
      'wall', 'entry_already_reversed', 'active_pair_id', pr.id,
      'active_pair_status', pr.status,
      'wall_advice', case
        when exists (select 1 from clara.journal_entries j where j.auto_reversal_of = v_occ)
          then 'this occurrence''s correction is already complete. clara.reverse_adjustment_pair '
               || 'reports the same terminal state as pair_half_already_reversed -- the verb-side '
               || 'spelling of this door''s entry_already_reversed; there is nothing left to correct.'
        else null::text end);
  end if;

  begin
    perform clara._wdb_reversal_blocked(p_entry);
    v_wall := null;
  exception when others then
    -- The MESSAGE is captured beside the detail [round 10]: the "any other wall" arm at the
    -- foot of this body reports a wall it cannot translate into a door, and a token with no
    -- sentence is a dead end for the human reading it.
    get stacked diagnostics v_detail = pg_exception_detail, v_detail_message = message_text;
    v_wall := coalesce(substring(coalesce(v_detail, '') from '"reason"[[:space:]]*:[[:space:]]*"([a-z0-9_]+)"'),
                       'reversal_blocked');
  end;

  if v_wall is null then
    -- THE SOLO DOOR, ROUTED -- AND THEN ASKED. clara._wdb_reversal_blocked's silence proves
    -- only that ITS OWN splice admits; clara.reverse_entry has three more walls and one whole
    -- envelope half that nothing raises early (measured: probe o3/p2-solo-branch.mjs -- a solo
    -- prepayment occurrence over an enrolled advance code read correctable:true here while the
    -- verb refused CLR40 unregistered_mirror).
    v_adm := clara._wdb_correction_admission('clara.reverse_entry', p_entry);
    if not (v_adm ->> 'admitted')::boolean then
      return jsonb_build_object('verb', null::text, 'entry', p_entry, 'correctable', false,
        'wall', v_adm ->> 'blocked_by', 'active_pair_id', pr.id,
        'active_pair_status', pr.status,
        'wall_advice', v_adm -> 'first' ->> 'message');
    end if;
    return jsonb_build_object('verb', 'clara.reverse_entry', 'entry', p_entry,
      'correctable', true, 'wall', null::text, 'active_pair_id', pr.id,
      'active_pair_status', pr.status, 'wall_advice', null::text);
  end if;
  if v_wall = 'adjustment_pair_locked' then
    if pr.id is not null then
      -- The pair door refuses its own second attempt; naming it would be the walled corridor.
      -- [R11 FIX 2026-08-04 -- W2 finding 1] ...AND THE PARK IS ASKED WHETHER IT CAN BE FINISHED, WHICH
      -- IS THE C1 CLASS ALIVE INSIDE THE C1 FIX. Round 10 taught the pair branch below to ask
      -- clara._wdb_correction_admission before reporting `correctable`; THIS branch returned above
      -- it and shipped the pair machine's state alone. MEASURED: an RM15,000 pair correction parks
      -- for a second bookkeeper (by design, for days); during the park an admin lawfully enrols the
      -- netted code as a staff-advance account; the DURABLE RUN RECEIPT still read {correctable:
      -- false, wall:'pair_already_active', wall_advice:NULL} and the card offered Approve -- which
      -- refuses CLR40 advance_movement_unregistered and rolls back. The one act that DOES work
      -- (cancel) was never distinguished from the one that cannot. The authority had the answer the
      -- whole time: the identical call returns {admitted:false, blocked_by:...} for both halves,
      -- and the same door reports it correctly the moment the pair is cancelled.
      -- BOTH FACTS ARE REPORTED, because the consumer needs both: the pair IS still active (the
      -- two active_pair keys keep their values, which is what tells a surface a park is in flight)
      -- and the completion is INADMISSIBLE (the wall reported is the admission's own, never the
      -- routing token -- the precedent this file set one branch down: "the wall reported is THAT
      -- wall, never the routing token"). When admission ADMITS, nothing changes: the answer is
      -- pair_already_active exactly as before, which is what keeps the round-8 cell x42.r8m1g and
      -- the round-9 door census green.
      select j.id, j.status, j.reversed_by into v_mirror from clara.journal_entries j
        where j.auto_reversal_of = v_occ limit 1;
      if v_mirror.id is not null and v_mirror.status = 'approved'
         and v_mirror.reversed_by is null then
        -- ASKED ONLY WHEN THE QUESTION IS ASKABLE. clara._wdb_correction_admission raises CLR10 on
        -- a pair verb handed no mirror, by design (fail-closed dispatch), and a park whose mirror
        -- is missing or already reversed is a state the branches below are written for -- but this
        -- branch returns above them, so it must not manufacture that raise. It reports the pair
        -- state alone there, exactly as it always did.
        v_adm := clara._wdb_correction_admission('clara.reverse_adjustment_pair', v_occ,
                                                 v_mirror.id);
        if not (v_adm ->> 'admitted')::boolean then
          return jsonb_build_object('verb', null::text, 'entry', v_occ, 'correctable', false,
            'wall', v_adm ->> 'blocked_by', 'active_pair_id', pr.id,
            'active_pair_status', pr.status,
            'wall_advice', v_adm -> 'first' ->> 'message');
        end if;
      end if;
      return jsonb_build_object('verb', null::text, 'entry', v_occ, 'correctable', false,
        'wall', 'pair_already_active', 'active_pair_id', pr.id,
        'active_pair_status', pr.status, 'wall_advice', null::text);
    end if;
    select j.id, j.status, j.reversed_by into v_mirror from clara.journal_entries j
      where j.auto_reversal_of = v_occ limit 1;
    if v_mirror.id is null or v_mirror.status <> 'approved' then
      return jsonb_build_object('verb', null::text, 'entry', v_occ, 'correctable', false,
        'wall', 'pair_half_not_approved', 'active_pair_id', null::uuid,
        'active_pair_status', null::text, 'wall_advice', null::text);
    end if;
    if v_mirror.reversed_by is not null then
      return jsonb_build_object('verb', null::text, 'entry', v_occ, 'correctable', false,
        'wall', 'pair_half_already_reversed', 'active_pair_id', null::uuid,
        'active_pair_status', null::text, 'wall_advice', null::text);
    end if;
    -- THE PAIR DOOR, ROUTED -- AND THEN ASKED, FOR BOTH HALVES [round 10, Codex finding 1].
    -- The pair state above is the pair MACHINE's own; it says nothing about whether the two
    -- corrections this verb is about to mint can be approved, and that is a question only
    -- clara._wdb_correction_admission can answer -- once per half, because each correction's
    -- approve runs clara._adv_on_approve GUARD III against ITS OWN original.
    v_adm := clara._wdb_correction_admission('clara.reverse_adjustment_pair', v_occ,
                                             v_mirror.id);
    if not (v_adm ->> 'admitted')::boolean then
      -- THE HONEST STATE: this run is correctable by NO verb until the wall's own subject
      -- changes -- so the wall reported is THAT wall, never the routing token (which would say
      -- "adjustment_pair_locked" about a run whose real obstacle is a staff-advance register),
      -- and the wall's own sentence rides with it so a composed remedy stays followable.
      return jsonb_build_object('verb', null::text, 'entry', v_occ, 'correctable', false,
        'wall', v_adm ->> 'blocked_by', 'active_pair_id', null::uuid,
        'active_pair_status', null::text,
        'wall_advice', v_adm -> 'first' ->> 'message');
    end if;
    return jsonb_build_object('verb', 'clara.reverse_adjustment_pair', 'entry', v_occ,
      'correctable', true, 'wall', v_wall, 'active_pair_id', null::uuid,
      'active_pair_status', null::text, 'wall_advice', null::text);
  end if;
  -- ANY OTHER WALL (the advance arms, or a refusal shape this body cannot translate into a
  -- door): say so instead of inventing one. NULL IS TYPED -- jsonb_build_object takes "any",
  -- and a bare NULL literal is `unknown` there, which raises at RUNTIME in the one branch that
  -- exists precisely because something unexpected happened.
  return jsonb_build_object('verb', null::text, 'entry', p_entry, 'correctable', false,
    'wall', v_wall, 'active_pair_id', pr.id, 'active_pair_status', pr.status,
    'wall_advice', v_detail_message);
end $$;
revoke all on function clara._adj_correction_door(uuid) from public;

-- =====================================================================================
-- S2.1a-4 -- WHAT WOULD A RE-CUT LEAVE STANDING? THE ONE PREDECESSOR CENSUS (round 10,
-- WDB-R2).
--
-- THE DEFECT THIS BODY EXISTS FOR. Round 9 gave the shape_already_met refusal a second
-- clause -- "or give this template distinct account codes" -- and CONDITIONED it on the
-- standing writer's template STATUS, reading `retired` as "this is the generation you
-- replace" and printing a PROHIBITION. Round 10 measured that proxy wrong in BOTH
-- directions, each with money (probes z1/p1-retired-sibling.mjs, z1/p5-order-bypass.mjs,
-- re-run on this rig):
--   * A RETIRED SIBLING THAT IS NOT A PREDECESSOR. Audit fees accrued monthly on 900/400,
--     the engagement ends, the template is RETIRED through the granted verb; the firm then
--     accrues LEGAL fees on 901/400 -- the shared "Accruals" code this file's own comment
--     names as the DESIGNED collision. The refusal asserted "it is the generation this one
--     replaces" (false), FORBADE the distinct-codes act (measured CORRECT: 401 books both
--     months clean, EXPA 600000 / EXPB 240000 / ACCR -600000 / ACCR2 -240000), and its one
--     remaining instruction, followed verbatim, erased RM6,000 of a legitimate audit
--     accrual (EXPA 600000 -> 0, ACCR -600000 -> -240000).
--   * THE ORDER BYPASS. Propose the replacement FIRST and retire the old one after -- the
--     order a professional actually works in, and nothing requires the other -- and the
--     status reads `live`, the doubling instruction prints again, and following it ran four
--     standing months onto fresh codes with blocked:[]: RM18,000 of expense against an
--     RM6,000 intention.
-- One root: STATUS IS A SNAPSHOT PROXY FOR LINEAGE THE SCHEMA DOES NOT RECORD, and its
-- value depends on the user's click order. The lineage fix (`replaces_template_id` stamped
-- at re-propose) is a [WDB-G13] design-pin amendment and is the OWNER's fork -- recorded on
-- OWNER-SITTING under the G13 item, NOT built here.
--
-- SO THE RULE THIS BODY ENFORCES IS THE HONEST MINIMUM: NO SURFACE MAY ASSERT OR PROHIBIT
-- WHAT ONLY LINEAGE CAN PROVE. What the books CAN prove is narrower and is exactly what
-- this census returns: which OTHER templates of this client carry a shape that collides
-- with the caller's, and what each of them ALREADY HAS STANDING. The refusal states that
-- measurement and the conditional consequence ("IF this template replaces that one, ...")
-- and leaves the act available -- the professional is the one party who knows whether it is
-- a replacement, and this file has no business telling them it knows.
--
-- IT IS ONE BODY BECAUSE THREE DOORS PROMISE ITS OUTCOME (WDB-R2): the poster's
-- shape_already_met caution, the poster's template_line_ineligible caution (the cross-family
-- re-cut road, round-10 finding 3), and clara.propose_adjustment_template's advisory warning.
-- Three inline copies of "is there a candidate predecessor" is precisely the drift that put
-- the round-9 discriminant on one door and not the other.
--
-- THE CENSUS COUNTS role='occurrence' ENTRIES ONLY, and that is a money decision rather than
-- a convenience. A charge that a re-cut would leave standing is an OCCURRENCE: an
-- auto-reversal MIRROR is the release of one, so a template whose occurrence has been
-- corrected while its mirror still stands has NOTHING a fresh-coded replacement could double,
-- and cautioning there would be the same kind of unearned assertion this body exists to
-- delete. `reversed_by is null` is the standing test, exactly as clara._wdb_rerun_breach
-- spells it.
--
-- THE PERIOD BOUNDS ARE COMPARED collate "C", the same C-collation the gate's own stamp
-- comparison uses: these are ISO text, and min()/max() under a linguistic collation is not
-- guaranteed to order them. A malformed stamp can therefore only mis-order a DISPLAYED
-- period bound in a caution; it can never change a count, and no admission decision reads
-- either bound.
-- =====================================================================================
-- S2.1a-1b -- IS THIS PERIOD STAMP A DAY AT ALL? [R12 FIX 2026-08-04 -- confirming round, native H2/H3]
-- =====================================================================================
-- ONE SPELLING FOR ONE THING (WDB-R2), and the thing is small: a `recurring_adjustment` period
-- stamp is either a well-formed ISO DAY or it is not a stamp. Returns the text unchanged when it
-- is, and NULL -- "unstamped" -- when it is not, so every caller's existing coalesce default is
-- what a malformed stamp now takes.
--
-- WHY THIS EXISTS AT ALL, IN MONEY. The stamps are text, compared under collate "C" against
-- to_char(...,'YYYY-MM-DD') and never cast (a cast that raises 22P02 inside an ADMISSION path
-- turns a refusal into an error). Text comparison cannot raise -- but it also cannot tell a
-- SHORTER string from a smaller date: MEASURED, a stamp truncated to month grain ('2026-02', the
-- shape a restored or legacy register can carry) sorts BELOW '2026-02-01', so an ancestor's
-- standing charge for that month fell out of the wall's window entirely and the replacement
-- posted the second charge in silence. A blank stamp ('') did the same. The direction of the
-- error is what makes this a money fix rather than a tidy-up: the fail-OPEN direction.
--
-- IT IS A GRAMMAR AND A CALENDAR, AND THE SENTENCE THAT STOOD HERE ARGUED THE OPPOSITE
-- [R13 FIX 2026-08-04 -- re-confirming round, Codex RC2, MONEY]. It read: "IT IS A GRAMMAR, NOT A
-- CALENDAR. '2026-13-45' matches and is returned ... a syntactically well-formed but impossible
-- date compares meaningfully (it sorts after every real day of 2026, which places it INSIDE any
-- window that reaches forward -- the fail-closed direction again)."
-- THE PARENTHESIS IS THE DEFECT, AND IT IS THIS BODY'S OWN DEFECT ONE ROUND ON. A window has TWO
-- bounds. `period_end >= window_start` is the forward one and an over-large stamp does land inside
-- it; `period_start <= window_end` is the other, and '2026-13-45' sorts ABOVE every real day of
-- 2026, so the charge fails THAT half and leaves the window entirely -- which is precisely what
-- month grain did at the lower bound, and precisely what this function was written to stop. Both
-- the wall (clara._wdb_replaced_generation_standing) and the advisory
-- (clara._wdb_period_overlap_advisory) went blind, and the replacement posted the second charge
-- in silence. The malformation is the shape a restored or legacy register carries, which is the
-- only reason either body reads these stamps defensively at all.
-- SO THE CAST IS ATTEMPTED, AND ITS FAILURE IS AN ANSWER RATHER THAN AN ERROR. The rule the
-- callers may not break is "an ADMISSION path must never raise 22P02 on a bad stamp", not "an
-- admission path must never cast": a cast inside an exception block cannot escape, and its
-- failure means exactly what a failed regex means -- UNSTAMPED, which every caller already
-- coalesces to the fail-CLOSED default. So '2026-13-45', '2026-00-00' and '2026-02-30' now take
-- the same road '2026-02', '' and null take, and land INSIDE every window.
-- IT COSTS ONE SUBTRANSACTION PER WELL-FORMED STAMP, named rather than discovered later: only a
-- stamp that has already passed the regex reaches the block, and the rows that reach it are the
-- standing charges of one template inside one window. That is the price of letting the SERVER's
-- calendar answer instead of writing a second one here -- and a second calendar in this file
-- would be exactly the "one spelling for one thing" violation (WDB-R2) the first cut of this body
-- was trying to avoid.
-- THE EXCEPTION LIST IS NAMED, NOT `others`. The regex has already excluded every shape but
-- `NNNN-NN-NN`, so the only failures reachable here are the two the date parser raises for a
-- syntactically valid, calendrically impossible day. Anything else escaping this body is a defect
-- somebody must see, not a stamp to swallow.
create function clara._wdb_iso_day(p_stamp text) returns text
  language plpgsql immutable as $$
declare v_day date;
begin
  if p_stamp is null or p_stamp !~ '^\d{4}-\d{2}-\d{2}$' then
    return null;
  end if;
  begin
    v_day := p_stamp::date;
  exception when invalid_datetime_format or datetime_field_overflow then
    return null;
  end;
  return p_stamp;
end $$;
revoke all on function clara._wdb_iso_day(text) from public;

create function clara._wdb_template_standing_charges(p_client uuid, p_template uuid)
  returns jsonb
  language sql stable security definer set search_path = clara, pg_temp as $$
  select jsonb_build_object(
    'standing', count(*),
    'first_period', min((je.flags -> 'recurring_adjustment' ->> 'period_start') collate "C"),
    'last_period', max((je.flags -> 'recurring_adjustment' ->> 'period_end') collate "C"))
    from clara.journal_entries je
   where je.client_id = p_client
     and je.flags ? 'recurring_adjustment'
     and (je.flags -> 'recurring_adjustment' ->> 'template_id') = p_template::text
     and (je.flags -> 'recurring_adjustment' ->> 'role') = 'occurrence'
     and je.status = 'approved'
     and je.reversed_by is null $$;
revoke all on function clara._wdb_template_standing_charges(uuid, uuid) from public;

-- =====================================================================================
-- S2.1a-6b -- ARE YOU ABOUT TO RE-CHARGE MONTHS THAT ARE ALREADY CHARGED? THE PROPOSE/SIGN
-- ADVISORY [R12 FIX 2026-08-04 -- confirming round; round 11 built this INLINE at propose and scoped
-- it to retired siblings].
--
-- IT HAS NO SHAPE REQUIREMENT ON THE RETIRED ARM, AND THAT IS THE WHOLE POINT. The sibling
-- census (clara._wdb_overlapping_siblings) takes a SHAPE and returns only what collides with it;
-- a [WDB-G13] edit that RE-CODES has no shape overlap by construction, which is exactly why
-- every shape-keyed defence in this file was silent on the measured double. This term reads
-- PERIODS and nothing else.
--
-- WHY THE SUBJECT IS 'retired' OR 'live' AND NOT 'retired' ALONE, MEASURED (Codex CXR1; the
-- native lens reproduced it live). This file BLESSES the propose-first order -- propose the
-- replacement, satisfy yourself it is right, then retire the old one. In that order, at the
-- moment of propose:
--   * `p_replaces` is REFUSED (template_replaces_not_retired), so there is no recorded edge and
--     admission predicate (5) can never fire on this pair;
--   * the predecessor's status is 'live', so a retired-only term has no subject;
--   * and the codes are disjoint, so no shape-keyed defence sees anything.
-- All three defences were structurally unavailable AT ONCE, and the professional was told
-- nothing at the one moment they were still one edit away from being right.
--
-- ...BUT THE LIVE ARM IS NARROWED BY SHAPE, AND THE NARROWING IS THE OPPOSITE OF THE RETIRED
-- ARM'S FOR A MEASURED REASON. Where a LIVE sibling's shape INTERSECTS this proposal's, the
-- poster's own period_shape_already_met wall stops the second charge at the moment money would
-- move -- the professional meets a refusal, not silence -- and the propose receipt's term (a)
-- already names that sibling, its standing charges and the doubling risk in the same breath.
-- Warning twice about one template would be the noise that teaches a reader to skip this key.
-- Where the shapes are DISJOINT there is no wall at all on an undeclared pair: that is the
-- measured silent double, and this sentence is its only defence. So: retired siblings, any
-- shape; live siblings, disjoint shapes only.
--
-- IT IS ADVISORY AND MUST STAY ADVISORY. The propose-first order is lawful, back-dating a
-- replacement over corrected months is lawful, and the WALL for the case that is not lawful is
-- admission predicate (5) -- which refuses at the moment money moves, on a DECLARED lineage, and
-- cannot be defeated by click order. A refusal here would refuse on a guess about intent at a
-- moment when nothing is being posted.
--
-- THE WINDOW IS THE CALLER'S BOOKABLE ONE, [p_start, coalesce(p_end, +inf)), and a stamp that is
-- not an ISO day is treated as UNSTAMPED (clara._wdb_iso_day) -- which takes the coalesce default
-- and therefore lands INSIDE the window. Fail-loud: the worst outcome is one sentence a reader
-- did not need, never a silence.
--
-- p_self IS THE CALLER'S OWN ROW (NULL at propose-before-insert; the template's id at sign), so a
-- template can never warn about itself. Every other filter is status-based and would exclude a
-- 'proposed' row anyway; this is the belt for the sign-time call, where the row is about to
-- become the very status it is scanning for.
create function clara._wdb_period_overlap_advisory(p_client uuid, p_self uuid, p_shape text[],
    p_start date, p_end date) returns jsonb
  language sql stable security definer set search_path = clara, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'axis', 'replaced_period_overlap',
           'template_id', q.id,
           'name', q.name,
           'status', q.status,
           'standing_charges', (q.census ->> 'standing')::int,
           'first_period', q.census ->> 'first_period',
           'last_period', q.census ->> 'last_period',
           'message', 'the ' || upper(q.status) || ' template ' || q.id || ' ("' || q.name
             || '") still carries ' || (q.census ->> 'standing') || ' standing charge(s) for '
             || coalesce(q.census ->> 'first_period', 'an unstated period') || ' .. '
             || coalesce(q.census ->> 'last_period', 'an unstated period')
             || ', and this template covers those periods. IF this one replaces it, those months '
             || 'are already charged: correct those entries in their own periods, or start this '
             || 'template after '
             || coalesce(q.census ->> 'last_period', 'that generation''s last period')
             || case when q.status = 'live'
                     then '. That template is still LIVE, so nothing has stopped yet: retire it '
                          || 'when this one takes over, and declare the lineage (p_replaces) on '
                          || 'the replacement -- a declaration made while it is still live is '
                          || 'refused, which is why this sentence is here instead.'
                     else '. Declaring the lineage (p_replaces) turns this sentence into a WALL '
                          || '-- the run of an already-charged period is then refused instead of '
                          || 'posted.' end)
           order by q.id), '[]'::jsonb)
    from (select a.id, a.name, a.status,
                 clara._wdb_template_standing_charges(p_client, a.id) as census
            from clara.adjustment_templates a
           where a.client_id = p_client
             and a.status in ('retired', 'live')
             and (p_self is null or a.id <> p_self)
             and (a.status = 'retired'
                  or coalesce(cardinality(clara._wdb_shape_overlap(
                        p_shape, clara._wdb_line_shape(a.lines))), 0) = 0)) q
   where coalesce((q.census ->> 'standing')::int, 0) > 0
     and coalesce(clara._wdb_iso_day(q.census ->> 'last_period'), '9999-12-31') collate "C"
           >= to_char(p_start, 'YYYY-MM-DD') collate "C"
     and (p_end is null
          or coalesce(clara._wdb_iso_day(q.census ->> 'first_period'), '0001-01-01') collate "C"
               <= to_char(p_end, 'YYYY-MM-DD') collate "C") $$;
revoke all on function clara._wdb_period_overlap_advisory(uuid, uuid, text[], date, date) from public;

-- WHICH OTHER TEMPLATES OF THIS CLIENT COLLIDE WITH THIS SHAPE, AND WHAT DOES EACH ALREADY
-- CARRY? `p_exclude` is the caller's own template (NULL at propose, where the row does not
-- exist yet) -- a template is never its own predecessor.
--
-- THE COLLISION TEST IS THE GATE'S OWN (clara._wdb_shape_overlap), not a second opinion of
-- it: the caution has to speak about the same intersection the refusal was raised on, or the
-- two drift the moment either definition moves.
--
-- CONTAINMENT IS REPORTED, NOT ENFORCED, and it is what lets a consumer tell the three
-- shapes a [WDB-G13] EDIT actually takes from the DESIGNED collision:
--   identical  -- the same accounts and sides (the commonest edit: a figure changed)
--   contains   -- the sibling's whole shape sits inside this one (an ADDED leg)
--   contained  -- this whole shape sits inside the sibling's (a REMOVED leg)
--   partial    -- neither contains the other (audit fees and legal fees sharing one accrual
--                 code: the designed grain, argued at clara._wdb_line_shape)
-- clara.propose_adjustment_template warns only on the first three, because a partial overlap
-- is a state the product deliberately supports and warning on it would be noise. The
-- poster's caution deliberately does NOT filter on containment: by the time a period is
-- refused, a partial-overlap sibling with standing months is ALSO a doubling candidate if it
-- is the predecessor, and this file may not decide that it is not.
--
-- THE STATUS IS CARRIED AS A FACT AND NEVER AS A DISCRIMINANT. Round 9's defect was not
-- reading the status, it was BELIEVING it; a reader is entitled to know that the sibling is
-- retired, and no branch of the composed remedy may be chosen by it.
--
-- ...AND UNCERTAINTY FAILS TOWARD THE CAUTION, NOT AWAY FROM IT [round 10, Codex r10 finding
-- 3, LOW; probe o3/probes/p5-unknown-writer.mjs, re-run on this rig]. The census above walks
-- TEMPLATES and counts the charges STAMPED WITH EACH -- so a standing charge whose stamp names
-- no template of this client at all (a malformed or legacy `template_id`; a stamp pointing at
-- another client's template) is attributable to NOBODY and was therefore counted for nobody.
-- MEASURED: one approved RM3,000 accrual restamped `template_id:"legacy-not-a-uuid"` with
-- malformed period keys; the colliding template's run was refused period_shape_already_met
-- with `standing_template_status:"unknown"` -- and `predecessor_candidates:[]`, `remedy:
-- ["correct_the_standing_entry_in_period","distinct_codes"]`, i.e. the PLAIN branch, the very
-- sentence that tells the professional to re-cut onto fresh codes while that RM3,000 stays
-- standing on the old ones. The real template was in the census with `standing: 0`, because
-- its own charge no longer counts as its own, and the `standing > 0` filter then dropped it.
--
-- The fix is at the census rather than at either refusal (three doors read this body; a
-- discriminant added at one of them is exactly the round-9 defect one round on). A SECOND TERM
-- reports the same fact the template term reports -- "what would a re-cut leave standing?" --
-- for the charges no template can claim, as ONE aggregated row with `template_id: null`,
-- `status: 'unknown'` and `containment: 'unattributed'`. It asserts nothing about lineage: it
-- says only that these charges exist, that they collide, and that nothing in the register of
-- templates accounts for them. clara.propose_adjustment_template's advisory filters
-- `status = 'live'` and therefore never sees this row, which is correct and not an oversight --
-- that warning's whole content is "retire the sibling instead", and there is no template here
-- to retire.
--
-- THE TWO TERMS ARE DISJOINT BY CONSTRUCTION, so nothing is double counted: a charge is either
-- stamped with a template of this client (term 1 counts it, through
-- clara._wdb_template_standing_charges) or it is not (term 2 counts it). `p_exclude` needs no
-- echo in term 2 -- an unattributable charge is by definition not the caller's own template's.
create function clara._wdb_overlapping_siblings(p_client uuid, p_exclude uuid, p_shape text[])
  returns jsonb
  language sql stable security definer set search_path = clara, pg_temp as $$
  with orphan as (
    -- STANDING, MACHINE-POSTED, ROLE='occurrence' -- the same four predicates
    -- clara._wdb_template_standing_charges uses, so the two terms count the same KIND of thing
    -- and differ only on attributability. The shape compared is the entry's OWN
    -- (role='occurrence' means there is nothing to resolve; the census counts occurrences only,
    -- for the money reason argued above).
    select clara._wdb_shape_overlap(clara._wdb_entry_shape(je.id), p_shape) as collide,
           (je.flags -> 'recurring_adjustment' ->> 'period_start') as ps,
           (je.flags -> 'recurring_adjustment' ->> 'period_end') as pe
      from clara.journal_entries je
     where je.client_id = p_client
       and je.flags ? 'recurring_adjustment'
       and (je.flags -> 'recurring_adjustment' ->> 'role') = 'occurrence'
       and je.status = 'approved'
       and je.reversed_by is null
       -- THE TEXT COMPARISON IS THE SAFE DIRECTION: `a.id::text = <stamp>` can never raise,
       -- while casting the stamp to uuid raises 22P02 on the malformed value this term exists
       -- for. The same argument the gate's regex-not-cast reader carries two screens up.
       and not exists (select 1 from clara.adjustment_templates a
                        where a.client_id = p_client
                          and a.id::text = (je.flags -> 'recurring_adjustment' ->> 'template_id'))
  ), orphan_hit as (
    select * from orphan where collide is not null and cardinality(collide) > 0
  )
  select coalesce(jsonb_agg(jsonb_build_object(
             'template_id', q.id,
             'name', q.name,
             'status', q.status,
             'colliding_elements', to_jsonb(q.collide),
             'containment', q.containment,
             'standing', (q.census ->> 'standing')::int,
             'first_period', q.census ->> 'first_period',
             'last_period', q.census ->> 'last_period')
           order by (q.census ->> 'standing')::int desc, q.id), '[]'::jsonb)
    from (select a.id, a.name, a.status, s.collide,
                 case when s.collide = sh.sib and s.collide = p_shape then 'identical'
                      when s.collide = sh.sib then 'contains'
                      when s.collide = p_shape then 'contained'
                      else 'partial' end as containment,
                 clara._wdb_template_standing_charges(p_client, a.id) as census
            from clara.adjustment_templates a
            cross join lateral (select clara._wdb_line_shape(a.lines) as sib) sh
            cross join lateral (select clara._wdb_shape_overlap(sh.sib, p_shape) as collide) s
           where a.client_id = p_client
             and (p_exclude is null or a.id <> p_exclude)
             and s.collide is not null
             and cardinality(s.collide) > 0
          union all
           -- THE UNATTRIBUTED TERM, as ONE row: the reader's question is "is there anything a
           -- re-cut would leave standing", and N separate anonymous rows would say the same
           -- thing N times without naming anybody. The period bounds use the same collate "C"
           -- the template term does -- these are ISO text and a malformed stamp may only
           -- mis-order a DISPLAYED bound, never a count.
           select null::uuid, 'unattributable standing charges', 'unknown',
                  (select array_agg(distinct z order by z)
                     from orphan_hit o2 cross join lateral unnest(o2.collide) z),
                  'unattributed',
                  jsonb_build_object(
                    'standing', (select count(*) from orphan_hit),
                    'first_period', (select min(o3.ps collate "C") from orphan_hit o3),
                    'last_period', (select max(o4.pe collate "C") from orphan_hit o4))
            where exists (select 1 from orphan_hit)) q $$;
revoke all on function clara._wdb_overlapping_siblings(uuid, uuid, text[]) from public;

-- WHAT DOES THIS TEMPLATE SAY IT REPLACES? THE ONE LINEAGE WALK (round 10, lane P1; the OWNER's
-- option (b), ruled 2026-08-04).
--
-- THE CENSUS ABOVE ANSWERS "WHAT COULD A RE-CUT LEAVE STANDING"; THIS BODY ANSWERS "AND IS ANY OF
-- IT MINE TO REPLACE". They are different questions and are deliberately different bodies: the
-- census measures the BOOKS (which siblings collide, what stands under each) and may not guess a
-- lineage; this one reads a RECORDED DECLARATION (clara.adjustment_templates.replaces_template_id,
-- stamped by the professional at propose) and may not guess a collision. Round 9's whole defect
-- was one body doing both from a proxy -- the standing writer's STATUS -- and being wrong in both
-- directions with money. Keeping the two apart is what lets the refusal say exactly as much as it
-- knows: a caution when only the census speaks, an ASSERTION when this body does.
--
-- IT IS ONE BODY BECAUSE TWO DOORS PROMISE ITS OUTCOME (WDB-R2): clara.propose_adjustment_template
-- validates the stamp it is about to write against it (the CAP, below), and
-- clara._adj_run_occurrence_core's shape_already_met refusal decides on it whether it may assert
-- and forbid. Two inline recursive walks with two different caps is precisely the drift that put
-- round 9's discriminant on one door and not the other.
--
-- THE WALK IS UPWARD AND CLIENT-SCOPED. `replaces_template_id -> id` is a PRIMARY KEY hop; the
-- client predicate on the recursive term is belt over the composite FK (which already makes a
-- cross-client edge unstorable) so that a restored or hand-patched row cannot make this body walk
-- out of the caller's tenancy. MEASURED on the lane rig: Index Scan using
-- adjustment_templates_pkey, one row per hop -- which is why no index was added for it (the
-- argument is at the column, SECTION S1).
--
-- THE CAP AND THE CYCLE GUARD ARE BOTH FORGED-GRAPH BELTS, NOT LAWS ABOUT REAL BOOKS. A lawful
-- graph cannot cycle (the FK requires the target to pre-exist and the transition trigger makes the
-- pointer immutable, so every edge points backwards in time and none is ever repointed) and cannot
-- exceed the cap (propose refuses to EXTEND a chain that is already at it -- the root fix at the
-- door that creates the state, so the gate's walk can never truncate on anything these verbs
-- built). What remains is a restored, imported or hand-patched database, and there the honest
-- answer is "I walked this far and stopped": `truncated` says so, and the caller is told rather
-- than silently given a partial answer that looks total.
--
-- 64 IS THE CAP, and it is a number rather than a principle: [WDB-G13] makes every EDIT of a
-- template a new generation, so a chain of 64 is a template a client has revised 64 times. The
-- cost of being generous is one PK lookup per hop on a refusal path; the cost of being mean is a
-- refusal at propose on a lawful history. It is returned in the answer (`cap`) rather than
-- restated at the caller, so the door that refuses and the walk that stops can never disagree
-- about where the edge is.
--
-- A TRUNCATED WALK STILL REPORTS THE ANCESTORS IT FOUND, and the refusal that reads this body is
-- entitled to assert on one of them: an ancestor found by walking real edges IS an ancestor,
-- whatever lies beyond the cap. Truncation means "there may be MORE", never "these may be wrong",
-- and conflating the two would make a forged row switch the gate's honesty OFF -- exactly the
-- fail-open a forged row should not be able to buy.
create function clara._wdb_template_ancestry(p_client uuid, p_template uuid)
  returns jsonb
  language sql stable security definer set search_path = clara, pg_temp as $$
  with recursive cap(n) as (select 64),
  walk(id, replaces, depth, path) as (
    select a.id, a.replaces_template_id, 0, array[a.id]
      from clara.adjustment_templates a
     where a.id = p_template and a.client_id = p_client
    union all
    select n.id, n.replaces_template_id, w.depth + 1, w.path || n.id
      from walk w
      join clara.adjustment_templates n
        on n.id = w.replaces and n.client_id = p_client
     where w.depth < (select c.n from cap c)
       and not (w.replaces = any (w.path))
  )
  select jsonb_build_object(
    -- THE ANCESTORS, NEAREST FIRST -- depth 0 is the caller itself and is deliberately NOT in the
    -- list: a template is never its own predecessor (the S1 CHECK says the same thing in the
    -- storage layer), and a consumer that had to strip the head would one day forget.
    'ancestors', coalesce((select jsonb_agg(to_jsonb(w.id) order by w.depth)
                             from walk w where w.depth > 0), '[]'::jsonb),
    'depth', coalesce((select max(w.depth) from walk w), 0),
    'cap', (select c.n from cap c),
    -- NOT REACHED THE ROOT: some row's pointer was left unfollowed, either because the cap stopped
    -- the walk, because following it would have re-entered the path, or -- [R11 FIX 2026-08-04] -- because
    -- the row it points AT is not there to follow. All three are forged-graph states; all three are
    -- reported the same way because the consumer's decision is the same.
    -- THE THIRD ARM IS THE ONE THE FLAG WAS WRITTEN FOR AND THE ONE IT DID NOT HAVE (W1 finding 5;
    -- Codex round-11 finding 3). MEASURED on a staged register whose non-null pointer named a row
    -- that does not exist: the walk answered {depth:0, ancestors:[], truncated:FALSE} -- "I reached
    -- a root" -- because the recursive term is an INNER JOIN and an unfollowable pointer simply
    -- disappears. The ABI's own sentence ("a true is a forged or restored register") was therefore
    -- false of the exact shape it describes, and clara.propose_adjustment_template -- which refuses
    -- to EXTEND a chain it cannot walk to a root -- was admitting extensions of a damaged one. The
    -- arm is a `not exists` over the walk's own result: a row whose `replaces` is non-null and which
    -- produced no child in this walk stopped before a root, whatever the reason. Cheap (the walk is
    -- at most 65 rows) and it fails in the safe direction: an honest chain has a child for every
    -- non-null pointer, so nothing lawful is newly flagged.
    'truncated', coalesce((select bool_or(w.replaces is not null
                                          and (w.depth >= (select c.n from cap c)
                                               or w.replaces = any (w.path)
                                               or not exists (select 1 from walk x
                                                               where x.id = w.replaces)))
                             from walk w), false)) $$;
revoke all on function clara._wdb_template_ancestry(uuid, uuid) from public;

-- =====================================================================================
-- S2.1a-6 -- WHAT DOES A GENERATION THIS TEMPLATE REPLACES STILL HAVE STANDING OVER THESE
-- MONTHS? THE PERIOD-KEYED LINEAGE AUTHORITY [R11 FIX 2026-08-04; as-built ladder round 11].
--
-- THE TWO MECHANISMS THIS BODY EXISTS TO CLOSE, BOTH MEASURED, BOTH MONEY:
--   (1) THE SILENT RE-CODE DOUBLE (W1 finding 1, HIGH; Codex r11 finding 1, HIGH, confidence
--       1.00). A [WDB-G13] edit that RE-CODES the accounts doubles the books in total silence.
--       gen1 (900:D / 400:C, RM3,000/mo) charges four months and is retired; gen2 (901:D / 401:C,
--       RM1,500/mo) is proposed -- DECLARED or not, it makes no difference -- and all four
--       catch-up months run with propose `warnings: []`, the oracle's `blocked: []`, and no
--       refusal anywhere. Final: RM18,000 of expense against an RM6,000 intention, RM12,000 of an
--       abandoned generation standing forever on the old codes. Both existing defences are keyed
--       on SHAPE COLLISION -- clara._wdb_overlapping_siblings only ever returns shape-colliding
--       siblings, and clara._wdb_rerun_breach is keyed on shape intersection -- so a re-code, whose
--       whole point is that the shape changed, is invisible to both. The recorded ruling: a
--       declared edge needs its own PERIOD-MEMBERSHIP wall, INDEPENDENT OF SHAPE.
--   (2) THE PERIOD-BLIND PROHIBITION (W1 finding 2, HIGH). The gate's union term (a) admitted any
--       recorded ancestor with `standing > 0` counted over ALL PERIODS, with no reachability
--       predicate at all -- so a lawful FORWARD-ONLY re-code (gen2 starting after gen1's last
--       charged month) drew a FALSE assertion that distinct codes "would book those periods a
--       SECOND time", and the first act it offered destroyed an unrelated live template's accrual
--       irrecoverably. The predicate that fixes it is the same one the wall needs: an ancestor's
--       standing charge only proves a double when it lies in a period the replacement CAN BOOK.
--
-- SO THE QUESTION IS ASKED WITH A WINDOW, AND THE WINDOW IS THE CALLER'S:
--   * the poster's admission predicate (5) asks it of THIS PERIOD -- "would running this month
--     re-charge a month a generation I replace still carries?";
--   * the due oracle asks the identical question of the identical period, so the verb and the
--     oracle can never name different reasons for one period (this family's oldest law);
--   * the gate's union term (a) asks it of the template's WHOLE BOOKABLE WINDOW
--     [start_date, coalesce(end_date, 9999-12-31)] -- "is any of this generation's money even
--     reachable by me?" -- which is exactly the reachability predicate finding 2 says was missing.
-- One body, three windows. Nothing here decides what to DO about the answer: the wall, the oracle
-- and the sentence each own their own consequence.
--
-- WHY THE ANCESTRY WALK AND NOT A ONE-HOP READ. `replaces_template_id` is one hop, but a chain is
-- lawful ([WDB-G13] makes every edit a generation and clara._wdb_template_ancestry caps it at 64),
-- and a grandparent's standing charge doubles exactly as hard as a parent's -- measured on the
-- three-generation chain in W1's cleared set, where gen3 declares only gen2 and the refusal
-- correctly names gen1 AND gen2. The walk is the ONE body that answers "who are my generations"
-- (WDB-R2) and this body may not re-derive it.
--
-- THE PERIOD COMPARISON IS TEXT UNDER collate "C", against to_char(...,'YYYY-MM-DD'), and never a
-- cast. These stamps are written by this family but may be MALFORMED on a restored or legacy row
-- (the whole reason the gate's own reader is a regex and not a cast), and a cast that raises
-- 22P02 inside an ADMISSION path would turn a refusal into an error. Text comparison cannot raise.
-- A MALFORMED STAMP IS NOT A SMALLER DATE, AND THIS COMMENT USED TO SAY IT WAS [R12 FIX 2026-08-04 --
-- confirming round, native H2/H3]. It read: "a malformed stamp can therefore only ever mis-place
-- a charge in or out of the window, and the coalesces below place an unstamped one INSIDE it --
-- the fail-closed direction ... never a silent double". The first clause was true; the second was
-- MEASURED FALSE, and it was false in the money direction. Text comparison places a SHORTER
-- string first, so a stamp truncated to month grain ('2026-02') or blanked ('') sorts BELOW
-- '2026-02-01' and the ancestor's charge left the window entirely -- the fail-OPEN direction the
-- sentence promised could not happen, on the exact shape it described (a restored or legacy row).
-- THE LAW IS NOW BUILT, NOT ASSERTED: every stamp read here goes through clara._wdb_iso_day,
-- which returns NULL for anything that is not `^\d{4}-\d{2}-\d{2}$` AND NOT A REAL CALENDAR DAY
-- [R13 FIX 2026-08-04 -- re-confirming round, Codex RC2], so a malformed stamp takes the SAME coalesce
-- default a missing one does and lands INSIDE the window. The second half of that sentence is the
-- re-confirming round's: the regex alone let '2026-13-45' through, and a stamp that sorts ABOVE
-- every real day of its year fails the window's UPPER bound exactly as month grain failed its
-- lower one -- the same silent double, through the hole the first fix left. The claim above is
-- therefore true of null, of month grain, of a blank, of a timestamp grain, of DD/MM/YYYY and of
-- an impossible day alike, and each of those is a cell rather than a sentence.
--
-- OVERLAP, NOT CONTAINMENT. A charge counts when its stamped period overlaps the window at all
-- (`period_end >= window_start and period_start <= window_end`). A part-overlapping generation is
-- still money standing in months the replacement covers, and requiring containment would let a
-- cadence change (monthly -> annual, or an FYE move) walk straight through.
--
-- `last_period_any` IS DELIBERATELY UNBOUNDED. The window says which charges are IN THE WAY; the
-- date a non-doubling replacement may start after is the generation's LAST charge, full stop,
-- and answering that from inside the window would name a date that still re-charges the months
-- after it. It comes from clara._wdb_template_standing_charges -- the body that owns "what does
-- this template have standing" -- so the two counts can never disagree about what standing means.
create function clara._wdb_replaced_generation_standing(p_client uuid, p_template uuid,
    p_from date, p_to date)
  returns jsonb
  language sql stable security definer set search_path = clara, pg_temp as $$
  with anc as (
    select (a #>> '{}')::uuid as id
      from jsonb_array_elements(
             clara._wdb_template_ancestry(p_client, p_template) -> 'ancestors') as t(a)
  ), std as (
    select an.id as tid, je.id as entry_id, je.posting_date,
           (je.flags -> 'recurring_adjustment' ->> 'period_start') as ps,
           (je.flags -> 'recurring_adjustment' ->> 'period_end') as pe
      from anc an
      join clara.journal_entries je
        on je.client_id = p_client
       and je.flags ? 'recurring_adjustment'
       and (je.flags -> 'recurring_adjustment' ->> 'template_id') = an.id::text
       and (je.flags -> 'recurring_adjustment' ->> 'role') = 'occurrence'
       and je.status = 'approved'
       and je.reversed_by is null
     -- [R12 FIX 2026-08-04 -- confirming round, native H2/H3] THE COALESCES NOW CATCH A MALFORMED STAMP
     -- AND NOT ONLY A MISSING ONE. The comment above claimed an unstamped charge lands INSIDE the
     -- window; MEASURED, that was true of NULL and false of every other malformation --
     -- '2026-02' and '' both sort BELOW '2026-02-01' under collate "C" (a prefix sorts first), so
     -- the charge fell out of the window and the replacement posted the double in silence.
     -- clara._wdb_iso_day turns "not an ISO day" into NULL, which is what the coalesce defaults
     -- were always written for.
     where coalesce(clara._wdb_iso_day(je.flags -> 'recurring_adjustment' ->> 'period_end'),
                    '9999-12-31') collate "C"
             >= to_char(p_from, 'YYYY-MM-DD') collate "C"
       and coalesce(clara._wdb_iso_day(je.flags -> 'recurring_adjustment' ->> 'period_start'),
                    '0001-01-01') collate "C"
             <= to_char(p_to, 'YYYY-MM-DD') collate "C"
  )
  select coalesce(jsonb_agg(z.q order by z.q ->> 'template_id'), '[]'::jsonb)
    from (select jsonb_build_object(
                   'template_id', s.tid,
                   'name', (select a.name from clara.adjustment_templates a where a.id = s.tid),
                   'status', (select a.status from clara.adjustment_templates a where a.id = s.tid),
                   'standing_in_window', count(*)::int,
                   'first_period_in_window', min(s.ps collate "C"),
                   'last_period_in_window', max(s.pe collate "C"),
                   'last_period_any',
                     clara._wdb_template_standing_charges(p_client, s.tid) ->> 'last_period',
                   -- THE ENTRY A HUMAN IS SENT TO: the OLDEST standing charge of this generation
                   -- inside the window, ordered the way every other refusal in this file orders a
                   -- window (posting_date, id), so the wall and the gate name the same row.
                   'entry_id', (array_agg(s.entry_id order by s.posting_date, s.entry_id))[1])
              as q
           from std s group by s.tid) z $$;
revoke all on function clara._wdb_replaced_generation_standing(uuid, uuid, date, date) from public;

-- =====================================================================================
-- S2.1b -- IS THIS PERIOD SOUND TO RUN AGAIN? (as-built ladder round 5, recut to a CLASS
-- authority in round 6; the enforcement half of the correct-and-re-run ruling stated at
-- clara._wdb_correction_posting_date.)
--
-- THE INVARIANT, in one sentence: for one client and one stretch of calendar the books may carry
-- at most ONE net machine-posted charge on any given (account, side) -- so every approved posting
-- that COLLIDES with the caller's shape over an overlapping period and has since been corrected
-- must have been neutralised ON THE VERY date it was booked at, no half of it may still be
-- standing, and none of it may still be standing UNCORRECTED under a different authority, before
-- any lane posts into it again. (Round 8 restated "the same shape" as "a colliding shape"; the
-- argument is at clara._wdb_shape_overlap and the measurement is two [WDB-G13] edits that
-- re-accrued ten standing months between them.)
--
-- WHY IT IS ONE BODY WITH TWO ARMS AND NOT TWO BODIES (WDB-R2, and the round-6 finding).
-- clara._acct_role_reserved is the house precedent: ONE authority, one answer shape, a per-
-- DOMAIN arm inside it, consulted by every claiming door. The same shape is used here because
-- the two lanes keep their evidence in different books -- the adjustment lane in
-- clara.journal_entries under its stamp, the fixed-asset lane in its own clara.fa_depreciation
-- register -- while the QUESTION ("is anything of this period still standing un-neutralised on
-- its own date?") is identical. Two bodies is exactly how round 5's remedy came to exist on one
-- lane only; p_stamp selects which BOOKS to read, never whose template or whose authority wrote
-- the row, and an unregistered stamp RAISES rather than answering "sound".
--
-- WHY THE ENFORCEMENT IS HERE AND NOT AT THE CORRECTION DOORS. The doubling can only enter
-- the books through ONE act -- a SECOND occurrence being posted into a period that already
-- carries an unbalanced first one -- and every such act goes through
-- clara._adj_run_occurrence_core's admission (both twins call it, both cadences, both lanes).
-- The correction doors are many, this migration owns only two of them, and a third already
-- exists: clara.approve_wrong_client_correction takes caller-named entry ids, joins them to no
-- document and is granted to bookkeepers. It dates its reversal at clara._book_today() -- the
-- house MYT legal date, which SECTION S5.21 splices in over the session `current_date` this
-- comment used to name (MEASURED on the applied catalog: the live body holds
-- clara._book_today() and no current_date) -- but it is deliberately NOT wired to
-- clara._wdb_correction_posting_date, so its correction of a period-dated posting still lands
-- on TODAY rather than on the corrected entry's own date. Fixing the clock did not make the
-- door safe for this invariant, which is the whole point: a rule enforced only where the build
-- happens to write it is a point-fix; this is the gate.
--
-- THE SUBJECT IS DELIBERATELY WIDER THAN THE INSTANCE (the round-5 lesson: a correctly-placed
-- guard with a too-narrow predicate is still a point-fix; the round-6 lesson: a predicate keyed
-- on a LANE or an IDENTITY is too narrow by construction). Three axes come out of it:
--   correction_out_of_period  a corrected posting whose correction sits on a different date.
--                             The re-run would add its figure on top of a standing one.
--   pair_half_uncorrected     the set is MIXED -- something in it has been corrected and
--                             something else in it is still standing. On the adjustment lane
--                             that is a MIRROR whose occurrence was corrected without it, a
--                             shape clara._wdb_reversal_blocked arm (a) forbids at
--                             clara.reverse_entry but which no wall stands over at the other
--                             doors. The re-run then books a second accrual AND a second
--                             release against ONE surviving release: the accrual month looks
--                             right and the release month is wrong, which is the harder half to
--                             ever notice. STATED AS "MIXED" RATHER THAN "ANY STANDING HALF"
--                             deliberately: an entirely-standing set is not a defect, it is a
--                             period that is simply MET, and each lane's own met-ness test owns
--                             that -- which is why the fixed-asset lane can share this body
--                             without its noop-on-a-charged-period behaviour changing.
--   shape_already_met         an approved, UN-corrected posting standing under some other
--                             authority over an OVERLAPPING period shares at least one
--                             (account, side) with the caller's shape. This is the round-6
--                             generation bypass: the caller's own identity-keyed met-ness test
--                             says "unmet" because the standing entry belongs to a retired
--                             predecessor, and the books say otherwise. Round 8 widened the
--                             comparison from equality to intersection and the payload now
--                             names the colliding elements, because "these collide" without
--                             "on WHAT" is a remedy nobody can follow.
--
-- Returns NULL when the period is sound. The adjustment arm's access path is per-template so it
-- rides ix_je_adj_occurrence (ABI SSC) exactly as the round-5 cut did -- but the DECISION is
-- per-shape, never per-template. Identity is allowed to be an index key; it is not allowed to
-- be the question.
-- [SPLIT D-b2 2026-08-04] THIS IS THE FULL-FORM RE-CREATE, AND IT IS THE ONE `create or replace` IN
-- THIS FILE. D-b0 created this body with its TWO FIXED-ASSET ARMS byte-exact and, in place of
-- the arm below, the "registered stamp with no books arm" refusal -- narrowed, never weakened
-- (census sect.2 Class D measured that both of D-b0's callers pass only
-- p_stamp='depreciation_charges', so their answer was identical to the whole unit's). This
-- statement restores the adjustment arm by re-creating the WHOLE canonical body: every line
-- below, the two FA arms included, is byte-exact from 0042-sections/s2-adjustments.sql
-- L1321-1863, with ONE character sequence changed -- `create function` becomes `create or
-- replace function`, because the body already exists.
-- ITS FA CALLERS PICK THE RESTORED BODY UP WITH NO EDIT, which is why the gate stays ONE body:
-- clara._fa_oldest_unmet_period and clara._fa_run_period_core call it by name and get the SAME
-- answer for the depreciation stamps they pass (the arms are the same text) plus a real answer
-- for the third stamp they never pass. `create or replace` on an ABSENT body would CREATE it
-- silently and D-b0's FA arms would vanish with no error anywhere -- so SECTION 0's probe 7 pins
-- this signature as a [SPLIT-CREATED] anchor first (errata E9, the class D-b1 established when
-- it completed the two reservation shells).
-- FINAL FORM: this is it. No later slice touches this body.
create or replace function clara._wdb_rerun_breach(p_client uuid, p_stamp text, p_shape text[],
    p_period_start date, p_period_end date) returns jsonb
  language plpgsql stable security definer set search_path = clara, pg_temp as $$
declare e record; d record; v_corr date;
        v_standing int := 0; v_corrected int := 0;
        v_first_standing jsonb; v_met jsonb;
        v_met_entry uuid; v_door jsonb; v_wall text;
        v_met_tpl text; v_met_tpl_status text;
        v_collide_all text[];
begin
  -- FAIL CLOSED ON AN UNREGISTERED STAMP. A fourth period-dated poster that reaches this body
  -- with its own key must be adjudicated into clara._wdb_period_stamps(), not silently told its
  -- period is sound -- "silently sound" is precisely how the fixed-asset lane spent a whole
  -- round outside round 5's remedy.
  if p_stamp is null or not (p_stamp = any (clara._wdb_period_stamps())) then
    raise exception 'clara._wdb_rerun_breach was asked about the period stamp "%", which is not in the registry', coalesce(p_stamp, '<null>')
      using errcode = 'CLR10', detail = '{"reason":"period_stamp_unregistered"}';
  end if;
  -- ...AND FAIL CLOSED AGAIN ON A REGISTERED STAMP WITH NO ARM (round 7). The registry answers
  -- "is this a period-dated posting whose correction must ride its own date" -- a question about
  -- an ENTRY's flags. THIS body's p_stamp answers a different question: "which BOOKS hold the
  -- evidence". They are not the same question, and round 7 measured what happens when one
  -- enumeration is made to serve both without an exhaustive dispatch: adding 'fa_disposal' to
  -- the registry passed the check above and then FELL THROUGH to the adjustment arm, which reads
  -- clara.journal_entries under a stamp no adjustment entry carries and answers "sound" for a
  -- fixed-asset question. That is a fail-open manufactured by the fix itself. So the dispatch
  -- below is EXHAUSTIVE over the registry and anything unclaimed raises here, and SECTION S5's
  -- S5.15e census asserts from the catalog that every registered stamp is named in this body --
  -- so a fourth stamp cannot reach production without an arm, at BUILD time rather than at the
  -- first unlucky sweep.
  --
  -- BOTH FIXED-ASSET STAMPS SHARE ONE ARM because they share one book. A disposal's stub charges
  -- are clara.fa_depreciation rows exactly as a run's charges are (0041:2446 mints them in the
  -- same table with the same columns), so "read the client's own charge rows" already covers
  -- them; the arm is chosen by which ledger holds the evidence, never by which verb wrote it.
  if p_stamp = any (array['depreciation_charges', 'fa_disposal']) then
    -- THE FIXED-ASSET ARM READS THE CLIENT'S OWN CHARGE ROWS, never an authority id -- the
    -- instrument clara._fa_oldest_unmet_period already uses to decide what is due. A charge row
    -- and its unwind are the register's two halves of one act, and the register's as-of view
    -- nets to zero only when they carry the SAME effective_date. An unwind effective-dated
    -- elsewhere leaves the charged period reading its old figure while the poster's coverage
    -- probe reports the month uncovered -- so the month is re-charged on top of money that
    -- never left. Scoped to rows this run could re-charge (period_start <= p_period_end):
    -- later rows are not this run's business.
    --
    -- NO MIXED ARM HERE, and it is not an omission: clara._fa_on_approve unwinds EVERY live row
    -- of the entry it is reversing in one statement, so a partially-unwound entry is not a
    -- state this schema can hold. If a future writer makes it reachable, the arm belongs here.
    for d in
      select o.id as charge_id, o.asset_id, o.period_start, o.period_end,
             o.effective_date as charged_at, u.effective_date as unwound_at, o.entry_id
        from clara.fa_depreciation o
        join clara.fa_depreciation u on u.unwind_of = o.id
       where o.client_id = p_client
         and o.period_start <= p_period_end
         and u.effective_date is distinct from o.effective_date
       order by o.period_start, o.id
       limit 1
    loop
      return jsonb_build_object('axis', 'correction_out_of_period', 'entry_id', d.entry_id,
        'role', 'charge', 'posting_date', d.charged_at,
        'correction_posting_date', d.unwound_at, 'asset_id', d.asset_id,
        'period_start', d.period_start, 'period_end', d.period_end);
    end loop;
    return null;
  end if;
  if p_stamp <> 'recurring_adjustment' then
    raise exception 'clara._wdb_rerun_breach was asked about the registered period stamp "%", which has no books arm in this body', p_stamp
      using errcode = 'CLR10', detail = '{"reason":"period_stamp_no_rerun_arm"}';
  end if;

  -- THE ADJUSTMENT ARM. The set is every APPROVED, STAMPED entry of this client that this
  -- stretch of calendar has to answer for and whose account shape COLLIDES with the caller's.
  -- p_shape NULL means "every shape", which no caller uses today and which the tests pin as the
  -- widest read.
  --
  -- IT IS A UNION OF TWO TERMS (round 9), BECAUSE "WHAT DOES THIS PERIOD ALREADY CARRY" IS TWO
  -- QUESTIONS AND ROUNDS 5-8 ASKED ONLY ONE OF THEM:
  --
  --   (A) THE ACT TERM -- "has an ACT that charges this stretch of calendar already run?"  The
  --       entry's own period STAMP overlaps the caller's period, and the shape compared is the
  --       RESOLVED occurrence's (clara._wdb_entry_shape(coalesce(auto_reversal_of, id))): an
  --       accrual and its auto-reversal are ONE act in two entries, so a mirror stands proxy for
  --       its occurrence and comparing the mirror's leg-swapped spelling here would silently drop
  --       every pair out of the set. This is rounds 5-8's law, unchanged to the character.
  --
  --   (B) THE MONEY TERM -- "is money standing on these (account, side) INSIDE this stretch?"
  --       The entry's own POSTING DATE falls inside the caller's period, and the shape compared
  --       is the entry's OWN (clara._wdb_entry_shape(je.id)).
  --
  -- WHY (B) HAD TO EXIST, MEASURED, NOT REASONED (round 9; probes y1/p3-mirror-period.mjs and
  -- y1/p6-unattended.mjs, re-run on this rig). A mirror's money is ALWAYS in the period AFTER the
  -- one its stamp files it under: clara._adj_on_approve writes the OCCURRENCE's period_start /
  -- period_end onto a row it dates v_pe + 1. And a mirror's own shape is the occurrence's
  -- leg-SWAPPED. So under (A) alone an auto-reversal mirror is invisible in both terms at once --
  -- it is not in the set for the month its money actually lands in (the stamp says the month
  -- before), and in the month where it IS in the set the shape compared is not the shape its
  -- money moves. Two ordinary INVERSE templates -- "accrue audit fee RM2,500 monthly,
  -- auto-reverse" and "release audit fee accrual RM2,500 monthly", which is an accountant's
  -- habitual pair and which the (account, side) element makes fully DISJOINT at propose, at sign
  -- and at every run -- therefore never met this gate at all. MEASURED on this rig, unattended,
  -- mode='post' from the second month: after four months the expense account carried a RM10,000
  -- CREDIT balance and the accrual liability a RM10,000 DEBIT balance -- both impossible for the
  -- accounts' own natures -- drifting a further RM2,500 every month, with
  -- clara.adjustment_run_due answering {"due":true,"blocked":[]} throughout. Every month carried
  -- THREE machine postings on the same two codes, two of which moved the SAME (account, side),
  -- which is the literal violation of this body's own stated law four paragraphs down.
  --
  -- (B) ADDS MIRRORS AND NOTHING ELSE, WHICH IS WHY IT IS SAFE TO ADD -- proved from the two
  -- minting sites, not hoped. For a role='occurrence' entry the two terms COINCIDE: its own shape
  -- IS the resolved shape (there is nothing to resolve), and its posting_date IS its stamp's
  -- period_end (the poster dates the draft v_pe), so "posting_date inside the caller's window"
  -- implies "the stamps overlap". (B) is therefore a strict subset of (A) for every non-mirror
  -- row, and the only rows it can newly admit are auto-reversal mirrors whose own money lands
  -- inside the caller's window. Nothing that was in the set before this round leaves it.
  -- The set can hold no third kind of row: section 6 tail 6(a) pins the stamp's writer set at
  -- exactly the poster (role='occurrence') and the hook (role='reversal'), and a CORRECTION
  -- entry -- clara.reverse_entry's mirror, clara._pair_reverse_core's two halves -- carries
  -- reversal_of and NO D-b flags at all, so it is not in this scan under either term.
  --
  -- AND A LAWFUL AUTO-REVERSE TEMPLATE STILL DRAINS ITS WHOLE RAMP, by the design's own pair
  -- law: a mirror is its occurrence leg-SWAPPED, so the mirror that lands on day 1 of month N+1
  -- is fully DISJOINT from that very template's own month-N+1 occurrence and (B) never fires on
  -- it (cell x42.r7b4 walks four consecutive months; x42.r9n1b walks the ramp with the money term
  -- live). The one line shape where a template's own mirror does collide with its own next
  -- occurrence is a template that moves the SAME account in BOTH directions
  -- ({900:D, 400:C, 400:D, 900:C}) -- a degenerate shape whose net charge on an account no reader
  -- can attribute, and whose second month is refused with the colliding codes named and the
  -- ordinary remedy ("give this template distinct account codes") attached. MEASURED, not
  -- assumed: cell x42.r9n1e.
  --
  -- COLLIDES, NOT EQUALS (round 8; the full argument is at clara._wdb_shape_overlap). Exact
  -- array equality made the set membership an IDENTITY test on a key the template author still
  -- controls, and the two ordinary [WDB-G13] edits that vary it -- add an accrual leg, move one
  -- sen into a second accrual code -- were measured re-posting six and four standing months
  -- respectively, unattended, through the due ladder. Sharing ANY (account, side) element is the
  -- predicate, and each colliding element is carried onto the payload so the refusal can name
  -- the codes the professional has to re-cut.
  --
  -- THE PERIOD TERM IS A RANGE OVERLAP, NOT A period_start EQUALITY (round 7). Round 6 keyed the
  -- set on period_start alone, and clara._adj_period_start(client,'monthly',d) and
  -- clara._adj_period_start(client,'annual',d) return the SAME date for the FY-OPENING MONTH. The
  -- consequence was measured in both directions (probes L2R7/p1 and p9c): a standing monthly
  -- January accrual refused the annual template's whole-FY run, and a standing annual FY accrual
  -- refused the monthly January run -- and then ADMITTED February through December. One month of
  -- twelve blocked is not a law, it is an artefact of the key, and the eleven it admits are the
  -- expensive half: a [WDB-G13] edit that changes a template's CADENCE (retire the monthly
  -- accrual, propose the annual one) is an ordinary user story, and under a start-equality key
  -- the annual template's ladder walks the FY and books its figure ON TOP of the twelve monthly
  -- accruals already standing on those very accounts. That is the round-6 double arriving
  -- through the cadence door.
  --
  -- SO THE LAW IS STATED ON THE PERIOD ITSELF: at most one machine-posted charge of a given
  -- account shape may be STANDING over any stretch of a client's calendar. Two periods that do
  -- not overlap are different facts and never collide -- January and February, FY2025 and
  -- FY2026, this month and the next -- which is the whole of "two different periods of the same
  -- cadence must not collide". Two periods that DO overlap are one stretch of calendar carrying
  -- two charges on accounts the books cannot tell apart, and that is exactly the double this
  -- gate exists to refuse, whichever cadences produced it. The remedy is the same sentence
  -- clara._wdb_line_shape already owes the professional: distinct accrual accounts per liability
  -- class.
  --
  -- THE COMPARISON IS ON ISO TEXT, NOT ON A CAST, and that is deliberate rather than lazy. The
  -- stamp's dates are 'YYYY-MM-DD' (jsonb_build_object serialises a DATE as ISO 8601 regardless
  -- of DateStyle), and equal-length ISO strings order byte-for-byte exactly as the dates do --
  -- under `collate "C"`, which is stated so no future collation change can make that an
  -- assumption. Casting the ENTRY side instead would put a possible cast ERROR inside the gate:
  -- a body whose whole job is to answer "is this period sound" must not be able to answer by
  -- raising 22007. It also keeps the to_char idiom round 6 chose so the predicate stays on the
  -- ABI SSC index expressions rather than casting its way off them.
  --
  -- AN ENTRY THAT CANNOT STATE ITS OWN PERIOD IS IN THE SET. Both minting sites write
  -- period_start AND period_end into the stamp (the poster at the draft INSERT, the hook at the
  -- mirror INSERT) and section 6 tail 6(a) pins that writer set at exactly those two, so a
  -- stamped entry missing or malforming either key is unreachable today -- which is precisely
  -- why the arm is written: an absent or non-ISO key would make the range comparison NULL, NULL
  -- drops the row from the set, and a dropped row is a fail-OPEN in the one body whose whole job
  -- is to fail closed. The same argument the NULL-element coalesce in clara._wdb_entry_shape
  -- carries, at the other end of the same gate.
  --
  -- IT READS NO TEMPLATE FOR MEMBERSHIP, and that is deliberate: template_id was round 5's key
  -- and [WDB-G13]'s retire-and-re-propose mints a new one, so a body that joined
  -- clara.adjustment_templates to decide who is IN THE SET would invite the next author to filter
  -- on it. (One template read does happen, far below, purely to choose which REMEDY the refusal
  -- may honestly offer -- it can never change whether the period is met. Its argument is at the
  -- v_met branch.)
  --
  -- THE COST CLAIM THAT USED TO STAND HERE WAS FALSE, AND IS WITHDRAWN RATHER THAN SOFTENED
  -- (round 9, Codex finding 1). This comment asserted that the bound was "the 0003-era partial
  -- index ix_je_client_approved_posting (client_id, posting_date, id)". MEASURED on a 6,001-entry
  -- client, one month's window: the plan is an Index Scan whose Index Cond is `client_id = $1`
  -- AND NOTHING ELSE, `Rows Removed by Filter: 6000`, ~6,760 shared buffers, 12.8 ms for ONE gate
  -- call. The client due oracle runs one gate call PER LIVE TEMPLATE, so this is a reachable
  -- T x E: Codex measured clara.adjustment_run_due at 2.48 s over 100 live templates x 6,000
  -- occurrences and 17.8 s at 50,000. The gate is CORRECT at every scale; it is the sweep's
  -- wall-clock that grows.
  --
  -- AND THE REASON IS STRUCTURAL, NOT A SPELLING -- WHICH IS WHY NO INDEX WAS ADDED HERE. This
  -- body is SECURITY DEFINER and therefore reads as clara_fn_owner, and clara.journal_entries
  -- carries relforcerowsecurity = true -- so RLS applies to the owner too and every qual sits
  -- above a security barrier. Postgres may only turn a qual into an INDEX CONDITION below a
  -- barrier when the qual is LEAKPROOF, and (measured from pg_proc.proleakproof on this rig)
  -- `jsonb_object_field_text` = f, `jsonb_exists` = f, `textregexeq` = f, while `uuid_eq`,
  -- `texteq`, `date_le`, `date_ge` = t. Every term of the period predicate is built out of the
  -- three that are NOT leakproof, so it can only ever be a FILTER for the role this body actually
  -- runs as. MEASURED, not inferred: the same predicate rewritten as a two-sided comparison on
  -- normalised span expressions, with a purpose-built partial expression index on
  -- (client_id, <normalised start>, <normalised end>), plans as a 199-row BitmapOr in 2.5 ms for
  -- a SUPERUSER -- and, as clara_fn_owner, falls straight back to `Index Cond: client_id = $1` +
  -- `Rows Removed by Filter: 6000` at 14.8 ms, i.e. SLOWER than the spelling above, because the
  -- normalisation costs two extra regex evaluations per row and buys nothing. The index was
  -- therefore measured, rejected and NOT shipped; the round-8 spelling stands unchanged.
  --
  -- THE TWO ROOTS THAT WOULD ACTUALLY BOUND IT are both bigger than a fix lane's remit and are
  -- recorded for the owner rather than half-built here:
  --   * make the stamp's period expressible in LEAKPROOF terms -- i.e. carry period_start /
  --     period_end as real DATE columns on clara.journal_entries beside the flags stamp, with the
  --     ISO grammar enforced as a write-time CHECK instead of as this read-time belt. Then
  --     `client_id + a date range` is index-bindable under RLS and the candidate set is bounded
  --     on both sides. That is an S1 DDL change plus a new structural invariant.
  --   * hoist ONE shared per-client period-window scan out of clara.adjustment_run_due's
  --     per-template loop. That splits this derivation in two, which is exactly the drift WDB-R2
  --     forbids, so it needs the owner's call on where the single authority then lives.
  -- What was NOT done, deliberately: bounding the scan by a DERIVED posting-date window. Every
  -- member's posting_date is >= p_period_start (an occurrence is dated its period_end, a mirror
  -- period_end + 1), but the UPPER bound needs "no stamped period is longer than the client's
  -- financial year", which is true only while the cadence vocabulary stays {monthly, annual}
  -- [WDB-G3]. A bound that silently stops being true makes this gate fail OPEN, and trading a
  -- money gate's fail-closed posture for a sweep's wall-clock is not a trade this file makes.
  --
  -- THE COLLISIONS ARE COMPUTED IN A LATERAL, NOT TWICE IN THE PREDICATE. The membership test and
  -- the payload's `colliding_elements` are the SAME derivation, and writing it once is what
  -- stops "why was this refused" and "which codes collided" from ever answering differently.
  -- The OWN shape is taken only for a mirror: for every other row it is the resolved shape by
  -- construction, so the second clara._wdb_entry_shape call is spent exactly where the two terms
  -- can actually disagree and nowhere else.
  for e in
    select je.id, je.posting_date, je.reversed_by,
           coalesce(je.auto_reversal_of, je.id) as occurrence_id,
           (je.flags -> 'recurring_adjustment' ->> 'role') as role,
           -- WHICH TERM PUT THIS ROW IN THE SET. Both the met-ness arm and the payload need it,
           -- and deriving it twice is how two answers about one row start to differ.
           (je.posting_date between p_period_start and p_period_end
              and (p_shape is null or s.own_collision is not null)) as in_money,
           -- THE ELEMENTS THAT ACTUALLY COLLIDED. A row admitted on its OWN money reports its own
           -- elements -- those are the ones the reader has to act on; every other row reports the
           -- act's, exactly as before.
           case when je.posting_date between p_period_start and p_period_end
                     and s.own_collision is not null
                then s.own_collision else s.act_collision end as collision
      from clara.journal_entries je
      cross join lateral (select
                   clara._wdb_entry_shape(coalesce(je.auto_reversal_of, je.id)) as act_shape,
                   case when je.auto_reversal_of is null then null
                        else clara._wdb_entry_shape(je.id) end as own_shape) sh
      cross join lateral (select
                   clara._wdb_shape_overlap(sh.act_shape, p_shape) as act_collision,
                   clara._wdb_shape_overlap(coalesce(sh.own_shape, sh.act_shape), p_shape)
                     as own_collision) s
     where je.client_id = p_client
       and je.status = 'approved'
       and je.flags ? 'recurring_adjustment'
       and (
             -- (A) THE ACT TERM: the stamp's span overlaps the caller's period. Spelled exactly
             -- as round 7 left it -- a malformed key is IN, by the fail-closed argument above.
             ((coalesce(je.flags -> 'recurring_adjustment' ->> 'period_start', '')
                 !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
               or coalesce(je.flags -> 'recurring_adjustment' ->> 'period_end', '')
                 !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
               or ((je.flags -> 'recurring_adjustment' ->> 'period_start') collate "C"
                     <= to_char(p_period_end, 'YYYY-MM-DD')
                   and (je.flags -> 'recurring_adjustment' ->> 'period_end') collate "C"
                     >= to_char(p_period_start, 'YYYY-MM-DD')))
              and (p_shape is null or s.act_collision is not null))
             -- (B) THE MONEY TERM: this entry's OWN posting lands inside the caller's period.
          or (je.posting_date between p_period_start and p_period_end
              and (p_shape is null or s.own_collision is not null))
           )
     order by je.posting_date, je.id
  loop
    if e.reversed_by is null then
      v_standing := v_standing + 1;
      if v_first_standing is null then
        v_first_standing := jsonb_build_object('axis', 'pair_half_uncorrected',
          'entry_id', e.id, 'role', e.role, 'posting_date', e.posting_date,
          'colliding_elements', to_jsonb(e.collision));
      end if;
      -- EVERY STANDING MEMBER'S COLLIDING ELEMENTS, UNIONED (round 10, finding 8). The
      -- payload named only the FIRST standing member's, and the remedy it carries is "give
      -- this template distinct account codes" -- so a window in which BOTH union terms fire
      -- (an occurrence colliding on 900:D and, separately, that template's own MIRROR
      -- colliding on 900:C inside an annual caller window) told the professional to re-cut
      -- ONE code, then refused them again on the next. MEASURED (probe z1/p2-union-seams.mjs
      -- arm B): colliding_elements ["900-D42:D"] where the window actually collides on
      -- 900-D42:D and 900-D42:C. No money moved wrongly -- it is a followability tax -- but
      -- the gate's own stated law two screens up is that a refusal saying "these collide"
      -- without saying WHERE is a remedy the reader cannot follow, and half of where is
      -- half a remedy. CORRECTED members are deliberately excluded: their elements are not
      -- something a re-cut has to clear. NULL survives as NULL (the p_shape-is-null read has
      -- no opinion about elements and must not acquire one here).
      if e.collision is not null then
        v_collide_all := (select array_agg(distinct x order by x)
                            from unnest(coalesce(v_collide_all, '{}'::text[]) || e.collision) x);
      end if;
      -- MET-NESS HAS TWO DOORS NOW, FOR THE TWO GRAINS THE SET IS BUILT ON (round 9).
      --   * a standing role='occurrence' entry whose ACT charges this stretch -- rounds 5-8's
      --     law, verbatim: "has this template's period already been accrued?";
      --   * ANY standing entry that is in the set BY ITS OWN MONEY -- which, per the proof
      --     above, can only ever be an auto-reversal MIRROR whose posting lands inside this
      --     window and whose own (account, side) elements collide. Its money is standing here
      --     and a second machine charge on the same element is the double this gate exists to
      --     refuse, whichever role wrote it.
      -- pair_half_uncorrected stays exactly as reachable as it was: it needs v_met NULL, and a
      -- mirror in the set by the ACT term ALONE (the classic case -- occurrence corrected, mirror
      -- still standing in the NEXT period) has its money outside this window, so it does not
      -- stamp v_met. Cell x42.r9n1d walks that state and pins the axis.
      if v_met is null and (e.role = 'occurrence' or e.in_money) then
        v_met := jsonb_build_object('axis', 'shape_already_met', 'entry_id', e.id,
          'role', e.role, 'posting_date', e.posting_date,
          'colliding_elements', to_jsonb(e.collision));
        -- The ENTRY, not the resolved occurrence: clara._adj_correction_door performs the
        -- mirror->occurrence resolution itself, from the entry alone, and owning that
        -- resolution in one body is what stops the gate and the run-receipt card from ever
        -- naming two different ids for one correction.
        v_met_entry := e.id;
      end if;
    else
      v_corrected := v_corrected + 1;
      select c.posting_date into v_corr from clara.journal_entries c where c.id = e.reversed_by;
      if v_corr is distinct from e.posting_date then
        return jsonb_build_object('axis', 'correction_out_of_period', 'entry_id', e.id,
          'role', e.role, 'posting_date', e.posting_date,
          'correction_entry_id', e.reversed_by, 'correction_posting_date', v_corr,
          'colliding_elements', to_jsonb(e.collision));
      end if;
    end if;
  end loop;
  -- PRECEDENCE. correction_out_of_period still returns from INSIDE the loop and so outranks
  -- both arms below -- it names two dates and is the sharpest diagnosis available, and a set
  -- holding one is unsound whatever else it holds. What follows is the order of the other two.
  --
  -- ORDER OF THE REMAINING TWO ARMS, RE-DERIVED FROM THE SET'S OWN STATE (round 7). Round 6
  -- returned pair_half_uncorrected whenever the set was mixed, stamped at whichever standing
  -- member the scan happened to reach first, and justified it in a comment that argued the
  -- divergent set was unreachable and the two spellings indistinguishable. BOTH claims were
  -- false, and the comment has been deleted rather than softened -- a comment that argues a
  -- falsehood is worse than no comment. The set was PRODUCED (probe r7x1/p4) through three
  -- granted verbs with no forgery: template A auto-reverses and is corrected in-period through
  -- clara.reverse_adjustment_pair (leaving a corrected occurrence AND a corrected mirror in the
  -- set), template B posts the SAME shape into the same period and stands. And the spellings are
  -- anything but indistinguishable -- shape_already_met is a BENIGN fact with a followable
  -- remedy, while every other axis maps to the TERMINAL period_correction_unsound at both the
  -- poster and the oracle, whose remedy is "retire this template". A healthy template was being
  -- told to retire itself because of the order the scan happened to run in.
  --
  -- SO MET-NESS OUTRANKS MIXEDNESS, unconditionally: if this client's overlapping calendar
  -- carries a standing, un-corrected posting that COLLIDES with the caller's shape then the
  -- period IS met, whatever else the set holds, and that is the honest diagnosis. (Round 8
  -- changed the membership test from equality to collision, so "met" now means "a standing
  -- posting collides" -- one element is enough, and the entry the refusal names is the entry
  -- that actually collided, carrying the colliding elements with it. Round 9 added the second
  -- met-ness door, for a mirror standing on its own money inside this window.)
  -- pair_half_uncorrected is reachable only when the period is NOT met -- which now means every
  -- standing member is a MIRROR that is in the set by the ACT term alone, i.e. one whose
  -- occurrence was corrected without it and whose own money lies OUTSIDE this window. That is
  -- exactly the fact the axis is named for, and it can only ever be returned about that fact.
  if v_met is not null then
    -- THE REMEDY IS ASKED OF THE ONE BODY THAT OWNS THE QUESTION, NEVER GUESSED (WDB-R2). This
    -- axis's refusal tells a human to correct the standing entry; WHICH door actually admits
    -- that entry today is clara._adj_correction_door's question, and it is the same question
    -- clara._adj_run_json's `correctable` asks for the run-receipt card. Round 6 hard-coded
    -- clara.reverse_entry and handed the reader a verb that refuses CLR39 adjustment_pair_locked
    -- on every auto-reverse pair; round 7 asked clara._wdb_reversal_blocked inline here and
    -- handed the reader clara.reverse_adjustment_pair even when THAT verb refuses CLR10
    -- pair_already_active. Both were the same defect -- a second opinion about another verb's
    -- admission logic -- and the cure is one authority, asked, not two inline copies.
    --
    v_door := clara._adj_correction_door(v_met_entry);
    v_wall := v_door ->> 'wall';

    -- WHO WROTE THE CHARGE IN THE WAY? TWO REPORTED FACTS -- AND, SINCE ROUND 10, NOTHING MORE.
    --
    -- WHAT ROUND 9 DID WITH THEM AND WHY IT IS GONE. Round 9 turned `standing_template_status`
    -- into a DISCRIMINANT: `retired` was read as "this is the generation the caller replaces",
    -- and the poster's refusal then ASSERTED that lineage and PROHIBITED the distinct-codes act.
    -- The comment that shipped with it argued the proxy erred only in the safe direction ("a
    -- retired sibling that is NOT this template's predecessor merely loses a remedy it did not
    -- need"). Round 10 measured it wrong in BOTH directions, each with money -- the retired
    -- SIBLING whose only offered act erased RM6,000 of a legitimate audit accrual, and the order
    -- bypass that reads `live` and reprints the doubling instruction for RM18,000 against an
    -- RM6,000 intention. That argument has been DELETED rather than softened, on this file's own
    -- rule: a comment that argues a falsehood is worse than no comment. The full measurement,
    -- and the census that replaced the inference, are at clara._wdb_overlapping_siblings.
    --
    -- THEY ARE STILL CARRIED, because a reader is entitled to know WHICH template's charge is
    -- standing and what state it is in -- the two facts are true, cheap and load-bearing for a
    -- human. What no consumer may do is BRANCH on the status: it is a snapshot whose value
    -- depends on the order the professional clicked in, and the ladder's whole recurring defect
    -- family is a body promising an outcome it has no state to know (WDB-R2).
    --
    -- IT CANNOT CHANGE WHETHER THE PERIOD IS MET. The read happens AFTER v_met is decided and
    -- feeds two advisory keys and nothing else, which is why "the membership test reads no
    -- template at all" upstairs is still true to the character.
    --
    -- THE UUID IS MATCHED, NOT CAST. A failed cast inside a diagnosis turns the diagnosis into an
    -- error 22P02 -- the same argument clara._adj_correction_door's regex-not-cast detail reader
    -- carries, and the same one the poster's jsonb_typeof guard carries.
    --
    -- OPTION (b) HAS SINCE BEEN TAKEN, AND IT DID NOT MOVE THESE TWO KEYS [round 10, lane P1; the
    -- owner ruled the fork on 2026-08-04 as an ADDITIVE [WDB-G13] amendment -- template
    -- immutability and the retire-and-re-propose idiom are unchanged; a replacement now merely
    -- RECORDS what it replaces]. clara.adjustment_templates.replaces_template_id is stamped at
    -- propose, is immutable, and lets the poster's refusal ASSERT a lineage instead of cautioning
    -- about one. What it deliberately did NOT do is turn the status back into a discriminant: the
    -- assertion is driven by the RECORDED edge (clara._wdb_template_ancestry), read at the refusal
    -- and nowhere near this membership scan, so everything the paragraph above says still holds --
    -- these two keys remain reported facts and no consumer may branch on the status. A template
    -- proposed before that column existed, or by a professional who did not declare a predecessor,
    -- carries no edge at all and lands on lane O1's measured caution, which is why that grammar is
    -- the fallback rather than dead code.
    select nullif(je.flags -> 'recurring_adjustment' ->> 'template_id', '') into v_met_tpl
      from clara.journal_entries je where je.id = v_met_entry;
    if v_met_tpl ~ '^[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$' then
      select a.status into v_met_tpl_status from clara.adjustment_templates a
        where a.id = v_met_tpl::uuid and a.client_id = p_client;
    end if;
    v_met := v_met || jsonb_build_object(
      'standing_template_id', v_met_tpl,
      'standing_template_status', coalesce(v_met_tpl_status, 'unknown'));
    -- THE WINDOW'S FULL COLLISION SET, stamped over the first standing member's (the union
    -- argued in the loop above). Only when there IS one: a p_shape-is-null read keeps its
    -- no-opinion `null`.
    if v_collide_all is not null then
      v_met := v_met || jsonb_build_object('colliding_elements', to_jsonb(v_collide_all));
    end if;

    return v_met || case
      when (v_door ->> 'verb') is null then
        -- NULL IS TYPED. jsonb_build_object takes "any", and a bare NULL literal is `unknown`
        -- there -- which raises at RUNTIME, in the one branch that exists precisely because
        -- something unexpected happened. A defensive arm that itself throws is not defensive.
        -- `correction_wall_advice` is carried ONLY on this arm because it is the only one whose
        -- consumer composes a "cannot be corrected directly" sentence -- and a token with no
        -- act behind it is the walled corridor in miniature [round 10]. It stays jsonb-null
        -- rather than absent when the wall's owning body composed no sentence, so a reader
        -- never has to tell "no advice" from "key not written".
        jsonb_build_object('correction_verb', null::text,
                           'correction_entry', v_door -> 'entry',
                           'correction_wall', coalesce(v_wall, 'reversal_blocked'),
                           'correction_wall_advice', coalesce(v_door -> 'wall_advice', 'null'::jsonb))
      when v_wall is null then
        jsonb_build_object('correction_verb', v_door ->> 'verb',
                           'correction_entry', v_door -> 'entry')
      else
        jsonb_build_object('correction_verb', v_door ->> 'verb',
                           'correction_entry', v_door -> 'entry',
                           'correction_wall', v_wall) end;
  end if;
  if v_standing > 0 and v_corrected > 0 then
    -- THE SAME UNION on the mixed-set payload. This axis is terminal (its remedy is "retire
    -- this template"), so the elements are informational rather than followable here -- but two
    -- payloads out of one loop naming DIFFERENT collision sets for one window is exactly the
    -- kind of drift that makes a reader distrust both.
    if v_collide_all is not null then
      v_first_standing := v_first_standing
        || jsonb_build_object('colliding_elements', to_jsonb(v_collide_all));
    end if;
    return v_first_standing;
  end if;
  return null;
end $$;
revoke all on function clara._wdb_rerun_breach(uuid, text, text[], date, date) from public;

-- =====================================================================================
-- S2.2 -- THE TEMPLATE FAMILY (design SS2.2; WD-R8/R9). The house rule-family shape
-- (propose -> sign -> retire) with the SIGN floor at admin+, cloned from the 0041
-- depreciation-authority trio. A template is IMMUTABLE outside its transitions [WDB-G13]:
-- "editing" is retire + propose again, which re-ramps by construction because the new
-- template has no approved occurrences.
--
-- WHO TAKES THE LEAF. propose and retire WRITE role-claiming state (they add / release a
-- template's claim on its line accounts), so both take clara._fa_lock_roles -- LEAF-LAST,
-- after the 203005004 client rung, which is the pinned acquisition order for every taker.
-- SIGN claims no new account role (the lines were fixed at propose) and is therefore NOT a
-- taker; it takes only the client rung, which is what the FYE revalidation needs.
-- =====================================================================================

-- `p_replaces` IS OPTIONAL AND LAST, AND BOTH HALVES OF THAT ARE THE HOUSE SIGNATURE LAW [round
-- 10, lane P1; the OWNER's option (b)]. LAST + DEFAULT NULL is what makes this an ADDITIVE ABI
-- delta: every existing named-argument caller (the dashboard's rpc mapper, the x42 batteries, the
-- runtime) compiles and behaves EXACTLY as before, and the grant loop's one signature string is
-- the only place the arity is restated. Making it required would have re-cut every caller for a
-- fact most proposals do not have.
--
-- WHAT IT DECLARES, and why the DB may believe it. This is the professional saying "the template I
-- am proposing REPLACES that one" at the moment they would otherwise say it in a memo. It is the
-- one fact rounds 8-10 kept trying to infer from a status snapshot and kept getting wrong with
-- money; a declaration is not an inference, and once recorded it is immutable (SECTION S1).
create function clara.propose_adjustment_template(p_client uuid, p_name text, p_cadence text,
    p_start_date date, p_end_date date, p_auto_reverse boolean, p_lines jsonb,
    p_memo_template text, p_op_key text, p_replaces uuid default null)
  returns jsonb
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare
  c record; v_dedupe jsonb; v_firm uuid; v_id uuid; v_lines jsonb; v_hash text;
  v_dr bigint := 0; v_cr bigint := 0; v_n int; v_breach jsonb; x jsonb;
  v_d bigint; v_k bigint; v_warn jsonb := '[]'::jsonb;
  v_repl_status text; v_anc jsonb;
  v_repl_root uuid;    -- [R12 FIX 2026-08-04] the predecessor's lineage root, read with its status
  v_constraint text;   -- [R11 FIX 2026-08-04] which of this table's partial uniques raised -- three now
begin
  c := clara._human_ctx(clara.role_rank('bookkeeper'));
  if p_op_key is null or btrim(p_op_key) = '' then
    raise exception 'op_key is required' using errcode = 'CLR10';
  end if;

  -- ARGUMENT VALIDATION RUNS BEFORE THE RESERVATION, because the op-key request hash is
  -- ('client', p_client, 'hash', content_hash) (ABI SSE) and the content hash is only
  -- computable once the lines canonicalise. A malformed proposal therefore never occupies an
  -- op_receipts slot at all.
  if p_name is null or btrim(p_name) = '' then
    raise exception 'a template name is required'
      using errcode = 'CLR10', detail = '{"reason":"template_name_required"}';
  end if;
  if p_memo_template is null or btrim(p_memo_template) = '' then
    raise exception 'a memo template is required -- it is the memo every occurrence carries'
      using errcode = 'CLR10', detail = '{"reason":"template_memo_required"}';
  end if;
  -- [WDB-G3] the cadence vocabulary is monthly + annual, and nothing else.
  if p_cadence is null or p_cadence not in ('monthly', 'annual') then
    raise exception 'template cadence must be monthly or annual (WDB-G3)'
      using errcode = 'CLR10', detail = '{"reason":"template_cadence_invalid"}';
  end if;
  if p_auto_reverse is null then
    raise exception 'auto_reverse must be stated true or false'
      using errcode = 'CLR10', detail = '{"reason":"template_auto_reverse_required"}';
  end if;
  if p_start_date is null then
    raise exception 'a start date is required'
      using errcode = 'CLR10', detail = '{"reason":"template_start_required"}';
  end if;
  -- THE SUPPORTED DATE DOMAIN, AT THE DOOR THAT LETS A DATE IN (round 8). Every period bound
  -- this family ever derives descends from start_date, and every one of them is serialised into
  -- an entry's period stamp and compared as ISO text by clara._wdb_rerun_breach -- whose
  -- four-digit form can faithfully carry AD 0001-01-01 .. 9999-12-31 and nothing else. Refusing
  -- HERE rather than teaching the gate about eras is the root fix: a BC or five-digit stamp is
  -- not a comparison problem, it is a date this product has no accounting meaning for, and one
  -- accepted at propose brings the client's WHOLE calendar into every gate's set (measured: a
  -- BC-dated occurrence made May 2026 read as shape_already_met). The full measurement is at
  -- clara._wdb_iso_date_supported.
  if not clara._wdb_iso_date_supported(p_start_date) then
    raise exception 'the start date % is outside the supported range 0001-01-01 .. 9999-12-31 (AD)', p_start_date
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_date_unsupported', 'axis', 'start_date',
          'supported_from', date '0001-01-01', 'supported_to', date '9999-12-31')::text;
  end if;
  if not clara._wdb_iso_date_supported(p_end_date) then
    raise exception 'the end date % is outside the supported range 0001-01-01 .. 9999-12-31 (AD)', p_end_date
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_date_unsupported', 'axis', 'end_date',
          'supported_from', date '0001-01-01', 'supported_to', date '9999-12-31')::text;
  end if;
  if p_end_date is not null and p_end_date < p_start_date then
    raise exception 'the end date precedes the start date'
      using errcode = 'CLR10', detail = '{"reason":"template_window_invalid"}';
  end if;

  -- THE LINE SHAPE (ABI SSC): an array of at least two rows; exactly one of debit/credit
  -- positive per row; balanced to the sen. An occurrence ALWAYS carries a charge, which is
  -- why the zero-charge noop branch the 0041 poster needs does not exist here [L3/11].
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' then
    raise exception 'template lines must be a JSON array'
      using errcode = 'CLR10', detail = '{"reason":"template_lines_invalid","axis":"shape"}';
  end if;
  v_n := jsonb_array_length(p_lines);
  if v_n < 2 then
    raise exception 'a template needs at least two lines'
      using errcode = 'CLR10', detail = '{"reason":"template_lines_invalid","axis":"too_few"}';
  end if;
  for x in select value from jsonb_array_elements(p_lines) loop
    if jsonb_typeof(x) <> 'object' or nullif(btrim(coalesce(x ->> 'account_code', '')), '') is null then
      raise exception 'every template line needs an account_code'
        using errcode = 'CLR10',
          detail = '{"reason":"template_lines_invalid","axis":"account_code"}';
    end if;
    v_d := coalesce((x ->> 'debit_cents')::bigint, 0);
    v_k := coalesce((x ->> 'credit_cents')::bigint, 0);
    if v_d < 0 or v_k < 0 or (v_d > 0) = (v_k > 0) then
      raise exception 'every template line carries exactly one positive side (debit or credit), in cents'
        using errcode = 'CLR10',
          detail = jsonb_build_object('reason', 'template_lines_invalid', 'axis', 'one_side',
            'account_code', x ->> 'account_code')::text;
    end if;
    v_dr := v_dr + v_d;
    v_cr := v_cr + v_k;
  end loop;
  if v_dr <> v_cr then
    raise exception 'template lines must balance exactly to the sen (debit % vs credit %)', v_dr, v_cr
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_lines_invalid', 'axis', 'unbalanced',
          'debit_cents', v_dr, 'credit_cents', v_cr)::text;
  end if;

  v_lines := clara._adj_canon_lines(p_lines);
  v_hash := clara._adj_template_hash(btrim(p_name), p_cadence, p_start_date, p_end_date,
    p_auto_reverse, v_lines, p_memo_template);

  -- THE LINEAGE DECLARATION IS PART OF THE REQUEST'S IDENTITY, and it has to be [round 10, lane
  -- P1]. content_hash covers {name, cadence, start, end, auto_reverse, lines, memo} and NOT the
  -- declaration, so without this term two proposals that differ ONLY in what they say they replace
  -- hash identically: a caller who retried one op_key with a CORRECTED p_replaces would be handed
  -- the first receipt and would believe a declaration that was never written. clara._reserve_op
  -- already has the right refusal for that shape ('op_key reused with different args', CLR10) --
  -- it just needs to be able to SEE the difference.
  --
  -- THE TERM IS CONDITIONAL SO ABI SSE IS UNTOUCHED FOR EVERY EXISTING CALLER: with p_replaces
  -- NULL the object is byte-for-byte the ('client', 'hash') pair ABI SSE pins, so no receipt this
  -- product has ever minted changes shape. Only a proposal that MAKES a declaration carries it.
  v_dedupe := clara._reserve_op(c.firm, 'propose_adjustment_template', p_op_key,
    clara._hash(jsonb_build_object('client', p_client, 'hash', v_hash)
      || case when p_replaces is null then '{}'::jsonb
              else jsonb_build_object('replaces', p_replaces) end));
  if v_dedupe is not null then return v_dedupe; end if;

  select cl.firm_id into v_firm from clara.clients cl where cl.id = p_client;
  if v_firm is null or v_firm <> c.firm then
    raise exception 'client is not in your firm' using errcode = 'CLR11';
  end if;

  -- THE CLIENT RUNG, THEN THE LEAF (the pinned order for every role-claiming writer). The
  -- rung is what makes the FY read below and the reservation read under the leaf ONE
  -- lock-holding transaction against a concurrent clara.set_client_fy_end or enrolment.
  perform pg_advisory_xact_lock(203005004, hashtext(p_client::text));

  -- START AND END ARE CADENCE BOUNDARIES, VALIDATED AGAINST THE CLIENT'S CURRENT FY
  -- [L2/23, L7/3]. start_date MUST be a period START (the first eligible period begins at
  -- it, so a mid-period start would silently shift every window); end_date, when stated,
  -- MUST be a period END (else the last occurrence would straddle a partial period and the
  -- admission window would never close cleanly). For an ANNUAL template both are FY-relative,
  -- which is why clara.set_client_fy_end refuses while a live annual template exists and why
  -- sign re-validates: the propose -> FYE-change -> sign window is the one gap left, and
  -- sign closes it.
  if clara._adj_period_start(p_client, p_cadence, p_start_date) is distinct from p_start_date then
    raise exception 'the start date % is not the first day of a % period for this client', p_start_date, p_cadence
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_fy_stale', 'axis', 'start_date',
          'cadence', p_cadence, 'expected',
          clara._adj_period_start(p_client, p_cadence, p_start_date))::text;
  end if;
  if p_end_date is not null
     and clara._adj_period_end(p_client, p_cadence, p_end_date) is distinct from p_end_date then
    raise exception 'the end date % is not the last day of a % period for this client', p_end_date, p_cadence
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_fy_stale', 'axis', 'end_date',
          'cadence', p_cadence, 'expected',
          clara._adj_period_end(p_client, p_cadence, p_end_date))::text;
  end if;

  -- THE DATE THE CADENCE DERIVES IS ASKED THE SAME QUESTION AS THE DATE THE HUMAN SUPPLIED
  -- (round 9, Codex finding 2). Round 8 domain-checked start_date and end_date -- the two dates a
  -- caller can type -- and a template's periods are DERIVED from start_date, not typed. MEASURED:
  -- a client with FYE 30 November and an ANNUAL template starting 9999-12-01 proposes and SIGNS
  -- live, because 9999-12-01 is inside the domain AND is a genuine annual period start; its first
  -- period then ENDS 10000-11-30, and every run of it is refused CLR38
  -- period_request_invalid/date_unsupported, forever. A template that signs live and can never
  -- run is a walled corridor in time, and the door that let the date in is this one.
  --
  -- THE FIRST DERIVED END IS SUFFICIENT, and this is the whole of "any end the cadence can derive
  -- inside the template's own life": with end_date STATED, it is itself domain-checked above and
  -- is a period end, so every derived end in between is <= it; with end_date NULL, the only
  -- derived end that can leave the domain is the first one, because every later period opens the
  -- day after its predecessor closes and the poster refuses any period that has not ENDED in MYT
  -- (v_pe >= clara._fa_today()) long before the calendar could reach year 10000. The cadence
  -- algebra itself does not overflow -- Postgres DATE runs to 5874897-12-31 -- so this is a
  -- DOMAIN refusal, not an arithmetic guard.
  --
  -- IT IS ASKED HERE, AFTER THE FY ALIGNMENT, because the derivation needs the client's financial
  -- year and therefore the 203005004 rung, and because a start date that is not a period start at
  -- all deserves its own refusal (template_fy_stale) before this one.
  if not clara._wdb_iso_date_supported(clara._adj_period_end(p_client, p_cadence, p_start_date)) then
    raise exception 'this template''s first % period would end % , which is outside the supported range 0001-01-01 .. 9999-12-31 (AD)', p_cadence, clara._adj_period_end(p_client, p_cadence, p_start_date)
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_date_unsupported',
          'axis', 'derived_period_end', 'cadence', p_cadence, 'period_start', p_start_date,
          'period_end', clara._adj_period_end(p_client, p_cadence, p_start_date),
          'supported_from', date '0001-01-01', 'supported_to', date '9999-12-31')::text;
  end if;

  -- LEAF-LAST. propose CLAIMS the line accounts for this template, so it serialises against
  -- every other role-claiming writer on this client through the one `client:fa-roles` leaf.
  perform clara._fa_lock_roles(p_client);

  v_breach := clara._adj_line_eligibility_breach(p_client, v_lines);
  if v_breach is not null then
    raise exception 'template line account % cannot back a recurring adjustment (%)', v_breach ->> 'account_code', v_breach ->> 'axis'
      using errcode = 'CLR10',
        detail = (jsonb_build_object('reason', 'template_line_ineligible') || v_breach)::text;
  end if;

  -- THE FRIENDLY DUPLICATE REFUSAL. The partial unique index is the durable half; this is the
  -- half that names the twin, so a human sees which template they already have.
  if exists (select 1 from clara.adjustment_templates t
             where t.client_id = p_client and t.content_hash = v_hash
               and t.status in ('proposed', 'live')) then
    raise exception 'this client already has a proposed or live template with identical content; retire it before proposing the same one again'
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_duplicate', 'content_hash', v_hash)::text;
  end if;

  -- ------------------------------------------------------------------------------------
  -- THE LINEAGE DECLARATION (round 10, lane P1; the OWNER's option (b)). FAIL-CLOSED: a
  -- declaration this body cannot verify is REFUSED, never stored and never softened into a
  -- warning -- because the gate downstream will ASSERT on it and forbid a lawful act, and an
  -- assertion is only allowed to rest on a fact that was checked at the door that wrote it.
  --
  -- IT IS VALIDATED HERE, AFTER THE RESERVATION AND UNDER THE CLIENT RUNG, and that placement is
  -- deliberate rather than lazy: every term of it is a READ of this client's template register
  -- (existence, tenancy, status, chain depth), so it cannot run before the firm check that
  -- establishes the caller may read that register at all, and it must run under the 203005004 rung
  -- so a concurrent clara.retire_adjustment_template cannot move the predecessor's status between
  -- the read and the INSERT. It sits with the other two register-reading refusals
  -- (template_line_ineligible, template_duplicate) for exactly that reason.
  --
  -- THREE TERMS, EACH REFUSED BY NAME, and each refusal names an act the caller can actually take
  -- (WDB-R2 -- the remedy in a refusal is a promise about another door):
  --   (i)   THE PREDECESSOR MUST BE A TEMPLATE OF THIS CLIENT. The read is client-scoped, so a
  --         forged id, a deleted-and-restored id and ANOTHER CLIENT'S template all land here as
  --         one fact -- "these books have no such template" -- rather than three, and none of them
  --         can be used to probe whether some other client owns that id (the CLR11 read-shape
  --         discipline this file already keeps at clara.get_adjustment_run).
  --   (ii)  IT MUST BE RETIRED. [WDB-G13]'s edit is retire-and-re-propose, and a replacement for
  --         something still LIVE is not a replacement, it is a second live template moving the
  --         same accounts -- the state the poster refuses every month and the state O1's propose
  --         advisory already warns about. Refusing here is what keeps the recorded fact TRUE:
  --         "replaces" must mean the predecessor stopped.
  --         WHAT THIS COSTS THE PROPOSE-FIRST ORDER, MEASURED RATHER THAN WAVED AWAY [R12 FIX
  --         2026-08-04 -- confirming round, Codex CXR1]. The sentence that stood here said the
  --         propose-first order "keeps working exactly as lane O1 shipped it, WITHOUT p_replaces
  --         and with its warning". The warning was the false half: round 11's term (c) scanned
  --         RETIRED siblings only, and in this order the predecessor is LIVE at propose -- so
  --         the pair got no declaration (refused here), no wall (predicate (5) needs a recorded
  --         edge) and no advisory (no retired subject) AT ONCE. MEASURED end to end: four
  --         already-charged months re-ran on fresh codes for RM1,800,000 against an RM600,000
  --         intention, with `warnings: []`, `blocked: []` and the sweep advertising it as due.
  --         The order is still lawful and still refused nothing; what changed is that the
  --         advisory now covers LIVE siblings too (clara._wdb_period_overlap_advisory) and is
  --         re-asked at SIGN, the last human moment before money can move. The two acts that
  --         make the declaration itself possible are unchanged: retire, then propose -- or
  --         propose, retire, and re-propose with the stamp.
  --   (iii) THE CHAIN MUST STILL HAVE ROOM. The gate walks this chain upward under a cap
  --         (clara._wdb_template_ancestry, which OWNS the number); refusing to EXTEND a chain that
  --         is already at it is the root fix -- it means a walk can never truncate on a history
  --         these verbs built, and truncation stays what it should be: a signal of a forged or
  --         restored graph. `truncated` is refused for the same reason and with the same act: a
  --         predecessor whose own ancestry cannot be walked to a root is not a foundation to
  --         assert on.
  -- SELF-REFERENCE IS NOT A TERM HERE because it is not reachable here: `id` is minted by the
  -- table's own default at INSERT, so p_replaces cannot name it. The S1 CHECK stands over the
  -- storage layer for a hand-written row, which is the only writer that could ever try.
  if p_replaces is not null then
    -- [R12 FIX 2026-08-04] The predecessor's LINEAGE ROOT is read with its status, in one statement under
    -- the rung: the root is what term (v) below tests and what this row will carry for the rest of
    -- the chain's life, and reading it twice would be two answers to one question.
    select t.status, coalesce(t.lineage_root_id, t.id)
      into v_repl_status, v_repl_root
      from clara.adjustment_templates t
      where t.id = p_replaces and t.client_id = p_client;
    if v_repl_status is null then
      raise exception 'the template this one says it replaces (%) is not a template of this client; propose it without naming a predecessor, or name one from this client''s own register', p_replaces
        using errcode = 'CLR10',
          detail = jsonb_build_object('reason', 'template_replaces_unknown',
            'replaces_template_id', p_replaces)::text;
    end if;
    if v_repl_status <> 'retired' then
      raise exception 'the template this one says it replaces (%) is still %; retire it first (clara.retire_adjustment_template) and propose this one again, or propose it now without naming a predecessor', p_replaces, v_repl_status
        using errcode = 'CLR10',
          detail = jsonb_build_object('reason', 'template_replaces_not_retired',
            'replaces_template_id', p_replaces, 'replaces_status', v_repl_status)::text;
    end if;
    -- (iv) IT MUST NOT ALREADY HAVE A SUCCESSOR [R11 FIX 2026-08-04 -- Codex round-11 finding 4].
    -- MEASURED: two concurrent sessions each proposed a different child of one retired
    -- predecessor; B waited correctly behind A's 203005004 rung and then also succeeded, both
    -- signed, and the predecessor ended with TWO LIVE DIRECT SUCCESSORS. That is a lineage FORK,
    -- and every consumer of the walk is written for a chain -- "the ancestors" as an ordered list,
    -- a cap that counts "generations", a prohibition that says "the generation this template
    -- replaces" in the singular. Read under the rung with the status read above, so a concurrent
    -- proposer cannot slip between the two; the partial unique index at SS1.1 is the belt for the
    -- writer the rung cannot serialise. The refusal names both acts that exist: take the existing
    -- successor's place by retiring it first, or propose without the declaration.
    if exists (select 1 from clara.adjustment_templates s
                where s.replaces_template_id = p_replaces and s.client_id = p_client
                  and s.status in ('proposed', 'live')) then
      raise exception 'the template this one says it replaces (%) already has a successor on this client; retire that successor first (clara.retire_adjustment_template) and propose this one again, or propose it now without naming a predecessor -- one generation may be replaced once', p_replaces
        using errcode = 'CLR10',
          detail = jsonb_build_object('reason', 'template_replaces_already_succeeded',
            'replaces_template_id', p_replaces,
            'successor_template_id', (select s.id from clara.adjustment_templates s
                                       where s.replaces_template_id = p_replaces
                                         and s.client_id = p_client
                                         and s.status in ('proposed', 'live')
                                       order by s.created_at, s.id limit 1))::text;
    end if;
    -- (v) NO OTHER TEMPLATE OF THIS LINEAGE MAY BE UNRETIRED [R12 FIX 2026-08-04 -- confirming round,
    -- Codex CXR2]. MEASURED: P retired, A replaces P, A retired, B replaces A and goes LIVE, C
    -- replaces P -- and (iv) admits C, because P's only DIRECT successor A is retired. The
    -- lineage ends with TWO LIVE LEAVES, B and C, and on disjoint codes neither branch can see
    -- the other: both book the same months, and every consumer of the walk (an ordered ancestor
    -- list, a cap that counts generations, a prohibition in the singular) is true of one branch
    -- and silent about the other. E30's recorded intent is ONE ACTIVE CONTINUATION per lineage,
    -- which is a fact about the ROOT and cannot be expressed one edge at a time.
    -- THE ROOT IS THE PREDECESSOR'S, INHERITED: coalesce(its own root, itself). Read under the
    -- same 203005004 rung as the status above, so a concurrent proposer cannot slip between the
    -- two; uq_adjustment_templates_one_live_leaf is the belt for the writer the rung cannot
    -- serialise. The refusal NAMES the live template in the way, because "some other template in
    -- this lineage" is not a remedy anyone can follow.
    if exists (select 1 from clara.adjustment_templates s
                where s.client_id = p_client
                  and coalesce(s.lineage_root_id, s.id) = v_repl_root
                  and s.status in ('proposed', 'live')) then
      raise exception 'another template of this lineage (%) is still %; a generation may have only one unretired continuation -- retire that one first (clara.retire_adjustment_template) and propose this again, or propose it now without naming a predecessor', (select s.id from clara.adjustment_templates s where s.client_id = p_client and coalesce(s.lineage_root_id, s.id) = v_repl_root and s.status in ('proposed', 'live') order by s.created_at, s.id limit 1), (select s.status from clara.adjustment_templates s where s.client_id = p_client and coalesce(s.lineage_root_id, s.id) = v_repl_root and s.status in ('proposed', 'live') order by s.created_at, s.id limit 1)
        using errcode = 'CLR10',
          detail = jsonb_build_object('reason', 'template_lineage_root_occupied',
            'replaces_template_id', p_replaces,
            'lineage_root_id', v_repl_root,
            'occupying_template_id', (select s.id from clara.adjustment_templates s
                                       where s.client_id = p_client
                                         and coalesce(s.lineage_root_id, s.id) = v_repl_root
                                         and s.status in ('proposed', 'live')
                                       order by s.created_at, s.id limit 1))::text;
    end if;
    v_anc := clara._wdb_template_ancestry(p_client, p_replaces);
    if (v_anc ->> 'depth')::int >= (v_anc ->> 'cap')::int
       or (v_anc ->> 'truncated')::boolean then
      raise exception 'the template this one says it replaces (%) already stands on a chain of % recorded generation(s) (the limit is %); propose this one without naming a predecessor', p_replaces, v_anc ->> 'depth', v_anc ->> 'cap'
        using errcode = 'CLR10',
          detail = jsonb_build_object('reason', 'template_replaces_chain_too_long',
            'replaces_template_id', p_replaces,
            'axis', case when (v_anc ->> 'truncated')::boolean then 'unwalkable' else 'depth' end,
            'depth', (v_anc ->> 'depth')::int, 'cap', (v_anc ->> 'cap')::int)::text;
    end if;
  end if;

  begin
    -- [R12 FIX 2026-08-04] lineage_root_id is v_repl_root -- the predecessor's own root, or the
    -- predecessor itself when it is one -- and NULL when nothing was declared, which is this
    -- column's spelling for "I am my own root" (argued at the column). It is set here and never
    -- again: the transition trigger's frozen-set subtraction makes it immutable from this moment.
    insert into clara.adjustment_templates(firm_id, client_id, status, name, cadence,
        start_date, end_date, auto_reverse, lines, memo_template, content_hash,
        replaces_template_id, lineage_root_id, proposed_by, proposed_op_key)
      values (c.firm, p_client, 'proposed', btrim(p_name), p_cadence, p_start_date, p_end_date,
        p_auto_reverse, v_lines, p_memo_template, v_hash, p_replaces,
        case when p_replaces is null then null else v_repl_root end, c.actor, p_op_key)
      returning id into v_id;
  exception when unique_violation then
    -- The index caught a twin the precheck could not see (a concurrent proposer inside the
    -- same rung is impossible, but a re-apply against a restored database is not). Same token
    -- either way -- a caller must never have to tell the two apart.
    -- [R11 FIX 2026-08-04] ...BUT THERE ARE NOW TWO PARTIAL UNIQUES ON THIS TABLE, so this handler asks
    -- WHICH ONE bit instead of assuming. Before the single-successor index existed, `unique_
    -- violation` here could only ever mean the content-hash slot; today a lineage fork raced past
    -- the precheck lands here too, and reporting it as `template_duplicate` would send a
    -- professional to look for an identical template that does not exist. `constraint_name` is
    -- the only fact that tells them apart, and it is read rather than inferred from the message.
    -- [R12 FIX 2026-08-04] ...AND THERE ARE NOW THREE. uq_adjustment_templates_one_live_leaf is the
    -- root-keyed belt, and a race past term (v) lands here exactly as a race past term (iv) does.
    get stacked diagnostics v_constraint = constraint_name;
    if v_constraint = 'uq_adjustment_templates_one_live_leaf' then
      raise exception 'another template of this lineage is still unretired; a generation may have only one unretired continuation -- retire that one first (clara.retire_adjustment_template) and propose this again, or propose it now without naming a predecessor'
        using errcode = 'CLR10',
          detail = jsonb_build_object('reason', 'template_lineage_root_occupied',
            'replaces_template_id', p_replaces, 'lineage_root_id', v_repl_root,
            'axis', 'storage_layer')::text;
    end if;
    if v_constraint = 'uq_adjustment_templates_one_successor' then
      raise exception 'the template this one says it replaces (%) already has a successor on this client; retire that successor first (clara.retire_adjustment_template) and propose this one again, or propose it now without naming a predecessor -- one generation may be replaced once', p_replaces
        using errcode = 'CLR10',
          detail = jsonb_build_object('reason', 'template_replaces_already_succeeded',
            'replaces_template_id', p_replaces, 'axis', 'storage_layer')::text;
    end if;
    raise exception 'this client already has a proposed or live template with identical content'
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_duplicate', 'content_hash', v_hash)::text;
  end;

  -- THE DECLARATION IS AUDITED WITH THE PROPOSAL [round 10, lane P1]. The column is immutable, so
  -- the row itself is already the durable record -- but the audit line is where a reviewer reads
  -- WHO declared the lineage the gate later asserts on, and a fact that drives a prohibition
  -- belongs in the trail beside the actor who stated it. The key is always present (jsonb null
  -- when nothing was declared) for the same reason the propose receipt's `warnings` always is.
  perform clara._audit(c.firm, c.actor, null, null, 'propose_adjustment_template', null,
    jsonb_build_object('client', p_client, 'template', v_id, 'cadence', p_cadence,
      'start_date', p_start_date, 'end_date', p_end_date, 'auto_reverse', p_auto_reverse,
      'content_hash', v_hash, 'replaces_template_id', p_replaces, 'op_key', p_op_key));

  -- ------------------------------------------------------------------------------------
  -- THE ADVISORY WARNINGS (round 10). ADVISORY, NOT REFUSALS -- the distinction is the whole
  -- design of this block and it is deliberate on both counts.
  --
  -- (a) A LIVE SIBLING THIS ONE COLLIDES WITH. [WDB-G13] says an edit IS retire + propose
  -- again, and NOTHING in this product requires the retire to come first: propose-then-retire
  -- is the order a professional actually works in (confirm the replacement is right, then
  -- withdraw the old one). MEASURED (probe z1/p5-order-bypass.mjs): worked in that order, the
  -- poster's refusal reads the predecessor as `live`, prints the plain distinct-codes clause,
  -- and following it ran four already-charged months onto fresh codes with blocked:[] --
  -- RM18,000 of expense against an RM6,000 intention. The propose-first ORDER IS LAWFUL AND
  -- MUST STAY, so this is not a refusal; what was missing is that nobody was ever told the
  -- collision exists at the moment they create it. The warning names the sibling id, so the
  -- reader can act on it before the sweep ever runs.
  --
  -- IT FIRES ONLY ON A CONTAINMENT OVERLAP (identical / contains / contained), never on a
  -- PARTIAL one: two liabilities sharing one accrual code is the DESIGNED grain (argued at
  -- clara._wdb_line_shape) and warning on it would be noise the reader must learn to ignore --
  -- which is how a warning stops being read. The three containment shapes are exactly the three
  -- an edit takes: the same accounts (a figure changed), a leg added, a leg removed.
  --
  -- (a) DOES NOT WARN ON A RETIRED SIBLING, and that is term (c)'s subject rather than an
  -- oversight -- [R11 FIX 2026-08-04]. THE JUSTIFICATION THAT STOOD HERE WAS MEASURED FALSE AND HAS BEEN
  -- DELETED RATHER THAN SOFTENED (this file's own rule, stated at clara._wdb_rerun_breach: a
  -- comment that argues a falsehood is worse than no comment). It read: "retire-then-propose is
  -- the lawful order, THE REPLACEMENT IS REFUSED ON THE PREDECESSOR'S STANDING PERIODS rather than
  -- doubling them". Round 11 measured that the replacement was refused on nothing at all once the
  -- codes differed: this advisory returns only SHAPE-COLLIDING siblings and then filters them to
  -- `status='live'`, and clara._wdb_rerun_breach is keyed on shape intersection -- so a RE-CODED
  -- replacement, the commonest [WDB-G13] edit after a figure change, was invisible to every
  -- defence in this file. RM18,000 of expense stood against an RM6,000 intention with
  -- `warnings: []` and `blocked: []` (probe w1i-no-declaration.mjs, no lineage feature used at
  -- all -- the only call shape the dashboard could send).
  -- THE SENTENCE IS TRUE NOW, and it is true because two things were built: admission predicate
  -- (5) in clara._adj_run_occurrence_core actually refuses a replaced generation's standing
  -- periods, and term (c) below tells the professional at the door where the edit is still one
  -- act away from being right.
  --
  -- (b) A START DATE NO MALAYSIAN CLIENT'S BOOKS CAN REACH. Round 8 ruled the supported date
  -- domain AD 0001-01-01 .. 9999-12-31 and that ruling is not touched here: this is a
  -- PLAUSIBILITY floor, not a grammar. MEASURED (probe z1/p3-domain-and-scale.mjs): a monthly
  -- template starting 0001-01-01 -- an ordinary typo for 2001 -- proposes, signs, and
  -- clara.adjustment_run_due advertises {due:true, period 0001-01-01..0001-01-31, blocked:[]},
  -- so the sweep drafts an occurrence dated in the first millennium. Nothing posts unattended
  -- (it is catch-up, so it drafts, and draft-N-blocks-N+1 then parks the template in front of a
  -- human) which is why this is a WARNING and not a refusal: refusing would invent a date law
  -- the design has not ruled, and the smallest honest act is to say so at the door where the
  -- typo is still one edit away from being fixed.
  select coalesce(jsonb_agg(jsonb_build_object(
           'axis', 'colliding_live_sibling',
           'template_id', e ->> 'template_id',
           'name', e ->> 'name',
           'status', e ->> 'status',
           'containment', e ->> 'containment',
           'colliding_elements', e -> 'colliding_elements',
           'standing_charges', (e ->> 'standing')::int,
           'first_period', e ->> 'first_period',
           'last_period', e ->> 'last_period',
           'message', 'template ' || (e ->> 'template_id') || ' ("' || (e ->> 'name')
             || '") is LIVE on this client and '
             || case when (e ->> 'containment') = 'identical'
                       then 'carries exactly this template''s account shape'
                     when (e ->> 'containment') = 'contains'
                       then 'carries a shape this one fully contains (a leg was added)'
                     else 'carries a shape that fully contains this one (a leg was removed)' end
             || '; every period both cover will be refused '
             || 'period_shape_already_met until one of them is retired or re-coded. It already '
             || 'carries ' || (e ->> 'standing') || ' standing charge(s)'
             || case when coalesce((e ->> 'standing')::int, 0) = 0 then ''
                     else ' for ' || coalesce(e ->> 'first_period', 'an unstated period') || ' .. '
                          || coalesce(e ->> 'last_period', 'an unstated period') end
             || '. IF this template replaces that one, retire it and correct those charges: '
             || 'giving this template distinct codes instead would book those periods twice.')
           order by e ->> 'template_id'), '[]'::jsonb)
    into v_warn
    from jsonb_array_elements(
           clara._wdb_overlapping_siblings(p_client, v_id,
             clara._wdb_line_shape(v_lines))) as t(e)
   where (e ->> 'status') = 'live' and (e ->> 'containment') <> 'partial';
  -- (c) A GENERATION WHOSE STANDING MONTHS THIS PROPOSAL REACHES BACK OVER
  -- [R11 FIX 2026-08-04 -- W1 finding 1, the propose-side half of the silent re-code double;
  --  R12 FIX 2026-08-04 -- the confirming round widened its subject from RETIRED to RETIRED-OR-LIVE and
  --  moved it into clara._wdb_period_overlap_advisory, which is now asked at SIGN as well].
  --
  -- THE WHOLE ARGUMENT LIVES AT THE BODY (S2.1a-6b), including why the retired arm has no shape
  -- requirement, why the live arm has one, and what was measured when the term was retired-only.
  -- What belongs HERE is only the caller's window and its own row: this proposal's bookable
  -- window is [p_start_date, p_end_date], its shape is v_lines', and it may not warn about
  -- itself.
  v_warn := v_warn || clara._wdb_period_overlap_advisory(p_client, v_id,
    clara._wdb_line_shape(v_lines), p_start_date, p_end_date);

  if p_start_date < date '1900-01-01' then
    v_warn := v_warn || jsonb_build_array(jsonb_build_object(
      'axis', 'implausible_start_date',
      'start_date', p_start_date,
      'plausible_from', date '1900-01-01',
      'message', 'the start date ' || p_start_date
        || ' is before 1900 -- no Malaysian client''s books begin there, so this is almost '
        || 'certainly a typo. The sweep will offer the first period from that date as catch-up '
        || 'and the template will then park behind that draft. Retire this template and propose '
        || 'one with the intended start date.'));
  end if;

  -- THE KEY IS ALWAYS PRESENT, empty array and all: a caller that has to test for the key's
  -- EXISTENCE before reading it is a caller that will one day forget, and the house rule for
  -- this migration's stamps is that a shape stays stable and says "nothing" honestly.
  return clara._finish_op(c.firm, 'propose_adjustment_template', p_op_key,
    jsonb_build_object('template_id', v_id, 'status', 'proposed', 'content_hash', v_hash,
      'warnings', v_warn));
end $$;
revoke all on function clara.propose_adjustment_template(uuid, text, text, date, date,
  boolean, jsonb, text, text, uuid) from public;

-- SIGN (admin+, WD-R9). The signature is what the autonomy derives from, so it sits with the
-- firm's administration -- and it is re-validated, not merely stamped: cadence, start_date and
-- end_date are re-checked against the client's CURRENT financial year under the 203005004
-- rung, so the propose -> FYE-change -> sign window closes with a named refusal instead of a
-- template whose annual periods silently no longer exist [L7/3].
--
-- signed_by IS THE last_human_editor IDENTITY every occurrence carries (design SS2.2/SS2.3):
-- it is what puts the signer on clara._approve_entry_core's distinct-checker arm when a
-- machine-born high-stakes occurrence reaches CLR05.
create function clara.sign_adjustment_template(p_client uuid, p_template uuid, p_op_key text)
  returns jsonb
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare c record; v_dedupe jsonb; v_firm uuid; t record; v_warn jsonb;
begin
  c := clara._human_ctx(clara.role_rank('admin'));
  if p_op_key is null or btrim(p_op_key) = '' then
    raise exception 'op_key is required' using errcode = 'CLR10';
  end if;
  v_dedupe := clara._reserve_op(c.firm, 'sign_adjustment_template', p_op_key,
    clara._hash(jsonb_build_object('client', p_client, 'template', p_template)));
  if v_dedupe is not null then return v_dedupe; end if;
  select cl.firm_id into v_firm from clara.clients cl where cl.id = p_client;
  if v_firm is null or v_firm <> c.firm then
    raise exception 'client is not in your firm' using errcode = 'CLR11';
  end if;
  perform pg_advisory_xact_lock(203005004, hashtext(p_client::text));
  select * into t from clara.adjustment_templates a
    where a.id = p_template and a.client_id = p_client for update;
  if not found then
    raise exception 'adjustment template is not in this client' using errcode = 'CLR11';
  end if;
  if t.status <> 'proposed' then
    raise exception 'only a proposed adjustment template can be signed (this one is %)', t.status
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_not_proposed', 'status', t.status)::text;
  end if;

  -- THE SIGN-TIME FRESHNESS RE-DERIVATION. Cadence is immutable on the row, so it is asserted
  -- rather than re-chosen; start_date and end_date are re-measured against the FY the client
  -- has TODAY.
  if t.cadence not in ('monthly', 'annual') then
    raise exception 'this template carries an unknown cadence'
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_fy_stale', 'axis', 'cadence',
          'cadence', t.cadence)::text;
  end if;
  if clara._adj_period_start(p_client, t.cadence, t.start_date) is distinct from t.start_date then
    raise exception 'this client''s financial year changed since this template was proposed: the start date % is no longer the first day of a % period', t.start_date, t.cadence
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_fy_stale', 'axis', 'start_date',
          'cadence', t.cadence, 'start_date', t.start_date)::text;
  end if;
  if t.end_date is not null
     and clara._adj_period_end(p_client, t.cadence, t.end_date) is distinct from t.end_date then
    raise exception 'this client''s financial year changed since this template was proposed: the end date % is no longer the last day of a % period', t.end_date, t.cadence
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_fy_stale', 'axis', 'end_date',
          'cadence', t.cadence, 'end_date', t.end_date)::text;
  end if;
  -- AND THE DERIVED FIRST PERIOD END IS RE-ASKED HERE FOR THE REASON EVERY OTHER FRESHNESS CHECK
  -- IS (round 9): the derivation depends on the client's FY, the FY can move between propose and
  -- sign, and a template that goes LIVE with a first period outside the stamp grammar's domain
  -- can never run. Same token, same axis, same domain as propose -- one condition, one word.
  if not clara._wdb_iso_date_supported(clara._adj_period_end(p_client, t.cadence, t.start_date)) then
    raise exception 'this template''s first % period would end % , which is outside the supported range 0001-01-01 .. 9999-12-31 (AD)', t.cadence, clara._adj_period_end(p_client, t.cadence, t.start_date)
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'template_date_unsupported',
          'axis', 'derived_period_end', 'cadence', t.cadence, 'period_start', t.start_date,
          'period_end', clara._adj_period_end(p_client, t.cadence, t.start_date),
          'supported_from', date '0001-01-01', 'supported_to', date '9999-12-31')::text;
  end if;

  -- THE PERIOD-OVERLAP ADVISORY, RE-ASKED AT THE LAST HUMAN MOMENT [R12 FIX 2026-08-04 -- confirming
  -- round]. Every other check in this body is a sign-time RE-DERIVATION for one reason: the world
  -- moves between propose and sign, and sign is the act that makes a template able to post. The
  -- advisory is no different, and the confirming round measured why it matters -- in the blessed
  -- propose-first order the predecessor is still LIVE at propose and may have charged NOTHING
  -- yet, so a propose-time snapshot can be honestly empty and the same pair be a doubling by the
  -- time an admin signs. It is computed BEFORE the update, so a template can never appear in its
  -- own advisory, and p_self excludes it belt-and-braces.
  -- IT IS NOT A GATE. Signing is refused for staleness (template_fy_stale) and for an unsupported
  -- derived period, and for nothing else; this key is advisory exactly as propose's is, carries
  -- the same shape, and the [WDB-G13] edit stays a professional judgement.
  v_warn := clara._wdb_period_overlap_advisory(p_client, p_template,
    clara._wdb_line_shape(t.lines), t.start_date, t.end_date);

  update clara.adjustment_templates set status = 'live', signed_by = c.actor,
    signed_at = now(), signed_op_key = p_op_key where id = p_template;
  perform clara._audit(c.firm, c.actor, null, null, 'sign_adjustment_template', null,
    jsonb_build_object('client', p_client, 'template', p_template, 'op_key', p_op_key,
      'advisories', jsonb_array_length(v_warn)));
  -- THE KEY IS ALWAYS PRESENT, empty array and all -- propose's rule, and for the same reason.
  return clara._finish_op(c.firm, 'sign_adjustment_template', p_op_key,
    jsonb_build_object('template_id', p_template, 'status', 'live', 'warnings', v_warn));
end $$;
revoke all on function clara.sign_adjustment_template(uuid, uuid, text) from public;

-- RETIRE (admin+, reason mandatory). Refuses while an occurrence DRAFT is outstanding: a
-- retired template's occurrence would fail hook arm (2)'s template_retired axis at approve,
-- so retiring under a live draft would strand it. The lawful escape for the draft itself is
-- clara.withdraw_draft, which is why retire can never wedge [L4/sound].
--
-- REQUEST HASH: ('client', p_client, 'template', p_template) -- the ABI SSE row, which
-- deliberately does NOT carry the reason (unlike 0041's retire_depreciation_authority). Two
-- retires of the same template under one op_key therefore REPLAY rather than raising on a
-- changed reason, which is the ABI's single-owner call.
create function clara.retire_adjustment_template(p_client uuid, p_template uuid,
    p_reason text, p_op_key text)
  returns jsonb
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare c record; v_dedupe jsonb; v_firm uuid; t record;
begin
  c := clara._human_ctx(clara.role_rank('admin'));
  if p_op_key is null or btrim(p_op_key) = '' then
    raise exception 'op_key is required' using errcode = 'CLR10';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'a retirement reason is required' using errcode = 'CLR10';
  end if;
  v_dedupe := clara._reserve_op(c.firm, 'retire_adjustment_template', p_op_key,
    clara._hash(jsonb_build_object('client', p_client, 'template', p_template)));
  if v_dedupe is not null then return v_dedupe; end if;
  select cl.firm_id into v_firm from clara.clients cl where cl.id = p_client;
  if v_firm is null or v_firm <> c.firm then
    raise exception 'client is not in your firm' using errcode = 'CLR11';
  end if;
  perform pg_advisory_xact_lock(203005004, hashtext(p_client::text));
  select * into t from clara.adjustment_templates a
    where a.id = p_template and a.client_id = p_client for update;
  if not found then
    raise exception 'adjustment template is not in this client' using errcode = 'CLR11';
  end if;
  if t.status = 'retired' then
    raise exception 'this adjustment template is already retired'
      using errcode = 'CLR10', detail = '{"reason":"template_already_retired"}';
  end if;
  if clara._adj_occurrence_outstanding(p_client, p_template) then
    raise exception 'an occurrence draft for this template is still outstanding; approve or withdraw it before retiring the template'
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'occurrence_draft_outstanding',
          'template_id', p_template)::text;
  end if;
  -- LEAF-LAST: retire RELEASES this template's claim on its line accounts, so it is a taker
  -- on the same leaf propose took, in the same order (rung first).
  perform clara._fa_lock_roles(p_client);

  -- The signed pair is back-filled on a never-signed template exactly as
  -- clara.retire_depreciation_authority does, so the row satisfies a
  -- signed-required-for-terminal-status CHECK on either shape of the SECTION S1 DDL.
  update clara.adjustment_templates set status = 'retired', retired_by = c.actor,
    retired_at = now(), retired_reason = p_reason, retired_op_key = p_op_key,
    signed_by = coalesce(t.signed_by, c.actor), signed_at = coalesce(t.signed_at, now())
    where id = p_template;
  perform clara._audit(c.firm, c.actor, null, null, 'retire_adjustment_template', null,
    jsonb_build_object('client', p_client, 'template', p_template, 'reason', p_reason,
      'op_key', p_op_key));
  return clara._finish_op(c.firm, 'retire_adjustment_template', p_op_key,
    jsonb_build_object('template_id', p_template, 'status', 'retired'));
end $$;
revoke all on function clara.retire_adjustment_template(uuid, uuid, text, text) from public;

-- =====================================================================================
-- S2.3 -- THE POSTER (design SS2.3). ONE (template, period) PER CALL, ONE TRANSACTION.
--
-- LOCK ORDER: op receipt -> the derived :approve sub-key -> the derived :mirror:approve
-- sub-key -> advisory 203005004 (client) -> every template/entry read. Both sub-keys are
-- claimed BEFORE the rung for the reason 0037 records at allocate_receipt and 0041 restates
-- at 3410-3415: clara._reserve_op writes a row and can BLOCK on a concurrent same-key
-- inserter, and taking that block while holding a client rung makes a deadlock reachable.
--
-- BOTH DERIVED KEYS ARE RESERVED UNCONDITIONALLY [L5/9, L4/4]. :mirror:approve is reserved
-- even when the template does not auto-reverse, because the branch is not knowable before the
-- rung; the non-auto_reverse branch then CLOSES it with a deferral marker (the 0038:4644-4664
-- idiom) rather than leaving an op_receipts row nobody can ever finish. On the DRAFT branch
-- the :approve key stays CLAIMED-BUT-UNFINISHED for the life of the draft -- the ratified
-- 0041:3412 posture: a committed reservation is lawfully spent PREHELD by the LATER
-- transaction that approves the draft.
--
-- A NON-NULL DERIVED PRE-RESERVATION RAISES, NEVER REPLAYS (ABI SSE, stated once): the
-- derived keys are not the caller's to retry, so finding one already taken is a collision
-- (approve_key_collision), not an idempotent re-run.
--
-- THE POSTER IS NOT A LEAF TAKER. It only READS eligibility, through the lock-free
-- clara._acct_role_reserved; posting and approve paths are never takers (SS2.1's census).
-- =====================================================================================
create function clara._adj_run_occurrence_core(p_client uuid, p_template uuid,
    p_period_start date, p_period_end date, p_op_key text, p_actor uuid, p_firm uuid,
    p_verb text)
  returns jsonb
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare
  v_dedupe jsonb; v_approve_key text; v_mirror_key text; t record; r record;
  v_ps date; v_pe date; v_entry uuid; v_rev uuid; v_actor uuid; v_breach jsonb;
  v_corr_breach jsonb; v_shape text[]; v_remedy text; v_collide text;
  v_pred jsonb; v_pred_txt text; v_own jsonb;
  -- [round 10, lane P1] the RECORDED lineage half of the same refusal: the ancestry answer, the
  -- ancestor ids as text (the census speaks jsonb, the stamp speaks uuid), the subset of them that
  -- actually has something standing, the sentence built from that subset, and the last period it
  -- charged (the date a non-doubling replacement must start after).
  v_anc jsonb; v_anc_ids text[]; v_repl_ids text[]; v_repl_txt text; v_repl_last text;
  -- [R11 FIX 2026-08-04] admission predicate (5)'s subject: what a generation this template replaces
  -- still has standing IN THE PERIOD being run. The shape gate's own use of v_repl_txt/v_repl_last
  -- is one branch further down and cannot collide -- (5) raises before it is reached.
  v_repl_std jsonb;
  -- ...and the same question over the template's WHOLE BOOKABLE WINDOW, which is the reachability
  -- predicate term (a) was missing.
  v_repl_win jsonb;
  -- Whether the entry the shape gate names was written by a generation this template replaces.
  -- The two facts were composed as if they were one, and on the finding's scenario they were not.
  v_blocker_is_ancestor boolean;
  v_dr bigint; v_cr bigint; v_ramp boolean; v_high boolean; v_catch_up boolean;
  v_mode text; v_status text; v_label text; v_memo text; v_watermark timestamptz;
  v_run uuid; v_rev_entry uuid; v_amount bigint;
begin
  if p_op_key is null or btrim(p_op_key) = '' then
    raise exception 'op_key is required' using errcode = 'CLR10';
  end if;
  v_dedupe := clara._reserve_op(p_firm, p_verb, p_op_key,
    clara._hash(jsonb_build_object('client', p_client, 'template', p_template,
      'ps', p_period_start, 'pe', p_period_end)));
  if v_dedupe is not null then return v_dedupe; end if;

  v_approve_key := p_op_key || ':approve';
  if clara._reserve_op(p_firm, 'approve_entry', v_approve_key,
       clara._hash(jsonb_build_object('template', p_template, 'ps', p_period_start,
         'pe', p_period_end, 'role', 'occurrence'))) is not null then
    raise exception 'the derived approve op key is already in use'
      using errcode = 'CLR10', detail = '{"reason":"approve_key_collision"}';
  end if;
  v_mirror_key := p_op_key || ':mirror:approve';
  if clara._reserve_op(p_firm, 'approve_entry', v_mirror_key,
       clara._hash(jsonb_build_object('template', p_template, 'ps', p_period_start,
         'pe', p_period_end, 'role', 'reversal'))) is not null then
    raise exception 'the derived mirror approve op key is already in use'
      using errcode = 'CLR10', detail = '{"reason":"approve_key_collision"}';
  end if;

  -- THE CLIENT RUNG, BEFORE ANY TEMPLATE OR ENTRY READ (the 0041 poster's law restated).
  -- It is what makes the admission decision, the mode decision, the post and any concurrent
  -- correction ONE lock-holding transaction -- which is why ramp flap is impossible rather
  -- than merely unlikely.
  perform pg_advisory_xact_lock(203005004, hashtext(p_client::text));

  select * into t from clara.adjustment_templates a
    where a.id = p_template and a.client_id = p_client;
  if not found or t.status <> 'live' then
    raise exception 'this adjustment template is not live for this client'
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'template_not_live',
          'template_id', p_template)::text;
  end if;
  v_actor := coalesce(p_actor, t.signed_by);

  -- THE NON-AUTO_REVERSE BRANCH CLOSES THE MIRROR KEY (ABI SSE closer column). Done as soon
  -- as the branch is knowable, with an honest deferral marker: nothing will ever spend it.
  if not t.auto_reverse then
    perform clara._finish_op(p_firm, 'approve_entry', v_mirror_key,
      jsonb_build_object('deferred', true, 'reason', 'template_not_auto_reverse',
        'template_id', p_template));
  end if;

  -- THE PERIOD BOUNDS ARE INSIDE THE SUPPORTED DATE DOMAIN (round 8), asked BEFORE the cadence
  -- algebra runs on them. clara.run_adjustment_manual takes both bounds from a human, so this
  -- door lets dates in independently of propose's window check -- and a period stamp outside
  -- clara._wdb_iso_date_supported's range makes the re-run gate read that entry as in-set for
  -- the client's whole calendar. Refused with the poster's own period_request_invalid grammar
  -- (CLR38 + an axis), not propose's, because a shared asserter would have had to be handed both
  -- families' error codes. The measurement is at clara._wdb_iso_date_supported.
  if not clara._wdb_iso_date_supported(p_period_start)
     or not clara._wdb_iso_date_supported(p_period_end) then
    raise exception 'the period % .. % is outside the supported date range 0001-01-01 .. 9999-12-31 (AD)', p_period_start, p_period_end
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'period_request_invalid',
          'axis', 'date_unsupported', 'period_start', p_period_start,
          'period_end', p_period_end, 'supported_from', date '0001-01-01',
          'supported_to', date '9999-12-31')::text;
  end if;
  -- THE PERIOD IS THE CADENCE'S, NOT THE CALLER'S (WD-R8 consumed; the 0041 poster's shape).
  v_ps := clara._adj_period_start(p_client, t.cadence, p_period_start);
  v_pe := clara._adj_period_end(p_client, t.cadence, p_period_start);
  if v_ps is distinct from p_period_start or v_pe is distinct from p_period_end then
    raise exception 'this template''s % cadence runs % .. %, not % .. %', t.cadence, v_ps, v_pe, p_period_start, p_period_end
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'period_request_invalid',
          'axis', 'not_cadence_aligned', 'cadence', t.cadence,
          'period_start', v_ps, 'period_end', v_pe)::text;
  end if;
  -- A PERIOD IS RUNNABLE ONLY ONCE IT HAS ENDED, IN MALAYSIA. clara._fa_today() is the house
  -- MYT legal date (0041:1012): a UTC runtime between 00:00 and 08:00 MYT is a calendar day
  -- BEHIND the books it is posting into, and this file never asks the session zone.
  if v_pe >= clara._fa_today() then
    raise exception 'the period % .. % has not ended yet (MYT %)', v_ps, v_pe, clara._fa_today()
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'period_request_invalid', 'axis', 'not_ended',
          'period_end', v_pe)::text;
  end if;

  -- ------------------------------------------------------------------------------------
  -- THE ADMISSION LAW (design SS2.3), three predicates, each with its own token.
  -- ------------------------------------------------------------------------------------
  -- (1) THE WINDOW: [start_date, coalesce(end_date, infinity)]. Both bounds are cadence
  -- boundaries (validated at propose and re-validated at sign), so comparing the period's own
  -- ends against them is exact.
  if v_ps < t.start_date or (t.end_date is not null and v_pe > t.end_date) then
    raise exception 'the period % .. % lies outside this template''s window (% .. %)', v_ps, v_pe, t.start_date, coalesce(t.end_date::text, 'open')
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'period_out_of_window',
          'template_id', p_template, 'period_start', v_ps, 'period_end', v_pe,
          'start_date', t.start_date, 'end_date', t.end_date)::text;
  end if;
  -- (2) UNMET: no APPROVED, UN-REVERSED role='occurrence' entry exists for this
  -- (template, period). Entries are the truth -- receipts are never read for eligibility
  -- (the 0041:695-697 law restated), because a pair-corrected period must become unmet again
  -- and its receipt legitimately survives. Written as TEXT comparisons on the two expressions
  -- the ABI SSC index ix_je_adj_occurrence is built over, so this rides the index instead of
  -- casting its way off it (the D-a F10 measured law).
  if exists (select 1 from clara.journal_entries je
             where je.flags ? 'recurring_adjustment'
               and (je.flags -> 'recurring_adjustment' ->> 'template_id') = p_template::text
               and (je.flags -> 'recurring_adjustment' ->> 'period_start')
                     = to_char(v_ps, 'YYYY-MM-DD')
               and (je.flags -> 'recurring_adjustment' ->> 'role') = 'occurrence'
               and je.status = 'approved' and je.reversed_by is null) then
    raise exception 'this template already has an approved, un-reversed occurrence for % .. %', v_ps, v_pe
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'period_already_met',
          'template_id', p_template, 'period_start', v_ps, 'period_end', v_pe)::text;
  end if;
  -- (3) NOT BLOCKED: draft-N blocks N+1, per template (never client-wide -- two templates on
  -- one client are independent lanes). This is blocked[]'s TRANSIENT reason; the due oracle
  -- also reports template_line_ineligible, which is the eligibility refusal just below.
  if clara._adj_occurrence_outstanding(p_client, p_template) then
    raise exception 'an occurrence draft for this template is outstanding; approve or withdraw it before running another period'
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'occurrence_draft_outstanding',
          'template_id', p_template)::text;
  end if;
  -- (4) THE PERIOD IS SOUND TO RE-RUN [as-built ladder round 5 -- THE CORRECT-AND-RE-RUN
  -- DOUBLE]. (2) proves the period is UNMET; this proves it is unmet SOUNDLY -- that whatever
  -- made it unmet actually left the period's own books flat. Without it, the two settled laws
  -- this file and clara.reverse_entry each hold correctly compose into a permanent doubling of
  -- a statutory year-end balance: measured at RM100,000.00 of FY2025 expense (and RM100,000.00
  -- of FY2025 accrual liability) against a RM50,000.00 accrual, on BOTH lanes, with this very
  -- oracle re-proposing the period on every sweep.
  --
  -- IT IS ADDITIVE AND LAST AMONG THE ADMISSION PREDICATES, deliberately: the window /
  -- period_already_met / occurrence_draft_outstanding trio keeps its pinned order, wording and
  -- precedence exactly (round 4 measured three regressions in this body's admission law and
  -- the lesson was to add beside, never to reorder). It sits ABOVE the eligibility
  -- re-derivation for one reason: a period that cannot lawfully be re-run at all must not be
  -- reported as an ACCOUNT problem, and clara._adj_oldest_unmet_period asks the two in exactly
  -- this order so the verb and the oracle can never name different reasons for one period.
  --
  -- THE REMEDY NAMES ONLY ACTS THAT EXIST (WDB-R2: "if a message cannot honestly promise an
  -- outcome, it must not promise it"). An earlier cut of this refusal said "book the correction
  -- into the period by hand" -- and that is the right ACCOUNTING act, but it does NOT clear
  -- this gate and could never have: a hand-booked entry sets no reversed_by, the original's
  -- reversed_by still names the out-of-period correction, and clara.reverse_entry refuses to
  -- re-reverse an already-reversed entry. The state is TERMINAL for the automatic lane, and
  -- exactly one act reaches it: retiring the template, which stops the period being advertised
  -- and hands the books to a human. So that is what is named, in the detail as a machine-
  -- readable `remedy` key as well as in the sentence. (`period_correction_unsound` is terminal
  -- for the PERIOD in the same way template_line_ineligible is terminal for the TEMPLATE.)
  --
  -- The refusal names BOTH entries and BOTH dates, because the one thing a human cannot
  -- reconstruct from a token is which two dates disagreed.
  --
  -- ASKED WITH THE TEMPLATE'S ACCOUNT SHAPE, NOT ITS ID [round 6]. (2) above is the
  -- template-keyed met-ness test and it keeps its exact pinned wording and precedence -- but it
  -- can only ever see THIS template's own occurrences, and [WDB-G13] says an edit IS a new
  -- template. Asking the shared gate with clara._wdb_line_shape(t.lines) is what makes the
  -- question the books' rather than the register-of-templates': "does this client's overlapping
  -- calendar already carry a posting that moves ANY of these accounts in the same direction?"
  -- (round 8: ANY, not ALL -- the equality form was an identity test a one-sen edit could vary).
  v_shape := clara._wdb_line_shape(t.lines);
  v_corr_breach := clara._wdb_rerun_breach(p_client, 'recurring_adjustment', v_shape, v_ps, v_pe);
  if v_corr_breach is not null and (v_corr_breach ->> 'axis') = 'shape_already_met' then
    -- A DIFFERENT REFUSAL FROM period_correction_unsound, because it is a different fact with a
    -- different remedy. Nothing here is unsound: a posting that moves at least one of this
    -- template's accounts in the same direction is standing, correctly, in a period overlapping
    -- this one, under another authority. (2) has already proved it is not this template's, so it
    -- is either the generation this template replaces -- correct that entry, in its own period,
    -- and this period reopens by itself -- or a genuinely separate live template sharing an
    -- account with this one, in which case the books cannot tell the two charges on that account
    -- apart and neither can any reader; give it its own code. BOTH remedies are acts that exist
    -- and that clear this gate (WDB-R2).
    --
    -- THE PRODUCT LAW THIS REFUSAL ENFORCES, written down at the gate so nobody has to infer it
    -- from the key: at most one standing machine-posted charge per (client, overlapping calendar,
    -- account, side) is the designed grain [round 8]. Two templates that genuinely accrue
    -- different things but SHARE an account -- audit fees and legal fees, both crediting one
    -- "Accruals" code -- ARE refused here, deliberately: the books record two charges on that
    -- code and no reader, human or machine, can attribute them afterwards. The professional's
    -- remedy is a distinct accrual account per liability class, and under the round-8
    -- intersection test it is actually SUFFICIENT -- under round 7's equality key, distinct codes
    -- on the debit side alone still left the shared accrual carrying both charges and the gate
    -- said nothing.
    --
    -- ...AND IT IS OFFERED WITH THE MEASUREMENT BESIDE IT, WHICH IS ROUND 10's REPAIR OF ROUND
    -- 9's REPAIR OF ROUND 8's SENTENCE. "Give this template distinct account codes" clears THIS
    -- gate in every case -- and on a [WDB-G13] EDIT it clears it by booking the charge a second
    -- time on fresh codes while the retired generation's entry stays standing on the old ones
    -- (measured, probe y1/p1-reclass.mjs: five months, RM30,000 against an RM15,000 intention).
    -- Round 9 answered that by CONDITIONING the clause on the standing writer's template status
    -- -- prohibiting the act, and asserting "it is the generation this one replaces". Round 10
    -- measured that assertion wrong in both directions, each with money: on a retired SIBLING the
    -- prohibition forbade the correct act and the one remaining instruction erased RM6,000 of a
    -- legitimate audit accrual (z1/p1-retired-sibling.mjs, z1/p1b-follow-the-only-remedy.mjs),
    -- and on the natural propose-then-retire ORDER the status read `live` and reprinted the
    -- doubling instruction anyway (z1/p5-order-bypass.mjs: RM18,000 against RM6,000, blocked:[]).
    --
    -- SO THE SENTENCE NOW NEITHER ASSERTS NOR PROHIBITS WHAT ONLY LINEAGE CAN PROVE. Three
    -- clauses, each keyed on something the books can actually show:
    --   1. correct the standing entry in its own period, with the verb the door named -- ALWAYS
    --      offered, unchanged;
    --   2. give this template distinct account codes -- ALWAYS offered as an ACT, because it is
    --      lawful and, on the designed audit-fee/legal-fee collision, it is the CORRECT act
    --      (measured: 401 books both months clean, every figure right, nothing doubled);
    --   3. ...carrying the CAUTION whenever this client has a sibling template whose shape
    --      collides with this one AND which already has standing charges -- naming that sibling,
    --      its status, how many periods it carries and which. The consequence is stated
    --      conditionally ("IF this template replaces that one, ...") because the professional is
    --      the only party who knows whether it does, and this file has no state that can.
    -- The census is clara._wdb_overlapping_siblings -- ONE body, consulted here, at the
    -- template_line_ineligible refusal below (the cross-family re-cut road) and at
    -- clara.propose_adjustment_template, so the three doors that promise this outcome cannot
    -- drift (WDB-R2).
    --
    -- ...AND WHERE THE LINEAGE IS RECORDED, THE CAUTION BECOMES AN ASSERTION [round 10, lane P1;
    -- the OWNER took option (b) on 2026-08-04]. The three clauses above are what this file can say
    -- when it is GUESSING at lineage. It no longer always has to: a professional who declares
    -- `p_replaces` at propose writes an immutable edge, and where that edge reaches a generation
    -- with charges still standing, clause 3 stops being conditional -- the refusal says "this
    -- template REPLACES that one", FORBIDS the distinct-codes act, and offers the two acts that do
    -- not double (correct the standing entry; or start the replacement after that generation's
    -- last charged period). The discriminant is the recorded edge and NOTHING ELSE -- never the
    -- status, never the shape, never which member of the window the scan reached first -- which is
    -- what makes it immune to the click order that defeated round 9. The walk is
    -- clara._wdb_template_ancestry (ONE body, shared with propose's validation, WDB-R2), and the
    -- fallback when no edge exists is lane O1's caution, VERBATIM and permanently reachable: every
    -- template proposed without a declaration lands there.
    --
    -- THE SENTENCE NAMES THE COLLIDING CODES. `colliding_elements` comes off the gate's own
    -- membership derivation (clara._wdb_shape_overlap), so "these collide" is always accompanied
    -- by "on WHAT" -- with three-line templates there are up to three candidate codes to re-cut
    -- and a reader who is not told which one cannot follow the remedy at all.
    --
    -- THE FIRST CLAUSE NAMES THE VERB THE GATE WAS TOLD, NOT ONE THIS BODY GUESSED (round 7,
    -- WDB-R2; round 8 moved the derivation into clara._adj_correction_door so the run-receipt
    -- card and this refusal cannot drift). Round 6 hard-coded clara.reverse_entry here, and for a
    -- [WDB-G13] edit of an AUTO-REVERSE template (the commonest case this gate fires on) that
    -- verb refuses CLR39 adjustment_pair_locked: the refusal handed the reader a door that
    -- refuses them. Where the door body names a wall it cannot translate into a verb -- including
    -- pair_already_active, the SECOND walled corridor, found inside round 7's own repair -- the
    -- sentence says so instead of inventing one.
    -- THE jsonb_typeof GUARD IS NOT DECORATION. `colliding_elements` is to_jsonb(text[]), and a
    -- NULL array serialises to the jsonb SCALAR `null` (which the p_shape-is-null read produces),
    -- on which jsonb_array_elements_text raises 22023. A cast or an extraction that can throw
    -- inside a refusal path turns a diagnosis into an error -- the same argument the gate's own
    -- regex-not-cast handler carries.
    v_collide := coalesce(nullif(array_to_string(
      array(select jsonb_array_elements_text(
        case when jsonb_typeof(v_corr_breach -> 'colliding_elements') = 'array'
             then v_corr_breach -> 'colliding_elements' else '[]'::jsonb end)), ', '), ''),
      'these accounts');
    v_remedy := case
      when (v_corr_breach ->> 'correction_verb') is not null then
        'Correct entry ' || (v_corr_breach ->> 'correction_entry') || ' within its own period with '
        || (v_corr_breach ->> 'correction_verb')
        || ' (a correction of a period-dated posting is now dated with the entry it corrects)'
      else
        -- THE WALL'S OWN SENTENCE RIDES WITH ITS TOKEN [round 10, Codex finding 1]. This
        -- clause used to end at "so clear that first", which names a token and no act: when
        -- the wall is the advance register's (a run whose halves move a code that has since
        -- been enrolled as a staff advance), "clear that first" is not something a bookkeeper
        -- can do without being told WHAT. `correction_wall_advice` is composed by the body
        -- that OWNS the wall and is carried through clara._adj_correction_door untouched, so
        -- this sentence can only ever say what that body actually says -- never a second
        -- opinion of it (WDB-R2).
        'Entry ' || (v_corr_breach ->> 'correction_entry')
        || ' cannot be corrected directly (' || coalesce(v_corr_breach ->> 'correction_wall', 'blocked')
        || ')'
        || coalesce(': ' || (v_corr_breach ->> 'correction_wall_advice'), '')
        || ', so clear that first' end;
    -- THE SECOND CLAUSE, AND THE MEASUREMENT THAT RIDES IT WHEN THERE IS ONE. The census is
    -- asked ONCE and both the sentence and the machine payload are built from that one answer,
    -- so "why was I cautioned" and "which templates were you looking at" can never disagree.
    -- Siblings with NOTHING standing are dropped here rather than inside the census: a template
    -- that has never posted (or whose occurrences are all corrected) cannot leave a charge behind
    -- a re-cut, and cautioning about it would be the unearned assertion this round deleted.
    -- THE RECORDED LINEAGE IS ASKED FIRST, AND IT OUTRANKS THE CENSUS [round 10, lane P1; the
    -- OWNER's option (b), ruled 2026-08-04]. The census can only ever say "these collide and this
    -- much stands under them"; clara.adjustment_templates.replaces_template_id says "and THAT one
    -- is the generation I replace", because the professional declared it at propose and the column
    -- is immutable. Where the declaration reaches the standing charge in the way, the sentence
    -- below stops cautioning and states it -- which is the whole difference between round 10's
    -- honest minimum and a gate that can actually stop the double.
    --
    -- THE ANCESTORS ARE TAKEN AS TEXT because the two sources speak different types: the census
    -- returns `template_id` as a jsonb string and clara._wdb_rerun_breach carries
    -- `standing_template_id` as the raw stamp text (which may be MALFORMED -- that is the whole
    -- point of the regex-not-cast reader at the v_met branch). Comparing as text can never raise
    -- 22P02 inside a refusal path; casting could, and a diagnosis that turns into an error is the
    -- defect this file guards against in four other places.
    v_anc := clara._wdb_template_ancestry(p_client, p_template);
    select coalesce(array_agg(a #>> '{}'), '{}'::text[]) into v_anc_ids
      from jsonb_array_elements(v_anc -> 'ancestors') as t(a);
    -- [R11 FIX 2026-08-04] IS THE ENTRY IN THE WAY ONE OF MINE TO REPLACE? Compared as TEXT, never cast:
    -- `standing_template_id` is the raw recurring_adjustment stamp and may be malformed, which is
    -- the whole reason the gate's own reader is a regex. A NULL stamp (an unattributable charge)
    -- coalesces to FALSE -- a charge these books cannot attribute to any template cannot be
    -- attributed to an ANCESTOR either, which is the same rule the census rows already follow.
    v_blocker_is_ancestor := coalesce(
      (v_corr_breach ->> 'standing_template_id') = any (v_anc_ids), false);

    -- THE CENSUS ROWS, EACH CARRYING THE LINEAGE FACT ABOUT ITSELF. `replaced` is reported on
    -- every candidate (never omitted on the false ones -- a key a reader has to test for existence
    -- before trusting is a key they will one day forget), and it is what lets a surface render
    -- "the generation you replace" and "a sibling that merely collides" as the different things
    -- they are. The unattributed row's `template_id` is jsonb null, and `null = any(...)` is NULL,
    -- so it is coalesced to FALSE explicitly: a charge these books cannot attribute to any
    -- template cannot be attributed to an ANCESTOR either.
    select jsonb_agg(e || jsonb_build_object('replaced',
             coalesce((e ->> 'template_id') = any (v_anc_ids), false))
             order by (e ->> 'standing')::int desc, e ->> 'template_id') into v_pred
      from jsonb_array_elements(
             clara._wdb_overlapping_siblings(p_client, p_template, v_shape)) as t(e)
     where (e ->> 'standing')::int > 0;

    -- WHICH RECORDED GENERATIONS A RE-CUT WOULD PROVABLY DOUBLE. Two sources, unioned, and the
    -- union is what makes the answer ORDER-INDEPENDENT -- the defect round 9 died of:
    --   (a) any colliding sibling with standing charges that is a recorded ancestor. Not "the one
    --       the refusal happens to name": which member of the window the scan reached first is an
    --       artefact of `order by posting_date, id`, and a prohibition that switches off because a
    --       different row sorted first is round 9's status snapshot wearing a new hat.
    --   (b) the writer of the entry this refusal NAMES, when that writer is a recorded ancestor --
    --       even if the census counted 0 for it. The census counts role='occurrence' only (its
    --       money argument is at clara._wdb_template_standing_charges), so an ancestor whose
    --       standing member here is its auto-reversal MIRROR would otherwise slip out of the set
    --       while its money is demonstrably standing in this very window. That is the mirror arm
    --       of Z1's probe 2, and it needs no separate branch -- only this second term.
    -- [R11 FIX 2026-08-04 -- W1 finding 2, HIGH] TERM (a) IS KEYED ON THE MONEY THIS TEMPLATE CAN
    -- ACTUALLY REACH. It used to admit any colliding ancestor with `standing > 0` counted over ALL
    -- PERIODS, with no reachability predicate anywhere -- and clara._wdb_template_standing_charges
    -- has none either, by design. MEASURED (probe w1d-period-blind-assert.mjs): gen1 charged
    -- 2026-01 and 2026-02 and was retired; gen2 honestly DECLARED it and started 2026-05-01 --
    -- FORWARD-ONLY, after gen1's last charged period, the lawful edit this file's own note calls
    -- safe. The 2026-05 run collided with a genuinely SEPARATE live template on a shared accrual
    -- code (the designed grain this file documents), and the refusal ASSERTED that gen2's distinct
    -- codes "would book 2026-01 .. 2026-02 a SECOND time". False: gen2 starts 2026-05-01 and can
    -- never book them. Following the forbidden act was measured CORRECT to the sen; following the
    -- FIRST remedy erased RM900 of an unrelated legitimate accrual, permanently.
    -- THE WINDOW IS THE TEMPLATE'S OWN, not this period's: the assertion's claim is "distinct codes
    -- would re-charge periods that generation carries", and the periods this template could ever
    -- re-charge are exactly [start_date, coalesce(end_date, the far horizon)]. Asking the same
    -- authority admission predicate (5) asks, with a wider window, is what keeps the wall and the
    -- sentence from ever disagreeing about whose money is in the way (WDB-R2).
    -- TERM (b) NEEDS NO PREDICATE and gets none: it names the writer of the entry THIS refusal is
    -- raised on, which is in this period by construction.
    v_repl_win := clara._wdb_replaced_generation_standing(p_client, p_template,
                    t.start_date, coalesce(t.end_date, date '9999-12-31'));
    select array_agg(distinct x order by x) into v_repl_ids
      from unnest(v_anc_ids) x
     where x = (v_corr_breach ->> 'standing_template_id')
        or exists (select 1 from jsonb_array_elements(coalesce(v_pred, '[]'::jsonb)) as t(e)
                    where (e ->> 'template_id') = x
                      and coalesce((e ->> 'replaced')::boolean, false)
                      and exists (select 1 from jsonb_array_elements(v_repl_win) as t2(g)
                                   where (g ->> 'template_id') = x));
    -- THE UN-NAMED ROW GETS A SENTENCE OF ITS OWN [round 10, Codex finding 3]. The census's
    -- second term reports standing charges no template of this client can claim, with
    -- `template_id` NULL -- and `'template ' || NULL` is NULL, which string_agg DROPS, so the
    -- caution would have gone silent on exactly the case it was widened for. The two spellings
    -- are branch-distinct here rather than papered over with a coalesce: "some template you can
    -- go and look at" and "a charge whose writer these books cannot identify" are different
    -- facts and a professional has to be able to tell them apart.
    select string_agg(
             case when (e ->> 'template_id') is null
               then 'a standing charge these books cannot attribute to any template of this '
                    || 'client (its recurring_adjustment stamp names none)'
               else 'template ' || (e ->> 'template_id') || ' ("' || (e ->> 'name') || '", '
                    || (e ->> 'status') || ', ' || (e ->> 'containment') || ' shape)' end
             || ' already carries ' || (e ->> 'standing') || ' standing charge(s) for '
             || coalesce(e ->> 'first_period', 'an unstated period') || ' .. '
             || coalesce(e ->> 'last_period', 'an unstated period'), '; ')
      into v_pred_txt
      from jsonb_array_elements(coalesce(v_pred, '[]'::jsonb)) as t(e);
    -- THE ASSERTED SENTENCE'S OWN FACTS [round 10, lane P1]. Built with a LEFT JOIN rather than
    -- from the census alone, because term (b) above can name a generation the census dropped (a
    -- standing MIRROR): that arm gets the honest shorter phrase -- "wrote the standing charge named
    -- above" -- instead of a fabricated count. The period bound is the max over the replaced
    -- generations under collate "C" (ISO text, the same collation every other comparison of these
    -- stamps uses), and it is the date a replacement may start after without re-charging anything.
    if v_repl_ids is not null then
      select string_agg(
               'template ' || x
               || coalesce(' ("' || (c.e ->> 'name') || '", ' || (c.e ->> 'status') || ', '
                           || (c.e ->> 'containment') || ' shape)', '')
               || case when c.e is null then ', which wrote the standing charge named above'
                       else ', which already carries ' || (c.e ->> 'standing')
                            || ' standing charge(s) for '
                            || coalesce(c.e ->> 'first_period', 'an unstated period') || ' .. '
                            || coalesce(c.e ->> 'last_period', 'an unstated period') end,
               '; ' order by x)
        into v_repl_txt
        from unnest(v_repl_ids) x
        left join lateral (select e from jsonb_array_elements(coalesce(v_pred, '[]'::jsonb)) as t(e)
                            where (e ->> 'template_id') = x) c on true;
      -- [R11 FIX 2026-08-04 -- W1 finding 2] THE BOUND IS THE MAX OVER THE GENERATIONS THIS REFUSAL
      -- ACTUALLY ASSERTS ON, not over every replaced candidate the census returned. Under the old
      -- form `start_after_replaced_generation` was measured VACUOUS in the finding's own scenario:
      -- it printed 2026-02-28 at a template that already started 2026-05-01, so the "other act
      -- that does not double" was an act the professional had already taken. It is also taken
      -- from clara._wdb_template_standing_charges rather than from the census row, because the
      -- date a replacement may safely start after is the generation's LAST CHARGE, full stop --
      -- an in-window bound would name a date that still re-charges the months after it.
      -- THE CAST IS SAFE HERE AND NOWHERE ELSE IN THIS BODY: v_repl_ids is a subset of v_anc_ids,
      -- which comes from the ancestry walk's own uuid rows -- never from a recurring_adjustment
      -- STAMP, which may be malformed and which this file therefore only ever compares as text.
      select max((clara._wdb_template_standing_charges(p_client, x::uuid) ->> 'last_period')
                 collate "C") into v_repl_last
        from unnest(v_repl_ids) x;
    end if;
    -- THREE SPELLINGS OF THE SECOND CLAUSE, ONE PER STATE OF WHAT THIS FILE ACTUALLY KNOWS.
    --   * NOTHING COLLIDING STANDS -> offer the act plainly (round 8's sentence, untouched).
    --   * SOMETHING STANDS AND MIGHT BE A PREDECESSOR -> offer the act WITH the measurement and a
    --     CONDITIONAL consequence (round 10 lane O1's caution, kept verbatim: it is what the books
    --     can prove and no more, and it is the branch every template proposed before this column
    --     existed will always land on).
    --   * A RECORDED GENERATION THIS TEMPLATE REPLACES HAS CHARGES STANDING -> ASSERT and FORBID.
    --     This is the one branch round 9 reached for and had no state to earn: the doubling is not
    --     a possibility here, it is arithmetic -- the professional declared the lineage, the
    --     declaration is immutable, and fresh codes would re-charge every period that generation
    --     already carries while its charge stays where it is.
    -- THE PROHIBITION IS NOT A DEAD END, and this file may not let it be one (the walled-corridor
    -- class, the ladder's most-repeated defect): the sentence carries TWO acts that do not double
    -- -- correct the standing entry in its own period (clause 1, the verb the door named, printed
    -- above), and start the replacement after the last period that generation charged. Both are
    -- acts a professional can take today with the verbs they already hold.
    --
    -- ...AND A THIRD, WHICH IS THE ONE ROUND 9's GHOST COMES BACK THROUGH IF IT IS LEFT OUT.
    -- Round 9 forbade a lawful act on a lineage the SYSTEM inferred wrongly. This branch forbids
    -- it on a lineage the PROFESSIONAL declared -- and a professional can be wrong too. Work the
    -- z1/p1 scenario with one slip: the retired AUDIT template is declared as the predecessor of a
    -- genuinely separate LEGAL-fee template. The assertion is then false in exactly round 9's way,
    -- the distinct-codes act (which here is the CORRECT one -- measured, x42.r10p1e) is forbidden,
    -- and the two acts above are useless: correcting the standing entry destroys a legitimate
    -- audit accrual, and starting later does not give the legal fee the months it is owed. The
    -- declaration is IMMUTABLE, so there is no un-declaring it, and a corridor whose only exits
    -- are wrong is the defect family this ladder exists to kill. So the sentence NAMES THE
    -- RECOVERY: retire this template and propose it again without naming a predecessor. That act
    -- is available (the run was refused, so no occurrence draft is outstanding to block the
    -- retire; the retired row frees its content_hash slot, so the identical proposal is admitted),
    -- it restores lane O1's caution branch with both acts offered, and it leaves BOTH declarations
    -- in the audit trail rather than editing a claim in place. Celled end-to-end, with the four
    -- balances asserted after the recovery: x42.r10p1h.
    --
    -- WHAT THIS PROHIBITION IS NOT, STATED PLAINLY RATHER THAN LEFT TO BE DISCOVERED [round 10,
    -- lane P1; probe p1/probes/pA-lineage-assert.mjs]. It is a SENTENCE, not a wall. A
    -- professional who reads it and re-cuts anyway -- proposing a THIRD template on free codes,
    -- declaring the same predecessor -- is not stopped: that template's shape is disjoint from the
    -- standing charges, clara._wdb_rerun_breach is keyed on shape intersection, and the four
    -- already-charged months run as ordinary catch-up drafts (MEASURED on this rig: EXPA 1,200,000
    -- standing plus EXPB 600,000 booked, against a 600,000 intention). Closing THAT needs a
    -- membership term keyed on the recorded lineage rather than on the shape, which is a NEW
    -- admission law with its own refusal token, its own blocked[] word and its own surface gloss --
    -- an adjudication, not a fix lane's call. It is recorded here, at the sentence that names the
    -- act, so the next reader inherits a measurement instead of a surprise. What was measured and
    -- REJECTED as the cheap version: folding the ancestors' accounts into the shape this gate is
    -- asked about. It is over-broad in a way that parks healthy templates -- a lawful FORWARD-ONLY
    -- re-code (a replacement on fresh codes starting after the predecessor's last period) would be
    -- refused whenever any unrelated template happens to charge the predecessor's OLD accounts in
    -- a period the replacement covers, and a shape argument cannot say "only for the periods that
    -- generation actually charged".
    v_remedy := v_remedy || case
      when v_repl_txt is not null then
        '. Do NOT give this template distinct account codes: this template was PROPOSED AS THE '
        || 'REPLACEMENT FOR ' || v_repl_txt || ' -- that lineage is RECORDED on this template '
        || '(replaces_template_id, declared at propose and immutable since), not inferred -- so '
        || 'distinct codes would book those periods a SECOND time while that charge stays standing '
        || 'on ' || v_collide || '. '
        -- [R11 FIX 2026-08-04 -- W1 finding 2 (the remedy[0] half) and finding 4] CLAUSE 1 AND CLAUSE 2
        -- ARE NO LONGER COMPOSED AS IF THEY CONCERNED THE SAME MONEY. The entry clause 1 names is
        -- whichever standing charge blocks THIS period; the generation clause 2 asserts on is
        -- whichever ancestor this template declared. MEASURED (probe w1f-corridor-exits.mjs): on a
        -- shared accrual code those are DIFFERENT templates, the first machine remedy named an
        -- entry belonging to an unrelated LIVE template, and following it erased RM900 of a
        -- legitimate accrual and left that template's own period refused forever. So when the
        -- blocker is not an ancestor, the sentence says so instead of implying that correcting a
        -- stranger's entry is the act this prohibition calls for.
        -- AND THE REOPEN PROMISE IS CONDITIONAL ON THE CENSUS. "Correct the entry named above and
        -- this period reopens by itself" was made unconditionally; MEASURED (probe w1h-promise.mjs)
        -- with two standing charges that collide with this shape on DIFFERENT elements, the first
        -- correction did not reopen the period and the refusal made the same promise again about
        -- the second. The payload already carried both rows -- only the sentence lied -- so the
        -- count is read from it rather than promised away.
        -- THE TAIL CLAUSE KEEPS ITS EXACT CANONICAL SHAPE ("; the only other act that does not
        -- double them is a replacement starting after <date>") -- only the clause BEFORE it moves.
        -- Cell x42.r10p1a pins that sentence verbatim, and a fix that re-punctuated a contract
        -- test's subject while repairing a different clause would be a delta nobody adjudicated.
        || case
             when not v_blocker_is_ancestor then
               'The entry named above was written by a template this one does NOT replace, so '
               || 'correcting it is not what this prohibition asks of you -- it is somebody '
               || 'else''s charge standing in your way and has to be dealt with on its own terms; '
               || 'what this prohibition is about is the generation named here'
             when jsonb_array_length(coalesce(v_pred, '[]'::jsonb)) > 1 then
               'Correct the standing entry named above -- and measure before you expect the '
               || 'period back: ' || jsonb_array_length(coalesce(v_pred, '[]'::jsonb))::text
               || ' colliding templates carry standing charges here, so this period reopens only '
               || 'once every one of them is corrected'
             else 'Correct the standing entry named above and this period reopens by itself'
           end
        || '; the only other act that does not double them is a replacement starting '
        || 'after ' || coalesce(v_repl_last, 'the last period that generation charged')
        || '. If this template does NOT in fact replace that generation, retire it '
        || '(clara.retire_adjustment_template) and propose it again without naming a predecessor: '
        || 'a recorded lineage is a claim about these books and is corrected by making it again, '
        || 'never by editing it.'
      when v_pred_txt is null then ', or give this template distinct account codes.'
      else ', or give this template distinct account codes -- BUT MEASURE FIRST: ' || v_pred_txt
        || '. IF this template replaces that one, distinct codes would book those periods a '
        || 'second time while that charge stays standing on ' || v_collide
        || ': reverse those charges first, or keep these codes and correct the standing entry '
        || 'named above. If the two templates genuinely accrue different things (the same '
        || 'accrual code for two liabilities), distinct codes is the right act.' end;
    raise exception 'period % .. % already carries an approved posting on % (entry %, dated %) booked under another authority; a second one would leave the figure standing twice. %', v_ps, v_pe, v_collide, v_corr_breach ->> 'entry_id', v_corr_breach ->> 'posting_date', v_remedy
      using errcode = 'CLR38',
        detail = (jsonb_build_object('reason', 'period_shape_already_met',
          'template_id', p_template, 'period_start', v_ps, 'period_end', v_pe,
          'account_shape', to_jsonb(v_shape),
          -- THE MACHINE KEY IS THE COMPOSED REMEDY, BRANCH-DISTINCT (round 10, ABI delta). It
          -- was the scalar `correct_the_standing_entry_in_period` in BOTH round-9 branches, so
          -- no consumer could ever learn that a second act was offered -- or withheld. It is now
          -- the ORDERED LIST of the acts the sentence actually offers: clause 1's token is kept
          -- verbatim and is always first, and the second element says which spelling of the
          -- distinct-codes act was printed. `predecessor_candidates` carries the facts the
          -- caution was composed from, so a surface can render them without re-deriving them.
          -- [round 10, lane P1] Position 2 stays what lane O1 defined it to be -- WHICH SPELLING of
          -- the distinct-codes clause was printed -- and gains its third value,
          -- `distinct_codes_forbidden_replaced_generation`, for the branch where the act is
          -- refused by grammar. A THIRD element joins ONLY on that branch, because on that branch
          -- the sentence offers a second act (start the replacement after the replaced
          -- generation's last charged period) and a machine list that hid an act the human
          -- sentence offers is exactly the drift O1's defect was, one round on.
          'remedy', jsonb_build_array('correct_the_standing_entry_in_period',
            case when v_repl_txt is not null then 'distinct_codes_forbidden_replaced_generation'
                 when v_pred_txt is null then 'distinct_codes'
                 else 'distinct_codes_with_predecessor_caution' end)
            || case when v_repl_txt is not null
                    then jsonb_build_array('start_after_replaced_generation',
                                           're_propose_without_predecessor')
                    else '[]'::jsonb end,
          'predecessor_candidates', coalesce(v_pred, '[]'::jsonb),
          -- THE PROOF, SEPARATELY MACHINE-READABLE. `replaced_generations` is the subset of this
          -- template's RECORDED ancestry that the refusal proved has charges standing -- the facts
          -- the prohibition rests on, so a consumer can render or audit the prohibition without
          -- re-deriving it (and, when it is empty, can see that the caution branch was a caution
          -- and not a hidden assertion). `lineage_truncated` says the upward walk stopped before a
          -- root: unreachable through these verbs (propose refuses to extend a chain to the cap),
          -- so a true here is a forged or restored register and worth a census of its own. Both
          -- keys are ALWAYS present -- empty array, false -- for this file's stable-shape rule.
          'replaced_generations', to_jsonb(coalesce(v_repl_ids, '{}'::text[])),
          'lineage_truncated', coalesce((v_anc ->> 'truncated')::boolean, false))
          || v_corr_breach)::text;
  end if;
  if v_corr_breach is not null then
    raise exception 'period % .. % cannot be run again: entry % is dated % but its correction is dated %, so the period''s own balance never cleared and re-running it would leave the figure standing twice. This period must be finished by hand; retire this template (clara.retire_adjustment_template) to stop it being proposed.', v_ps, v_pe, v_corr_breach ->> 'entry_id', v_corr_breach ->> 'posting_date', coalesce(v_corr_breach ->> 'correction_posting_date', 'nothing -- the half is still standing un-corrected')
      using errcode = 'CLR38',
        detail = (jsonb_build_object('reason', 'period_correction_unsound',
          'template_id', p_template, 'period_start', v_ps, 'period_end', v_pe,
          'remedy', 'retire_adjustment_template')
          || v_corr_breach)::text;
  end if;

  -- (5) THE PERIOD IS NOT ONE A GENERATION THIS TEMPLATE REPLACES HAS ALREADY CHARGED
  -- [R11 FIX 2026-08-04 -- as-built ladder round 11; W1 finding 1 HIGH, Codex r11 finding 1 HIGH].
  --
  -- THIS IS THE WALL THE SENTENCE WAS NOT. The prohibition one screen down is a SENTENCE inside
  -- the shape gate's refusal, and this file said so in as many words: "a professional who reads it
  -- and re-cuts anyway ... is not stopped: that template's shape is disjoint from the standing
  -- charges, clara._wdb_rerun_breach is keyed on shape intersection, and the four already-charged
  -- months run as ordinary catch-up drafts". Round 11 MEASURED both halves of that note as live
  -- money -- RM18,000 of expense against an RM6,000 intention, declared and undeclared alike, with
  -- warnings [] and blocked [] -- and the owned adjudication ruled the sentence insufficient. The
  -- note also named what the fix must be ("a membership term keyed on the recorded lineage rather
  -- than on the shape ... a NEW admission law with its own refusal token, its own blocked[] word
  -- and its own surface gloss -- an adjudication, not a fix lane's call"). It was adjudicated, and
  -- this is it, with all three of those pieces.
  --
  -- IT IS ADDITIVE AND LAST, exactly as (4) was: the window / period_already_met /
  -- occurrence_draft_outstanding trio and the re-run gate keep their pinned order, wording and
  -- precedence to the character (round 4 measured three regressions in this body's admission law
  -- and the lesson was to add beside, never to reorder). Being last also makes its blast radius
  -- exactly what it should be: where the shape gate already refuses -- every [WDB-G13] edit that
  -- keeps its accounts -- the reader still gets (4)'s refusal with its remedy grammar, unchanged.
  -- What reaches HERE is the case nothing else could see: the RE-CODE, whose shape is disjoint by
  -- construction.
  --
  -- IT SITS ABOVE THE ELIGIBILITY RE-DERIVATION for (4)'s own reason, restated: a period that
  -- cannot lawfully be run at all must not be reported as an ACCOUNT problem, and
  -- clara._adj_oldest_unmet_period asks the two in exactly this order so the verb and the oracle
  -- can never name different reasons for one period.
  --
  -- WHAT IT CANNOT DO, STATED SO NOBODY EXPECTS IT TO. It keys on the RECORDED edge and nothing
  -- else -- never the status, never the shape, never the click order (that immunity is the whole
  -- point of round 10's column). A professional who declares nothing gets no wall here; what
  -- reaches them is propose's term (c) advisory, at the door where the start date is still one
  -- edit from being right. That asymmetry is deliberate and it is why BOTH were built: a wall
  -- that guessed at lineage would be round 9's defect a third time.
  --
  -- THE FALSE-POSITIVE PROOF THAT MAKES IT SAFE TO BUILD (W1 probe w1b-lawful-recode.mjs, both
  -- lawful re-code roads, measured): (1) FORWARD-ONLY -- gen1 charged 2026-03/04, gen2 declared
  -- and starting 2026-05 -- both months RAN and the books are exactly right, because gen1's
  -- standing periods do not overlap the periods gen2 books, so this predicate does not fire;
  -- (2) CORRECT-THEN-RECUT -- reversing gen1's occurrences in their own periods drops its standing
  -- count to zero, after which the disjoint re-cut books every month exactly once. Every lawful
  -- re-code is already covered by acts the professional holds today, and this wall parks neither.
  v_repl_std := clara._wdb_replaced_generation_standing(p_client, p_template, v_ps, v_pe);
  if jsonb_array_length(v_repl_std) > 0 then
    select string_agg('template ' || (g ->> 'template_id')
                      || coalesce(' ("' || (g ->> 'name') || '", ' || (g ->> 'status') || ')', '')
                      || ' carries ' || (g ->> 'standing_in_window')
                      || ' standing charge(s) in this period (entry ' || (g ->> 'entry_id')
                      || '), and last charged anything at '
                      || coalesce(g ->> 'last_period_any', 'an unstated period'),
                      '; ' order by g ->> 'template_id'),
           max((g ->> 'last_period_any') collate "C")
      into v_repl_txt, v_repl_last
      from jsonb_array_elements(v_repl_std) as t(g);
    raise exception 'period % .. % is already charged by a generation this template REPLACES, so running it would book those months a second time: %. That lineage is RECORDED on this template (replaces_template_id, declared at propose and immutable since), not inferred, and the account codes are irrelevant to it -- a replacement on fresh codes doubles the figure just as exactly as one on the same codes. Two acts do not double: correct that standing entry within its own period (the run receipt names the verb that admits it today), or retire this template and propose it again starting after %. If this template does NOT in fact replace that generation, retire it (clara.retire_adjustment_template) and propose it again without naming a predecessor -- a recorded lineage is a claim about these books and is corrected by making it again, never by editing it.', v_ps, v_pe, v_repl_txt, coalesce(v_repl_last, 'that generation''s last charged period')
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'replaced_generation_period_standing',
          'template_id', p_template, 'period_start', v_ps, 'period_end', v_pe,
          -- THE FACTS THE PROHIBITION RESTS ON, SEPARATELY MACHINE-READABLE, in the same two
          -- spellings the shape gate uses -- `replaced_generations` as bare ids for a consumer
          -- that only needs to know WHO, and the full rows for one that renders the measurement.
          'replaced_generations', (select coalesce(jsonb_agg(g ->> 'template_id'
                                                    order by g ->> 'template_id'), '[]'::jsonb)
                                     from jsonb_array_elements(v_repl_std) as t(g)),
          'standing_in_period', v_repl_std,
          'start_after', v_repl_last,
          'remedy', jsonb_build_array('correct_the_standing_entry_in_period',
                                      'start_after_replaced_generation',
                                      're_propose_without_predecessor'),
          'lineage_truncated', coalesce(
            (clara._wdb_template_ancestry(p_client, p_template) ->> 'truncated')::boolean,
            false))::text;
  end if;

  -- ELIGIBILITY IS RE-DERIVED AT EVERY OCCURRENCE (design SS2.1), not only at propose: an
  -- account can be deactivated, re-classed, bound to a bank account or enrolled into a
  -- register between the signature and the run. Refusing here (rather than at approve) keeps
  -- the honest state visible in the due oracle instead of minting a draft that can only die.
  v_breach := clara._adj_line_eligibility_breach(p_client, t.lines);
  if v_breach is not null then
    -- THE OTHER ROAD TO THE SAME DOUBLING, AND THE ONE ROUND 9 LEFT UNWARNED (round 10,
    -- finding 3). This refusal NAMES A REMEDY -- "retire this template and propose a corrected
    -- one" -- and a remedy that names an act is asserting something about that act's
    -- consequences (WDB-R2). MEASURED (probes z2/p5-fa-claims-template-code.mjs and
    -- z2/p6-realistic-recut.mjs, re-run on this rig): a live RM500/month accrual Dr EXPA / Cr
    -- ACCR with May and June standing (EXPA 100000, ACCR -100000); an admin binds EXPA as a
    -- fixed-asset profile's expense role on the /assets screen -- an ordinary act on another
    -- family's door, admitted silently -- and this template goes terminally blocked. The
    -- bookkeeper follows the printed remedy, and the replacement necessarily lands on FREE codes
    -- (the old one is claimed), so its shape is FULLY DISJOINT from the standing charges and
    -- clara._wdb_rerun_breach -- which is keyed on shape intersection -- cannot see them: the
    -- sweep offered May, June and July, all three arrived as ordinary catch-up drafts with
    -- blocked:[], and the books carried EXPA 100000 + EXPB 150000 against an intention of
    -- 150000. The sibling refusal above has warned about exactly this since round 9, but only
    -- inside a branch that REQUIRES an overlap to fire -- and this road is the one where an
    -- overlap is impossible by construction.
    --
    -- SO THE CAUTION RIDES HERE TOO, MEASURED, FROM THE SAME CENSUS BODY. And here it needs no
    -- lineage inference at all: the predecessor of the replacement this refusal is asking for is
    -- THIS template, by construction, so what its own standing charges are is a fact rather than
    -- a guess. It is a caution and not a refusal because retire-and-re-propose IS the right act
    -- -- there is no other -- and the periods only double if the replacement's start date reaches
    -- back over them.
    v_own := clara._wdb_template_standing_charges(p_client, p_template);
    raise exception 'template line account % is no longer eligible (%); retire this template and propose a corrected one%', v_breach ->> 'account_code', v_breach ->> 'axis',
      case when coalesce((v_own ->> 'standing')::int, 0) = 0 then ''
           else '. MEASURE FIRST: this template already carries ' || (v_own ->> 'standing')
             || ' standing charge(s) for ' || coalesce(v_own ->> 'first_period', 'an unstated period')
             || ' .. ' || coalesce(v_own ->> 'last_period', 'an unstated period')
             || '; a replacement whose start date reaches back over them re-charges those '
             || 'periods, and because the replacement must use FREE account codes it shares no '
             || 'account with these charges, so the re-run gate cannot see the double. Start the '
             || 'replacement after ' || coalesce(v_own ->> 'last_period', 'the last charged period')
             || ', or reverse those charges first.' end
      using errcode = 'CLR38',
        detail = (jsonb_build_object('reason', 'template_line_ineligible',
          'template_id', p_template,
          'standing_charges', coalesce((v_own ->> 'standing')::int, 0),
          'standing_first_period', v_own ->> 'first_period',
          'standing_last_period', v_own ->> 'last_period') || v_breach)::text;
  end if;

  -- ------------------------------------------------------------------------------------
  -- THE DRAFT (SS9.5 direct INSERT; the SS2.3 column recipe).
  -- ------------------------------------------------------------------------------------
  -- HEADERS ARE FALSE, ALWAYS [L5/3]: a template is an ORDINARY periodic adjustment.
  -- Year-end and tax-affecting adjustments are hand-draft territory in v1 -- a stated
  -- boundary -- which is what makes the template lane's CLR05 exposure amount-driven only.
  v_label := clara._adj_period_label(t.cadence, v_pe);
  v_memo := t.memo_template || ' — ' || v_label;   -- ABI SSC memo grammar (U+2014 em dash)
  insert into clara.journal_entries(client_id, status, posting_date, memo, origin,
      is_opening_balance, is_year_end, tax_affecting, maker_actor, last_human_editor, flags)
    values (p_client, 'draft', v_pe, v_memo, 'scheduled_run',
      false, false, false, v_actor,
      -- THE SIGNER STAMP (the 0041 poster's law): with last_human_editor NULL,
      -- clara._approve_entry_core accepts ANY approver plus an attestation and WD-R8's
      -- distinct-checker intent would not bind at all on a machine-born high-stakes
      -- adjustment. Stamping the TEMPLATE SIGNER puts that signer on the distinct-checker arm.
      t.signed_by,
      jsonb_build_object('recurring_adjustment', jsonb_build_object(
        'template_id', p_template, 'op_key', p_op_key, 'role', 'occurrence',
        'auto_reverse', t.auto_reverse,
        -- The mirror's posting date, stated on the occurrence so /queue can disclose the
        -- pair before it exists (the [L1/24] G2 disclosure item). NULL when the template does
        -- not auto-reverse: the key stays present so the flags schema is stable, and it says
        -- honestly that no mirror is coming.
        'reversal_date', case when t.auto_reverse then v_pe + 1 end,
        'period_start', v_ps, 'period_end', v_pe)))
    returning id into v_entry;

  for r in select (x.value ->> 'account_code') as code,
                  coalesce((x.value ->> 'debit_cents')::bigint, 0) as dr,
                  coalesce((x.value ->> 'credit_cents')::bigint, 0) as cr,
                  nullif(btrim(coalesce(x.value ->> 'description', '')), '') as descr,
                  x.ord::int as n
           from jsonb_array_elements(t.lines) with ordinality as x(value, ord)
           order by x.ord loop
    insert into clara.journal_lines(entry_id, line_no, account_code, debit_cents,
        credit_cents, description)
      values (v_entry, r.n, r.code, r.dr, r.cr, r.descr);
  end loop;

  -- EXACT EQUALITY BEFORE THE VALIDATOR (the 0041 poster's law). clara._validate_entry_lines
  -- tolerates a five-sen rounding residue and would silently route it to a rounding account;
  -- a signed template that does not balance to the sen is a defect, not a rounding event.
  select coalesce(sum(debit_cents), 0), coalesce(sum(credit_cents), 0) into v_dr, v_cr
    from clara.journal_lines where entry_id = v_entry;
  if v_dr <> v_cr then
    raise exception 'the occurrence does not balance exactly (% vs %)', v_dr, v_cr
      using errcode = 'CLR07';
  end if;
  perform clara._assert_balanced(v_entry);

  -- ------------------------------------------------------------------------------------
  -- THE MODE DECISION (design SS2.3). post IFF ramp-earned AND NOT high-stakes AND NOT
  -- catch-up. All three are decided HERE, under the rung, and the answer is STAMPED into the
  -- flags [L5/8] -- the hook re-checks the stamp against the two facts that can still be
  -- true at approve (forced-draft, high-stakes) and NEVER re-derives the ramp.
  -- ------------------------------------------------------------------------------------
  -- THE UNIFIED RAMP CLOCK [L6/1 -- the round-6 money defect]. A correction on EITHER lane
  -- resets the template's clock: a COMPLETED pair reversal (auto-reverse templates) and a
  -- plain clara.reverse_entry on a SOLO occurrence (non-auto-reverse templates). Without the
  -- second term the sweep would re-post the very occurrence a human had just corrected.
  -- GREATEST ignores NULLs, so a template with only one kind of correction still reads its
  -- own clock correctly, and a template with none coalesces to -infinity.
  select coalesce(greatest(
           (select max(pr.completed_at) from clara.adjustment_pair_reversals pr
             where pr.template_id = p_template and pr.status = 'completed'),
           (select max(m.approved_at) from clara.journal_entries m
              join clara.journal_entries o on o.id = m.reversal_of
             where m.status = 'approved'
               and o.flags ? 'recurring_adjustment'
               and (o.flags -> 'recurring_adjustment' ->> 'template_id') = p_template::text
               and (o.flags -> 'recurring_adjustment' ->> 'role') = 'occurrence')),
         '-infinity'::timestamptz)
    into v_watermark;
  -- THE RAMP IS DERIVED, PER TEMPLATE, WITH NO COLUMN AND NO RECEIPT JOIN: autonomy is earned
  -- iff at least one OTHER approved, un-reversed occurrence of THIS template was approved
  -- strictly after the watermark. Occurrence #1 always drafts; a corrected period's re-run
  -- drafts; a mirror never earns (role='reversal' is excluded by the predicate itself).
  v_ramp := exists (select 1 from clara.journal_entries j
                    where j.client_id = p_client
                      and j.flags ? 'recurring_adjustment'
                      and (j.flags -> 'recurring_adjustment' ->> 'template_id') = p_template::text
                      and (j.flags -> 'recurring_adjustment' ->> 'role') = 'occurrence'
                      and j.status = 'approved' and j.reversed_by is null
                      and j.id <> v_entry
                      and j.approved_at > v_watermark);

  -- CATCH-UP OCCURRENCES ALL DRAFT [WDB-G4]. A period that had already ENDED, in Malaysia,
  -- when the template was signed is history being written -- it gets a human's eyes every
  -- time, however earned the ramp is. The boundary is strict: a period ending ON the MYT sign
  -- date was not "already ended at signing" and follows the normal ramp law [L1/E3].
  v_catch_up := (v_pe < (t.signed_at at time zone 'Asia/Kuala_Lumpur')::date);

  -- HIGH STAKES IS ASKED OF THE ENTRY, NOT RE-DERIVED. clara.is_high_stakes is the product's
  -- single definition of the term and it takes an entry id, so the stamp is a SECOND
  -- statement on the draft: `flags` is in the draft->draft allowset of
  -- clara._tf_entry_immutable (0015:1057-1059), which is exactly what that allowset is for.
  -- Re-deriving the threshold arithmetic here to fit the stamp into the INSERT would put a
  -- second copy of the high-stakes law in the file, and the copy would be the one that rots.
  v_high := clara.is_high_stakes(v_entry);
  v_mode := case when v_ramp and not v_high and not v_catch_up then 'post' else 'draft' end;
  update clara.journal_entries
     set flags = jsonb_set(flags, '{recurring_adjustment,mode}', to_jsonb(v_mode), true),
         updated_at = now()
   where id = v_entry;

  -- The revision token is read AFTER both the line inserts (t_jl_rotate_token rotates it) and
  -- the mode stamp, so the value handed to the approve core is the live one.
  select je.revision_token into v_rev from clara.journal_entries je where je.id = v_entry;

  if v_mode = 'post' then
    -- The CLR26 open-question block or any other core refusal leaves the entry a DRAFT and
    -- the period due, honestly -- the transaction rolls back and nothing half-lands.
    perform clara._approve_entry_core(
      jsonb_build_object('actor', t.signed_by, 'firm', p_firm, 'receipt_preheld', true),
      v_entry, v_rev, null, v_approve_key);
    v_status := 'posted';
    -- The receipt and the mirror were minted by clara._adj_on_approve inside that call; the
    -- envelope reports what the hook actually wrote rather than what this verb intended.
    select ar.id, ar.reversal_entry_id, ar.amount_cents
      into v_run, v_rev_entry, v_amount
      from clara.adjustment_runs ar where ar.entry_id = v_entry;
  else
    v_status := 'drafted';
    v_amount := v_dr;
  end if;

  perform clara._audit(p_firm, v_actor, null, null, p_verb, v_entry,
    jsonb_build_object('client', p_client, 'template', p_template, 'period_start', v_ps,
      'period_end', v_pe, 'period_label', v_label, 'mode', v_mode, 'status', v_status,
      'ramp_earned', v_ramp, 'catch_up', v_catch_up, 'high_stakes', v_high,
      'amount_cents', v_amount, 'op_key', p_op_key));
  return clara._finish_op(p_firm, p_verb, p_op_key,
    jsonb_build_object('status', v_status, 'entry_id', v_entry, 'mode', v_mode)
      || case when v_run is not null then jsonb_build_object('run_id', v_run)
              else '{}'::jsonb end
      || case when v_rev_entry is not null
              then jsonb_build_object('reversal_entry_id', v_rev_entry)
              else '{}'::jsonb end);
end $$;
revoke all on function clara._adj_run_occurrence_core(uuid, uuid, date, date, text, uuid,
  uuid, text) from public;

-- THE MACHINE TWIN (design SS2.3/SS2.7). Granted to clara_runtime ONLY -- there is no
-- _human_ctx here because there is no human: the leader loop calls it under `set role
-- clara_runtime` with an op key of the pinned shape adj:<client>:<template>:<period_start>:
-- <rand8> (ABI SSE; the random suffix is load-bearing, so an abandoned claimed-but-unfinished
-- reservation from a crashed tick never blocks the next one).
create function clara.run_adjustment_occurrence(p_client uuid, p_template uuid,
    p_period_start date, p_period_end date, p_op_key text)
  returns jsonb
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare v_firm uuid;
begin
  select cl.firm_id into v_firm from clara.clients cl where cl.id = p_client;
  if v_firm is null then
    raise exception 'client not found' using errcode = 'CLR11';
  end if;
  return clara._adj_run_occurrence_core(p_client, p_template, p_period_start, p_period_end,
    p_op_key, null, v_firm, 'run_adjustment_occurrence');
end $$;
revoke all on function clara.run_adjustment_occurrence(uuid, uuid, date, date, text) from public;

-- THE HUMAN TWIN (bookkeeper+). Same core, same law; the caller becomes maker_actor while
-- last_human_editor stays the template's signer, so a bookkeeper running a period by hand
-- cannot dissolve the signer's distinct-checker binding.
create function clara.run_adjustment_manual(p_client uuid, p_template uuid,
    p_period_start date, p_period_end date, p_op_key text)
  returns jsonb
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare c record; v_firm uuid;
begin
  c := clara._human_ctx(clara.role_rank('bookkeeper'));
  select cl.firm_id into v_firm from clara.clients cl where cl.id = p_client;
  if v_firm is null or v_firm <> c.firm then
    raise exception 'client is not in your firm' using errcode = 'CLR11';
  end if;
  return clara._adj_run_occurrence_core(p_client, p_template, p_period_start, p_period_end,
    p_op_key, c.actor, c.firm, 'run_adjustment_manual');
end $$;
revoke all on function clara.run_adjustment_manual(uuid, uuid, date, date, text) from public;

-- =====================================================================================
-- S2.4 -- THE DUE ORACLE (design SS2.3). The sweep never calls into a refusal it can
-- predict, and /rules renders the same advisory the sweep acts on.
-- =====================================================================================

-- PER TEMPLATE: the OLDEST unmet, ended, in-window period. The walk starts at the template's
-- start_date (a period start by construction) and steps period by period; only the FIRST
-- unmet one matters, so it returns at once. Both predicates ride the ABI SSC indexes.
create function clara._adj_oldest_unmet_period(p_client uuid, p_template uuid) returns jsonb
  language plpgsql stable security definer set search_path = clara, pg_temp as $$
declare t record; v_today date; v_ps date; v_pe date; v_guard int := 0; v_breach jsonb;
        v_corr_breach jsonb;
begin
  select * into t from clara.adjustment_templates a
    where a.id = p_template and a.client_id = p_client;
  if not found or t.status <> 'live' then
    return jsonb_build_object('due', false, 'reason', 'template_not_live');
  end if;
  -- DRAFT-N BLOCKS N+1, per template. Answered here rather than left to the verb's refusal,
  -- so the sweep can skip the template and the panel can badge it.
  if clara._adj_occurrence_outstanding(p_client, p_template) then
    return jsonb_build_object('due', false, 'reason', 'occurrence_draft_outstanding');
  end if;
  -- A LIVE TEMPLATE WHOSE start_date IS NO LONGER A PERIOD START cannot be run: the poster
  -- would refuse it not_cadence_aligned. clara.set_client_fy_end refuses while a live ANNUAL
  -- template exists, so this is unreachable in practice -- and the oracle says so honestly
  -- rather than advertising a period the verb would then refuse.
  if clara._adj_period_start(p_client, t.cadence, t.start_date) is distinct from t.start_date then
    return jsonb_build_object('due', false, 'reason', 'template_fy_stale');
  end if;
  v_today := clara._fa_today();
  v_ps := t.start_date;
  loop
    v_guard := v_guard + 1;
    -- THE GUARD'S TRUE SUBJECT, MEASURED (round 10, finding 8). It claimed to catch "a template
    -- whose window is that wide" -- a start-date typo -- and it cannot: the walk RETURNS at the
    -- first UNMET period, so an ancient start date exits at v_guard = 1 and this arm is silent.
    -- MEASURED (probe z1/p3-domain-and-scale.mjs): a monthly template starting 0001-01-01
    -- answers {due:true, 0001-01-01 .. 0001-01-31, blocked:[]} on the FIRST iteration. Every
    -- iteration past the first is a period that IS met, and every met period is an approved,
    -- un-corrected occurrence row -- so the counter measures postings, not calendar. The
    -- implausible start date is now warned at the door that can actually see it
    -- (clara.propose_adjustment_template's implausible_start_date advisory), and what reaches
    -- HERE is one of two genuine defects, each with its own axis:
    --   met_period_run       -- 2,400 CONSECUTIVE met periods, i.e. 2,400 approved,
    --                           un-corrected occurrences for one template (200 monthly years of
    --                           real postings). The honest remedy is not "propose a realistic
    --                           start date" -- the start date is not what produced them -- but
    --                           to look at what wrote them and retire the template so the sweep
    --                           stops asking.
    --   period_not_advancing -- clara._adj_period_end returned an end BEFORE the period's own
    --                           start, so `v_ps := v_pe + 1` walks BACKWARD and the loop can
    --                           never terminate. That is the runaway the counter was actually
    --                           protecting against, and naming it where it happens turns 2,400
    --                           wasted iterations into one sharp diagnosis.
    -- BOTH RAISE rather than answering on blocked[], unlike every neighbouring terminal state:
    -- these are corrupt-state defects rather than accounting facts a bookkeeper can act on, and
    -- the token stays the ABI's `template_window_scan_exceeded` because it is the word this
    -- family already owns for "this walk cannot be finished".
    if v_guard > 2400 then
      raise exception 'adjustment template % has walked 2400 consecutive met periods from % without reaching an unmet one -- that is 2400 approved, un-corrected occurrences for one template; inspect what wrote them, and retire this template to stop the sweep', p_template, t.start_date
        using errcode = 'CLR38',
          detail = jsonb_build_object('reason', 'template_window_scan_exceeded',
            'axis', 'met_period_run', 'template_id', p_template,
            'start_date', t.start_date, 'periods_walked', v_guard - 1)::text;
    end if;
    v_pe := clara._adj_period_end(p_client, t.cadence, v_ps);
    if v_pe < v_ps then
      raise exception 'adjustment template % (% cadence) derived the period % .. %, which ends before it starts, so this walk cannot advance; retire this template', p_template, t.cadence, v_ps, v_pe
        using errcode = 'CLR38',
          detail = jsonb_build_object('reason', 'template_window_scan_exceeded',
            'axis', 'period_not_advancing', 'template_id', p_template,
            'cadence', t.cadence, 'period_start', v_ps, 'period_end', v_pe)::text;
    end if;
    exit when t.end_date is not null and v_pe > t.end_date;   -- window exhausted
    exit when v_pe >= v_today;                                -- not ended yet, in MYT
    if not exists (select 1 from clara.journal_entries je
                   where je.flags ? 'recurring_adjustment'
                     and (je.flags -> 'recurring_adjustment' ->> 'template_id') = p_template::text
                     and (je.flags -> 'recurring_adjustment' ->> 'period_start')
                           = to_char(v_ps, 'YYYY-MM-DD')
                     and (je.flags -> 'recurring_adjustment' ->> 'role') = 'occurrence'
                     and je.status = 'approved' and je.reversed_by is null) then
      -- PERIOD SOUNDNESS IS ASKED FIRST OF THE TWO LAZY QUESTIONS [as-built ladder round 5],
      -- in the SAME order clara._adj_run_occurrence_core asks them, so the oracle and the verb
      -- can never name different reasons for one period. Asked HERE, lazily, for the reason
      -- the eligibility probe below is: a blocked, FY-stale or fully caught-up template pays
      -- nothing for it, and the walk returns at the first unmet period so it runs at most once
      -- per template per call.
      --
      -- WHY IT MUST BE ASKED AT ALL, and this is the round-2 template_line_ineligible lesson
      -- restated: without it the oracle answers {due:true} for a triple the poster is
      -- GUARANTEED to refuse CLR38 period_correction_unsound -- forever, once per daily sweep,
      -- with nothing self-limiting it (the refusal mints no draft, so the draft-N-blocks-N+1
      -- arm never engages), and the reconciler isolates a raise PER CLIENT, so one such
      -- template would cost every OTHER due template on that client its whole tick.
      --
      -- THE WALK STOPS HERE rather than skipping to the next period, exactly as
      -- occurrence_draft_outstanding stops it: accrual periods are sequential, and posting a
      -- later period over an earlier one that is still double-counting would compound the
      -- defect instead of parking it.
      --
      -- ASKED WITH THE SHAPE [round 6], exactly as clara._adj_run_occurrence_core asks it, so
      -- the two still cannot name different reasons for one period. The generation bypass is
      -- visible HERE first: a template that replaces a retired one is advertised for every
      -- period the retired generation already met, and that advertisement IS the mechanism --
      -- the sweep acts on it unattended. The walk STOPS rather than skipping to the next
      -- period, for the reason the neighbouring arms stop it: accrual periods are sequential,
      -- and quietly accruing a later month while an earlier one is still double-countable
      -- compounds the defect instead of parking it in front of a human.
      v_corr_breach := clara._wdb_rerun_breach(p_client, 'recurring_adjustment',
                                               clara._wdb_line_shape(t.lines), v_ps, v_pe);
      if v_corr_breach is not null then
        return jsonb_build_object('due', false, 'reason',
          case when (v_corr_breach ->> 'axis') = 'shape_already_met'
               then 'period_shape_already_met' else 'period_correction_unsound' end);
      end if;
      -- LINE ELIGIBILITY IS THE ORACLE'S LAST QUESTION (as-built ladder fix 2026-08-02), and
      -- it is asked HERE -- lazily, at the one point where the answer would otherwise be
      -- `due: true` -- rather than at the top of the body. A blocked, FY-stale or fully
      -- caught-up template then pays NOTHING for it, and the probe runs at most once per
      -- template per call because the walk returns at the first unmet period.
      --
      -- WHY IT MUST BE ASKED AT ALL. The poster re-derives eligibility on EVERY occurrence
      -- (design SS2.1: an account can be deactivated, re-classed, bound to a bank account or
      -- enrolled into a register between the signature and the run), while the enrolment
      -- doors -- clara.enrol_staff_advance_account, clara.upsert_fa_account_profile -- do NOT
      -- consult template lines, nor could they: a zero-balance code is lawfully enrollable
      -- and the enrol verb's own enrolment_balance_nonzero guard never binds on one. So an
      -- admin can reserve a live template's line account at any moment, and from that instant
      -- this oracle was answering {due:true} with an EMPTY blocked[] for a triple
      -- clara.run_adjustment_occurrence is GUARANTEED to refuse CLR38
      -- template_line_ineligible -- once per daily sweep, forever, with nothing self-limiting
      -- it (the refusal mints no draft, so the draft-N-blocks-N+1 arm never engages). Worse,
      -- the reconciler isolates a raise PER CLIENT, not per template, so one dead template
      -- silently cost every OTHER due template on that client its whole tick.
      --
      -- THE TOKEN IS template_line_ineligible -- the SAME ABI SSF word propose (CLR10) and the
      -- poster (CLR38) already use for this exact condition, so blocked[]'s vocabulary grows
      -- by a word the ABI already owns rather than by a new one. The ROW SHAPE is unchanged:
      -- ABI SSA pins blocked[] rows as {template_id, reason} and they stay exactly that, so
      -- the breach's account_code and finer axis are deliberately NOT surfaced here -- a
      -- human's remedy is the same whichever line broke (retire the template, propose a
      -- corrected one), and clara.run_adjustment_manual names the account when they ask.
      -- [R11 FIX 2026-08-04 -- as-built ladder round 11] AND THE LINEAGE MEMBERSHIP WALL IS ASKED IN THE
      -- SAME PLACE THE VERB ASKS IT: after the re-run gate, before eligibility. Admission predicate
      -- (5) at clara._adj_run_occurrence_core refuses a period a generation this template REPLACES
      -- has already charged; without this arm the oracle would advertise exactly those periods,
      -- {due:true, blocked:[]}, and the unattended sweep would drive straight into a CLR38 once a
      -- day forever -- with nothing self-limiting it, because a refusal mints no draft and the
      -- draft-N-blocks-N+1 arm never engages. That is the round-2 template_line_ineligible lesson
      -- and the round-6 shape-gate lesson, and this is the third member of the same family.
      -- THE WALK STOPS HERE rather than skipping to the next period, for the neighbours' reason:
      -- accrual periods are sequential, and quietly accruing a later month while an earlier one is
      -- still double-countable compounds the defect instead of parking it in front of a human.
      if jsonb_array_length(
           clara._wdb_replaced_generation_standing(p_client, p_template, v_ps, v_pe)) > 0 then
        return jsonb_build_object('due', false,
                                  'reason', 'replaced_generation_period_standing');
      end if;
      v_breach := clara._adj_line_eligibility_breach(p_client, t.lines);
      if v_breach is not null then
        return jsonb_build_object('due', false, 'reason', 'template_line_ineligible');
      end if;
      return jsonb_build_object('due', true, 'period_start', v_ps, 'period_end', v_pe,
        'cadence', t.cadence);
    end if;
    v_ps := v_pe + 1;   -- both cadences: the next period opens the day after this one closes
  end loop;
  return jsonb_build_object('due', false, 'reason', 'nothing_due');
end $$;
revoke all on function clara._adj_oldest_unmet_period(uuid, uuid) from public;

-- THE CLIENT-LEVEL ORACLE (ABI SSA envelope): the oldest unmet (template, period) across every
-- live template that is NOT draft-blocked, plus the blocked[] advisory the /rules panel
-- renders per template. Firm-scoped exactly like clara.depreciation_run_due -- and now
-- through the SAME body: both consult clara._assert_due_read_ctx (S2.0), so the two members
-- of this family cannot drift apart again (owner ruling 2026-08-03, WDB-R1/WDB-R2).
create function clara.adjustment_run_due(p_client uuid) returns jsonb
  language plpgsql stable security definer set search_path = clara, pg_temp as $$
declare
  v_firm uuid; tp record; v_one jsonb; v_blocked jsonb := '[]'::jsonb;
  v_best_template uuid; v_best_ps date; v_best_pe date;
begin
  select cl.firm_id into v_firm from clara.clients cl where cl.id = p_client;
  -- ADMISSION BEFORE ANSWERING ANYTHING -- INCLUDING 'client_not_found'. The lookup runs
  -- first only because the predicate needs the firm to compare against; the verdict is
  -- reached before ANY branch returns, so an unadmitted caller cannot use this oracle to
  -- probe which client ids exist. A caller who IS admitted keeps the pre-existing
  -- client_not_found / CLR11 distinction exactly as the ABI pins it.
  perform clara._assert_due_read_ctx(v_firm);
  if v_firm is null then
    return jsonb_build_object('due', false, 'reason', 'client_not_found',
      'blocked', '[]'::jsonb);
  end if;
  for tp in select a.id from clara.adjustment_templates a
            where a.client_id = p_client and a.status = 'live'
            order by a.created_at, a.id loop
    v_one := clara._adj_oldest_unmet_period(p_client, tp.id);
    -- THREE REASONS REACH blocked[] (two from the 2026-08-02 fix, the third from as-built
    -- ladder round 5). Each names a template the sweep must skip and a human must act on, and
    -- the row shape stays the ABI SSA pair {template_id, reason}:
    --   occurrence_draft_outstanding  -- transient: approve or withdraw the draft (design SS2.3)
    --   template_line_ineligible      -- terminal: retire the template and propose a corrected
    --                                    one, because the poster will refuse this triple CLR38
    --                                    every single time (the eligibility comment upstairs).
    --   period_correction_unsound     -- terminal for this period: the period was corrected
    --                                    outside itself (or a pair half is still standing), so
    --                                    re-running it would double a statutory figure. Named
    --                                    on blocked[] rather than swallowed because the whole
    --                                    point of the poster's refusal is that a HUMAN must
    --                                    decide which figure the books should end up with, and
    --                                    a human who is never told cannot decide.
    --   period_shape_already_met      -- terminal for this period [round 6]: an approved,
    --                                    uncorrected posting on this template's OWN account
    --                                    shape is standing in this period under another
    --                                    authority. The overwhelmingly common cause is the
    --                                    [WDB-G13] edit -- retire, re-propose with the
    --                                    corrected figure -- and the whole reason it reaches
    --                                    blocked[] is that the alternative is what round 6
    --                                    measured: the oracle advertising those periods and
    --                                    the sweep silently re-accruing every one of them.
    -- template_fy_stale stays EXCLUDED-not-reported: clara.set_client_fy_end refuses while a
    -- live annual template exists, so it is structurally unreachable rather than merely rare,
    -- and reporting an unreachable state on /rules would be noise the panel cannot act on.
    --   replaced_generation_period_standing
    --                                 -- terminal for this period [R11 FIX 2026-08-04, round 11]: a
    --                                    generation this template RECORDS as its predecessor has a
    --                                    standing, un-corrected charge in this period, and the
    --                                    account codes are irrelevant to that -- a replacement on
    --                                    fresh codes doubles the figure just as exactly as one on
    --                                    the same codes, which is precisely why the shape-keyed
    --                                    reason above cannot see it. It reaches blocked[] for the
    --                                    reason every other terminal reason does: the sweep must
    --                                    skip the template, and the human who has to choose which
    --                                    figure the books end up with cannot choose if nobody
    --                                    tells them.
    if (v_one ->> 'reason') in ('occurrence_draft_outstanding', 'template_line_ineligible',
                                'period_correction_unsound', 'period_shape_already_met',
                                'replaced_generation_period_standing') then
      v_blocked := v_blocked || jsonb_build_array(jsonb_build_object(
        'template_id', tp.id, 'reason', v_one ->> 'reason'));
    elsif coalesce((v_one ->> 'due')::boolean, false)
          and (v_best_ps is null or (v_one ->> 'period_start')::date < v_best_ps) then
      v_best_template := tp.id;
      v_best_ps := (v_one ->> 'period_start')::date;
      v_best_pe := (v_one ->> 'period_end')::date;
    end if;
  end loop;
  if v_best_template is null then
    return jsonb_build_object('due', false, 'reason',
      case when jsonb_array_length(v_blocked) > 0 then 'all_blocked' else 'nothing_due' end,
      'blocked', v_blocked);
  end if;
  return jsonb_build_object('due', true, 'template_id', v_best_template,
    'period_start', v_best_ps, 'period_end', v_best_pe, 'blocked', v_blocked);
end $$;
revoke all on function clara.adjustment_run_due(uuid) from public;


-- [SPLIT D-b2 2026-08-04] THE TWO SUGGESTION-DERIVATION BODIES STAND HERE IN THE WHOLE UNIT AND ARE NOT
-- IN THIS SLICE. clara._wdb_suggestion_rule_hit and clara._wdb_suggestion_lines (s2 L3417-3482)
-- read ONLY clara.bank_statement_lines, clara.bank_rules and clara.bank_accounts and carry no
-- adjustment dependency at all; census sect.2 Class A calls them misfiled and sect.8 assigns
-- them to D-b3, the family whose verb is their FIRST reader. D-b3 shipped them.
-- THIS FILE'S clara._adj_on_approve ARM (3) IS THEIR SECOND READER, AND DELIBERATELY NOT A
-- SECOND IMPLEMENTATION: the whole point of the approve-time re-validation is that the checker
-- approves what the rule says TODAY, and two independent derivations would only ever prove that
-- two pieces of code agree with themselves. The canonical header that stood here says exactly
-- that, and it is why this slice CALLS D-b3's pair rather than re-creating them.

-- =====================================================================================
-- S2.5 -- THE APPROVE-TIME HOOK (design SS2.6; the SS5 producer's arm rides here too).
--
-- SPLICE POINT: SECTION S5 splices `perform clara._adj_on_approve(p_entry);` into
-- clara._subledger_on_approve immediately AFTER `perform clara._fa_on_approve(p_entry);`
-- and ABOVE the settlement early-return, with a positional assert in the tail. That keeps
-- the approve PATHS at the pinned FOUR and the hook-CALLER census at FOUR: every D-b
-- approval goes through clara._approve_entry_core, which makes the _subledger_on_approve
-- call itself [L3/1].
--
-- THE FOUR ARMS, IN ORDER:
--   (0) role='reversal'                  -> return   (keep arm (2) off the mirror)
--   (1) reversal_of IS NOT NULL          -> the pair defense, then return
--   (2) role='occurrence'                -> seven-axis re-validation, mirror, receipt, event
--   (3) flags ? 'bank_rule_suggested'    -> the SS5 producer's approve-time re-validation
--
-- RECURSION BOUNDS AT DEPTH 2. Arm (2) approves the mirror through
-- clara._approve_entry_core, which re-enters this hook with role='reversal' -- arm (0), which
-- mints nothing and calls nothing. There is no third level.
-- =====================================================================================
create function clara._adj_on_approve(p_entry uuid) returns void
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare
  e record; t record; pr record; rl record; ln record;
  v_prop jsonb; v_role text; v_ps date; v_pe date; v_mode text; v_actor uuid;
  v_attest text; v_mirror uuid; v_rev uuid; v_run uuid; v_amount bigint;
  v_want jsonb; v_have jsonb; v_breach jsonb; v_sug jsonb;
  v_derived jsonb; v_actual jsonb;
begin
  select * into e from clara.journal_entries where id = p_entry;
  if not found then return; end if;
  v_prop := e.flags -> 'recurring_adjustment';
  v_role := v_prop ->> 'role';

  -- -----------------------------------------------------------------------------------
  -- (0) THE AUTO-REVERSAL MIRROR. It exists ONLY to keep arm (2) off the mirror -- nothing
  -- else. This is NOT a soft-birth exemption and must never be read as one [L4/9]:
  -- clara._fa_on_approve has already run by the time we are called, and SECTION S3's
  -- clara._adv_on_approve runs after us regardless, so nothing here could suppress a register
  -- birth even if it wanted to. The mirror's immunity is carried by SS2.1 line eligibility
  -- ALONE -- a template line is never an enrolled FA cost account and never an enrolled
  -- advance account, at propose, at every occurrence and again at axis (2g) below. An
  -- eligibility violation therefore RAISES up there; it is never skipped down here.
  -- -----------------------------------------------------------------------------------
  if v_role = 'reversal' then
    return;
  end if;

  -- -----------------------------------------------------------------------------------
  -- (1) THE PAIR DEFENSE (design SS2.4). A pair correction is born by
  -- clara._pair_reverse_core carrying reversal_of and NO D-b flags -- which is exactly why
  -- reversal_of is the right discriminator here and why the (0)(1)(2)(3) order stands.
  --
  -- THE RECEIPT IS THE AUTHORIZATION CHANNEL [L4/1]. This hook has a one-argument signature
  -- and cannot see who called it, so the pair verbs transition their receipt into the
  -- transaction-only `approving` state BEFORE their core calls, and we refuse any pair
  -- correction whose receipt is not in it. An ordinary clara.approve_entry on one half
  -- therefore cannot break the pair apart; the remedy names the atomic verbs.
  -- -----------------------------------------------------------------------------------
  if e.reversal_of is not null then
    select * into pr from clara.adjustment_pair_reversals r
      where r.occurrence_correction_id = p_entry or r.mirror_correction_id = p_entry
      limit 1;
    if found and pr.status <> 'approving' then
      raise exception 'this draft is one half of an adjustment pair reversal and cannot be approved on its own; use clara.approve_pair_reversal (or clara.cancel_pair_reversal to abandon both halves)'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'pair_draft_locked', 'entry_id', p_entry,
            'pair_id', pr.id, 'pair_status', pr.status)::text;
    end if;
    return;
  end if;

  -- -----------------------------------------------------------------------------------
  -- (2) THE OCCURRENCE. Seven axes re-validated under the locks the approve core already
  -- holds, then the mirror, then the receipt, then the event. Same doctrine as the D-a
  -- depreciation arm: the stored proposal is a statement about a world, and if the world
  -- moved the honest answer is one named refusal whose remedy is stated.
  -- -----------------------------------------------------------------------------------
  if v_role = 'occurrence' then
    v_actor := coalesce(e.checker_actor, e.maker_actor);
    v_ps := (v_prop ->> 'period_start')::date;
    v_pe := (v_prop ->> 'period_end')::date;

    -- (2a) ORIGIN. The proposal and the origin are one fact; a recurring-adjustment proposal
    -- on a manual entry would be a forged machine post wearing a human's clothes.
    if e.origin <> 'scheduled_run' then
      raise exception 'a recurring-adjustment proposal may only ride an origin=scheduled_run entry'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'adjustment_stale', 'axis', 'origin',
            'entry_id', p_entry)::text;
    end if;

    -- (2b) THE ISSUER BINDING THAT SURVIVES THE MAKER-CHECKER GAP. A flags blob alone proves
    -- nothing about who wrote it; a durable op receipt does. clara.op_receipts carries no
    -- client column, but clara._reserve_op stores the REQUEST HASH and the poster hashes
    -- exactly (client, template, ps, pe) -- so re-deriving that hash from this entry's own
    -- client and the period the proposal names turns a firm-wide receipt lookup into an exact
    -- match on the act that minted it. A receipt belonging to a SIBLING CLIENT, a sibling
    -- template, or a sibling period no longer authenticates this proposal.
    if not exists (select 1 from clara.op_receipts r
                   where r.firm_id = e.firm_id
                     and r.fn in ('run_adjustment_occurrence', 'run_adjustment_manual')
                     and r.op_key = v_prop ->> 'op_key'
                     and r.request_hash = clara._hash(jsonb_build_object(
                           'client', e.client_id,
                           'template', (v_prop ->> 'template_id')::uuid,
                           'ps', v_ps, 'pe', v_pe))) then
      raise exception 'this adjustment proposal carries no issuer op-key receipt for this client, template and period; withdraw the draft and re-run the period'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'adjustment_stale', 'axis', 'issuer_receipt',
            'entry_id', p_entry)::text;
    end if;

    -- (2c) THE TEMPLATE IS STILL LIVE, and still this client's.
    select * into t from clara.adjustment_templates a
      where a.id = (v_prop ->> 'template_id')::uuid;
    if not found or t.client_id <> e.client_id or t.status <> 'live' then
      raise exception 'the adjustment template this occurrence names is not live for this client; withdraw the draft'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'adjustment_stale', 'axis', 'template_retired',
            'template_id', v_prop ->> 'template_id')::text;
    end if;

    -- (2d) THE LINE SET IS BYTE-EQUAL TO THE TEMPLATE'S. Templates are immutable outside
    -- their transitions, so this axis catches the OTHER direction: a draft whose lines were
    -- edited between the run and the approval. (clara.revise_entry refuses a D-b proposal
    -- draft outright -- SECTION S5 -- so this is defense in depth, and it is cheap.)
    v_want := clara._adj_canon_lines(t.lines);
    select coalesce(jsonb_agg(jsonb_build_object(
             'account_code', jl.account_code,
             'debit_cents', jl.debit_cents,
             'credit_cents', jl.credit_cents,
             'description', jl.description) order by jl.line_no), '[]'::jsonb)
      into v_have from clara.journal_lines jl where jl.entry_id = p_entry;
    if v_want is distinct from v_have then
      raise exception 'this occurrence''s lines no longer equal its template''s; withdraw the draft and re-run the period'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'adjustment_stale', 'axis', 'lines_changed',
            'template_id', t.id)::text;
    end if;

    -- (2e) THE PERIOD IS STILL A CADENCE PERIOD, AND IT HAS ENDED. The FY end is client data
    -- and can move between the run and the approval, which is precisely what this axis
    -- catches for an ANNUAL template. posting_date is asserted against period_end in the same
    -- axis: it is the one column of the recipe a proposal could otherwise misstate.
    if clara._adj_period_start(e.client_id, t.cadence, v_ps) is distinct from v_ps
       or clara._adj_period_end(e.client_id, t.cadence, v_ps) is distinct from v_pe
       or e.posting_date is distinct from v_pe
       or v_pe >= clara._fa_today() then
      raise exception 'the period % .. % is no longer a valid, ended % period for this client', v_ps, v_pe, t.cadence
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'adjustment_stale', 'axis', 'period_invalid',
            'cadence', t.cadence, 'period_start', v_ps, 'period_end', v_pe)::text;
    end if;

    -- (2f) THE MODE STAMP [L5/8]. The ramp is NEVER re-derived here (the sequencing law
    -- freezes it for the draft's whole life: a second run is refused while a draft is
    -- outstanding). What CAN still become true between the run and the approval is
    -- forced-draft (a template signed later than this period ended cannot happen -- signed_at
    -- is immutable -- but the predicate is re-measured anyway) and HIGH STAKES (the firm's
    -- threshold is firm data and can be lowered). A 'post' stamp under either is refused.
    v_mode := v_prop ->> 'mode';
    if v_mode is null or v_mode not in ('post', 'draft') then
      raise exception 'this occurrence carries no lawful mode stamp'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'adjustment_stale', 'axis', 'mode',
            'mode', v_mode)::text;
    end if;
    if v_mode = 'post'
       and (v_pe < (t.signed_at at time zone 'Asia/Kuala_Lumpur')::date
            or clara.is_high_stakes(p_entry)) then
      raise exception 'this occurrence was stamped for auto-posting but now requires a human checker; withdraw the draft and re-run the period'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'adjustment_stale', 'axis', 'mode',
            'mode', v_mode, 'high_stakes', clara.is_high_stakes(p_entry))::text;
    end if;

    -- (2g) LINE ELIGIBILITY -- the SEVENTH axis [L4/9], and the load-bearing one: it is the
    -- SOLE guarantee that the mirror born below cannot soft-birth a register row anywhere.
    -- The cell that proves it: enrol or reserve one of the template's accounts DURING the
    -- draft window, then approve.
    -- THE BREACH'S OWN `axis` IS RE-KEYED, NEVER MERGED OVER THE ARM'S. ABI SSF pins the
    -- arm-(2) vocabulary exactly -- axis IN origin, issuer_receipt, template_retired,
    -- lines_changed, period_invalid, mode, line_eligibility -- and jsonb `||` lets the
    -- right operand win, so a bare concat let _adj_line_eligibility_breach's finer-grained
    -- axis ('account_reserved', 'account_inactive', 'control_account', 'bank_account',
    -- 'account_unknown') CLOBBER the ABI's own token. The two axes are at different
    -- altitudes and both are worth keeping: `axis` answers "which of the seven", and
    -- `eligibility_axis` answers "which of the five conditions inside the seventh".
    -- The other two callers (propose CLR10 / poster CLR38) raise `template_line_ineligible`,
    -- for which the ABI names no axis at all, so they keep the breach's axis verbatim.
    v_breach := clara._adj_line_eligibility_breach(e.client_id, t.lines);
    if v_breach is not null then
      raise exception 'template line account % is no longer eligible to back an adjustment (%); withdraw this draft', v_breach ->> 'account_code', v_breach ->> 'axis'
        using errcode = 'CLR39',
          detail = (jsonb_build_object('reason', 'adjustment_stale', 'axis', 'line_eligibility',
            'template_id', t.id, 'eligibility_axis', v_breach ->> 'axis')
            || (v_breach - 'axis'))::text;
    end if;

    -- ---------------------------------------------------------------------------------
    -- THE MIRROR (design SS2.4; [WDB-G1] hook-born at approve, dated next-period day 1;
    -- [WDB-G2] ONE act births the approved pair).
    -- ---------------------------------------------------------------------------------
    if coalesce((v_prop ->> 'auto_reverse')::boolean, false) then
      -- THE ATTESTATION IS RE-READ AFTER THE OUTER UPDATE [L4/10]. clara._approve_entry_core
      -- stamps self_approval_attestation on the occurrence and THEN calls the subledger hook,
      -- so the value is already durable when we arrive -- but it is re-selected explicitly
      -- rather than taken from the `e` snapshot, because the whole point of the G2 one-act law
      -- under high stakes is that the occurrence's attestation is the mirror's attestation.
      select je.self_approval_attestation into v_attest
        from clara.journal_entries je where je.id = p_entry;

      -- THE 13-COLUMN RECIPE, adapted from clara.reverse_entry's mirror: the three HEADER
      -- booleans are copied VERBATIM from the occurrence so clara.is_high_stakes is provably
      -- equal on both halves and CLR05 cannot diverge across the pair [L4/10]. maker_actor and
      -- last_human_editor are the TEMPLATE SIGNER (not the checker), which keeps the
      -- distinct-checker arm binding on the mirror exactly as it binds on the occurrence.
      -- LINKAGE IS ONE-WAY [L2/4]: the mirror carries auto_reversal_of (FK, UNIQUE) and the
      -- occurrence carries no column at all -- no immutability-trigger recut, boundary clean.
      insert into clara.journal_entries(client_id, status, posting_date, memo, origin,
          resolution_id, is_opening_balance, is_year_end, tax_affecting,
          maker_actor, last_human_editor, flags, auto_reversal_of)
        values (e.client_id, 'draft', v_pe + 1, 'Auto-reversal: ' || coalesce(e.memo, ''),
          'scheduled_run', e.resolution_id,
          e.is_opening_balance, e.is_year_end, e.tax_affecting,
          t.signed_by, t.signed_by,
          jsonb_build_object('recurring_adjustment', jsonb_build_object(
            'template_id', t.id, 'op_key', v_prop ->> 'op_key', 'role', 'reversal',
            'auto_reverse', true, 'reversal_date', v_pe + 1,
            'period_start', v_ps, 'period_end', v_pe, 'mode', v_mode)),
          p_entry)
        returning id into v_mirror;
      insert into clara.journal_lines(entry_id, line_no, account_code, debit_cents,
          credit_cents, description, counterparty_id)
        select v_mirror, jl.line_no, jl.account_code, jl.credit_cents, jl.debit_cents,
               jl.description, jl.counterparty_id
        from clara.journal_lines jl where jl.entry_id = p_entry order by jl.line_no;
      perform clara._assert_balanced(v_mirror);
      select je.revision_token into v_rev from clara.journal_entries je where je.id = v_mirror;

      -- THE MIRROR FLIPS THROUGH THE CORE, PREHELD, ON THE POSTER-RESERVED KEY [L3/1]. Never
      -- a direct UPDATE to 'approved': routing through clara._approve_entry_core is what keeps
      -- the approve-path census at FOUR, restores CLR05 on the mirror, and makes the mirror's
      -- own subledger hook run exactly as a human approval's would. ANY refusal in here aborts
      -- the WHOLE approving statement, so no committed half-pair can exist -- that is the
      -- intended semantics, by construction rather than by cleanup.
      perform clara._approve_entry_core(
        jsonb_build_object('actor', v_actor, 'firm', e.firm_id, 'receipt_preheld', true),
        v_mirror, v_rev, v_attest, (v_prop ->> 'op_key') || ':mirror:approve');
    end if;

    -- ---------------------------------------------------------------------------------
    -- THE RECEIPT, MINTED AFTER THE MIRROR (design SS2.5) so reversal_entry_id is a birth
    -- fact and never an UPDATE on an immutable row [L2/18]. mode is READ FROM THE FLAGS
    -- STAMP, not re-decided: the receipt records what the poster ruled.
    -- ---------------------------------------------------------------------------------
    select coalesce(sum(jl.debit_cents), 0) into v_amount
      from clara.journal_lines jl where jl.entry_id = p_entry;
    insert into clara.adjustment_runs(firm_id, client_id, template_id, period_start,
        period_end, mode, entry_id, reversal_entry_id, amount_cents, op_key)
      values (e.firm_id, e.client_id, t.id, v_ps, v_pe, v_mode, p_entry, v_mirror, v_amount,
        v_prop ->> 'op_key')
      returning id into v_run;

    -- THE EVENT, LAST OF THE THREE (ABI SSG payload -- identifiers and figures the receipt
    -- already holds, nothing else). EVENT ORDER IS LAW AND IT IS STRUCTURAL: the mirror's
    -- events were emitted inside the core call above, this one is emitted here, and the
    -- OCCURRENCE's own entry.approved is emitted by the outer clara._approve_entry_core only
    -- after this hook returns. So the mirror's events precede the occurrence's, always, with
    -- no ordering code anywhere.
    perform clara._append_event(e.firm_id, 'adjustment.posted', e.client_id, v_actor,
      null, null, p_entry, null, null,
      jsonb_build_object('template_id', t.id, 'run_id', v_run,
        'period_start', v_ps, 'period_end', v_pe, 'amount_cents', v_amount,
        'reversal_entry_id', v_mirror));
  end if;

  -- -----------------------------------------------------------------------------------
  -- (3) THE BANK-RULE SUGGESTION (design SS5). Hosted HERE rather than as a fifth splice:
  -- the approve-time re-validation of a suggestion draft is the same kind of act as arm (2)
  -- and adding a splice would move the hook-caller census for no gain [L4/9].
  --
  -- SIX axes, one token (suggestion_stale) with a named axis -- the design's five plus the
  -- ROLE-ELIGIBILITY axis the as-built ladder ruled in (round 2). The draft's own legs are
  -- re-derived from the LIVE line and the LIVE rule through clara._wdb_suggestion_lines --
  -- the same body clara.accept_bank_rule_suggestion mints from -- so "the rule still says
  -- this" is one definition in one place, and the accept verb and this arm can never disagree.
  -- -----------------------------------------------------------------------------------
  if e.flags ? 'bank_rule_suggested' then
    v_sug := e.flags -> 'bank_rule_suggested';
    select * into rl from clara.bank_rules br where br.id = (v_sug ->> 'rule_id')::uuid;
    if not found or rl.client_id <> e.client_id or rl.status <> 'signed'
       or rl.kind <> 'coding' then
      raise exception 'the bank rule this suggestion names is no longer a signed coding rule for this client; withdraw the draft'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'suggestion_stale', 'axis', 'rule',
            'rule_id', v_sug ->> 'rule_id')::text;
    end if;
    select l.* into ln from clara.bank_statement_lines l where l.id = (v_sug ->> 'line_id')::uuid;
    if not found or ln.client_id <> e.client_id then
      raise exception 'the statement line this suggestion names is not this client''s'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'suggestion_stale', 'axis', 'line',
            'line_id', v_sug ->> 'line_id')::text;
    end if;
    if not exists (select 1 from clara.bank_statements bs
                   where bs.id = ln.statement_id and bs.status = 'live') then
      raise exception 'the statement carrying this line is no longer live; withdraw the draft'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'suggestion_stale', 'axis', 'statement',
            'statement_id', ln.statement_id)::text;
    end if;
    -- UNMATCHED AND UN-EXCEPTED, at exactly the 0040 list_bank_line_suggestions predicate:
    -- ANY exception on the line disqualifies it (not merely an open one), because an excepted
    -- line's booking is the exception machinery's business, not a coding rule's.
    if exists (select 1 from clara.bank_match_line_members m
               where m.line_id = ln.id and m.group_status in ('pending', 'live'))
       or exists (select 1 from clara.bank_line_exceptions ex where ex.line_id = ln.id) then
      raise exception 'this statement line is now matched or excepted; withdraw the draft'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'suggestion_stale', 'axis', 'line_claimed',
            'line_id', ln.id)::text;
    end if;
    if not clara._wdb_suggestion_rule_hit(ln.id, rl.id) then
      raise exception 'this rule no longer matches this statement line; withdraw the draft'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'suggestion_stale', 'axis', 'predicate',
            'rule_id', rl.id, 'line_id', ln.id)::text;
    end if;
    v_derived := clara._wdb_suggestion_lines(e.client_id, ln.id, rl.id);
    select coalesce(jsonb_agg(jsonb_build_object(
             'account_code', jl.account_code,
             'debit_cents', jl.debit_cents,
             'credit_cents', jl.credit_cents) order by jl.line_no), '[]'::jsonb)
      into v_actual from clara.journal_lines jl where jl.entry_id = p_entry;
    if v_derived is distinct from v_actual then
      raise exception 'this draft''s legs no longer equal what the rule derives for this line; withdraw the draft'
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'suggestion_stale', 'axis', 'legs',
            'rule_id', rl.id, 'line_id', ln.id)::text;
    end if;
    -- THE SIXTH AXIS -- THE PROPOSED ACCOUNT IS STILL ELIGIBLE (as-built ladder round 2, the
    -- PHANTOM STAFF ADVANCE). clara.accept_bank_rule_suggestion asks this at its door, and this
    -- arm re-asks it here for the same reason it re-asks the other five: an account can be
    -- ENROLLED between the accept and the approval. A DEBIT leg on a code enrolled as a staff
    -- advance is SOFT-BIRTHED by SECTION S3's clara._adv_on_approve arm (3) -- so the register
    -- would say a named person owes the firm money they never received, while the GL, the
    -- entry and clara.staff_advance_tie all agree to the sen and no instrument fires. (An FA
    -- cost/accum/expense role is the same defect from the other family.)
    --
    -- THE SAME BODY THE DOOR READS, over the SAME account clara._wdb_suggestion_lines derives
    -- from -- the rule's own `proposal ->> 'account_code'` -- so the two sites cannot drift.
    -- The CONTRA leg ALONE is asked: the other derived leg IS this client's bank account, and
    -- clara._adj_line_eligibility_breach would refuse it on its own `bank_account` axis. The
    -- axis is LAST, deliberately: the five axes above keep their pinned precedence, and the
    -- `legs` axis immediately above has already proved this draft equals what the rule derives,
    -- so the account asked about here is provably one of the draft's own two.
    --
    -- THE BREACH'S OWN `axis` IS RE-KEYED, never merged over this arm's (the arm-(2g) idiom):
    -- `axis` answers "which of the six", `eligibility_axis` "which of the five conditions".
    v_breach := clara._adj_line_eligibility_breach(e.client_id,
      jsonb_build_array(jsonb_build_object('account_code',
        nullif(btrim(coalesce(rl.proposal ->> 'account_code', '')), ''))));
    if v_breach is not null then
      raise exception 'the account bank rule % proposes is no longer eligible to carry a coding suggestion (%); withdraw the draft', rl.id, v_breach ->> 'axis'
        using errcode = 'CLR39',
          detail = (jsonb_build_object('reason', 'suggestion_stale', 'axis', 'line_eligibility',
            'rule_id', rl.id, 'line_id', ln.id, 'eligibility_axis', v_breach ->> 'axis')
            || (v_breach - 'axis'))::text;
    end if;
  end if;
end $$;
revoke all on function clara._adj_on_approve(uuid) from public;

-- =====================================================================================
-- S2.6 -- THE PAIR MACHINE (design SS2.4). Correcting an auto-reversed accrual means
-- correcting BOTH halves or neither: a lone reversal of the occurrence would leave the
-- mirror standing as a naked credit, and a lone reversal of the mirror would re-open an
-- accrual the books have already released.
--
-- clara.reverse_entry IS NEVER THE PAIR PATH [L2/3]. Its 7th splice (clara._wdb_reversal_
-- blocked, S2.7 below) refuses either half by name, and its high-stakes branch would strand
-- two unrelated drafts with no way to approve them together. So the pair has its own private
-- core, which births both mirrors itself and holds them under ONE receipt.
--
-- A SOLO (non-auto-reverse) OCCURRENCE HAS NO PAIR [L3/11]. Plain clara.reverse_entry is its
-- path, clara._wdb_reversal_blocked does not fire on it, and clara.reverse_adjustment_pair
-- refuses it by name.
-- =====================================================================================

create function clara._pair_reverse_core(p_client uuid, p_occurrence uuid, p_reason text,
    p_op_key text, p_actor uuid, p_firm uuid)
  returns jsonb
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare
  o record; m record; v_mirror_id uuid; v_occ_key text; v_mir_key text; v_template uuid;
  v_today date; v_occ_corr uuid; v_mir_corr uuid; v_pair uuid; v_rev uuid;
  v_high boolean; v_status text; v_padm jsonb;
begin
  -- THE TWO HALF KEYS ARE RESERVED BEFORE ANY LOCK (ABI SSE: reserver =
  -- clara._pair_reverse_core, pre-lock). Their hashes are pre-lock-knowable by construction
  -- [L7/1]: ('occurrence', p_occurrence, 'half', 'occ' | 'mir') needs no minted uuid.
  v_occ_key := p_op_key || ':occ:approve';
  v_mir_key := p_op_key || ':mir:approve';
  if clara._reserve_op(p_firm, 'approve_entry', v_occ_key,
       clara._hash(jsonb_build_object('occurrence', p_occurrence, 'half', 'occ'))) is not null then
    raise exception 'the derived occurrence-half approve op key is already in use'
      using errcode = 'CLR10', detail = '{"reason":"approve_key_collision"}';
  end if;
  if clara._reserve_op(p_firm, 'approve_entry', v_mir_key,
       clara._hash(jsonb_build_object('occurrence', p_occurrence, 'half', 'mir'))) is not null then
    raise exception 'the derived mirror-half approve op key is already in use'
      using errcode = 'CLR10', detail = '{"reason":"approve_key_collision"}';
  end if;

  -- UNLOCKED IDENTITY READ, so we know WHICH two rows to lock. Everything it decides is
  -- re-decided under the locks below.
  select * into o from clara.journal_entries where id = p_occurrence;
  if not found or o.client_id <> p_client or o.firm_id <> p_firm then
    raise exception 'entry not in your firm' using errcode = 'CLR11';
  end if;
  if o.auto_reversal_of is not null then
    raise exception 'entry % is the auto-reversal mirror, not the occurrence; name the occurrence (%) instead', p_occurrence, o.auto_reversal_of
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'not_an_auto_pair', 'entry_id', p_occurrence,
          'occurrence_id', o.auto_reversal_of)::text;
  end if;
  select j.id into v_mirror_id from clara.journal_entries j
    where j.auto_reversal_of = p_occurrence;
  if v_mirror_id is null then
    raise exception 'entry % has no auto-reversal mirror, so it is not an auto pair; a solo occurrence is corrected with clara.reverse_entry', p_occurrence
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'not_an_auto_pair',
          'entry_id', p_occurrence)::text;
  end if;

  -- BOTH JOURNAL ROWS FIRST, IN ID ORDER (the 0037 invariant (1) row-lock-before-rung law,
  -- and the clara.resolve_bank_line_exception in-id-order idiom so two concurrent callers
  -- naming the same pair cannot deadlock). THEN the client rung.
  perform 1 from clara.journal_entries j
    where j.id in (p_occurrence, v_mirror_id) order by j.id for update;
  perform pg_advisory_xact_lock(203005004, hashtext(p_client::text));

  -- RE-READ UNDER THE LOCKS. Every refusal below reads locked truth.
  select * into o from clara.journal_entries where id = p_occurrence;
  select * into m from clara.journal_entries where id = v_mirror_id;
  if m.auto_reversal_of is distinct from p_occurrence then
    raise exception 'the pair linkage changed mid-flight; retry' using errcode = 'CLR16';
  end if;

  -- THE DOUBLE-REVERSE WALLS, INLINE [L3/6]. clara.reverse_entry states these for its own
  -- door; the pair core is a second door onto the same act and states them itself rather than
  -- borrowing a body whose splice would refuse this very remedy.
  if o.status <> 'approved' or m.status <> 'approved' then
    raise exception 'both halves of an adjustment pair must be approved before the pair can be corrected'
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'pair_half_not_approved',
          'occurrence_status', o.status, 'mirror_status', m.status)::text;
  end if;
  if o.reversal_of is not null or m.reversal_of is not null then
    raise exception 'an adjustment pair half is itself a reversal; this is not a correctable pair'
      using errcode = 'CLR10', detail = '{"reason":"not_an_auto_pair"}';
  end if;
  if o.reversed_by is not null or m.reversed_by is not null then
    raise exception 'one half of this adjustment pair is already reversed'
      using errcode = 'CLR10', detail = '{"reason":"pair_half_already_reversed"}';
  end if;
  -- THE K BOUNDARY IS CLOSED BY VACUITY, AND DELIBERATELY CARRIES NO GUARD HERE.
  --
  -- Pair members are origin='scheduled_run' occurrences and their mirrors, which the poster
  -- births with is_opening_balance FALSE ALWAYS (design SS2.3's headers-FALSE law), so a
  -- K-family opening entry can never become a pair half. The design records this as "the
  -- K-boundary by vacuity (tail probe)" and the round-2 ladder itemized the guard set
  -- explicitly [L2/6, V4 MAJOR / C3-SOUND]: "the K-family boundary by VACUITY (pair members
  -- are origin='scheduled_run', never opening-balance -- PINNED AS A TAIL PROBE, no 0017
  -- extraction)".
  --
  -- ASSEMBLY RECONCILIATION S2-A1: an earlier cut of this body carried an inline
  -- is_opening_balance refusal here (the CLR31 K-family reason token), reasoning that a
  -- checked fact beats a belief. It was REMOVED at assembly, because the ladder had already
  -- adjudicated the instrument and tail 12 enforces the removal by scanning this body for
  -- that token. The reasoning is not lost, it is relocated: TAIL 12 asserts both that each
  -- poster stamps all three entry headers EXPLICITLY (so no occurrence can default into
  -- is_opening_balance) and that ZERO flagged occurrence/mirror rows are opening balances.
  -- A guard here would make the vacuity argument decorative rather than load-bearing -- and
  -- would hide, behind a refusal nobody could ever trigger, the day the poster's header law
  -- actually broke. (Deliberately phrased WITHOUT the literal token: tail 12 reads raw
  -- prosrc, in which a comment naming the token is indistinguishable from a live guard.)
  if exists (select 1 from clara.adjustment_pair_reversals r
             where r.occurrence_id = p_occurrence and r.status in ('pending', 'approving')) then
    raise exception 'this adjustment pair already has an active correction; approve or cancel it first'
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'pair_already_active',
          'occurrence_id', p_occurrence)::text;
  end if;

  -- THE THREE HELPER WALLS, DEFENSE IN DEPTH, ON BOTH HALVES [L3/6] -- ASKED THROUGH THE ONE
  -- BODY THAT STATES THEM, NOT INLINED [round 10, WDB-R2; Codex r10 finding 1]. Template line
  -- eligibility makes all three unreachable on a valid pair (non-control lines write no open
  -- items, an adjustment is never a bank member, and a template line is never an FA account),
  -- and they are called anyway: an unreachable guard that is present costs one index probe
  -- and turns a future eligibility bug into a refusal instead of a corrupted subledger.
  --
  -- WHY THEY MOVED. Until round 10 these three lived HERE as literals and
  -- clara._adj_correction_door -- which tells a professional that THIS VERB corrects their run
  -- -- knew nothing about them, so the door could advertise an act three walls refuse. That is
  -- WDB-R2's exact subject: two bodies promising one outcome with two enumerations of it. The
  -- wall set now lives once, in clara._wdb_correction_admission (S2.1a-2b); this site raises
  -- its `at_verb` half VERBATIM (same order, same errcodes, same sentences, same detail
  -- literals -- the envelope carries `detail` as TEXT precisely so what is raised here is
  -- byte-identical to what the inline form raised), and the door READS the same envelope. They
  -- cannot disagree because there is one derivation.
  --
  -- THE `at_approve` HALF IS DELIBERATELY NOT RAISED HERE. It is the advance-side admission of
  -- both halves, and S3.0's ruling is that raising it at the FIRST moment walls in the caller
  -- whose checker was going to re-enrol the account before approving. It stays enforced where
  -- it always was -- clara._adv_on_approve GUARD III, under that act's own row locks, reached
  -- from the approves below (low-stakes) or from clara.approve_pair_reversal (high-stakes) --
  -- and it is REPORTED by the door so nothing advertises an act it will refuse.
  v_padm := clara._wdb_correction_admission('clara.reverse_adjustment_pair', p_occurrence,
                                            m.id);
  if not (v_padm -> 'at_verb' ->> 'admitted')::boolean then
    raise exception '%', v_padm -> 'at_verb' ->> 'message'
      using errcode = v_padm -> 'at_verb' ->> 'errcode',
            detail = v_padm -> 'at_verb' ->> 'detail';
  end if;

  v_template := (o.flags -> 'recurring_adjustment' ->> 'template_id')::uuid;
  if v_template is null then
    raise exception 'entry % carries no recurring-adjustment template, so it is not an auto pair', p_occurrence
      using errcode = 'CLR10', detail = '{"reason":"not_an_auto_pair"}';
  end if;

  -- ---------------------------------------------------------------------------------
  -- BOTH CORRECTIONS, BORN HERE (clara.reverse_entry's 13-column recipe, verbatim in shape).
  -- origin='reversal' (NOT 'scheduled_run' -- these are human corrective acts and the
  -- scheduled_run writer census asserts exactly that); maker_actor = last_human_editor = the
  -- CALLER, so exactly ONE distinct checker can approve both.
  --
  -- EACH CORRECTION IS DATED FROM THE HALF IT REVERSES [as-built ladder round 5 -- THE
  -- CORRECT-AND-RE-RUN DOUBLE], through the one body that owns that question,
  -- clara._wdb_correction_posting_date. The MYT date from the DB clock (never current_date)
  -- stays here as the DEFAULT it is handed -- so the recipe still carries exactly one clock
  -- for anything outside this lane, and the two dates below are period-derived rather than
  -- clock-derived for everything inside it.
  --
  -- THE PAIR IS THE CASE THAT PROVES ONE DATE COULD NEVER HAVE BEEN RIGHT: its two entries sit
  -- on TWO dates by construction (the occurrence on period_end, the mirror on period_end + 1),
  -- so a single MYT-today date for both corrections leaves the accrual month AND the release
  -- month standing. The occurrence's correction therefore lands on the occurrence's date, the
  -- mirror's on the mirror's -- which is the same law the mirror itself was born under, and
  -- the same law clara._fa_own_ledger_periods has enforced in the FA register since 0041.
  -- ---------------------------------------------------------------------------------
  v_today := clara._fa_today();
  insert into clara.journal_entries(client_id, status, posting_date, memo, origin,
      resolution_id, is_opening_balance, is_year_end, tax_affecting,
      maker_actor, last_human_editor, reversal_of, reversal_reason)
    values (p_client, 'draft', clara._wdb_correction_posting_date(p_occurrence, v_today),
      'Reversal: ' || p_reason, 'reversal', o.resolution_id,
      o.is_opening_balance, o.is_year_end, o.tax_affecting, p_actor, p_actor,
      p_occurrence, p_reason)
    returning id into v_occ_corr;
  insert into clara.journal_lines(entry_id, line_no, account_code, debit_cents,
      credit_cents, description, counterparty_id)
    select v_occ_corr, jl.line_no, jl.account_code, jl.credit_cents, jl.debit_cents,
           jl.description, jl.counterparty_id
    from clara.journal_lines jl where jl.entry_id = p_occurrence order by jl.line_no;
  perform clara._assert_balanced(v_occ_corr);

  insert into clara.journal_entries(client_id, status, posting_date, memo, origin,
      resolution_id, is_opening_balance, is_year_end, tax_affecting,
      maker_actor, last_human_editor, reversal_of, reversal_reason)
    values (p_client, 'draft', clara._wdb_correction_posting_date(m.id, v_today),
      'Reversal: ' || p_reason, 'reversal', m.resolution_id,
      m.is_opening_balance, m.is_year_end, m.tax_affecting, p_actor, p_actor,
      m.id, p_reason)
    returning id into v_mir_corr;
  insert into clara.journal_lines(entry_id, line_no, account_code, debit_cents,
      credit_cents, description, counterparty_id)
    select v_mir_corr, jl.line_no, jl.account_code, jl.credit_cents, jl.debit_cents,
           jl.description, jl.counterparty_id
    from clara.journal_lines jl where jl.entry_id = m.id order by jl.line_no;
  perform clara._assert_balanced(v_mir_corr);

  -- THE RECEIPT IS INSERTED `pending` WITH BOTH CORRECTION IDS, AFTER THE DRAFTS EXIST
  -- [L6/9] -- the ids are NOT NULL columns, so the drafts must precede it -- and only then is
  -- it transitioned. template_id and completed_at are the unified ramp clock's filter and
  -- timestamp [L6/1]: created_at is the PENDING moment and is never the clock.
  insert into clara.adjustment_pair_reversals(firm_id, client_id, template_id, occurrence_id,
      mirror_id, occurrence_correction_id, mirror_correction_id, maker, status, op_key)
    values (p_firm, p_client, v_template, p_occurrence, m.id, v_occ_corr, v_mir_corr,
      p_actor, 'pending', p_op_key)
    returning id into v_pair;

  -- Both corrections carry identical headers and equal magnitudes, so is_high_stakes is
  -- provably equal on them; the OR is written anyway so a future asymmetry parks rather than
  -- posts.
  v_high := clara.is_high_stakes(v_occ_corr) or clara.is_high_stakes(v_mir_corr);

  if v_high then
    -- THE PARK (WCA-R7): both corrections stay DRAFTS on the `pending` receipt and one
    -- distinct checker approves them atomically through clara.approve_pair_reversal.
    v_status := 'pending';
  else
    -- ONE TRANSACTION, ONE ACT [WDB-G2]. The receipt is flipped to `approving` BEFORE the
    -- core calls, because that state IS the authorization the hook's arm (1) reads.
    update clara.adjustment_pair_reversals set status = 'approving' where id = v_pair;
    select je.revision_token into v_rev from clara.journal_entries je where je.id = v_occ_corr;
    perform clara._approve_entry_core(
      jsonb_build_object('actor', p_actor, 'firm', p_firm, 'receipt_preheld', true),
      v_occ_corr, v_rev, null, v_occ_key);
    select je.revision_token into v_rev from clara.journal_entries je where je.id = v_mir_corr;
    perform clara._approve_entry_core(
      jsonb_build_object('actor', p_actor, 'firm', p_firm, 'receipt_preheld', true),
      v_mir_corr, v_rev, null, v_mir_key);
    -- reversed_by IS STAMPED BY THE CORE (clara._approve_entry_core's reversal-linkage
    -- UPDATE), so this is an ASSERTION rather than a second write: two writers on one linkage
    -- column is how a half-linked pair gets built.
    if not exists (select 1 from clara.journal_entries j
                   where j.id = p_occurrence and j.reversed_by = v_occ_corr)
       or not exists (select 1 from clara.journal_entries j
                      where j.id = m.id and j.reversed_by = v_mir_corr) then
      raise exception 'the adjustment pair reversal did not link both halves; refusing to complete'
        using errcode = 'CLR10', detail = '{"reason":"pair_linkage_incomplete"}';
    end if;
    -- COMPLETED STAMPS THE CLOCK. Every occurrence of this template approved before this
    -- moment stops counting toward the ramp, so the corrected period's re-run DRAFTS.
    update clara.adjustment_pair_reversals set status = 'completed', completed_at = now()
      where id = v_pair;
    v_status := 'completed';
  end if;

  return jsonb_build_object('pair_id', v_pair, 'status', v_status,
    'occurrence_correction_id', v_occ_corr, 'mirror_correction_id', v_mir_corr);
end $$;
revoke all on function clara._pair_reverse_core(uuid, uuid, text, text, uuid, uuid) from public;

-- THE PAIR CORRECTION VERB (bookkeeper+, the clara.reverse_entry floor). Thin by design: the
-- floor, the op key and the tenancy check, then the core -- which must reserve its two derived
-- keys BEFORE any lock, so nothing here may take one.
create function clara.reverse_adjustment_pair(p_client uuid, p_occurrence uuid,
    p_reason text, p_op_key text)
  returns jsonb
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare c record; v_dedupe jsonb; v_firm uuid; v_res jsonb;
begin
  c := clara._human_ctx(clara.role_rank('bookkeeper'));
  if p_op_key is null or btrim(p_op_key) = '' then
    raise exception 'op_key is required' using errcode = 'CLR10';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'a reversal reason is required' using errcode = 'CLR10';
  end if;
  v_dedupe := clara._reserve_op(c.firm, 'reverse_adjustment_pair', p_op_key,
    clara._hash(jsonb_build_object('occurrence', p_occurrence)));
  if v_dedupe is not null then return v_dedupe; end if;
  select cl.firm_id into v_firm from clara.clients cl where cl.id = p_client;
  if v_firm is null or v_firm <> c.firm then
    raise exception 'client is not in your firm' using errcode = 'CLR11';
  end if;
  v_res := clara._pair_reverse_core(p_client, p_occurrence, p_reason, p_op_key,
    c.actor, c.firm);
  perform clara._audit(c.firm, c.actor, null, null, 'reverse_adjustment_pair',
    p_occurrence,
    jsonb_build_object('client', p_client, 'occurrence', p_occurrence,
      'reason', p_reason, 'op_key', p_op_key) || v_res);
  return clara._finish_op(c.firm, 'reverse_adjustment_pair', p_op_key, v_res);
end $$;
revoke all on function clara.reverse_adjustment_pair(uuid, uuid, text, text) from public;

-- THE HIGH-STAKES CHECKER'S VERB (design SS2.4). ONE distinct checker approves BOTH halves
-- atomically: the maker of the pair stamped last_human_editor on both corrections, so
-- clara._approve_entry_core's CLR05 arm binds on each of them exactly as it would on any
-- other high-stakes draft, and the solo-firm attestation branch is reached through
-- p_attestation.
--
-- RE-DERIVE, NEVER TRUST [L4/2]. Both corrections are re-derived BYTE-EXACTLY against the
-- halves they reverse, under the locks, before the receipt is flipped: the checker approves
-- the act the maker made, not a row that happens to be sitting there.
create function clara.approve_pair_reversal(p_client uuid, p_pair uuid, p_op_key text,
    p_attestation text default null)
  returns jsonb
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare
  c record; v_dedupe jsonb; v_firm uuid; pr record; v_rev uuid;
  v_want jsonb; v_have jsonb; v_corr uuid[]; v_orig uuid[]; i int;
begin
  c := clara._human_ctx(clara.role_rank('bookkeeper'));
  if p_op_key is null or btrim(p_op_key) = '' then
    raise exception 'op_key is required' using errcode = 'CLR10';
  end if;
  v_dedupe := clara._reserve_op(c.firm, 'approve_pair_reversal', p_op_key,
    clara._hash(jsonb_build_object('pair', p_pair)));
  if v_dedupe is not null then return v_dedupe; end if;
  select cl.firm_id into v_firm from clara.clients cl where cl.id = p_client;
  if v_firm is null or v_firm <> c.firm then
    raise exception 'client is not in your firm' using errcode = 'CLR11';
  end if;

  -- LOCK ORDER: the receipt, then all FOUR journal rows in id order (both corrections and
  -- both halves -- the halves are read by the re-derivation and written by the core's
  -- linkage UPDATE), then the client rung.
  select * into pr from clara.adjustment_pair_reversals r
    where r.id = p_pair and r.client_id = p_client for update;
  if not found then
    raise exception 'adjustment pair reversal is not in this client' using errcode = 'CLR11';
  end if;
  if pr.status <> 'pending' then
    raise exception 'only a pending adjustment pair reversal can be approved (this one is %)', pr.status
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'pair_not_pending', 'pair_id', p_pair,
          'status', pr.status)::text;
  end if;
  perform 1 from clara.journal_entries j
    where j.id in (pr.occurrence_correction_id, pr.mirror_correction_id,
                   pr.occurrence_id, pr.mirror_id)
    order by j.id for update;
  perform pg_advisory_xact_lock(203005004, hashtext(p_client::text));

  -- THE BYTE-EXACT RE-DERIVATION, per half. Two parallel arrays rather than a UNION of
  -- record fields: the pairing is positional, obvious, and needs no type inference over
  -- plpgsql parameters.
  v_corr := array[pr.occurrence_correction_id, pr.mirror_correction_id];
  v_orig := array[pr.occurrence_id, pr.mirror_id];
  for i in 1 .. 2 loop
    -- What the correction MUST be: the half's own lines, leg-swapped, line_no for line_no,
    -- description and counterparty carried.
    select coalesce(jsonb_agg(jsonb_build_object(
             'line_no', jl.line_no, 'account_code', jl.account_code,
             'debit_cents', jl.credit_cents, 'credit_cents', jl.debit_cents,
             'description', jl.description,
             'counterparty_id', jl.counterparty_id) order by jl.line_no), '[]'::jsonb)
      into v_want from clara.journal_lines jl where jl.entry_id = v_orig[i];
    select coalesce(jsonb_agg(jsonb_build_object(
             'line_no', jl.line_no, 'account_code', jl.account_code,
             'debit_cents', jl.debit_cents, 'credit_cents', jl.credit_cents,
             'description', jl.description,
             'counterparty_id', jl.counterparty_id) order by jl.line_no), '[]'::jsonb)
      into v_have from clara.journal_lines jl where jl.entry_id = v_corr[i];
    if v_want is distinct from v_have then
      raise exception 'correction % is no longer the exact leg-swap of the half it reverses; cancel this pair reversal and issue a fresh one', v_corr[i]
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'pair_correction_stale', 'pair_id', p_pair,
            'entry_id', v_corr[i], 'original_id', v_orig[i])::text;
    end if;
    -- ...AND ITS DATE IS STILL THE HALF'S OWN [as-built ladder round 5]. The high-stakes park
    -- is the one place a pair correction crosses a maker-checker gap as a DRAFT, and its
    -- posting_date is now load-bearing: dated anywhere but on the half it reverses, the pair
    -- clears no period and the next re-run doubles one. clara.revise_entry already refuses to
    -- edit a pair draft (SECTION S5.10) so this is defense in depth over a closed door -- the
    -- same posture as the byte-exact leg re-derivation immediately above, which clara.revise_
    -- entry also already makes unreachable, and which round 4 kept for exactly this reason.
    if not exists (select 1 from clara.journal_entries j
                   join clara.journal_entries og on og.id = v_orig[i]
                   where j.id = v_corr[i] and j.status = 'draft' and j.origin = 'reversal'
                     and j.reversal_of = v_orig[i]
                     and j.posting_date = og.posting_date) then
      raise exception 'correction % is no longer a draft reversal of %; cancel this pair reversal and issue a fresh one', v_corr[i], v_orig[i]
        using errcode = 'CLR39',
          detail = jsonb_build_object('reason', 'pair_correction_stale', 'pair_id', p_pair,
            'entry_id', v_corr[i], 'original_id', v_orig[i])::text;
    end if;
  end loop;

  -- THE FLIP PRECEDES THE CORE CALLS -- it is the authorization arm (1) reads.
  update clara.adjustment_pair_reversals set status = 'approving' where id = p_pair;
  select je.revision_token into v_rev from clara.journal_entries je
    where je.id = pr.occurrence_correction_id;
  perform clara._approve_entry_core(
    jsonb_build_object('actor', c.actor, 'firm', c.firm, 'receipt_preheld', true),
    pr.occurrence_correction_id, v_rev, p_attestation, pr.op_key || ':occ:approve');
  select je.revision_token into v_rev from clara.journal_entries je
    where je.id = pr.mirror_correction_id;
  perform clara._approve_entry_core(
    jsonb_build_object('actor', c.actor, 'firm', c.firm, 'receipt_preheld', true),
    pr.mirror_correction_id, v_rev, p_attestation, pr.op_key || ':mir:approve');
  if not exists (select 1 from clara.journal_entries j
                 where j.id = pr.occurrence_id and j.reversed_by = pr.occurrence_correction_id)
     or not exists (select 1 from clara.journal_entries j
                    where j.id = pr.mirror_id and j.reversed_by = pr.mirror_correction_id) then
    raise exception 'the adjustment pair reversal did not link both halves; refusing to complete'
      using errcode = 'CLR10', detail = '{"reason":"pair_linkage_incomplete"}';
  end if;
  update clara.adjustment_pair_reversals set status = 'completed', completed_at = now()
    where id = p_pair;

  perform clara._audit(c.firm, c.actor, null, null, 'approve_pair_reversal', pr.occurrence_id,
    jsonb_build_object('client', p_client, 'pair', p_pair,
      'occurrence_correction_id', pr.occurrence_correction_id,
      'mirror_correction_id', pr.mirror_correction_id, 'op_key', p_op_key));
  return clara._finish_op(c.firm, 'approve_pair_reversal', p_op_key,
    jsonb_build_object('pair_id', p_pair, 'status', 'completed'));
end $$;
revoke all on function clara.approve_pair_reversal(uuid, uuid, text, text) from public;

-- THE MAKER'S ESCAPE (design SS2.4). A parked pair must be abandonable in ONE act, and it
-- must never reset the ramp clock -- a cancelled receipt is a correction that never happened.
--
-- IT WITHDRAWS INLINE, AS THE FN OWNER (the 0038:5207 idiom), and NEVER calls
-- clara.withdraw_draft: SECTION S5 recuts that verb to REFUSE a pair draft (naming this verb
-- as the remedy), so calling it here would be a self-refusing remedy [L4/5]. The column set
-- written is exactly clara.withdraw_draft's, and the entry.withdrawn event fires exactly as
-- the verb would fire it.
create function clara.cancel_pair_reversal(p_client uuid, p_pair uuid, p_reason text,
    p_op_key text)
  returns jsonb
  language plpgsql security definer set search_path = clara, pg_temp as $$
declare c record; v_dedupe jsonb; v_firm uuid; pr record; v_n int;
begin
  c := clara._human_ctx(clara.role_rank('bookkeeper'));
  if p_op_key is null or btrim(p_op_key) = '' then
    raise exception 'op_key is required' using errcode = 'CLR10';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'a cancellation reason is required' using errcode = 'CLR10';
  end if;
  v_dedupe := clara._reserve_op(c.firm, 'cancel_pair_reversal', p_op_key,
    clara._hash(jsonb_build_object('pair', p_pair, 'reason', p_reason)));
  if v_dedupe is not null then return v_dedupe; end if;
  select cl.firm_id into v_firm from clara.clients cl where cl.id = p_client;
  if v_firm is null or v_firm <> c.firm then
    raise exception 'client is not in your firm' using errcode = 'CLR11';
  end if;

  select * into pr from clara.adjustment_pair_reversals r
    where r.id = p_pair and r.client_id = p_client for update;
  if not found then
    raise exception 'adjustment pair reversal is not in this client' using errcode = 'CLR11';
  end if;
  if pr.status <> 'pending' then
    raise exception 'only a pending adjustment pair reversal can be cancelled (this one is %)', pr.status
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'pair_not_pending', 'pair_id', p_pair,
          'status', pr.status)::text;
  end if;
  perform 1 from clara.journal_entries j
    where j.id in (pr.occurrence_correction_id, pr.mirror_correction_id)
    order by j.id for update;
  perform pg_advisory_xact_lock(203005004, hashtext(p_client::text));

  select count(*)::int into v_n from clara.journal_entries j
    where j.id in (pr.occurrence_correction_id, pr.mirror_correction_id)
      and j.status = 'draft';
  if v_n <> 2 then
    raise exception 'both halves of this pair reversal must still be drafts to cancel it (% of 2 are)', v_n
      using errcode = 'CLR10',
        detail = jsonb_build_object('reason', 'pair_half_not_draft', 'pair_id', p_pair,
          'draft_count', v_n)::text;
  end if;

  update clara.journal_entries
     set status = 'withdrawn', withdrawn_by = c.actor, withdrawn_at = now(),
         withdrawal_reason = 'adjustment pair reversal cancelled: ' || p_reason,
         proposed_counterparty = null, match_fingerprint = null, updated_at = now()
   where id in (pr.occurrence_correction_id, pr.mirror_correction_id) and status = 'draft';
  perform clara._append_event(c.firm, 'entry.withdrawn', p_client, c.actor, null, null,
    pr.occurrence_correction_id, null, null, '{}'::jsonb);
  perform clara._append_event(c.firm, 'entry.withdrawn', p_client, c.actor, null, null,
    pr.mirror_correction_id, null, null, '{}'::jsonb);

  -- THE TWO HALF KEYS ARE CLOSED, NOT ABANDONED (ABI SSE closer column). They were reserved
  -- before the first lock and on THIS branch nothing will ever spend them.
  perform clara._finish_op(c.firm, 'approve_entry', pr.op_key || ':occ:approve',
    jsonb_build_object('deferred', true, 'reason', 'pair_reversal_cancelled',
      'pair_id', p_pair));
  perform clara._finish_op(c.firm, 'approve_entry', pr.op_key || ':mir:approve',
    jsonb_build_object('deferred', true, 'reason', 'pair_reversal_cancelled',
      'pair_id', p_pair));

  -- A CANCELLED RECEIPT NEVER RESETS THE RAMP CLOCK: only `completed` carries completed_at,
  -- and the clock reads completed receipts only.
  update clara.adjustment_pair_reversals set status = 'cancelled' where id = p_pair;

  perform clara._audit(c.firm, c.actor, null, null, 'cancel_pair_reversal', pr.occurrence_id,
    jsonb_build_object('client', p_client, 'pair', p_pair, 'reason', p_reason,
      'occurrence_correction_id', pr.occurrence_correction_id,
      'mirror_correction_id', pr.mirror_correction_id, 'op_key', p_op_key));
  return clara._finish_op(c.firm, 'cancel_pair_reversal', p_op_key,
    jsonb_build_object('pair_id', p_pair, 'status', 'cancelled'));
end $$;
revoke all on function clara.cancel_pair_reversal(uuid, uuid, text, text) from public;


-- [SPLIT D-b2 2026-08-04] S2.7 -- clara._wdb_reversal_blocked -- STANDS HERE IN THE WHOLE UNIT AND IS
-- NOT IN THIS SLICE. It reads ONLY clara.journal_entries.auto_reversal_of (plus D-b1's
-- clara._adv_reversal_blocked) and never an adjustment table, so census sect.4 Option A shipped
-- the column in D-b0 and the body in D-b1 -- one move that resolved six of the twenty-two
-- cross-slice order violations, including D-b0's clara.reverse_entry wall term (S5.9-b1) and
-- D-b3's clara._wdb_line_booking_block. THIS FILE READS IT: clara._adj_correction_door PERFORMs
-- it inside an exception block to learn WHICH door corrects an entry today (the round-8 WDB-R2
-- shape -- one wall, asked, rather than two bodies with opinions), and SECTION 0's probe 7 pins
-- it as a [SPLIT-CREATED] anchor.
-- ITS ARM (a) BECOMES REACHABLE FOR THE FIRST TIME WITH THIS SLICE, and that is worth saying
-- once: the pair-half refusal reads clara.journal_entries.auto_reversal_of, a column no body
-- wrote until the hook arm (2) below stamps it. Between D-b1 and this slice the arm was correct
-- and vacuous; from here it is correct and load-bearing.

-- =====================================================================================
-- S2.8 -- THE READ RPCs (design SS2.8: "the /rules AdjustmentTemplatePanel"). The D-a
-- list_fixed_assets / get_fixed_asset / list_depreciation_runs / get_depreciation_run
-- quartet is the precedent and is followed EXACTLY: viewer+ floor via clara._human_ctx,
-- firm scope asserted before a single row is read, ONE jsonb OBJECT returned (never a bare
-- array, so a later key can be added without breaking a caller), and not one figure
-- computed that a table does not already own.
--
-- WHY THEY EXIST AT ALL, WRITTEN DOWN. The ABI pins every WRITE verb of the template family
-- plus clara.adjustment_run_due, and pins NO list/get read -- so the panel that SS2.8
-- requires (propose / sign / retire / run-manual, per template) had no way to name the rows
-- it acts on. Sign and retire take a template id; the panel could not learn one. That is the
-- as-built ladder round-2 finding, and these three bodies are its fix. The names are the
-- D-a naming PAIRS transposed one family over, which is also what the dashboard lane had
-- already assumed in writing (`shared/adjustmentApi.ts`'s own header) rather than guessed.
--
-- ONE SPELLING FOR ONE THING. A template row names itself `template_id`, NOT `id`: the panel
-- joins these rows against clara.adjustment_run_due's `blocked[].template_id` and against the
-- `template_id` every write receipt returns, and two spellings for one identity is how a join
-- silently misses. A RUN row keeps `id` + `template_id`, exactly as clara.get_depreciation_run
-- reports its own receipt -- a run's identity and its parent's are different things.
-- =====================================================================================

-- THE ONE TEMPLATE PROJECTION every read returns, so /rules can never be shown two shapes of
-- the same row (the clara._fa_asset_json precedent). `occurrence_draft_entry_id` is the load-
-- bearing extra: clara.adjustment_run_due reports `occurrence_draft_outstanding` and names the
-- remedy ("approve or withdraw the draft"), and without the draft's own id on the row the
-- panel can state the remedy but not reach it -- a refusal whose named remedy is unreachable
-- is exactly the shape this build has already had to fix once.
create function clara._adj_template_json(p_template uuid) returns jsonb
  language plpgsql stable security definer set search_path = clara, pg_temp as $$
declare t clara.adjustment_templates%rowtype; v_draft uuid;
begin
  select * into t from clara.adjustment_templates where id = p_template;
  if not found then return null; end if;
  -- The oldest outstanding occurrence draft for this template, if any. Same predicate
  -- clara._adj_occurrence_outstanding uses (status='draft' + the ABI SSB stamp), so the row
  -- and the oracle can never disagree about whether a draft is in the way.
  select je.id into v_draft from clara.journal_entries je
   where je.client_id = t.client_id and je.status = 'draft'
     and je.flags ? 'recurring_adjustment'
     and (je.flags -> 'recurring_adjustment' ->> 'template_id') = t.id::text
   order by je.created_at, je.id limit 1;
  return jsonb_build_object(
    'template_id', t.id, 'client_id', t.client_id, 'status', t.status, 'name', t.name,
    'cadence', t.cadence, 'start_date', t.start_date, 'end_date', t.end_date,
    'auto_reverse', t.auto_reverse, 'lines', t.lines, 'memo_template', t.memo_template,
    'content_hash', t.content_hash, 'proposed_by', t.proposed_by, 'signed_by', t.signed_by,
    'signed_at', t.signed_at, 'retired_by', t.retired_by, 'retired_at', t.retired_at,
    'retired_reason', t.retired_reason, 'created_at', t.created_at,
    -- [R11 FIX 2026-08-04 -- W1 finding 3 / Codex r11 finding 2] THE RECORDED DECLARATION IS PROJECTED.
    -- The gate ASSERTS on this column and forbids an act on the strength of it; a professional who
    -- cannot see it on the row has no way to check the claim the refusal will one day make about
    -- their books, and no way to notice a mis-declaration until it refuses. jsonb null when
    -- nothing was declared -- ALWAYS present, this file's stable-shape rule.
    'replaces_template_id', t.replaces_template_id,
    'occurrence_draft_entry_id', v_draft);
end $$;
revoke all on function clara._adj_template_json(uuid) from public;

-- The ONE run-receipt projection (ABI SSD item 2's columns, verbatim) PLUS the pair's live
-- state (as-built ladder round 8).
--
-- THE RECEIPT COLUMNS ARE STILL COPIED AND NOTHING IS COMPUTED FROM THEM -- a receipt is
-- immutable by trigger, so there is nothing to derive there and that remains the point. What was
-- MISSING is a different thing: the receipt records what the run DID, and the card built on it
-- offers "Correct this run", which is a claim about what the books will accept NOW. Round 8
-- measured the consequence: the run-receipt card offered the act on runs whose occurrence was
-- already corrected and on runs whose pair correction was already parked for a checker, so a
-- reader followed an action into a refusal. A surface cannot be expected to re-derive the two
-- correction doors' admission logic -- that is exactly the drift WDB-R2 forbids -- so the DB
-- answers it, from the SAME body the re-run gate's own refusal is derived from
-- (clara._adj_correction_door). The card and the gate cannot disagree because there is one
-- derivation.
--
-- SEVEN KEYS [R12 2026-08-04 -- this header said SIX and then introduced the seventh forty lines down,
-- which is the kind of drift a reader has to re-count to catch], and their spellings are
-- load-bearing (the surface lane consumes them by name):
--   correctable            boolean     the door body's own verdict for THIS run's occurrence
--   active_pair_id         uuid|null   the pair-machine row in flight over it, if any
--   active_pair_status     text|null   its status -- 'pending' or 'approving'
--   correction_verb        text|null   the verb that admits this entry TODAY
--   correction_entry       uuid        the entry THAT verb takes (the pair verb takes the occurrence)
--   correction_wall        text|null   the reason token that closed the door, when one did
--   correction_wall_advice text|null   that wall's own followable sentence (R11-F8, argued below)
--
-- THE LAST THREE ARE ROUND 9's REPAIR OF ROUND 8's OWN REPAIR, and they are the same three keys
-- clara._wdb_rerun_breach's shape_already_met payload carries -- one spelling for one thing, from
-- one derivation. Round 8 exported `correctable` and DROPPED `verb`, and the run-receipt card,
-- having no other input, wired its one button to clara.reverse_adjustment_pair unconditionally.
-- MEASURED (round-9 lens Y2, probe y2/p3-correction-door.mjs): a SOLO occurrence -- an ordinary
-- non-auto-reverse prepayment amortisation, design SS2's commonest case -- reads
-- correctable:true with verb 'clara.reverse_entry', the card offers "Correct this run", and every
-- click refuses CLR10 not_an_auto_pair. That is the walled corridor again, one layer out: the DB
-- knew which verb admits the entry and did not say. `correctable` alone can never answer "which
-- act", so a surface that has only `correctable` must GUESS, and WDB-R2 exists to stop exactly
-- that guess. The card keys on `correction_verb`; the DB never asks it to infer.
-- "Active" is the SCHEMA's word, not this body's: uq_adjustment_pair_reversals_occurrence_active
-- is defined `where status in ('pending','approving')`, which is the same predicate
-- clara._pair_reverse_core's pair_already_active arm refuses on. A COMPLETED pair is therefore
-- honestly not active -- and the run reads correctable=false because its occurrence carries
-- reversed_by, which is the fact the card needs.
--
-- STABLE + SECURITY DEFINER, no longer IMMUTABLE: the three new keys read live rows. Cost is one
-- door probe per receipt row, and a client's receipt list is small and already per-client
-- firm-scoped -- the D-a F10 hot-loop law is about the SWEEP's path, and neither
-- clara.list_adjustment_runs nor clara.get_adjustment_run is on it.
create function clara._adj_run_json(r clara.adjustment_runs) returns jsonb
  language sql stable security definer set search_path = clara, pg_temp as $$
  with d as (select clara._adj_correction_door(r.entry_id) as j)
  select jsonb_build_object('id', r.id, 'client_id', r.client_id, 'template_id', r.template_id,
    'period_start', r.period_start, 'period_end', r.period_end, 'mode', r.mode,
    'entry_id', r.entry_id, 'reversal_entry_id', r.reversal_entry_id,
    'amount_cents', r.amount_cents, 'created_at', r.created_at)
    || jsonb_build_object(
         'correctable', coalesce((d.j ->> 'correctable')::boolean, false),
         'active_pair_id', coalesce(d.j -> 'active_pair_id', 'null'::jsonb),
         'active_pair_status', coalesce(d.j -> 'active_pair_status', 'null'::jsonb),
         'correction_verb', coalesce(d.j -> 'verb', 'null'::jsonb),
         'correction_entry', coalesce(d.j -> 'entry', 'null'::jsonb),
         'correction_wall', coalesce(d.j -> 'wall', 'null'::jsonb),
         -- SEVEN KEYS NOW [R11 FIX 2026-08-04 -- W2 finding 5]. The door has composed a followable
         -- sentence for its refusing states since round 10 and NOTHING consumed it on this path:
         -- MEASURED, a run whose correction the advance register refuses rendered exactly like a
         -- healthy uncorrected run minus the button, under a static line telling the reader the
         -- correction "rides reverse_adjustment_pair" -- a verb that refuses CLR40 in that state.
         -- A wall token with no sentence is a dead end for the human reading it, and this file
         -- already made that argument twice (at the door's own "any other wall" arm, and at the
         -- gate's first remedy clause). The key is ALWAYS present, jsonb null included.
         'correction_wall_advice', coalesce(d.j -> 'wall_advice', 'null'::jsonb))
  from d $$;
revoke all on function clara._adj_run_json(clara.adjustment_runs) from public;

create function clara.list_adjustment_templates(p_client uuid) returns jsonb
  language plpgsql stable security definer set search_path = clara, pg_temp as $$
declare c record; v_rows jsonb; v_live int; v_blocked int;
begin
  c := clara._human_ctx(clara.role_rank('viewer'));
  if not exists (select 1 from clara.clients cl where cl.id = p_client and cl.firm_id = c.firm) then
    raise exception 'client is not in your firm' using errcode = 'CLR11';
  end if;
  -- PROPOSED FIRST, then live, then retired: the panel's whole job is to get an unsigned
  -- proposal in front of an admin, and a long retired tail must never push it off the screen.
  select coalesce(jsonb_agg(clara._adj_template_json(t.id)
           order by case t.status when 'proposed' then 0 when 'live' then 1 else 2 end,
                    t.created_at, t.id), '[]'::jsonb)
    into v_rows from clara.adjustment_templates t
    where t.client_id = p_client and t.firm_id = c.firm;
  select count(*) filter (where t.status = 'live')::int,
         count(*) filter (where t.status <> 'retired'
                            and clara._adj_occurrence_outstanding(p_client, t.id))::int
    into v_live, v_blocked
    from clara.adjustment_templates t
    where t.client_id = p_client and t.firm_id = c.firm;
  return jsonb_build_object('client_id', p_client, 'templates', v_rows,
    'live_count', v_live, 'draft_blocked_count', v_blocked);
end $$;
revoke all on function clara.list_adjustment_templates(uuid) from public;

create function clara.list_adjustment_runs(p_client uuid) returns jsonb
  language plpgsql stable security definer set search_path = clara, pg_temp as $$
declare c record; v_rows jsonb;
begin
  c := clara._human_ctx(clara.role_rank('viewer'));
  if not exists (select 1 from clara.clients cl where cl.id = p_client and cl.firm_id = c.firm) then
    raise exception 'client is not in your firm' using errcode = 'CLR11';
  end if;
  -- NEWEST PERIOD FIRST (clara.list_depreciation_runs' own ordering): the panel's per-template
  -- echo takes the head of this list, so "the last run" must be the first row without the
  -- caller sorting anything.
  select coalesce(jsonb_agg(clara._adj_run_json(r)
           order by r.period_end desc, r.created_at desc), '[]'::jsonb)
    into v_rows from clara.adjustment_runs r
    where r.client_id = p_client and r.firm_id = c.firm;
  return jsonb_build_object('client_id', p_client, 'runs', v_rows);
end $$;
revoke all on function clara.list_adjustment_runs(uuid) from public;

-- The by-id getter behind the `adjustment_run_receipt` card (design SS2.5/SS2.7), cloned from
-- clara.get_depreciation_run down to the CLR11 wording: a receipt outside the reader's firm is
-- reported as not-in-your-firm rather than as not-found, so the read cannot be used to probe
-- for the existence of another firm's rows.
create function clara.get_adjustment_run(p_run uuid) returns jsonb
  language plpgsql stable security definer set search_path = clara, pg_temp as $$
declare c record; r clara.adjustment_runs%rowtype;
begin
  c := clara._human_ctx(clara.role_rank('viewer'));
  select * into r from clara.adjustment_runs where id = p_run and firm_id = c.firm;
  if not found then
    raise exception 'adjustment run receipt is not in your firm' using errcode = 'CLR11';
  end if;
  return jsonb_build_object('run', clara._adj_run_json(r));
end $$;
revoke all on function clara.get_adjustment_run(uuid) from public;

-- =====================================================================================
-- S2.9 -- GRANTS. The 0038:8056-8064 bulk loop idiom (copied 0040:4790-4801, 0041:4405-4424):
-- revoke from public, grant to the ONE lane that may call it, re-assert fn-owner ownership.
-- Every internal above already carries its own `revoke all ... from public` and is granted to
-- NOBODY -- reachable only from inside a SECURITY DEFINER body owned by clara_fn_owner.
-- =====================================================================================
do $s2acl$ declare f text; begin
  foreach f in array array[
      -- [round 10, lane P1] The signature gained an OPTIONAL trailing `p_replaces uuid` (the
      -- lineage declaration). The grant loop restates the arity, so this string is the one place
      -- in the file that has to move for an additive argument -- which is exactly why the house
      -- rule is "new arguments go LAST with a default": every caller, and every other census in
      -- this migration (all of which key on proname), is untouched.
      'clara.propose_adjustment_template(uuid,text,text,date,date,boolean,jsonb,text,text,uuid)',
      'clara.sign_adjustment_template(uuid,uuid,text)',
      'clara.retire_adjustment_template(uuid,uuid,text,text)',
      'clara.run_adjustment_manual(uuid,uuid,date,date,text)',
      'clara.reverse_adjustment_pair(uuid,uuid,text,text)',
      'clara.approve_pair_reversal(uuid,uuid,text,text)',
      'clara.cancel_pair_reversal(uuid,uuid,text,text)',
      -- the S2.8 reads: viewer-floored, firm-scoped, human lane only (the sweep reads the
      -- tables it writes; it has no use for a panel projection)
      'clara.list_adjustment_templates(uuid)',
      'clara.list_adjustment_runs(uuid)',
      'clara.get_adjustment_run(uuid)'] loop
    execute format('revoke all on function %s from public', f);
    execute format('grant execute on function %s to clara_authenticated', f);
    execute format('alter function %s owner to clara_fn_owner', f);
  end loop;
end $s2acl$;

-- THE MACHINE LANE (design SS2.7, the 0041:4426-4440 idiom). The leader runs under
-- `set role clara_runtime` -- a GROUP role; clara_runtime_login inherits nothing, so the grant
-- goes on the group. The due probe is granted to BOTH lanes (the /rules panel shows the same
-- advisory the sweep acts on); the RUN verb is granted to the RUNTIME ONLY -- a human runs an
-- occurrence through clara.run_adjustment_manual, which is _human_ctx-floored and firm-checked.
do $s2macl$ begin
  execute 'revoke all on function clara.run_adjustment_occurrence(uuid,uuid,date,date,text) from public';
  execute 'grant execute on function clara.run_adjustment_occurrence(uuid,uuid,date,date,text) to clara_runtime';
  execute 'alter function clara.run_adjustment_occurrence(uuid,uuid,date,date,text) owner to clara_fn_owner';
  execute 'revoke all on function clara.adjustment_run_due(uuid) from public';
  execute 'grant execute on function clara.adjustment_run_due(uuid) to clara_runtime';
  execute 'grant execute on function clara.adjustment_run_due(uuid) to clara_authenticated';
  execute 'alter function clara.adjustment_run_due(uuid) owner to clara_fn_owner';
end $s2macl$;


-- =====================================================================================
-- S2.9-b3 -- THE ONE GRANT D-b3 WITHHELD (confirming round, CF-B3-1 / Codex CX1)
-- =====================================================================================
-- [SPLIT D-b2 2026-08-04] THIS BLOCK IS NOT IN THE WHOLE UNIT AND HAS NO CANONICAL SITE, because in the
-- whole unit clara.accept_bank_rule_suggestion is created and granted by the SAME statement
-- (SECTION S4's $s4_acl$ loop, canonical s4 L4342-4350). The split separates the two, and this is
-- the second half.
-- WHY THE GRANT WAITED FOR THIS FILE. The producer has TWO account-role doors. The ACCEPT-time
-- door is D-b3's (it calls clara._adj_line_eligibility_breach before it mints the draft). The
-- APPROVE-time door is clara._adj_on_approve ARM (3) -- "THE SIXTH AXIS ... the PHANTOM STAFF
-- ADVANCE", as-built ladder round 2 -- which is a body THIS file creates (SECTION S2 above) and
-- which only reaches the approve path when S5.8-b2 below splices it into
-- clara._subledger_on_approve, ABOVE D-b1's advance line. Between 0044 and 0045 the second door
-- does not exist, and the confirming round PROBED what that costs on a live 0044 rig: accept a
-- money-OUT suggestion whose contra account is ordinary, ENROL that account as a staff-advance
-- account (D-b1's verb, live since 0043), approve -- the approve SUCCEEDS, D-b1's
-- clara._adv_on_approve arm (3) soft-births a staff_advance nobody received, and the summary,
-- the statement and the tie all agree with it (difference_cents 0). The same script on the
-- four-slice chain is refused CLR39 `suggestion_stale` on the `line_eligibility` axis. So D-b3
-- ships the verb CREATED, REVOKED FROM PUBLIC and OWNED by clara_fn_owner but NOT GRANTED, and
-- the single grant lands HERE, in the same migration as the wall it depends on.
-- THIS IS WHY THE END STATE IS STILL THE WHOLE UNIT'S. One statement moved one slice later; the
-- four-slice chain's final ACL for this function is identical to the twin's, and the twin-rig
-- equivalence proof (function owner + ACL axis, 599 vs 599, diff 0) was re-measured after the
-- move. Nothing about the body, its dedup index, its callers or its floors changed.
-- IT IS ASSERTED, NOT ASSUMED: the block re-reads the catalog and refuses if the grant did not
-- land, and it names the prerequisite it is safe under -- clara._adj_on_approve must exist by
-- now, and SECTION S2 above created it.
--
-- [light re-confirm RC1] AND IT DEMANDS ZERO REACHABILITY BEFORE IT GRANTS. Codex read the pair
-- of blocks correctly: D-b3 asserted the grant was absent, this one asserted it was present
-- afterwards, and NEITHER asked what else could already reach the verb. If a hotfix between
-- 0044 and 0045 granted EXECUTE to clara_runtime, or a default privilege made it reachable by
-- inheritance, both blocks passed and the phantom-staff-advance window the deferral exists to
-- close was open the whole time -- invisibly, because the end-state ACL that the twin-rig proof
-- compares is the same either way. So this block now opens with the PRESTATE the deferral
-- actually claims: nobody but the owner reaches this function yet. It fails LOUD and by name if
-- that is untrue, because the correct response is to investigate the grant, never to proceed.
do $s2acl_b3producer$
declare
  f text := 'clara.accept_bank_rule_suggestion(uuid,uuid,uuid,text)';
  v_oid oid;
  v_n int;
  v_roster text;
  r record;
begin
  if to_regprocedure(f) is null then
    raise exception '0042 S2.9-b3: clara.accept_bank_rule_suggestion does not exist -- it is D-b3''s (0044) verb and SECTION 0''s probe 1 should already have refused this apply'
      using errcode = 'CLR10';
  end if;
  if to_regprocedure('clara._adj_on_approve(uuid)') is null then
    raise exception '0042 S2.9-b3: clara._adj_on_approve does not exist, so the producer''s approve-time account-role door is still missing -- granting the verb here would re-open the round-2 phantom staff advance this deferral exists to close'
      using errcode = 'CLR10';
  end if;
  select p.oid into v_oid
    from pg_proc p
   where p.pronamespace = 'clara'::regnamespace
     and p.proname = 'accept_bank_rule_suggestion';

  -- PRESTATE (a): the COMPLETE non-owner ACL roster is empty -- PUBLIC included, every
  -- privilege kind included. D-b3 shipped it that way; anything here means somebody granted it
  -- between the two migrations.
  select count(*)::int, coalesce(string_agg(distinct g, ', ' order by g), '(none)')
    into v_n, v_roster
    from pg_proc p
    cross join lateral aclexplode(coalesce(p.proacl, '{}'::aclitem[])) a
    cross join lateral (select case when a.grantee = 0 then 'PUBLIC'
                                    else coalesce((select rolname from pg_roles where oid = a.grantee),
                                                  'oid ' || a.grantee::text) end) as x(g)
   where p.oid = v_oid
     and a.grantee <> p.proowner;
  if v_n <> 0 then
    raise exception '0042 S2.9-b3 prestate: clara.accept_bank_rule_suggestion already carries % non-owner ACL entr(y/ies) (grantees: %) BEFORE this grant -- D-b3 (0044) ships it reachable by nobody, so somebody granted it between the two migrations and the phantom-staff-advance window was open. Investigate the grant; do not proceed.', v_n, v_roster
      using errcode = 'CLR10';
  end if;

  -- PRESTATE (b): and nobody reaches it by INHERITANCE or default privilege either -- the half
  -- an ACL roster structurally cannot see.
  for r in select rolname from (values ('clara_authenticated'), ('clara_runtime'), ('clara_agent_ro'))
             as t(rolname) loop
    if to_regrole(r.rolname) is not null
       and has_function_privilege(r.rolname, v_oid, 'EXECUTE') then
      raise exception '0042 S2.9-b3 prestate: % can already EXECUTE clara.accept_bank_rule_suggestion before this grant even though the function''s own ACL is empty -- an inherited or default-privilege grant is in force, so the D-b3..D-b2 deferral did not actually hold. Investigate; do not proceed.', r.rolname
        using errcode = 'CLR10';
    end if;
  end loop;

  execute format('grant execute on function %s to clara_authenticated', f);
  select count(*)::int into v_n
    from pg_proc p
    cross join lateral aclexplode(coalesce(p.proacl, '{}'::aclitem[])) a
    join pg_roles rr on rr.oid = a.grantee
   where p.oid = v_oid
     and a.privilege_type = 'EXECUTE'
     and rr.rolname = 'clara_authenticated';
  if v_n <> 1 then
    raise exception '0042 S2.9-b3: clara.accept_bank_rule_suggestion holds % clara_authenticated EXECUTE grant(s) after this block, expected exactly 1', v_n
      using errcode = 'CLR10';
  end if;
  -- POSTSTATE: the ONE grant this block adds is the ONLY non-owner entry -- the end state is the
  -- whole unit's, grant for grant, which is what the twin-rig equivalence proof compares.
  select count(*)::int, coalesce(string_agg(distinct g, ', ' order by g), '(none)')
    into v_n, v_roster
    from pg_proc p
    cross join lateral aclexplode(coalesce(p.proacl, '{}'::aclitem[])) a
    cross join lateral (select case when a.grantee = 0 then 'PUBLIC'
                                    else coalesce((select rolname from pg_roles where oid = a.grantee),
                                                  'oid ' || a.grantee::text) end) as x(g)
   where p.oid = v_oid
     and a.grantee <> p.proowner;
  if v_n <> 1 or v_roster <> 'clara_authenticated' then
    raise exception '0042 S2.9-b3 postcheck: clara.accept_bank_rule_suggestion ends this block with % non-owner ACL entr(y/ies) (grantees: %), expected exactly one and only clara_authenticated', v_n, v_roster
      using errcode = 'CLR10';
  end if;
  raise notice '0042 S2.9-b3 OK: the bank-rule producer''s clara_authenticated grant -- withheld by D-b3 (0044) because clara._adj_on_approve arm (3) did not exist yet -- lands here, in the same file as that wall. The producer is reachable by a human from this migration forward, and the wave''s ACL end state now equals the whole unit''s.';
end $s2acl_b3producer$;

-- The clara_fn_owner region stays OPEN for SECTION S3 (the file header's shape map marks the
-- role change at S2 and closes it once, later); the assembler owns the matching `reset role`.
-- [SPLIT D-b2 2026-08-04] THE COMMENT ABOVE IS THE WHOLE UNIT'S AND IS KEPT VERBATIM BECAUSE IT
-- RECORDS WHY THE SCOPE WAS LEFT OPEN THERE -- but in THIS file there is no SECTION S3 to
-- inherit it, and census hazard sect.7.4 is explicit that the inherited-role coupling is the
-- thing the split has to break. So the scope this section opened is closed HERE, by this
-- section, and the assembler asserts the balance PER FILE rather than owning it.
reset role;

-- #####################################################################################
-- ###### SECTION S5 (D-b2 SLICE) -- THE FIVE LIVE-BODY BLOCKS THIS FAMILY OWNS #######
-- #####################################################################################
-- [SPLIT D-b2 2026-08-04] FIVE OF SECTION S5's THIRTY-THREE LABELLED BLOCKS LAND HERE, and every one
-- of them is a SPLICE on a body that already exists in production. Census sect.8's D-b2 bullets,
-- in order:
--   * S5.8-b2   -- the clara._adj_on_approve line into clara._subledger_on_approve, inserted
--                  ABOVE the advance line D-b1 installed. Census sect.2 Class C is the
--                  highest-severity edge in the whole partition: the whole unit's two `perform`
--                  lines are unconditional, PL/pgSQL resolves neither at CREATE time, and a
--                  slice that installed a call to a body it does not create would break every
--                  approve path in production at the first approval. D-b0 made NO hook edit;
--                  D-b1 added the advance line and left an anchor comment naming the position
--                  this line must take; this block takes it. ORDER IS LOAD-BEARING and the
--                  four-anchor postcheck below is the whole unit's own claim, made for the
--                  first time.
--   * S5.10 / S5.10a -- clara.revise_entry's three D-b proposal keys, its pair-draft lock, and
--                  the re-order that puts the pair arm ABOVE the 0037 reversal-mirror arm. Both
--                  blocks MOVE WHOLE (census sect.2 Class E: the pair arm reads
--                  clara.adjustment_pair_reversals, a relation SECTION S1 of THIS file creates).
--   * S5.11     -- clara.withdraw_draft's pair-receipt refusal. MOVES WHOLE, same reason.
--   * S5.12-b2  -- the clara.adjustment_templates CADENCE arm of clara.set_client_fy_end.
--
-- S5.9 HAS NO D-b2 FORM, AND THAT IS THE BINDING ERRATA RATHER THAN AN OMISSION. Census sect.8
-- gives this slice "S5.9-b2 (clara._wdb_correction_posting_date term, IF NOT ALREADY IN D-b0)".
-- It is already in D-b0: errata E1 records that D-b0 had to ship the correction-date half
-- because it also ships the re-run ENFORCEMENT (S5.15c/S5.15d put the fixed-asset due oracle and
-- poster on clara._wdb_rerun_breach), and shipping the gate without the remedy refuses a LAWFUL
-- reverse-then-re-run of any depreciation period with CLR38, permanently and irreparably.
-- D-b1 then shipped the other half (the reversal WALL and its ordering postcheck) as S5.9-b1.
-- MEASURED ON THIS SLICE'S RIG, not assumed: clara.reverse_entry carries
-- clara._wdb_correction_posting_date(p_entry, exactly once and
-- clara._wdb_reversal_blocked(p_entry) exactly once, with Asia/Kuala_Lumpur still at 1 and
-- current_date still at 0. The whole unit's S5.9 is COMPLETE before this file opens, and a
-- third splice on that body would have no subject.
--
-- S5.12's OTHER HALF IS ALSO ALREADY SHIPPED (errata E6). Census sect.3 records S5.12 as
-- "separable: rung -> D-b0, cadence guard -> D-b2", and D-b0's first cut deferred the WHOLE
-- guard on that wording -- which its own battery then measured as a regression (cell x41.f3: the
-- clara.fa_depreciation_authorities arm reads a 0041 relation and names no later-slice object at
-- all). Adjudicated and corrected there: D-b0 shipped the RUNG and the AUTHORITY arm; this file
-- ships the TEMPLATE arm, above it, and restores the whole unit's counts.
--
-- EVERY OTHER S5 BLOCK IS SOMEBODY ELSE'S. S5.1-S5.7, S5.9's correction-date half, S5.12's rung
-- and authority arms, S5.13, S5.15/S5.15b/S5.15c/S5.15d/S5.15f, S5.16-S5.18, S5.19's two helper
-- creates, S5.20-S5.27 and the four censuses shipped in D-b0; S5.8's advance line, S5.9's
-- reversal wall and S5.19's reader recut in D-b1. Census hazard sect.7.3 is honoured from the
-- far end: this file touches NONE of the four s4-owned bodies (clara._tf_bank_settled_authority_
-- belt, clara.complete_pending_match, clara.get_bank_reconciliation, clara.unmatch_bank_match),
-- and hazard sect.7.5's duplicate S5.15 label is not in this slice either.
--
-- ROLE SCOPING IS PER-BLOCK, as it is in the canonical section (census hazard sect.7.4): each
-- block below opens and closes its own `set role clara_fn_owner` scope.

-- =====================================================================================
-- S5.8 -- clara._subledger_on_approve: THE ADJUSTMENT AND STAFF-ADVANCE HOOK SPLICES
-- (design SS2.6 / SS3.3).
--
-- Placed IMMEDIATELY AFTER the FA hook and ABOVE the settlement early-return, for the
-- identical reason 0041 recorded when it put the FA hook there: everything below
-- `if v_prop is null then return; end if;` is DEAD CODE for every non-settlement entry --
-- which is every adjustment occurrence, every auto-reversal mirror, every staff-advance
-- disbursement and every application. All four approve paths funnel through this one body,
-- so these two lines are what make recurring-adjustment materialisation and staff-advance
-- register movement intrinsic at each of them (ARCHITECTURE SS3.5, PRD F3).
--
-- THE ORDER IS LOAD-BEARING AND IS ASSERTED BELOW, NOT ASSUMED. The adjustment hook runs
-- first: its arm (2) mints the auto-reversal mirror and its arm (1) is the pair-correction
-- defense, both of which must settle before the advance hook reads the entry's legs. The
-- advance hook then runs UNCONDITIONALLY -- including on an auto-reversal mirror -- because a
-- reversal mirror can carry advance-bearing legs whose register effect is exactly what its
-- correction arm exists to write.
-- [SPLIT D-b2 2026-08-04] THE HEADER ABOVE IS THE WHOLE UNIT'S AND IS KEPT VERBATIM -- and with this
-- block it becomes TRUE OF THE LIVE BODY for the first time: both `perform` lines are in place,
-- in the order it argues for, above the settlement early-return. D-b1 installed the advance line
-- and wrote the position of THIS line into the body itself; this block takes that position.
--
-- THE PRESTATE IS ANCHORED ON THE BODY AS D-b1 LEFT IT, AND THAT IS BINDING ERRATA E8. It is
-- SEVEN markers, not six: the six pre-0042 ones the whole unit counts PLUS
-- clara._adv_on_approve(p_entry), which D-b1's splice installed. Every count was HARVESTED with
-- pg_get_functiondef from a rig with 0042+0043+0044 applied, never read off the 0041 file text or
-- off the whole unit's eight-marker postcheck.
-- THE IDEMPOTENCY CLAIM IS THE SEVEN-MARKER CENSUS PLUS A ZERO ROW, NOT A BARE TEXT PROBE, and
-- E8 is the reason. D-b1 deliberately wrote its in-body anchor comment naming the adjustment hook
-- WITHOUT its open paren, because a prestate that read RAW pg_get_functiondef text and probed for
-- `clara._adj_on_approve(` would find that comment and conclude "already applied" on a database
-- where nothing had been applied. Measured on the rig: `clara._adj_on_approve(` occurs ZERO times
-- in the body D-b1 leaves. So the zero row below is safe TODAY -- and it is made as one row of
-- the same seven-marker census rather than as a standalone text probe, so a future comment that
-- reintroduced the string would fail this block by name instead of silently skipping it.
-- FINAL FORM: this is it. The whole unit's eight-marker postcheck and its four-anchor ordering
-- claim are both asserted below, on the live body.
-- =====================================================================================
set role clara_fn_owner;

do $s5_8_b2$
declare
  v_sig text := 'clara._subledger_on_approve(uuid)';
  v_def text; v_exe text; v_frm text; v_cnt int; v_n int; r record;
  -- [R13 FIX 2026-08-04] the four ordered anchor positions, read once through the shared matcher rather
  -- than re-derived inside one long boolean -- so the diagnostic below can PRINT them.
  v_pfa int; v_padj int; v_padv int; v_pset int;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p where p.oid = v_sig::regprocedure;
  if v_def is null then
    raise exception '0042 S5.8-b2 prestate: clara._subledger_on_approve is GONE' using errcode = 'CLR10';
  end if;
  -- [R11 FIX 2026-08-04 -- confirming-round Codex finding 6] THE CODE COPY, AND WHAT IT IS FOR. Errata
  -- E8 records that D-b1 wrote its in-body anchor comment naming this hook WITHOUT its open
  -- paren, deliberately, so that a raw-text probe for `clara._adj_on_approve(` would read zero on
  -- a database where nothing had been applied. That worked, and it made a COMMENT SPELLING
  -- load-bearing across two migrations: a lawful hotfix that re-created this body with IDENTICAL
  -- executable SQL and one extra explanatory comment naming the hook would make this block refuse
  -- a correct deploy as "already applied". Prose is not an idempotency token, so the absence
  -- judgement is made on the code alone.
  -- [R12 FIX 2026-08-04 -- confirming round, Codex CXR3] AND THE CODE IS NOW DECIDED BY A LEXER, ON THE
  -- SAME BODY SECTION 0's PROBE 11 READS. Round 11 used a regexp pair, which counts a marker
  -- inside a STRING as executable (a lawful hotfix carrying `$msg$...clara._adj_on_approve(
  -- p_entry)...$msg$` was REFUSED) and can span a block-comment match from inside one string
  -- literal to inside another, deleting the executable line between them (measured: the count
  -- fell to ZERO, which reads as "already applied" on a body nothing had touched).
  -- IT IS prosrc AND NOT pg_get_functiondef, AND THE DIFFERENCE IS NOT COSMETIC: functiondef
  -- wraps the whole body in a dollar-quoted string, so a real lexer blanks ALL of it and every
  -- marker would read zero -- the exact false-idempotency this fix exists to remove. prosrc is
  -- the body itself. The raw functiondef remains the instrument for the five whole-unit body
  -- counts below, which were measured on it and are unchanged.
  if to_regprocedure('pg_temp._wdb_sql_code(text)') is null then
    raise exception '0042 S5.8-b2 prestate: the shared SQL-lexical stripper pg_temp._wdb_sql_code is not in this session -- SECTION 0 creates it and probe 11 uses it; this block and that probe must judge the hook markers on the SAME instrument or one can admit an apply the other refuses'
      using errcode = 'CLR10';
  end if;
  select pg_temp._wdb_sql_code(p.prosrc) into v_exe from pg_proc p where p.oid = v_sig::regprocedure;
  if length(v_exe) <> (select length(p.prosrc) from pg_proc p where p.oid = v_sig::regprocedure) then
    raise exception '0042 S5.8-b2 prestate: the SQL-lexical stripper changed the body length -- it must BLANK comments and string literals, never delete them; a shortened result would under-count the hook markers'
      using errcode = 'CLR10';
  end if;
  -- THE SEVEN-MARKER PRESTATE CENSUS: 0041's five originals at their measured counts, 0041's own
  -- splice marker, and D-b1's advance hook -- the line this splice sits ABOVE. Requiring the
  -- seventh at 1 is what makes this block refuse to run on a database that skipped D-b1, and the
  -- eighth row (the adjustment hook at ZERO) is this block's idempotency claim.
  -- [SPLIT D-b2 2026-08-04] MEASURED ON A RIG WITH D-b0 + D-b1 + D-b3 APPLIED. D-b0 and D-b3 make no
  -- edit to this body (census hazard sect.7.3, confirmed from both ends), so the first six counts
  -- are exactly the whole unit's; the seventh is D-b1's.
  -- THE THIRD COLUMN IS THE INSTRUMENT [R11 FIX 2026-08-04; widened R12 2026-08-04]: `on_code` says whether
  -- this row is a question about the BODY (the raw functiondef, where a count of 3 for
  -- 'effective_date' includes the ones inside comments and always did) or about the CODE (the
  -- lexically blanked prosrc). ALL THREE HOOK ROWS ARE NOW CODE ROWS, and that is the confirming
  -- round's instrument-mismatch fix: SECTION 0's probe 11 judged fa/adv/adj on stripped text
  -- while this roster judged only the absence row that way, so a lawful comment naming the FA or
  -- the advance hook made the probe PASS and this prestate REFUSE -- a migration that dies in the
  -- middle of itself. The five body counts stay on the raw instrument they were measured on.
  -- ONE SPELLING PER MARKER, and probe 11 carries the same three. Round 12 wrote the ABSENCE row
  -- argument-blind (`clara._adj_on_approve(`) and left the two PRESENCE rows on exact arguments.
  -- [R13 FIX 2026-08-04 -- re-confirming round, Codex RC4, DEPLOY-BLOCKER] THAT WAS STILL THREE
  -- SPELLINGS IN ONE BLOCK, AND THE SPLIT IT LEAVES IS MEASURABLE: `clara._adj_on_approve(p_entry
  -- => p_entry)` is the same call in named notation, it is ABSENT to probe 11's `...(p_entry)` and
  -- PRESENT to this row's `...(`, so probe 11 admits an apply this prestate then refuses. All
  -- three hook rows are now CALL rows judged by pg_temp._wdb_call_count -- the qualified name, up
  -- to the paren, blind to the argument list, and blind to comments in the token gaps (RC3: a
  -- comment IS whitespace, so `clara._adj_on_approve/*hotfix*/(p_entry)` is a real call that this
  -- roster read as ABSENT while the splice added a second one beside it).
  -- THE FIVE BODY ROWS DO NOT MOVE. They are questions about TEXT -- a count of 3 for
  -- 'effective_date' includes the ones inside comments and always did -- and they are pinned on
  -- the raw functiondef they were measured on.
  for r in select * from (values
      ('payment_terms_days', 1, false),
      ('effective_date', 3, false),
      ($$item_kind in ('invoice','bill')$$, 1, false),
      ('cross_domain_control_entry', 1, false),
      ('allocation_stale', 6, false),
      ('clara._fa_on_approve', 1, true),
      ('clara._adv_on_approve', 1, true),
      ('clara._adj_on_approve', 0, true)) as t(marker, want, is_call) loop
    v_n := case when r.is_call then pg_temp._wdb_call_count(v_exe, r.marker)
                else (length(v_def) - length(replace(v_def, r.marker, ''))) / length(r.marker)
           end;
    if v_n <> r.want then
      raise exception '0042 S5.8-b2 prestate: the live _subledger_on_approve % % time(s), expected % -- the body drifted, D-b1''s advance hook is missing, or this splice has already been applied to this database', case when r.is_call then 'calls ' || r.marker || ' (measured on the CODE: comments and string literals blanked lexically, the call matched by qualified name and blind to its arguments)' else 'carries the body marker "' || r.marker || '"' end, v_n, r.want
        using errcode = 'CLR10';
    end if;
  end loop;

  -- THE ANCHOR IS D-b1's OWN LINE, and the splice goes ABOVE it. The whole unit anchored on the
  -- FA hook and emitted both lines at once; here the FA hook already has a line under it, so
  -- anchoring there would put the adjustment call BELOW the advance call -- the exact inversion
  -- the header argues against.
  v_frm := $f$  perform clara._adv_on_approve(p_entry);$f$;
  v_cnt := (length(v_def) - length(replace(v_def, v_frm, ''))) / length(v_frm);
  if v_cnt <> 1 then
    raise exception '0042 S5.8-b2 prestate: the staff-advance hook call anchor appears % time(s) (expected exactly once) -- the body drifted; re-derive this splice', v_cnt
      using errcode = 'CLR10';
  end if;
  v_def := replace(v_def, v_frm,
    $t$  -- [wave D-b slice D-b2, 2026-08-04] THE LINE THE NOTE ABOVE ASKED FOR, IN THE POSITION IT
  -- NAMED. The order is now fa -> adjustment -> advance -> the settlement early-return, which is
  -- the law the whole unit's header states, and the four-anchor census below asserts it.
  perform clara._adj_on_approve(p_entry);
  perform clara._adv_on_approve(p_entry);$t$);
  execute v_def;

  select pg_get_functiondef(p.oid) into v_def from pg_proc p where p.oid = v_sig::regprocedure;
  -- THE EIGHT-MARKER POSTCHECK CENSUS -- the six re-pinned at their measured counts plus the
  -- two D-b hooks, each exactly once.
  -- [SPLIT D-b2 2026-08-04] THIS IS THE WHOLE UNIT'S POSTCHECK, RESTORED. D-b1's form asserted the
  -- adjustment row at ZERO because it was D-b2's; here it is 1, on the same instrument.
  -- [R12 FIX 2026-08-04 -- confirming round, Codex CXR3] ...AND "THE SAME INSTRUMENT" NOW MEANS IT
  -- LITERALLY: the three hook rows are judged on the lexically blanked prosrc, exactly as the
  -- prestate above and probe 11 judge them. A postcheck that asked a different question from the
  -- prestate could pass a splice the prestate would have refused, which is the same class of
  -- disagreement this round is closing one screen up.
  -- [R13 FIX 2026-08-04 -- re-confirming round, Codex RC4] ...AND "THE SAME QUESTION" NOW MEANS IT
  -- LITERALLY: the three hook rows are CALL rows on pg_temp._wdb_call_count, exactly as the
  -- prestate above and probe 11 ask them. The count that matters here is ONE -- and it is one of
  -- the two places that would have caught RC3's double if it had been argument-blind and
  -- token-aware: with a comment-spliced call already in the body, the pre-fix census counted the
  -- newly spliced canonical call, read 1, and passed.
  select pg_temp._wdb_sql_code(p.prosrc) into v_exe from pg_proc p where p.oid = v_sig::regprocedure;
  for r in select * from (values
      ('payment_terms_days', 1, false),
      ('effective_date', 3, false),
      ($$item_kind in ('invoice','bill')$$, 1, false),
      ('cross_domain_control_entry', 1, false),
      ('allocation_stale', 6, false),
      ('clara._fa_on_approve', 1, true),
      ('clara._adj_on_approve', 1, true),
      ('clara._adv_on_approve', 1, true)) as t(marker, want, is_call) loop
    v_n := case when r.is_call then pg_temp._wdb_call_count(v_exe, r.marker)
                else (length(v_def) - length(replace(v_def, r.marker, ''))) / length(r.marker)
           end;
    if v_n <> r.want then
      raise exception '0042 S5.8-b2 postcheck: the body now % % time(s) (expected %) -- the splice damaged the body', case when r.is_call then 'calls ' || r.marker else 'carries the marker "' || r.marker || '"' end, v_n, r.want
        using errcode = 'CLR10';
    end if;
  end loop;
  -- ORDERED, ALL-PRESENT: FA hook -> adjustment hook -> advance hook -> the settlement early
  -- return. A bare position(a) < position(b) reads a MISSING marker (position 0) as correctly
  -- ordered and passes vacuously -- the absence-from-the-wrong-instrument mistake this repo
  -- has already paid for three times.
  -- [SPLIT D-b2 2026-08-04] FOUR ANCHORS: the whole unit's chain, and the claim D-b1's three-anchor
  -- form deferred here by name.
  -- [R12 FIX 2026-08-04 -- confirming round, Codex CXR3] AND ALL FOUR ARE READ FROM THE LEXED BODY,
  -- BECAUSE MEASURING PROVED THE RAW ONE STILL REFUSED A LAWFUL HOTFIX. The first cut of this
  -- wave left this claim on the raw functiondef and argued it could only ever be too STRICT.
  -- True -- and too strict is still a REFUSED CORRECT DEPLOY, which is the finding: the planted
  -- hotfix carries `$msg$... clara._adj_on_approve(p_entry) ...$msg$` ABOVE the FA hook, so on
  -- raw text position(adj) < position(fa) and 0045 died here instead of at the prestate. The
  -- false refusal had not been removed, only moved one screen down.
  -- THE FOURTH ANCHOR DROPS ITS STRING for the same reason: `'settlement_allocation'` is a
  -- literal and the lexer blanks it, so the anchor is the ASSIGNMENT that reads it --
  -- `v_prop := e.flags ->`, which is executable code, occurs exactly once, and is the same line.
  -- The positions are comparable across the two texts only because the stripper BLANKS rather
  -- than deletes: prosrc and its lexed copy have identical offsets, which is the invariant probe
  -- 11 and the prestate above both assert on every run.
  -- [R13 FIX 2026-08-04 -- re-confirming round, Codex RC4] AND THE THREE HOOK POSITIONS COME FROM THE
  -- SHARED MATCHER, not from three exact substrings. This claim was the LAST of the four
  -- instruments round 12 repaired and it was repaired to the lexed body but NOT to one spelling:
  -- a hook re-spliced in named notation would have read position 0 here and been reported as
  -- "not ordered" rather than as what it is. The fourth anchor stays a plain position because it
  -- is not a call: `'settlement_allocation'` is a literal the lexer blanks, so the anchor is the
  -- ASSIGNMENT that reads it, which is executable code and occurs exactly once.
  v_pfa  := pg_temp._wdb_call_pos(v_exe, 'clara._fa_on_approve');
  v_padj := pg_temp._wdb_call_pos(v_exe, 'clara._adj_on_approve');
  v_padv := pg_temp._wdb_call_pos(v_exe, 'clara._adv_on_approve');
  v_pset := position($p$v_prop := e.flags ->$p$ in v_exe);
  if not (v_pfa > 0 and v_padj > 0 and v_padv > 0 and v_pset > 0
          and v_pfa < v_padj and v_padj < v_padv and v_padv < v_pset) then
    raise exception '0042 S5.8-b2 postcheck: the D-b hooks are not ordered FA -> adjustment -> advance ABOVE the settlement early-return (fa=%, adj=%, adv=%, settlement early-return=%; 0 means not found) -- one of them is dead code for every non-settlement entry', v_pfa, v_padj, v_padv, v_pset
      using errcode = 'CLR10';
  end if;
  if (select p.proowner::regrole::text from pg_proc p where p.oid = v_sig::regprocedure)
     <> 'clara_fn_owner' then
    raise exception '0042 S5.8-b2 postcheck: _subledger_on_approve changed owner' using errcode = 'CLR10';
  end if;
  raise notice '0042 S5.8-b2 OK: the recurring-adjustment hook is spliced between the FA hook and D-b1''s staff-advance hook, above the settlement early-return; the whole unit''s eight-marker census and its four-anchor ordering claim are now both true of the live body.';
end $s5_8_b2$;

reset role;


-- =====================================================================================
-- [SPLIT D-b2 2026-08-04] S5.9 STANDS HERE IN THE WHOLE UNIT AND HAS NO D-b2 FORM. Both of its
-- independent replacements on clara.reverse_entry are already in place: the mirror's DATE
-- (clara._wdb_correction_posting_date) shipped as D-b0's S5.9-b0 under errata E1, and the D-b
-- reversal WALL (clara._wdb_reversal_blocked) with its ordering postcheck shipped as D-b1's
-- S5.9-b1. MEASURED on this slice's rig before this file was written, not inferred from the
-- errata: clara._wdb_correction_posting_date(p_entry, appears once, clara._wdb_reversal_blocked
-- (p_entry) appears once, Asia/Kuala_Lumpur still appears once and current_date still appears
-- zero times. Tail 3(2) below re-asserts the whole ordering claim on the live body.
-- =====================================================================================

-- =====================================================================================
-- S5.10 -- clara.revise_entry: THE THREE D-b PROPOSAL KEYS + THE PAIR-DRAFT LOCK
-- (design SS2.6, ABI SSB / SSF).
--
-- SAME LAW AS 0041's FA ARM, A SEPARATE TOKEN BY DESIGN (ABI SSB is explicit: "the FA arm
-- keeps its live fa_proposal_not_revisable"). This function rewrites an entry's LINES
-- wholesale and carries no concept of flags, so an edited occurrence, staff-advance
-- application or accepted bank-rule suggestion would reach the approve-time hook with legs
-- that contradict the proposal the hook is about to materialise -- and the hook's own
-- freshness check would then refuse it confusingly rather than this editor refusing it
-- honestly. Two tokens, not one merged token, because the two remedies name different verbs.
--
-- THE PAIR-DRAFT LOCK is a different mechanism with the same shape: the pair receipt IS the
-- authorization channel (design SS2.4). While it is pending or approving, the two correction
-- drafts it names are frozen -- clara.approve_pair_reversal re-derives both BYTE-EXACTLY
-- against the halves they correct, so an edited correction would either fail that
-- re-derivation with an opaque message or, worse, be approved through a path that never
-- re-read it. Remedy named: cancel_pair_reversal, which withdraws both halves atomically.
-- =====================================================================================
-- [SPLIT D-b2 2026-08-04] S5.10 AND S5.10a MOVE WHOLE -- NOT ONE LINE OF EITHER IS EDITED, and the
-- prestate they were written against still holds. Census sect.2 Class E names the edge
-- (clara.revise_entry -> clara.adjustment_pair_reversals) and sect.3's verdict is "NOT PURE --
-- D-b2 table + D-b3 flags key ... -> D-b2". Both halves of that verdict are satisfied HERE and
-- only here: SECTION S1 of this file creates clara.adjustment_pair_reversals, and D-b3 already
-- shipped the bank_rule_suggested producer whose flags key the three-flags refusal enumerates.
-- SPLITTING THE BLOCK A THIRD TIME WAS REFUSED ONE SLICE AGO AND IS NOT RE-OPENED (errata E7):
-- its three flags keys, its pair refusal and its ordering are ONE replacement, and E7 measured
-- the interim gap it leaves (between D-b1 and this slice a maker CAN revise a draft carrying the
-- staff_advance_application key -- and the approve is then refused CLR40
-- advance_application_missing by clara._adv_assert_proposal, the ONE authoritative guard, with
-- zero register rows born). That gap closes at this block.
-- MEASURED ON THIS SLICE'S RIG BEFORE THE BLOCK WAS PLACED: clara.revise_entry carries all NINE
-- of S5.10's prestate markers at their canonical counts and carries neither
-- {"reason":"proposal_not_revisable"} nor pair_draft_locked -- i.e. D-b0, D-b1 and D-b3 left this
-- body exactly as 0041 did, so the canonical prestate census is the correct prestate. Same for
-- clara.withdraw_draft at S5.11 below (six markers at their canonical counts, pair_draft_locked
-- at zero).
-- =====================================================================================
set role clara_fn_owner;

do $s5_10$
declare
  v_sig text := 'clara.revise_entry(uuid,jsonb,jsonb,jsonb,uuid,text,jsonb,jsonb)';
  v_def text; v_frm text; v_cnt int; v_n int; r record;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p where p.oid = v_sig::regprocedure;
  if v_def is null then
    raise exception '0042 S5.10 prestate: clara.revise_entry is GONE' using errcode = 'CLR10';
  end if;
  -- The idempotency probe uses the FULL detail literal: 'proposal_not_revisable' is a
  -- substring of 0041's 'fa_proposal_not_revisable', so a bare name probe would report this
  -- splice as already applied on every database 0041 touched.
  if position('{"reason":"proposal_not_revisable"}' in v_def) <> 0 then
    raise exception '0042 S5.10 prestate: revise_entry already refuses D-b proposal drafts -- this splice has already been applied to this database'
      using errcode = 'CLR10';
  end if;
  -- THE NINE-MARKER CENSUS: 0041 S4.7's eight (0017 R1-F1 + the 0028 binding regions +
  -- 0037 H.2b + 0038's closing-transfer wrapper) re-measured against the live body, PLUS
  -- 0041's own splice marker.
  for r in select * from (values
      ('opening_entry_k_family_only', 1),
      ('reversal_mirror_not_revisable', 1),
      ('closing_transfer', 7),
      ('vendor_binding_resolutions', 1),
      ('amount_exception', 2),
      ('duplicate_override', 8),
      ('journal_entry_revisions', 2),
      ('_validate_entry_lines', 1),
      ('fa_proposal_not_revisable', 1)) as t(marker, want) loop
    v_n := (length(v_def) - length(replace(v_def, r.marker, ''))) / length(r.marker);
    if v_n <> r.want then
      raise exception '0042 S5.10 prestate: revise_entry carries the marker "%" % time(s), expected % -- the body drifted or lost a prior splice', r.marker, v_n, r.want
        using errcode = 'CLR10';
    end if;
  end loop;

  v_frm := $f$  if (coalesce(e.flags,'{}'::jsonb) ? 'depreciation_charges')
     or (coalesce(e.flags,'{}'::jsonb) ? 'fa_disposal') then
    raise exception 'this draft carries a fixed-asset proposal and cannot be revised; withdraw it and re-issue the run or the disposal'
      using errcode='CLR10',detail='{"reason":"fa_proposal_not_revisable"}';
  end if;$f$;
  v_cnt := (length(v_def) - length(replace(v_def, v_frm, ''))) / length(v_frm);
  if v_cnt <> 1 then
    raise exception '0042 S5.10 prestate: the 0041 FA proposal refusal appears % time(s) (expected exactly once) -- the body drifted; re-derive this splice', v_cnt
      using errcode = 'CLR10';
  end if;
  v_def := replace(v_def, v_frm,
    $t$  if (coalesce(e.flags,'{}'::jsonb) ? 'depreciation_charges')
     or (coalesce(e.flags,'{}'::jsonb) ? 'fa_disposal') then
    raise exception 'this draft carries a fixed-asset proposal and cannot be revised; withdraw it and re-issue the run or the disposal'
      using errcode='CLR10',detail='{"reason":"fa_proposal_not_revisable"}';
  end if;
  -- 0042 (Wave D-b, design SS2.6; ABI SSB): THE THREE D-b PROPOSAL KEYS. Same law as the
  -- fixed-asset arm above, under its own token because the remedies name different verbs:
  -- withdraw and re-run the occurrence, re-book the staff-advance application, or re-accept
  -- the bank-rule suggestion. This function rewrites the LINES wholesale and knows nothing
  -- about flags, so an edited proposal-bearing draft reaches the approve-time hook with legs
  -- that contradict the proposal the hook is about to materialise.
  if (coalesce(e.flags,'{}'::jsonb) ? 'recurring_adjustment')
     or (coalesce(e.flags,'{}'::jsonb) ? 'staff_advance_application')
     or (coalesce(e.flags,'{}'::jsonb) ? 'bank_rule_suggested') then
    raise exception 'this draft carries a Wave D-b proposal and cannot be revised; withdraw it and re-issue it through the verb that owns its arithmetic'
      using errcode='CLR10',detail='{"reason":"proposal_not_revisable"}';
  end if;
  -- 0042 (design SS2.4): A PAIR-CORRECTION DRAFT IS OWNED BY ITS RECEIPT. The receipt is the
  -- authorization channel for both halves; while it is pending or approving they are frozen,
  -- because the approving verb re-derives both corrections BYTE-EXACTLY against the halves
  -- they correct. An edited correction would either fail that re-derivation with an opaque
  -- message or be approved through a path that never re-read it. Remedy named: cancel the
  -- pair reversal, which withdraws both halves in one transaction.
  if exists (select 1 from clara.adjustment_pair_reversals pr
             where pr.status in ('pending','approving')
               and p_entry in (pr.occurrence_correction_id, pr.mirror_correction_id)) then
    raise exception 'this draft is one half of an outstanding auto-reversal pair correction; cancel it with cancel_pair_reversal rather than editing it'
      using errcode='CLR39',detail='{"reason":"pair_draft_locked"}';
  end if;$t$);
  execute v_def;

  select pg_get_functiondef(p.oid) into v_def from pg_proc p where p.oid = v_sig::regprocedure;
  for r in select * from (values
      ('{"reason":"proposal_not_revisable"}', 1),
      ('{"reason":"pair_draft_locked"}', 1),
      ('clara.adjustment_pair_reversals', 1),
      ($$? 'recurring_adjustment'$$, 1),
      ($$? 'staff_advance_application'$$, 1),
      ($$? 'bank_rule_suggested'$$, 1),
      ('opening_entry_k_family_only', 1),
      ('reversal_mirror_not_revisable', 1),
      ('closing_transfer', 7),
      ('vendor_binding_resolutions', 1),
      ('amount_exception', 2),
      ('duplicate_override', 8),
      ('journal_entry_revisions', 2),
      ('_validate_entry_lines', 1),
      ('fa_proposal_not_revisable', 1)) as t(marker, want) loop
    v_n := (length(v_def) - length(replace(v_def, r.marker, ''))) / length(r.marker);
    if v_n <> r.want then
      raise exception '0042 S5.10 postcheck: marker "%" is now % (expected %)', r.marker, v_n, r.want
        using errcode = 'CLR10';
    end if;
  end loop;
  if (select p.proowner::regrole::text from pg_proc p where p.oid = v_sig::regprocedure)
     <> 'clara_fn_owner' then
    raise exception '0042 S5.10 postcheck: revise_entry changed owner' using errcode = 'CLR10';
  end if;
  raise notice '0042 S5.10 OK: revise_entry refuses all three D-b proposal keys under proposal_not_revisable and refuses a pair-correction draft under pair_draft_locked; the FA arm keeps its own token and all nine pre-existing markers survived.';
end $s5_10$;

-- =====================================================================================
-- S5.10a -- clara.revise_entry: THE PAIR ARM MUST BE ASKED BEFORE THE 0037 MIRROR ARM.
--
-- FOUND AT INTEGRATION (x42.c7), and it is a real defect, not a token quibble.
-- clara.reverse_adjustment_pair inserts BOTH correction halves with `reversal_of` set --
-- they ARE reversal mirrors, structurally. 0037's `reversal_mirror_not_revisable` arm
-- (`e.reversal_of is not null`, CLR10) sits ABOVE the pair arm S5.10 splices in after the FA
-- arm, so it swallows every pair-correction draft and ABI SSF's row "revise_entry on a pair
-- draft -> CLR39 pair_draft_locked" names a branch that is DEAD CODE on every input that can
-- exist. Measured on the assembled build before this step: of the entries named by
-- adjustment_pair_reversals.{occurrence,mirror}_correction_id, 76 of 76 carry reversal_of.
--
-- The consequence is not cosmetic. The 0037 arm's remedy text is "withdraw the mirror and
-- re-reverse the original" -- and clara.withdraw_draft on a pair half is itself refused
-- CLR39 pair_draft_locked naming cancel_pair_reversal (S5.11, immediately below). Left
-- as-is, the build sends a bookkeeper down a walled corridor: the message they are shown
-- names a remedy that is also refused, and the remedy that WOULD work is never surfaced.
--
-- Done as a SEPARATE re-cut rather than by re-ordering S5.10's own replacement, so S5.10
-- stays the single owner of "which arms exist" and this step owns only "in what order they
-- are asked". The net marker census is unchanged -- {"reason":"pair_draft_locked"} still
-- appears exactly once in the body -- so S5.10's postcheck loop above needed no edit.
-- =====================================================================================

do $s5_10a$
declare
  v_sig text := 'clara.revise_entry(uuid,jsonb,jsonb,jsonb,uuid,text,jsonb,jsonb)';
  v_def text; v_pair text; v_mirror text; v_n int;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p where p.oid = v_sig::regprocedure;

  -- The pair arm exactly as S5.10 emitted it, lifted from its post-FA position.
  v_pair := $p$
  -- 0042 (design SS2.4): A PAIR-CORRECTION DRAFT IS OWNED BY ITS RECEIPT. The receipt is the
  -- authorization channel for both halves; while it is pending or approving they are frozen,
  -- because the approving verb re-derives both corrections BYTE-EXACTLY against the halves
  -- they correct. An edited correction would either fail that re-derivation with an opaque
  -- message or be approved through a path that never re-read it. Remedy named: cancel the
  -- pair reversal, which withdraws both halves in one transaction.
  if exists (select 1 from clara.adjustment_pair_reversals pr
             where pr.status in ('pending','approving')
               and p_entry in (pr.occurrence_correction_id, pr.mirror_correction_id)) then
    raise exception 'this draft is one half of an outstanding auto-reversal pair correction; cancel it with cancel_pair_reversal rather than editing it'
      using errcode='CLR39',detail='{"reason":"pair_draft_locked"}';
  end if;$p$;

  v_mirror := $m$  if e.reversal_of is not null then
    raise exception 'a reversal mirror cannot be revised; withdraw the mirror and re-reverse the original'
      using errcode='CLR10',detail='{"reason":"reversal_mirror_not_revisable"}';
  end if;$m$;

  v_n := (length(v_def) - length(replace(v_def, v_pair, ''))) / length(v_pair);
  if v_n <> 1 then
    raise exception '0042 S5.10a prestate: the S5.10 pair arm appears % time(s), expected exactly 1 -- S5.10 drifted, so this re-order has no subject', v_n
      using errcode = 'CLR10';
  end if;
  v_n := (length(v_def) - length(replace(v_def, v_mirror, ''))) / length(v_mirror);
  if v_n <> 1 then
    raise exception '0042 S5.10a prestate: the 0037 reversal-mirror arm appears % time(s), expected exactly 1 -- re-derive this re-order against the live body', v_n
      using errcode = 'CLR10';
  end if;

  -- (1) lift the pair arm out of its post-FA position; (2) re-seat it ABOVE the mirror arm.
  v_def := replace(v_def, v_pair, '');
  v_def := replace(v_def, v_mirror,
    '  -- 0042 (design SS2.4; ABI SSF): A PAIR-CORRECTION DRAFT IS OWNED BY ITS RECEIPT, and it' || E'\n' ||
    '  -- is asked BEFORE the 0037 reversal-mirror arm below because every pair correction IS a' || E'\n' ||
    '  -- reversal mirror (clara.reverse_adjustment_pair inserts both halves with reversal_of' || E'\n' ||
    '  -- set), so the mirror arm would otherwise swallow this case entirely and ABI SSF''s named' || E'\n' ||
    '  -- token would be dead code on every input that can exist. It also matters to the human:' || E'\n' ||
    '  -- the mirror arm''s remedy is "withdraw the mirror", and clara.withdraw_draft refuses a' || E'\n' ||
    '  -- pair half with this very token -- so the message below would name a remedy that is also' || E'\n' ||
    '  -- refused. The receipt is the authorization channel for both halves; while it is pending' || E'\n' ||
    '  -- or approving they are frozen, because clara.approve_pair_reversal re-derives both' || E'\n' ||
    '  -- corrections BYTE-EXACTLY against the halves they correct. Remedy named:' || E'\n' ||
    '  -- cancel_pair_reversal, which withdraws both halves in one transaction.' || E'\n' ||
    '  if exists (select 1 from clara.adjustment_pair_reversals pr' || E'\n' ||
    '             where pr.status in (''pending'',''approving'')' || E'\n' ||
    '               and p_entry in (pr.occurrence_correction_id, pr.mirror_correction_id)) then' || E'\n' ||
    '    raise exception ''this draft is one half of an outstanding auto-reversal pair correction; cancel it with cancel_pair_reversal rather than editing it''' || E'\n' ||
    '      using errcode=''CLR39'',detail=''{"reason":"pair_draft_locked"}'';' || E'\n' ||
    '  end if;' || E'\n' || v_mirror);
  execute v_def;

  select pg_get_functiondef(p.oid) into v_def from pg_proc p where p.oid = v_sig::regprocedure;
  if position('{"reason":"pair_draft_locked"}' in v_def)
     > position('{"reason":"reversal_mirror_not_revisable"}' in v_def) then
    raise exception '0042 S5.10a postcheck: the pair arm is STILL below the 0037 mirror arm -- every pair-correction draft would refuse with the wrong token and the wrong remedy'
      using errcode = 'CLR10';
  end if;
  v_n := (length(v_def) - length(replace(v_def, '{"reason":"pair_draft_locked"}', '')))
         / length('{"reason":"pair_draft_locked"}');
  if v_n <> 1 then
    raise exception '0042 S5.10a postcheck: pair_draft_locked appears % time(s) in revise_entry, expected exactly 1 -- the lift-and-reseat duplicated or dropped the arm', v_n
      using errcode = 'CLR10';
  end if;
  raise notice '0042 S5.10a OK: revise_entry asks the pair-receipt lock BEFORE the 0037 reversal-mirror arm, so a pair half refuses CLR39 pair_draft_locked and is pointed at cancel_pair_reversal.';
end $s5_10a$;

reset role;

-- =====================================================================================
-- S5.11 -- clara.withdraw_draft: A PAIR-CORRECTION DRAFT CLOSES THROUGH ITS RECEIPT
-- (design SS2.4; ABI SSF -> CLR39 pair_draft_locked, remedy names cancel_pair_reversal).
--
-- Exactly the one-door law 0038 (WCB-R3) wrote into this body for a draft anchoring a
-- PENDING bank-match reservation, applied to the pair machine. A lone withdrawal would leave
-- clara.adjustment_pair_reversals sitting in 'pending' naming a draft that no longer exists
-- -- and that receipt is precisely what the approve-time hook's arm (1) consults to decide
-- whether either half may be approved, so the pair would become both un-completable and
-- un-cancellable. cancel_pair_reversal withdraws BOTH halves inline as the function owner
-- and closes the receipt, in one transaction.
-- =====================================================================================
-- [SPLIT D-b2 2026-08-04] S5.11 MOVES WHOLE -- not one line edited (census sect.3: "NOT PURE -- D-b2
-- -> move whole block to D-b2"; the refusal reads clara.adjustment_pair_reversals, which SECTION
-- S1 of this file creates). Its prestate was re-measured on this slice's rig: all six markers at
-- their canonical counts, pair_draft_locked absent.
-- =====================================================================================
set role clara_fn_owner;

do $s5_11$
declare
  v_sig text := 'clara.withdraw_draft(uuid,text,uuid,text)';
  v_def text; v_frm text; v_cnt int; v_n int; r record;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p where p.oid = v_sig::regprocedure;
  if v_def is null then
    raise exception '0042 S5.11 prestate: clara.withdraw_draft is GONE' using errcode = 'CLR10';
  end if;
  if position('pair_draft_locked' in v_def) <> 0 then
    raise exception '0042 S5.11 prestate: withdraw_draft already refuses a pair-correction draft -- this splice has already been applied to this database'
      using errcode = 'CLR10';
  end if;
  for r in select * from (values
      ('opening_entry_k_family_only', 1),
      ('pending_match_present', 1),
      ('entry.withdrawn', 1),
      ('withdrawal_reason', 1),
      ('match_fingerprint', 1),
      ('stale revision token', 1)) as t(marker, want) loop
    v_n := (length(v_def) - length(replace(v_def, r.marker, ''))) / length(r.marker);
    if v_n <> r.want then
      raise exception '0042 S5.11 prestate: withdraw_draft carries the marker "%" % time(s), expected % -- the body drifted or lost a prior splice', r.marker, v_n, r.want
        using errcode = 'CLR10';
    end if;
  end loop;

  v_frm := $f$  if exists (select 1 from clara.bank_matches bm
      where bm.draft_entry_id = p_entry and bm.status = 'pending') then
    raise exception 'this draft anchors a pending bank-match reservation; cancel via unmatch_bank_match (it withdraws the draft in the same transaction)'
      using errcode='CLR10',
        detail='{"reason":"pending_match_present"}';
  end if;$f$;
  v_cnt := (length(v_def) - length(replace(v_def, v_frm, ''))) / length(v_frm);
  if v_cnt <> 1 then
    raise exception '0042 S5.11 prestate: the 0038 one-door refusal appears % time(s) (expected exactly once) -- the body drifted; re-derive this splice', v_cnt
      using errcode = 'CLR10';
  end if;
  v_def := replace(v_def, v_frm,
    $t$  if exists (select 1 from clara.bank_matches bm
      where bm.draft_entry_id = p_entry and bm.status = 'pending') then
    raise exception 'this draft anchors a pending bank-match reservation; cancel via unmatch_bank_match (it withdraws the draft in the same transaction)'
      using errcode='CLR10',
        detail='{"reason":"pending_match_present"}';
  end if;
  -- 0042 (Wave D-b, design SS2.4): THE SAME ONE-DOOR LAW FOR THE PAIR MACHINE. A correction
  -- draft named by an outstanding pair receipt is cancelled through cancel_pair_reversal --
  -- which withdraws BOTH halves and closes the receipt atomically -- never alone. A lone
  -- withdrawal would strand the receipt in 'pending' naming a draft that no longer exists,
  -- and that receipt is exactly what the approve-time hook consults before letting either
  -- half be approved: the pair would become neither completable nor cancellable.
  if exists (select 1 from clara.adjustment_pair_reversals pr
             where pr.status in ('pending','approving')
               and p_entry in (pr.occurrence_correction_id, pr.mirror_correction_id)) then
    raise exception 'this draft is one half of an outstanding auto-reversal pair correction; cancel it with cancel_pair_reversal (it withdraws both halves in the same transaction)'
      using errcode='CLR39',
        detail='{"reason":"pair_draft_locked"}';
  end if;$t$);
  execute v_def;

  select pg_get_functiondef(p.oid) into v_def from pg_proc p where p.oid = v_sig::regprocedure;
  for r in select * from (values
      ('{"reason":"pair_draft_locked"}', 1),
      ('clara.adjustment_pair_reversals', 1),
      ('cancel_pair_reversal', 2),
      ('opening_entry_k_family_only', 1),
      ('pending_match_present', 1),
      ('entry.withdrawn', 1),
      ('withdrawal_reason', 1),
      ('match_fingerprint', 1),
      ('stale revision token', 1)) as t(marker, want) loop
    v_n := (length(v_def) - length(replace(v_def, r.marker, ''))) / length(r.marker);
    if v_n <> r.want then
      raise exception '0042 S5.11 postcheck: marker "%" is now % (expected %)', r.marker, v_n, r.want
        using errcode = 'CLR10';
    end if;
  end loop;
  -- ORDERED, BOTH-PRESENT: the pair refusal sits after the bank one-door refusal and before
  -- the withdrawal UPDATE, so it fires after every cheaper wall and before anything is written.
  if not (position('pending_match_present' in v_def) > 0
          and position('{"reason":"pair_draft_locked"}' in v_def) > 0
          and position($p$update clara.journal_entries set status='withdrawn'$p$ in v_def) > 0
          and position('pending_match_present' in v_def)
              < position('{"reason":"pair_draft_locked"}' in v_def)
          and position('{"reason":"pair_draft_locked"}' in v_def)
              < position($p$update clara.journal_entries set status='withdrawn'$p$ in v_def)) then
    raise exception '0042 S5.11 postcheck: the pair refusal is not between the bank one-door wall and the withdrawal UPDATE'
      using errcode = 'CLR10';
  end if;
  if (select p.proowner::regrole::text from pg_proc p where p.oid = v_sig::regprocedure)
     <> 'clara_fn_owner' then
    raise exception '0042 S5.11 postcheck: withdraw_draft changed owner' using errcode = 'CLR10';
  end if;
  raise notice '0042 S5.11 OK: withdraw_draft refuses a pair-correction draft by name and points at cancel_pair_reversal; all six pre-existing markers survived.';
end $s5_11$;

reset role;

-- =====================================================================================
-- S5.12 -- clara.set_client_fy_end: THE CLIENT RUNG + THE ANNUAL-CADENCE GUARD
-- (design SS2.2).
--
-- WHAT IT CLOSES. An ANNUAL cadence derives its period window from THIS client's financial-
-- year end. Moving the year end while an annual machine is live silently redefines every
-- period that machine has already met and every one it is about to run: a receipt naming
-- FY2026 would no longer describe the window the oracle computes, the unmet-period question
-- would answer about a window nobody ran, and a re-run would post a second charge into a
-- period the books already report. The verb had no guard at all and took no lock.
--
-- MONTHLY CADENCES DO NOT BLOCK, DELIBERATELY. A monthly period is a calendar month and is
-- wholly FY-independent -- and the sandbox's live monthly depreciation authority is the
-- design's own named cell for this. Refusing on a monthly cadence would make the guard
-- unfollowable on the one client that has one.
--
-- THE RUNG IS THE SAME 203005004 the poster, the disposal verb, the revise door and the
-- enrolment doors take, so an FY-end change and a concurrent run are serialised rather than
-- racing; taken here it is also what makes the two reads below a decision rather than a
-- snapshot. Token per assembly adjudication S5-A3 (additive, named deviation).
-- =====================================================================================
-- [SPLIT D-b2 2026-08-04] THIS SLICE SHIPS THE clara.adjustment_templates CADENCE ARM; THE RUNG AND
-- THE DEPRECIATION-AUTHORITY ARM ARE ALREADY IN PLACE. Binding errata E6: census sect.2 Class E
-- named ONE violating edge on this block (set_client_fy_end -> clara.adjustment_templates) and
-- sect.3 recorded it as "separable: rung -> D-b0, cadence guard -> D-b2". D-b0's first cut
-- deferred the WHOLE guard on that wording and its own battery measured the cost -- cell x41.f3
-- went red on a claim with no later-slice dependency at all, because
-- clara.fa_depreciation_authorities is a 0041 relation. Adjudicated and corrected there: the
-- authority arm came forward with the rung. THE HEADER ABOVE IS THE WHOLE UNIT'S AND IS KEPT
-- VERBATIM, because with this block it becomes true of the live body -- both arms, under the one
-- rung, both cadence-discriminated.
-- WHAT THIS BLOCK MAKES, AND WHY EACH PIECE IS SHAPED THE WAY IT IS:
--   * THE IDEMPOTENCY PROBE KEYS ON clara.adjustment_templates, NOT ON THE TOKEN. The token
--     fy_end_locked_by_annual_cadence is minted ONCE by D-b0 and a SECOND time here, so a probe
--     keyed on it would read D-b0's lawful work as a duplicate apply -- D-b0's own split note
--     says so and defers the keying to this block. The relation name is the thing this arm adds
--     and nothing else in the body can carry it.
--   * (a) COMPLETES THE DECLARATION. D-b0 added v_blocked_id (shared by both arms) and
--     deliberately did NOT add v_blocked_name, which only the TEMPLATE arm's raise reads -- a
--     local declared for a body that is not shipped is a dangling edit. This block adds it, and
--     the resulting declaration line is the whole unit's, character for character.
--   * (b) SPLICES THE TEMPLATE ARM **ABOVE** THE AUTHORITY ARM, anchored on the authority arm's
--     own first two lines. The order matters to the human, not to the machine: a client with
--     both a live annual template and a live annual authority is told about the template first,
--     which is the whole unit's order and the one the postcheck asserts.
--   * THE POSTCHECK IS THE WHOLE UNIT'S, BYTE-EXACT (token x2, clara.adjustment_templates x1,
--     clara.fa_depreciation_authorities x1, `cadence = 'annual'` x2, both guards ordered under
--     the rung and above the UPDATE). D-b0's narrowed form asserted the D-b2 half ABSENT and
--     carried a FORWARD TOLERANCE note naming exactly these counts; this is that final form.
-- FINAL FORM: this is it.
-- =====================================================================================
set role clara_fn_owner;

do $s5_12_b2$
declare
  v_sig text := 'clara.set_client_fy_end(uuid,integer,integer,text)';
  v_def text; v_frm text; v_cnt int; v_n int; r record;
begin
  select pg_get_functiondef(p.oid) into v_def from pg_proc p where p.oid = v_sig::regprocedure;
  if v_def is null then
    raise exception '0042 S5.12-b2 prestate: clara.set_client_fy_end is GONE' using errcode = 'CLR10';
  end if;
  if position('clara.adjustment_templates' in v_def) <> 0 then
    raise exception '0042 S5.12-b2 prestate: set_client_fy_end already reads clara.adjustment_templates -- this splice has already been applied to this database'
      using errcode = 'CLR10';
  end if;
  -- THE PRESTATE CENSUS, ON THE BODY AS D-b0 LEFT IT. Every count harvested with
  -- pg_get_functiondef from a rig with 0042+0043+0044 applied. The rung is present (D-b0 added
  -- it), the authority arm is present, the token stands at ONE, and v_blocked_name is absent --
  -- which is exactly what makes this block refuse to run on a database that never got D-b0's
  -- half, and refuse to run twice on one that already has this one.
  for r in select * from (values
      ('pg_advisory_xact_lock(203005004', 1),
      ('clara.fa_depreciation_authorities', 1),
      ('fy_end_locked_by_annual_cadence', 1),
      ('v_blocked_id uuid;', 1),
      ('v_blocked_name', 0),
      ('fa_particulars_invalid', 1),
      ('fy_end_month', 2),
      ('clara._audit', 1),
      ('clara._finish_op', 1)) as t(marker, want) loop
    v_n := (length(v_def) - length(replace(v_def, r.marker, ''))) / length(r.marker);
    if v_n <> r.want then
      raise exception '0042 S5.12-b2 prestate: set_client_fy_end carries the marker "%" % time(s), expected % -- the body drifted, or D-b0''s rung-and-authority half was never applied', r.marker, v_n, r.want
        using errcode = 'CLR10';
    end if;
  end loop;

  -- (a) THE DECLARATION gains the TEMPLATE arm's own local, completing the whole unit's line.
  v_frm := $f$declare c record; v_dedupe jsonb; v_firm uuid; v_blocked_id uuid;$f$;
  v_cnt := (length(v_def) - length(replace(v_def, v_frm, ''))) / length(v_frm);
  if v_cnt <> 1 then
    raise exception '0042 S5.12-b2 prestate (a): the D-b0 declaration line appears % time(s) (expected exactly once)', v_cnt
      using errcode = 'CLR10';
  end if;
  v_def := replace(v_def, v_frm,
    $t$declare c record; v_dedupe jsonb; v_firm uuid; v_blocked_id uuid; v_blocked_name text;$t$);

  -- (b) THE TEMPLATE ARM, ABOVE THE AUTHORITY ARM, anchored on that arm's own opening. The arm
  -- text below is byte-exact from the canonical S5.12 (0042-sections/s5-residuals.sql
  -- L1557-1566); nothing about it was re-derived.
  v_frm := $f$  select au.id into v_blocked_id
    from clara.fa_depreciation_authorities au$f$;
  v_cnt := (length(v_def) - length(replace(v_def, v_frm, ''))) / length(v_frm);
  if v_cnt <> 1 then
    raise exception '0042 S5.12-b2 prestate (b): D-b0''s depreciation-authority arm appears % time(s) (expected exactly once) -- the body drifted; re-derive this splice', v_cnt
      using errcode = 'CLR10';
  end if;
  v_def := replace(v_def, v_frm,
    $t$  select t.id, t.name into v_blocked_id, v_blocked_name
    from clara.adjustment_templates t
    where t.client_id = p_client and t.status = 'live' and t.cadence = 'annual'
    order by t.created_at, t.id limit 1;
  if v_blocked_id is not null then
    raise exception 'this client has a live ANNUAL-cadence adjustment template (%); retire it before moving the financial-year end, then propose and sign it again against the new one', v_blocked_name
      using errcode = 'CLR38',
        detail = jsonb_build_object('reason', 'fy_end_locked_by_annual_cadence',
          'axis', 'adjustment_template', 'template_id', v_blocked_id)::text;
  end if;
  select au.id into v_blocked_id
    from clara.fa_depreciation_authorities au$t$);
  execute v_def;

  -- [SPLIT D-b2 2026-08-04] FROM HERE THE POSTCHECK IS THE WHOLE UNIT'S, BYTE-EXACT: this slice is
  -- last, so the whole unit's counts and its two-guard ordering claim ARE the final form.
  select pg_get_functiondef(p.oid) into v_def from pg_proc p where p.oid = v_sig::regprocedure;
  for r in select * from (values
      ('fy_end_locked_by_annual_cadence', 2),
      ('clara.adjustment_templates', 1),
      ('clara.fa_depreciation_authorities', 1),
      ('pg_advisory_xact_lock(203005004', 1),
      ('v_blocked_id uuid; v_blocked_name text;', 1),
      ('fa_particulars_invalid', 1),
      ('fy_end_month', 2),
      ('clara._audit', 1),
      ('clara._finish_op', 1)) as t(marker, want) loop
    v_n := (length(v_def) - length(replace(v_def, r.marker, ''))) / length(r.marker);
    if v_n <> r.want then
      raise exception '0042 S5.12 postcheck: marker "%" is now % (expected %)', r.marker, v_n, r.want
        using errcode = 'CLR10';
    end if;
  end loop;
  -- ORDERED, ALL-PRESENT: the rung precedes both guard reads, and both precede the UPDATE.
  if not (position('pg_advisory_xact_lock(203005004' in v_def) > 0
          and position('clara.adjustment_templates' in v_def) > 0
          and position('clara.fa_depreciation_authorities' in v_def) > 0
          and position('update clara.clients set fy_end_month' in v_def) > 0
          and position('pg_advisory_xact_lock(203005004' in v_def)
              < position('clara.adjustment_templates' in v_def)
          and position('clara.adjustment_templates' in v_def)
              < position('clara.fa_depreciation_authorities' in v_def)
          and position('clara.fa_depreciation_authorities' in v_def)
              < position('update clara.clients set fy_end_month' in v_def)) then
    raise exception '0042 S5.12 postcheck: the client rung does not precede both cadence guards, or a guard does not precede the FY-end UPDATE'
      using errcode = 'CLR10';
  end if;
  -- THE MONTHLY CARVE-OUT IS STRUCTURAL, NOT INCIDENTAL: both guards must filter on the
  -- annual cadence literally, or a monthly machine would block a lawful FY-end change.
  if (length(v_def) - length(replace(v_def, $p$cadence = 'annual'$p$, '')))
     / length($p$cadence = 'annual'$p$) <> 2 then
    raise exception '0042 S5.12 postcheck: the two cadence guards do not both filter on the annual cadence -- a monthly machine would block the FY-end change'
      using errcode = 'CLR10';
  end if;
  if (select p.proowner::regrole::text from pg_proc p where p.oid = v_sig::regprocedure)
     <> 'clara_fn_owner' then
    raise exception '0042 S5.12 postcheck: set_client_fy_end changed owner' using errcode = 'CLR10';
  end if;
  raise notice '0042 S5.12-b2 OK: set_client_fy_end now refuses while a live ANNUAL-cadence adjustment TEMPLATE or depreciation AUTHORITY exists, both under D-b0''s 203005004 client rung and above the FY-end UPDATE; monthly cadences do not block.';
end $s5_12_b2$;
reset role;


-- #####################################################################################
-- ############################## TAIL -- THE CENSUS BLOCKS ############################
-- #####################################################################################
-- 0042 section 6 (design SS8's tail list, twenty blocks + the final notice). Each block is
-- INDEPENDENT: one named invariant, one remedy in the raise text, no shared state -- so a
-- reader greps for the property, not for a variable. Every count is EXACT where the design
-- states an exact number, and a lower bound ONLY where the design's own words admit a range
-- (each such place says so, and names what x42 asserts instead).
--
-- WHAT A TAIL IS FOR. Sections S1-S5 above are the migration's INTENT; these blocks are the
-- migration's SELF-VERIFICATION against the world it actually leaves behind. They read the
-- LIVE catalog (pg_proc.prosrc, pg_trigger, pg_policies, pg_index, information_schema) -- never
-- this file's own text -- so a splice that silently missed, a body a later section rebuilt, a
-- belt that was created but not deferred, or a grant that leaked cannot ship. A violated tail
-- aborts the whole transaction: 0042 either applies in full or not at all.
--
-- TWO HOUSE RULES THIS FILE FOLLOWS EXACTLY:
--   (1) BODY TEXT IS READ WIDENED [round-8 M2, revising the original "prosrc alone" rule below
--       -- read as history, not as the current instrument]. Round 7's lens (S5.15e) measured
--       that a PG14+ standard-body function (`language sql ... begin atomic`) stores its body
--       in prosqlbody and leaves prosrc the EMPTY STRING, not NULL -- so a census keyed on
--       prosrc alone reads such a function as bodiless and any pattern inside it evades every
--       predicate below. Every census in this file now reads
--       `coalesce(p.prosrc,'') || coalesce(pg_get_functiondef(p.oid),'')` (an EXISTENCE-safe
--       instrument: matching either representation is enough, and pg_get_functiondef embeds
--       prosrc verbatim for an ordinary plpgsql body, so concatenation changes no verdict for
--       today's 587/587 non-prosqlbody clara functions) OR, where a predicate COUNTS how many
--       times a token occurs INSIDE one already-fetched function body (a length()-difference
--       occurrence count, never a count(*) over many functions), the SINGLE-REPRESENTATION
--       form `coalesce(nullif(p.prosrc,''), pg_get_functiondef(p.oid))` -- concatenating both
--       representations would DOUBLE such a count for an ordinary body (the marker then
--       appears once in the prosrc half and once again inside the embedded copy in the
--       pg_get_functiondef half), which is a measured false failure, not a caught defect;
--       picking exactly one representation is immune to it and changes no value today either.
--       ONE NAMED EXCEPTION remains prosrc-only, adjudicated and commented at its own site
--       (TAIL 19's ACL-combined write-detector): the scripts/check-wiki-dynamic-sql.mjs gate
--       classifies any `do` block that BOTH calls pg_get_functiondef AND carries a bare
--       `execute` token ANYWHERE in the block (quote-blind) as a change-of-record patch, and
--       TAIL 19 shares its block with an ACL `privilege_type = 'EXECUTE'` literal -- MEASURED
--       to break the gate on a false positive if widened in place, and this file's own rule
--       (5) above ("each block is INDEPENDENT ... no shared state") rules out the cross-block
--       bridge that would be needed to widen it safely. TAIL 7 stays prosrc-free for the
--       identical reason, unchanged from round 7.
--   (2) EVERY DETECTOR IS MEASURED BEFORE IT IS TRUSTED. A census that asserts an EMPTY answer
--       is indistinguishable from a pattern that has quietly stopped matching anything -- the
--       absence-from-the-wrong-instrument mistake this repo has paid for three times. Every
--       regex census below therefore carries a positive/negative control on literal strings
--       immediately above it.
--
-- CITATIONS: [WDB-Gn] = design SS1 rulings; SSn = wave-d-b-design.md; ABI SSx =
-- wave-d-b-design-abi.md; [Ln/row] = the eight-round ladder record (part2/part3).
-- [SPLIT D-b2 2026-08-04] FOURTEEN OF THE TWENTY-ONE TAIL BLOCKS LAND HERE, AND THIRTEEN OF THEM ARE
-- BYTE-EXACT CANONICAL. That is not a shortcut; it is the consequence of shipping LAST.
--
-- Census sect.5 splits the tails by subject. A tail whose subject is a CLOSED SET ships pure,
-- per-slice; a tail that ENUMERATES A ROSTER SPANNING FAMILIES ships per-slice with a
-- slice-local roster and an explicit `-- FORWARD TOLERANCE:` note naming the final form -- "and
-- the FINAL form lands in D-b2". Every one of the other three slices had to write such a note.
-- THIS SLICE IS THE FINAL FORM: once this file applies, the database is the database the whole
-- unit describes, so the whole unit's roster IS the post-D-b2 truth and the faithful extraction
-- of it is THE CANONICAL TEXT rather than an authored narrowing. Copying the canonical block is
-- therefore both the least-authored option and the strongest one, and it is what this file does.
--
-- WHAT LANDS HERE, and why:
--   * PURE D-b2 (census sect.5): tails 2 (the origin='scheduled_run' writer census -- its final
--     three-name membership is only true once the occurrence poster and the mirror INSERT
--     exist), 12 (the K-boundary vacuity probe), 15 (the pair receipt's flip-before-approve and
--     the deferred trigger's re-query-by-id), 17 (the ramp-reset predicate over BOTH correction
--     lanes) and 18 (the two hot-loop partial indexes SS1.9 creates).
--   * FINAL FORMS of the roster tails (census sect.5's list): 1 (the approve-path / hook-caller
--     censuses and the bounded-recursion proof -- D-b0 asserted the four approve paths and the
--     FA hook only, D-b1 added the advance hook, and only NOW are both D-b hooks callable, so
--     (c) and (d) become assertable for the first time), 3 (the positional splice census / CoR
--     register), 6, 7, 8, 9 and 20.
--   * TAIL 10, WHOLE. Census sect.5 splits it 4/3 and D-b1 shipped its four rows; the remaining
--     three are this slice's. It is shipped as the CANONICAL SEVEN-ROW LOOP rather than as an
--     authored three-row narrowing, for two reasons: all seven relations exist by the time this
--     file runs, so the canonical block is correct as written; and re-asserting D-b1's four is a
--     REGRESSION FLOOR, which is exactly the rule census sect.6 states for the per-slice upgrade
--     drills ("each slice's drill inherits the prior slices' assertions as a regression floor").
--   * TAIL 14, WHOLE -- AND IT IS A CENSUS GAP THIS SLICE HAD TO CATCH. Sect.5's table assigns
--     tail 14 to "D-b2 + D-b3, split by event name" and D-b3's file map carries "14(D-b3 half)",
--     but sect.8's D-b2 bullet list OMITS tail 14 entirely. Shipped here in its whole-unit form,
--     because by now BOTH event names are registered and both emitters exist -- so the two-name
--     block is simply true. Recorded as errata E20; the alternative was to ship no tail 14 half
--     at all and leave the adjustment.posted emitter unasserted for good.
--   * A D-b2 FINAL NOTICE, authored, because the canonical one enumerates the whole unit.
--
-- WHAT IS NOT HERE, each already shipped with its family: tails 4, 5, 11 and 13 (D-b3's parked
-- declaration, the 0040 S4.Z pins, the bank_matches writer census and the settled-authority
-- belt), tail 16 (D-b0's cost_cents post-state) and tails 19 and 21 (D-b1's ea1955
-- migration-written-only census and its two entry_id indexes).
--
-- ROLE SCOPING: the canonical tail section takes no role at all -- every block below reads the
-- catalog as the plain migration role -- so this file opens and closes no scope and the
-- assembler's per-file balance assertion passes on 0/0.

-- =====================================================================================
-- TAIL 1 -- THE APPROVE-PATH CENSUS (FOUR), THE HOOK-CALLER CENSUS (FOUR) AND THE BOUNDED
-- RECURSION PROOF (design SS8 tail 1; the round-3 fold [L3/V1+V2] that made every D-b
-- approval route through clara._approve_entry_core).
--
-- WHY THREE CLAIMS IN ONE BLOCK. They are one property seen from three sides. D-b adds two
-- new materialisation hooks and an auto-reversal that APPROVES A SECOND ENTRY from inside an
-- approving transaction. The round-2 design had the mirror flip write the approval itself,
-- which would have made a FIFTH approve path and a FIFTH hook caller; round 3 routed it
-- through the core instead. If either census moves, that routing decision was silently
-- undone -- and with it CLR05 maker-checker on the mirror.
--
-- THE TWO INSTRUMENTS ARE DELIBERATELY DIFFERENT. (a) counts the bodies that WRITE the
-- approved status; (b) counts the bodies that CALL the hook. Same four names, measured two
-- ways: a body that approves without calling the hook (a materialisation hole) and a body
-- that calls the hook without approving (a phantom materialisation) are both caught, and
-- neither is visible to the other instrument alone.
-- =====================================================================================
do $tail1$
declare
  v_n int; v_names text; v_expect text := '_approve_entry_core, _approve_opening_entry, approve_wrong_client_correction, reverse_entry';
  v_adj text; v_adv text; v_sub text;
  -- [R14 FIX 2026-08-04] the CODE copies of the two hook bodies. v_adj/v_adv stay the comment-stripped
  -- text because (d)'s other assertions are about string CONTENT; these two are for the CALL
  -- questions, which may not be asked on text a comment can move.
  v_adjx text; v_advx text;
  v_a int; v_b int; v_c int; v_d int;
  r record;
begin
  -- (a) THE APPROVE-PATH CENSUS. The detector is whitespace-tolerant and recognises the BARE
  -- form too: every clara body runs `set search_path = clara`, so `update journal_entries set
  -- status='approved'` writes clara.journal_entries exactly as the qualified form does, and a
  -- census keyed on the qualified text alone would be blind to it (the 0041 tail 13(c) H3
  -- lesson, restated for a different table).
  if not ('update clara.journal_entries set status=''approved'',checker_actor=c.actor'
            ~* 'update[[:space:]]+(only[[:space:]]+)?(clara[[:space:]]*\.[[:space:]]*)?journal_entries[[:space:]]+set[[:space:]]+status[[:space:]]*=[[:space:]]*''approved''')
     or not ('update  journal_entries  set  status = ''approved'''
            ~* 'update[[:space:]]+(only[[:space:]]+)?(clara[[:space:]]*\.[[:space:]]*)?journal_entries[[:space:]]+set[[:space:]]+status[[:space:]]*=[[:space:]]*''approved''')
     or ('update clara.journal_entries_history set status=''approved'''
            ~* 'update[[:space:]]+(only[[:space:]]+)?(clara[[:space:]]*\.[[:space:]]*)?journal_entries[[:space:]]+set[[:space:]]+status[[:space:]]*=[[:space:]]*''approved''') then
    raise exception '0042 tail 1(a): the approved-status write detector no longer recognises the bare/whitespaced forms (or now sweeps in a sibling table) -- a census from it would be silence, not evidence';
  end if;
  -- EVERY ORDERED AGGREGATE IN THIS FILE SORTS UNDER `collate "C"`. proname is of type `name`
  -- (C-collated), but string_agg forces a text cast, and under a linguistic database collation
  -- an underscore is not a separator -- `_approve_entry_core` would sort as if it read
  -- `approve_entry_core`. A census that compares a JOINED STRING must therefore pin the
  -- collation, or it green/reds on the deployment's locale rather than on the schema.
  select count(*)::int, string_agg(p.proname::text, ', ' order by p.proname::text collate "C")
    into v_n, v_names
    from pg_proc p
   where p.pronamespace = 'clara'::regnamespace and p.prokind = 'f'
     and lower(regexp_replace(regexp_replace(regexp_replace(
           (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
         ~* 'update[[:space:]]+(only[[:space:]]+)?(clara[[:space:]]*\.[[:space:]]*)?journal_entries[[:space:]]+set[[:space:]]+status[[:space:]]*=[[:space:]]*''approved''';
  if v_n <> 4 or v_names <> v_expect then
    raise exception '0042 tail 1(a): the APPROVE PATHS are {%} (% of them) -- expected exactly the pinned four {%}. Wave D-b routes every approval it performs through clara._approve_entry_core (design SS2.4, the [L3/V1+V2] fold): a fifth writer means the mirror flip, a pair-correction approval or an advance posting is approving an entry BEHIND the core, which skips CLR05 maker-checker, the receipt, the events and the subledger hook in one stroke.', v_names, v_n, v_expect;
  end if;

  -- (b) THE HOOK-CALLER CENSUS, at 0041 tail 3's exact instrument (and SECTION 0 probe 10's,
  -- so this is a DELTA against a measured pre-state, not a guess). Same four names as (a).
  -- p.proname <> the target itself [round-8 M2, the S5.15e self-match fix, same class]:
  -- pg_get_functiondef's OWN header line (`CREATE OR REPLACE FUNCTION
  -- clara._subledger_on_approve(...)`) always contains the function's own qualified call
  -- shape verbatim (MEASURED against the live catalog: no space between name and paren), so
  -- widening the source to include it makes _subledger_on_approve self-match its own name --
  -- unguarded, this predicate would read 5 callers (the pinned four plus the hook itself).
  -- Excluding the target restores "who ELSE calls it" without losing prosqlbody coverage.
  -- [R14 FIX 2026-08-04 -- second re-confirming round, N13-1/CXR13-3, DEPLOY-BLOCKER] ON THE SHARED
  -- QUESTION, like SECTION 0's probe 10 it is a delta against. This census and that probe were the
  -- last two judges of "who calls this hook" still reading raw text, and raw text cannot tell a
  -- lawful respelling from a drift: an UPPER-CASE call (identical behaviour) vanished from both,
  -- and a COMMENT naming the hook in an unrelated body was counted by both as a caller. Either
  -- way a correct deploy is refused, which is E37's definition of a blocker.
  select count(*)::int, string_agg(p.proname::text, ', ' order by p.proname::text collate "C")
    into v_n, v_names
    from pg_proc p
   where p.pronamespace = 'clara'::regnamespace
     and p.proname <> '_subledger_on_approve'
     and pg_temp._wdb_call_count(
           pg_temp._wdb_sql_code(coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')),
           'clara._subledger_on_approve') > 0;
  if v_n <> 4 or v_names <> v_expect then
    raise exception '0042 tail 1(b): the callers of clara._subledger_on_approve are {%} (% of them) -- expected exactly the pinned four {%}, unchanged by this migration (the 0037:3779-3846 census, re-pinned by 0041 and again here)', v_names, v_n, v_expect;
  end if;

  -- (c) BOTH D-b HOOKS ARE CALLED FROM THE ONE PLACE, IN THE ONE ORDER. _adj_on_approve mints
  -- the auto-reversal mirror; _adv_on_approve reads the entry's legs. Calling either from a
  -- second site would materialise a proposal twice.
  -- COMMENT-STRIPPED, throughout (c) and (d). A splice comment that names the very call it sits
  -- above is good practice and would inflate every count below on raw source -- a tail that
  -- refuses correct code because the author explained it is a tail nobody keeps.
  -- [R12 FIX 2026-08-04 -- confirming round, Codex CXR3] ...AND IN (c) THE STRIPPING IS LEXICAL, on the
  -- same shared body SECTION 0's probe 11 and S5.8-b2's prestate use. Comments were never the
  -- whole story: a hotfix that names the hook inside a dollar-quoted MESSAGE inflates this count
  -- exactly as a comment did, and this tail was the THIRD site to refuse a lawful deploy for it.
  -- It was found by RUNNING the control end to end, not by reading the two sites the finding
  -- named -- which is why the control is this fix's acceptance criterion and not its argument.
  -- (d) BELOW IS DELIBERATELY LEFT ON THE COMMENT-ONLY INSTRUMENT, and that is not an oversight.
  -- (c) COUNTS CALLS, which is a question about code. (d) asserts that clara._adj_on_approve
  -- NAMES the role tokens, and it asks that by looking for the STRING LITERALS 'occurrence' and
  -- 'reversal' in the body -- lexing would blank the very text it is asking about and the
  -- assertion would fail on correct code. Two questions, two instruments.
  select lower(regexp_replace(regexp_replace(
           pg_temp._wdb_sql_code(coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid))),
           '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
    into v_sub from pg_proc p
    where p.oid = 'clara._subledger_on_approve(uuid)'::regprocedure;
  -- p.proname <> the target itself, per marker [round-8 M2, the S5.15e self-match fix]: under
  -- the widened read, _adj_on_approve's/_adv_on_approve's OWN pg_get_functiondef header
  -- ("CREATE OR REPLACE FUNCTION clara._adj_on_approve(...)") contains its own call shape
  -- verbatim, so unguarded this loop would find TWO callers (the real one plus the hook
  -- self-matching its own signature line) where exactly one is pinned.
  -- [R13 FIX 2026-08-04 -- re-confirming round, Codex RC4] ONE SPELLING, AND IT IS THE SHARED ONE. Round
  -- 12 left this roster on the argument-blind substring `clara._adj_on_approve(`, which is blind
  -- to a comment in the token gap (`clara._adj_on_approve/*hotfix*/(p_entry)` is a real call and
  -- read as none) -- and blind in the direction that matters here, because this census asserts
  -- "exactly 1": with a comment-spliced call already in the body it would have counted only the
  -- one THIS FILE spliced and reported the double as correct. The roster is now the qualified
  -- NAME and pg_temp._wdb_call_count decides, exactly as probe 11 and S5.8-b2 do.
  for r in select * from (values
      ('clara._adj_on_approve', '_adj_on_approve'),
      ('clara._adv_on_approve', '_adv_on_approve')) as t(marker, bare) loop
    v_names := r.marker;
    -- [R12 FIX 2026-08-04] Lexical here too: a body that merely MENTIONS the hook in a message is not a
    -- second call site, and counting it as one is how this census would refuse a lawful hotfix.
    -- The widened read (prosrc || functiondef) is unchanged and still carries the self-match the
    -- `proname <> r.bare` guard exists for: a functiondef HEADER is outside the body's dollar
    -- quote, so the signature line survives the lexer exactly as it survived the regexp.
    -- THE lower()/whitespace-fold STAYS AND IS NOW BELT, NOT MECHANISM [R13 FIX 2026-08-04]: the shared
    -- matcher is case-blind and gap-tolerant on its own, so the normalisation below no longer
    -- decides anything -- it is kept because it is the text round 12 measured this census on and
    -- removing it would be a delta with no finding behind it.
    select count(*)::int into v_n from pg_proc p
      where p.pronamespace = 'clara'::regnamespace
        and p.proname <> r.bare
        and pg_temp._wdb_call_count(lower(regexp_replace(regexp_replace(
              pg_temp._wdb_sql_code(coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')),
              '--[^\n]*', '', 'g'), '\s+', ' ', 'g')), v_names) > 0;
    if v_n <> 1 then
      raise exception '0042 tail 1(c): % is called from % body/bodies (expected exactly 1 -- clara._subledger_on_approve). Every approve path funnels through that one function; a second call site is a second materialisation of the same proposal.', v_names, v_n;
    end if;
    v_a := pg_temp._wdb_call_count(v_sub, v_names);
    if v_a <> 1 then
      raise exception '0042 tail 1(c): clara._subledger_on_approve calls % % time(s), expected exactly 1 -- the call is matched by qualified name, blind to its arguments and to comments in the token gaps, so two spellings of the same hook count as two calls', v_names, v_a;
    end if;
  end loop;

  -- (d) BOUNDED RECURSION, DEPTH 2 (design SS2.4/SS2.6, [L2] "the mirror hook re-entry is
  -- finite and mint-free"). The cycle is real and intended:
  --     _approve_entry_core -> _subledger_on_approve -> _adj_on_approve
  --       -> (arm 2) mirror INSERT + _approve_entry_core(preheld)
  --         -> _subledger_on_approve -> _adj_on_approve -> (arm 0) RETURN.
  -- What bounds it is that the mirror is stamped role='reversal' at INSERT and arm (0) returns
  -- on exactly that stamp. Three catalog-readable facts carry the bound, and all three are
  -- asserted because losing any one of them turns a finite re-entry into an unbounded one:
  --   (i)   _adj_on_approve knows both role tokens (arm 0 discriminates on them);
  --   (ii)  _adj_on_approve calls the core exactly ONCE (one mirror per occurrence, ever);
  --   (iii) _adv_on_approve calls the core NOT AT ALL -- it mints register rows only, so it
  --         contributes no re-entrant edge and the depth-2 bound does not depend on its arms.
  select lower(regexp_replace(regexp_replace(regexp_replace(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
    into v_adj from pg_proc p
    where p.pronamespace = 'clara'::regnamespace and p.proname = '_adj_on_approve';
  select lower(regexp_replace(regexp_replace(regexp_replace(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
    into v_adv from pg_proc p
    where p.pronamespace = 'clara'::regnamespace and p.proname = '_adv_on_approve';
  -- [R14 FIX 2026-08-04 -- second re-confirming round, N13-2] THE CALL QUESTIONS BELOW GET THE CODE, not
  -- the comment-stripped prose. The regexp pair above is the RETIRED instrument: it cannot tell a
  -- callee named in a dollar-quoted message from one that is called, and a body that explains its
  -- own recursion bound in a comment would be counted as calling the core twice.
  select pg_temp._wdb_sql_code(coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)))
    into v_adjx from pg_proc p
    where p.pronamespace = 'clara'::regnamespace and p.proname = '_adj_on_approve';
  select pg_temp._wdb_sql_code(coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)))
    into v_advx from pg_proc p
    where p.pronamespace = 'clara'::regnamespace and p.proname = '_adv_on_approve';
  if v_adj is null or v_adv is null then
    raise exception '0042 tail 1(d): clara._adj_on_approve and/or clara._adv_on_approve do not exist -- the D-b hooks were not created';
  end if;
  if position('''reversal''' in v_adj) = 0 or position('''occurrence''' in v_adj) = 0 then
    raise exception '0042 tail 1(d): clara._adj_on_approve does not name BOTH role tokens (occurrence/reversal, ABI SSB) -- arm (0) is what keeps arm (2) off the mirror, and without it the mirror mints a mirror';
  end if;
  if position('auto_reversal_of' in v_adj) = 0 then
    raise exception '0042 tail 1(d): clara._adj_on_approve does not stamp auto_reversal_of -- the pair linkage (design SS2.4) is the only edge between the halves; reversal_of/reversed_by are deliberately unused on the pair';
  end if;
  v_a := pg_temp._wdb_call_count(v_adjx, 'clara._approve_entry_core');
  if v_a <> 1 then
    raise exception '0042 tail 1(d): clara._adj_on_approve calls clara._approve_entry_core % time(s), expected exactly 1 (the mirror flip). More than one re-entrant approval from inside a hook is an unbounded recursion; none means the mirror is being approved outside the core.', v_a;
  end if;
  if pg_temp._wdb_call_count(v_advx, 'clara._approve_entry_core') <> 0 then
    raise exception '0042 tail 1(d): clara._adv_on_approve calls clara._approve_entry_core -- the advance hook mints REGISTER rows only (design SS3.3). An approval from there adds a re-entrant edge the depth-2 bound does not cover.';
  end if;

  raise notice '0042 tail 1 OK: the four approve paths and the four hook callers are the SAME pinned four (measured by two independent instruments); both D-b hooks are called exactly once, from clara._subledger_on_approve alone; recursion is bounded at depth 2 by arm (0) plus a single core call in _adj_on_approve and none in _adv_on_approve.';
end $tail1$;
-- =====================================================================================
-- TAIL 2 -- THE origin='scheduled_run' CENSUS (design SS8 tail 2; the SS9.5 single-writer
-- doctrine widened from 0041's ONE writer to D-b's THREE).
--
-- WHY IT MATTERS. origin='scheduled_run' is what tells the whole system "a machine sweep, not
-- a human, drafted this" -- the movement belt exempts it, the D-a authority read counts it as
-- earned ramp evidence, and _adj_on_approve arm (2) re-validates it as one of the seven
-- staleness axes. A body that learns to write it silently gains the ability to forge a
-- scheduled proposal. 0041 pinned ONE writer; D-b adds the occurrence poster and the mirror
-- INSERT inside the hook, so the lawful set is THREE and this census is what keeps it there.
--
-- ...AND THE PAIR MACHINE IS NOT ONE OF THEM. A pair correction is a REVERSAL, not a schedule
-- run: _pair_reverse_core writes origin='reversal' (design SS2.4). Asserted, because a pair
-- correction stamped scheduled_run would be counted as ramp evidence by its own template.
-- =====================================================================================
do $tail2$
declare
  v_n int; v_names text; v_src text; v_allow text[];
begin
  -- The WRITER instrument: a body that BOTH inserts into journal_entries AND carries the
  -- literal in CODE. Comments are stripped first -- a body that merely explains the origin
  -- vocabulary in a comment is not a writer, and 0041's positional literal ('scheduled_run',
  -- v_actor) is too column-order-specific to survive three independent authors.
  if not ('insert into clara.journal_entries(client_id,status) values(x,''scheduled_run'')'
            ~* 'insert[[:space:]]+into[[:space:]]+(clara[[:space:]]*\.[[:space:]]*)?journal_entries(?![a-z0-9_])')
     or not ('insert into journal_entries (a) values (b)'
            ~* 'insert[[:space:]]+into[[:space:]]+(clara[[:space:]]*\.[[:space:]]*)?journal_entries(?![a-z0-9_])')
     or ('insert into clara.journal_entries_archive(a) values(b)'
            ~* 'insert[[:space:]]+into[[:space:]]+(clara[[:space:]]*\.[[:space:]]*)?journal_entries(?![a-z0-9_])') then
    raise exception '0042 tail 2: the journal_entries INSERT detector no longer recognises the bare/qualified forms (or now sweeps in a sibling table) -- the writer census below would be silence, not evidence';
  end if;
  select count(*)::int, string_agg(p.proname::text, ', ' order by p.proname::text collate "C")
    into v_n, v_names
    from pg_proc p
   where p.pronamespace = 'clara'::regnamespace and p.prokind = 'f'
     and lower(regexp_replace(regexp_replace(regexp_replace(
           (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
         ~* 'insert[[:space:]]+into[[:space:]]+(clara[[:space:]]*\.[[:space:]]*)?journal_entries(?![a-z0-9_])'
     and lower(regexp_replace(regexp_replace(regexp_replace(
           (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
         like '%''scheduled_run''%';
  if v_names is distinct from '_adj_on_approve, _adj_run_occurrence_core, _fa_run_period_core' then
    raise exception '0042 tail 2(a): the origin=scheduled_run WRITERS are {%} (% of them) -- expected exactly {_adj_on_approve, _adj_run_occurrence_core, _fa_run_period_core} (design SS8: the D-a poster, the D-b occurrence poster and the D-b auto-reversal mirror). A fourth writer can forge a machine-drafted proposal; a missing one means a poster is stamping the wrong origin.', v_names, v_n;
  end if;

  -- ...AND THE MENTIONERS ARE ENUMERATED. Readers legitimately name the literal (the D-a
  -- authority read counts scheduled_run entries as earned ramp; the belt exempts them; the
  -- D-b hook re-validates the axis). What must never happen is a mention appearing in a body
  -- nobody adjudicated -- so the census is an ALLOWLIST, not a count: extra bodies from the
  -- named D-b families are lawful, an unlisted body is not. (A count alone would break every
  -- time a lane split a helper out; a set membership test does not, and is strictly stronger
  -- against the case this exists to catch.)
  v_allow := array[
    -- the four 0041 pinned this literal at
    '_fa_on_approve', '_fa_run_period_core', '_tf_fa_movement_belt', 'get_depreciation_authority',
    -- the D-b adjustment family (design SS2)
    '_adj_run_occurrence_core', '_adj_on_approve', '_adj_occurrence_outstanding',
    'adjustment_run_due', 'run_adjustment_occurrence', 'run_adjustment_manual',
    '_wdb_reversal_blocked', '_pair_reverse_core', 'reverse_adjustment_pair',
    'approve_pair_reversal', 'cancel_pair_reversal',
    -- the D-b advance family + the surfaces that read origins
    '_adv_on_approve', 'list_review_queue'];
  select coalesce(string_agg(p.proname::text, ', ' order by p.proname::text collate "C"), '')
    into v_names
    from pg_proc p
   where p.pronamespace = 'clara'::regnamespace
     and (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')) like '%scheduled_run%'
     and p.proname <> all (v_allow);
  if v_names <> '' then
    raise exception '0042 tail 2(b): {%} mention the scheduled_run origin and are not in the adjudicated D-a/D-b set -- a new mention is a new opinion about machine-drafted entries, and it has to be written down beside this list', v_names;
  end if;

  -- (c) THE PAIR MACHINE WRITES origin='reversal', NEVER scheduled_run.
  select coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)) into v_src from pg_proc p
    where p.pronamespace = 'clara'::regnamespace and p.proname = '_pair_reverse_core';
  if v_src is null then
    raise exception '0042 tail 2(c): clara._pair_reverse_core does not exist -- the SS2.4 pair-correction machine was not built';
  end if;
  v_src := lower(regexp_replace(regexp_replace(regexp_replace(
             v_src, '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'));
  if position('''reversal''' in v_src) = 0 then
    raise exception '0042 tail 2(c): clara._pair_reverse_core does not write origin=''reversal'' -- a pair correction IS a reversal (design SS2.4, the 13-column recipe)';
  end if;
  if position('''scheduled_run''' in v_src) <> 0 then
    raise exception '0042 tail 2(c): clara._pair_reverse_core mentions scheduled_run in code -- a correction stamped as a schedule run would be counted as ramp evidence by the very template it is correcting, which is the exact inversion the unified ramp clock exists to prevent';
  end if;

  raise notice '0042 tail 2 OK: exactly three origin=scheduled_run writers (_fa_run_period_core, _adj_run_occurrence_core, _adj_on_approve); every mentioner is inside the adjudicated D-a/D-b set; the pair machine writes origin=reversal and never names scheduled_run.';
end $tail2$;
-- =====================================================================================
-- TAIL 3 -- THE POSITIONAL SPLICE CENSUS (design SS8 tail 3 + the SS8 CoR register).
-- One row per change-of-record splice SECTIONS S4/S5 make, asserted on the LIVE body as
-- BOTH-PRESENT-AND-ORDERED. A bare `position(a) < position(b)` reads a MISSING marker
-- (position 0) as correctly ordered and passes vacuously -- the mistake 0041 tail 3 names in
-- its own comment -- so every ordered claim below first asserts both endpoints exist.
--
-- WHY POSITION AND NOT PRESENCE. Four of these splices are only correct in one place:
--   * the two D-b hooks must sit BELOW the FA hook and ABOVE the settlement early-return, or
--     they are dead code for every non-settlement entry (the 0041 [L2/round-1] defect, exactly);
--   * _wdb_reversal_blocked must sit ABOVE the mirror INSERT, or a pair half is reversed and
--     THEN refused, leaving the maker a success receipt for a mirror that can never approve;
--   * the pair/flags refusals must sit BELOW the FOR UPDATE row lock, or they read a world
--     that can change under them;
--   * set_client_fy_end's new rung must sit BETWEEN its op reservation and its write.
-- =====================================================================================
do $tail3$
declare
  r record; v_src text; v_raw text; v_n int; v_a int; v_b int; v_c int; v_d int;
  -- [R14 FIX 2026-08-04 -- N13-2] THE CODE COPY. Every CALL question and every ordering claim that
  -- involves one is measured here; v_src keeps the comment-stripped, whitespace-folded text and
  -- keeps only the questions that are genuinely about string CONTENT. Two questions, two
  -- instruments -- the rule tail 1(d) states and this tail did not follow.
  v_lex text;
begin
  -- ---------------------------------------------------------------------------------------
  -- (1) clara._subledger_on_approve -- THE HOOK CHAIN AND ITS ORDER (design SS2.6/SS3.3).
  -- ---------------------------------------------------------------------------------------
  select coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid))
    into v_raw
    from pg_proc p where p.oid = 'clara._subledger_on_approve(uuid)'::regprocedure;
  -- [R12 FIX 2026-08-04 -- confirming round, Codex CXR3] LEXICAL, AND THE FOURTH ANCHOR DROPS ITS
  -- STRING. This is the FOURTH instrument in this file that judges the same hook chain, and the
  -- lawful-hotfix control reached it after the other three were repaired: a message naming the
  -- hook ABOVE the FA anchor read here as "the chain is out of order". Comments were never the
  -- whole story -- a string literal names things too -- so the stripping is the shared lexical
  -- one and `'settlement_allocation'` (a literal, which the lexer blanks) gives way to the
  -- ASSIGNMENT that reads it. Same line, same position, no string.
  -- (2) BELOW IS DELIBERATELY LEFT ON THE COMMENT-ONLY INSTRUMENT: it asserts reverse_entry still
  -- carries 'asia/kuala_lumpur' and no longer carries current_date, which are questions about
  -- STRING CONTENT. Lexing there would erase the evidence and fail on correct code.
  v_src := lower(regexp_replace(regexp_replace(
             pg_temp._wdb_sql_code(v_raw), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'));
  -- POSITIONS ARE MEASURED ON THE CODE. The D-b splice necessarily comes with a comment
  -- explaining where it sits, and a comment that NAMES the anchor above it would move every
  -- position measured on raw source. Counts below are measured on RAW source instead,
  -- because that is the instrument 0041 pinned its five numbers with (two of the five markers
  -- legitimately appear inside comments, so a stripped count would read 2 and 5 for markers
  -- whose true counts are 3 and 6 -- a false failure, not a caught defect).
  -- [R13 FIX 2026-08-04 -- re-confirming round, Codex RC4] AND THE THREE HOOKS ARE LOCATED BY THE SHARED
  -- MATCHER. This block used TWO spellings in four lines -- the FA anchor with its argument, the
  -- two D-b hooks without -- which is RC4's finding in miniature: the fourth instrument disagreed
  -- with the first about what counts as a call. The settlement anchor is not a call and stays a
  -- plain position (it is the ASSIGNMENT that reads the blanked literal).
  v_a := pg_temp._wdb_call_pos(v_src, 'clara._fa_on_approve');
  v_b := pg_temp._wdb_call_pos(v_src, 'clara._adj_on_approve');
  v_c := pg_temp._wdb_call_pos(v_src, 'clara._adv_on_approve');
  v_d := position('v_prop := e.flags ->' in v_src);
  if v_a = 0 or v_b = 0 or v_c = 0 or v_d = 0 then
    raise exception '0042 tail 3(1): _subledger_on_approve is missing one of the four ordered anchors (fa=%, adj=%, adv=%, settlement early-return=%) -- the SS2.6 splice has no position to be measured at', v_a, v_b, v_c, v_d;
  end if;
  if not (v_a < v_b and v_b < v_c and v_c < v_d) then
    raise exception '0042 tail 3(1): the hook chain is out of order (fa=%, adj=%, adv=%, settlement early-return=%). The law is _fa_on_approve -> _adj_on_approve -> _adv_on_approve, ALL of them above `v_prop := e.flags -> ''settlement_allocation''` -- below that line the body returns for every non-settlement entry, which is every occurrence and every advance movement.', v_a, v_b, v_c, v_d;
  end if;
  -- The 0041 six-marker census, re-run here so a body this migration rebuilt cannot pass by
  -- carrying only the NEW markers (design SS8 CoR register: "_subledger_on_approve, six-marker
  -- census + anchor").
  for r in select * from (values
      ('payment_terms_days', 1), ('effective_date', 3),
      ($$item_kind in ('invoice','bill')$$, 1),
      ('cross_domain_control_entry', 1), ('allocation_stale', 6)) as t(marker, want) loop
    v_n := (length(v_raw) - length(replace(v_raw, r.marker, ''))) / length(r.marker);
    if v_n <> r.want then
      raise exception '0042 tail 3(1): _subledger_on_approve marker "%" is % (expected % -- the 0041 tail 3 census, re-pinned after the D-b splices)', r.marker, v_n, r.want;
    end if;
  end loop;
  v_n := pg_temp._wdb_call_count(v_src, 'clara._fa_on_approve');
  if v_n <> 1 then
    raise exception '0042 tail 3(1): _subledger_on_approve calls clara._fa_on_approve % time(s) in CODE, expected exactly 1 -- the D-a hook is the anchor the D-b splices are positioned against', v_n;
  end if;

  -- ---------------------------------------------------------------------------------------
  -- (2) clara.reverse_entry -- THE SEVENTH SPLICE (design SS2.4). Six 0041 markers survive,
  -- the D-b wall lands between the FA wall and the mirror INSERT.
  -- ---------------------------------------------------------------------------------------
  select lower(regexp_replace(regexp_replace(regexp_replace(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
    into v_src from pg_proc p where p.oid = 'clara.reverse_entry(uuid,text,text)'::regprocedure;
  -- [R14 FIX 2026-08-04 -- second re-confirming round, N13-2, DEPLOY-BLOCKER] THE FA-WALL CALL LEAVES THIS
  -- CHAIN, and the chain says FIVE because it now holds five. The six markers were never one kind
  -- of question: five are string CONTENT (a refusal token, a lock id, a timezone name) and the
  -- sixth was a CALL, judged on comment-stripped text. MEASURED by the native lens on planted
  -- reverse_entry bodies -- every one of them behaviourally identical to the original -- the CALL
  -- row refused a correct deploy three ways: `_fa_reversal_blocked( p_entry )` (whitespace),
  -- `_fa_reversal_blocked( -- hotfix ref` + newline (a line comment inside the argument list), and
  -- a `$m$...$m$` message naming the D-b wall above the FA one, which is CXR3's defect verbatim
  -- arriving at a fourth site. The call now asks the shared matcher; the five content markers stay
  -- exactly where they were measured.
  if position('opening_entry_k_family_only' in v_src) = 0
     or position('allocated_items_present' in v_src) = 0
     or position('live_bank_match_present' in v_src) = 0
     or position('pg_advisory_xact_lock(203005004' in v_src) = 0
     or position('asia/kuala_lumpur' in v_src) = 0
     or position('current_date' in v_src) <> 0 then
    raise exception '0042 tail 3(2): reverse_entry lost one of its five pre-0042 string-content splice markers, or dates its mirror on current_date again';
  end if;
  select lower(regexp_replace(pg_temp._wdb_sql_code(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid))), '\s+', ' ', 'g'))
    into v_lex from pg_proc p where p.oid = 'clara.reverse_entry(uuid,text,text)'::regprocedure;
  v_a := pg_temp._wdb_call_pos(v_lex, 'clara._fa_reversal_blocked');
  v_b := pg_temp._wdb_call_pos(v_lex, 'clara._wdb_reversal_blocked');
  -- [R15 FIX 2026-08-04 -- third re-confirming round, N14-2, E37] THE THIRD ANCHOR IS A PHRASE, NOT A
  -- CALL, AND W-R14 BROKE IT BY TREATING IT LIKE ONE. Moving this block onto the lexed body was
  -- right for the two calls above -- the matcher walks comments and spacing for them -- but this
  -- anchor stayed an EXACT substring, and on the lexed body a comment inside the phrase is a run
  -- of sentinel bytes an exact substring cannot cross. MEASURED on planted reverse_entry bodies
  -- whose executable behaviour is identical to the original: `insert /*hotfix 9101*/ into ...`
  -- and the line-comment-plus-newline form both APPLIED CLEAN on the round-13 build and were
  -- REFUSED after W-R14 -- a correct deploy refused, which is E37, and a regression this wave
  -- owns rather than inherits.
  -- IT IS NOT A REVERT, BECAUSE REVERTING WOULD NOT HAVE BEEN ENOUGH. The same measurement found
  -- a third shape, `journal_entries /*c*/ (`, refused on BOTH builds -- the anchor was already
  -- rigid about the space before its parenthesis, before this wave touched it. So the repair is
  -- ONE TOLERANT MATCH that admits whitespace and excised comments at every token boundary of the
  -- phrase, which covers all three shapes and the plain one.
  -- AND IT STAYS ON v_lex, DELIBERATELY. The obvious alternative -- measure this anchor on the
  -- comment-DELETED text instead -- would put v_c in a different string from v_a and v_b, and two
  -- offsets are only comparable when they come from the same text. That is the exact trap this
  -- file warns about at tail 3(5), and it would not even be conservative: one long comment between
  -- the second call and the INSERT would drag v_c BELOW v_b and refuse a correct deploy for a
  -- brand-new reason. The offset comes from substituting the first match, the same idiom
  -- pg_temp._wdb_call_pos uses for a call -- and it is taken AFTER that function has already run
  -- twice on this same text, so its chr(3) guard has vouched for the subject.
  v_c := position(chr(3) in regexp_replace(v_lex,
           'insert[[:space:]' || chr(1) || ']+into[[:space:]' || chr(1) || ']+clara[[:space:]'
             || chr(1) || ']*[.][[:space:]' || chr(1) || ']*journal_entries[[:space:]'
             || chr(1) || ']*[(]',
           chr(3), ''));
  if v_a = 0 then
    raise exception '0042 tail 3(2): reverse_entry no longer calls clara._fa_reversal_blocked -- the 0041 FA reversal wall is the anchor the D-b wall is positioned against';
  end if;
  if v_b = 0 then
    raise exception '0042 tail 3(2): reverse_entry does not call clara._wdb_reversal_blocked -- the pair halves, the advance disbursement with live applications and the correction-carrying entry all stay reversible one-sidedly (ABI SSF: adjustment_pair_locked / advance_applications_outstanding / correction_entry_irreversible)';
  end if;
  if v_c = 0 then
    raise exception '0042 tail 3(2): reverse_entry no longer contains the mirror INSERT anchor this ordering is measured against -- re-derive it';
  end if;
  if not (v_a < v_b and v_b < v_c) then
    raise exception '0042 tail 3(2): the D-b reversal wall is misplaced (fa=%, wdb=%, mirror insert=%) -- it must sit beside the FA wall and STRICTLY ABOVE the mirror INSERT, or a refused reversal has already written its mirror', v_a, v_b, v_c;
  end if;

  -- ---------------------------------------------------------------------------------------
  -- (3) clara.revise_entry -- THE THREE-FLAGS REFUSAL + THE PAIR-MEMBERSHIP REFUSAL
  -- (design SS2.6, ABI SSB: token proposal_not_revisable; the FA arm keeps its own token).
  -- The occurrence count is computed by SUBTRACTION because `fa_proposal_not_revisable`
  -- CONTAINS `proposal_not_revisable` as a substring -- a naive count would read the surviving
  -- D-a arm as the new D-b arm and green a body that never gained one.
  -- ---------------------------------------------------------------------------------------
  select lower(regexp_replace(regexp_replace(regexp_replace(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
    into v_src from pg_proc p
    where p.oid = 'clara.revise_entry(uuid,jsonb,jsonb,jsonb,uuid,text,jsonb,jsonb)'::regprocedure;
  v_a := (length(v_src) - length(replace(v_src, 'proposal_not_revisable', '')))
         / length('proposal_not_revisable');
  v_b := (length(v_src) - length(replace(v_src, 'fa_proposal_not_revisable', '')))
         / length('fa_proposal_not_revisable');
  if v_b < 1 then
    raise exception '0042 tail 3(3): revise_entry lost the 0041 fa_proposal_not_revisable arm';
  end if;
  if (v_a - v_b) < 1 then
    raise exception '0042 tail 3(3): revise_entry carries no BARE proposal_not_revisable refusal (% total occurrences, % of them the D-a fa_ arm) -- the three D-b flags keys (recurring_adjustment, staff_advance_application, bank_rule_suggested, ABI SSB) would stay editable, and an edited proposal reaches the hook with legs that contradict what the hook is about to materialise', v_a, v_b;
  end if;
  if position('reversal_mirror_not_revisable' in v_src) = 0 then
    raise exception '0042 tail 3(3): revise_entry lost the 0037 reversal_mirror_not_revisable arm';
  end if;
  if position('pair_draft_locked' in v_src) = 0 then
    raise exception '0042 tail 3(3): revise_entry carries no pair_draft_locked refusal -- a draft named by a pending/approving pair receipt must not be editable (design SS2.4: the receipt IS the authorization channel)';
  end if;
  for r in select * from (values ('recurring_adjustment'), ('staff_advance_application'),
                                 ('bank_rule_suggested')) as t(flagkey) loop
    if position(r.flagkey in v_src) = 0 then
      raise exception '0042 tail 3(3): revise_entry does not name the D-b flags key "%" -- the refusal must enumerate all three (ABI SSB), not a subset', r.flagkey;
    end if;
  end loop;
  v_c := position('select * into e from clara.journal_entries where id=p_entry for update' in v_src);
  if v_c = 0 then
    raise exception '0042 tail 3(3): revise_entry no longer takes its FOR UPDATE row lock in the shape this ordering is measured against -- re-derive the anchor';
  end if;
  if position('pair_draft_locked' in v_src) < v_c then
    raise exception '0042 tail 3(3): revise_entry checks pair membership BEFORE its FOR UPDATE row lock -- an authority statement read before the lock is a read of a world that can change under it';
  end if;

  -- ---------------------------------------------------------------------------------------
  -- (4) clara.withdraw_draft -- THE PAIR REFUSAL (design SS2.4: token pair_draft_locked, the
  -- remedy names cancel_pair_reversal). Ordered between the row lock and the withdrawal write.
  -- ---------------------------------------------------------------------------------------
  select lower(regexp_replace(regexp_replace(regexp_replace(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
    into v_src from pg_proc p where p.oid = 'clara.withdraw_draft(uuid,text,uuid,text)'::regprocedure;
  v_a := position('select * into e from clara.journal_entries where id=p_entry for update' in v_src);
  v_b := position('pair_draft_locked' in v_src);
  v_c := position('update clara.journal_entries set status=''withdrawn''' in v_src);
  if position('pending_match_present' in v_src) = 0 then
    raise exception '0042 tail 3(4): withdraw_draft lost the 0038 pending_match_present refusal';
  end if;
  if v_a = 0 or v_c = 0 then
    raise exception '0042 tail 3(4): withdraw_draft no longer carries the row-lock / withdrawal-write anchors this ordering is measured against (lock=%, write=%)', v_a, v_c;
  end if;
  if v_b = 0 then
    raise exception '0042 tail 3(4): withdraw_draft carries no pair_draft_locked refusal -- withdrawing ONE half of a pair correction strands the other half and the receipt that authorizes it (design SS2.4)';
  end if;
  if not (v_a < v_b and v_b < v_c) then
    raise exception '0042 tail 3(4): withdraw_draft''s pair refusal is misplaced (lock=%, refusal=%, write=%) -- it must read the LOCKED row and refuse BEFORE the withdrawal write', v_a, v_b, v_c;
  end if;

  -- ---------------------------------------------------------------------------------------
  -- (5) clara.set_client_fy_end -- THE RUNG + THE ANNUAL-CADENCE GUARD (design SS2.2).
  -- The verb had NO advisory rung before 0042: it read nothing it had to serialize against.
  -- It does now (a live annual template or annual authority blocks the change), and a guard
  -- read outside the rung is a check-then-act race with the sign verb.
  -- MONTHLY CADENCES DO NOT BLOCK -- that is the sandbox's live monthly authority, and the
  -- design names it as the cell. This tail asserts the rung and the guard, never the polarity;
  -- x42 owns the monthly-does-not-block cell.
  -- ---------------------------------------------------------------------------------------
  select lower(regexp_replace(regexp_replace(regexp_replace(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
    into v_src from pg_proc p
    where p.oid = 'clara.set_client_fy_end(uuid,integer,integer,text)'::regprocedure;
  -- [R14 FIX 2026-08-04 -- N13-2] THE WHOLE ORDERING TRIO MOVES TO THE CODE COPY, not just the call. Two
  -- offsets are only comparable when they are measured on the SAME text, and the comment-stripped
  -- text DELETES what it removes while the lexer BLANKS it -- so mixing the two would compare
  -- positions in two different strings. All three anchors here are executable code (a call, a
  -- lock, an UPDATE), so all three are findable in the lexed copy; the `'annual'` cadence token
  -- below is a string literal and stays on v_src, where it can still be seen.
  select lower(regexp_replace(pg_temp._wdb_sql_code(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid))), '\s+', ' ', 'g'))
    into v_lex from pg_proc p
    where p.oid = 'clara.set_client_fy_end(uuid,integer,integer,text)'::regprocedure;
  v_a := pg_temp._wdb_call_pos(v_lex, 'clara._reserve_op');
  v_b := position('pg_advisory_xact_lock(203005004' in v_lex);
  v_c := position('update clara.clients set fy_end_month' in v_lex);
  if v_a = 0 or v_c = 0 then
    raise exception '0042 tail 3(5): set_client_fy_end lost its op reservation or its write anchor (reserve=%, write=%)', v_a, v_c;
  end if;
  if v_b = 0 then
    raise exception '0042 tail 3(5): set_client_fy_end takes no 203005004 client rung -- the annual-cadence guard would read templates and authorities a concurrent sign verb is still writing (design SS2.2)';
  end if;
  if not (v_a < v_b and v_b < v_c) then
    raise exception '0042 tail 3(5): set_client_fy_end''s rung is misplaced (reserve=%, rung=%, write=%) -- reserve the op key BEFORE the rung (the 0037 deadlock lesson) and take the rung BEFORE the write', v_a, v_b, v_c;
  end if;
  if position('adjustment_templates' in v_src) = 0
     or position('fa_depreciation_authorities' in v_src) = 0 then
    raise exception '0042 tail 3(5): set_client_fy_end does not consult BOTH live-annual sources (clara.adjustment_templates AND clara.fa_depreciation_authorities) -- design SS2.2 blocks on either';
  end if;
  if position('''annual''' in v_src) = 0 then
    raise exception '0042 tail 3(5): set_client_fy_end''s guard is not cadence-discriminated -- a blanket block would wedge every client that carries the sandbox''s live MONTHLY authority';
  end if;

  -- ---------------------------------------------------------------------------------------
  -- (6) clara._fa_assert_code_unreserved -- THE SHARED UNION, LEAF KEPT (design SS3.1).
  -- The bank belt now reads the WIDER predicate (FA profiles + FA register + ACTIVE advance
  -- enrolments + their register rows) so a bank account can never bind an actively enrolled
  -- advance code -- and it keeps taking the fa-roles leaf FIRST, because a read-then-refuse
  -- outside the leaf races the enrolment doors.
  -- ---------------------------------------------------------------------------------------
  select lower(regexp_replace(regexp_replace(regexp_replace(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
    into v_src from pg_proc p where p.oid = 'clara._fa_assert_code_unreserved(uuid,text)'::regprocedure;
  -- [R14 FIX 2026-08-04 -- N13-2] BOTH ANCHORS ARE CALLS, so both move together and stay comparable.
  select lower(regexp_replace(pg_temp._wdb_sql_code(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid))), '\s+', ' ', 'g'))
    into v_lex from pg_proc p where p.oid = 'clara._fa_assert_code_unreserved(uuid,text)'::regprocedure;
  v_a := pg_temp._wdb_call_pos(v_lex, 'clara._fa_lock_roles');
  v_b := pg_temp._wdb_call_pos(v_lex, 'clara._acct_role_reserved');
  if v_a = 0 then
    raise exception '0042 tail 3(6): _fa_assert_code_unreserved no longer takes the fa-roles leaf -- concurrent enrolment and bank binding of one code would both pass (0041 tail 13(c), still the law)';
  end if;
  if v_b = 0 then
    raise exception '0042 tail 3(6): _fa_assert_code_unreserved does not read clara._acct_role_reserved -- the bank belt is still blind to staff-advance enrolments, so a bank account can bind an actively enrolled advance code (design SS3.1)';
  end if;
  if v_a > v_b then
    raise exception '0042 tail 3(6): _fa_assert_code_unreserved reads the reservation predicate BEFORE taking the leaf (leaf=%, read=%) -- that is the check-then-act window the leaf exists to close', v_a, v_b;
  end if;

  -- ---------------------------------------------------------------------------------------
  -- (7) clara._fa_asset_json -- THE G14 SPLIT-MONTH ADVISORY (design SS6.4, [WDB-G14]).
  -- DERIVED, NEVER STORED: no arithmetic changed, so the only evidence a reviewer ever sees
  -- is this projection. If the call is missing, the advisory silently does not exist.
  -- ---------------------------------------------------------------------------------------
  -- [R14 FIX 2026-08-04 -- N13-2] THE TWO PROJECTION QUESTIONS ARE CALL QUESTIONS and were being asked on
  -- text nothing had stripped at all -- so a comment mentioning either helper would have satisfied
  -- them, and a lawful respelling of either call would have failed them. The two TOKEN questions
  -- in (7b) (`disposal_draft_outstanding`, `disposal_draft_entry_id`, the keys the surface reads)
  -- are string content and stay on the raw text below, deliberately.
  select coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)) into v_src from pg_proc p where p.oid = 'clara._fa_asset_json(uuid,date)'::regprocedure;
  v_lex := pg_temp._wdb_sql_code(v_src);
  if pg_temp._wdb_call_count(v_lex, 'clara._fa_split_month_advisory') = 0 then
    raise exception '0042 tail 3(7): _fa_asset_json does not project clara._fa_split_month_advisory -- the [WDB-G14] reviewer advisory is derived and never stored, so an unprojected advisory is an advisory that does not exist';
  end if;
  -- (7b) THE SAME LAW FOR THE [WDB-G10] SECOND-DISPOSAL FREEZE (round-5 fix lane).
  -- S5.6 makes dispose_fixed_asset REFUSE while a disposal draft is outstanding. That refusal
  -- is only actionable if the register READ says the row is frozen: without this projection
  -- /assets goes on offering a dispose form whose sole outcome is the refusal, and the remedy
  -- the refusal names has no door on that screen. The verdict must come from the guard's own
  -- function, so surface and refusal cannot answer differently.
  if pg_temp._wdb_call_count(v_lex, 'clara._fa_disposal_draft_outstanding') = 0
     or position('disposal_draft_outstanding' in v_src) = 0
     or position('disposal_draft_entry_id' in v_src) = 0 then
    raise exception '0042 tail 3(7b): _fa_asset_json does not project the [WDB-G10] disposal freeze through clara._fa_disposal_draft_outstanding -- an unprojected freeze reads on /assets as a dispose form that can only ever be refused';
  end if;

  -- ---------------------------------------------------------------------------------------
  -- (8) THE S5 WRITER GUARDS (design SS6.1/SS6.2, [WDB-G10]/[WDB-G11]).
  -- The 64-edge cap has always existed on the THREE READERS (they refuse rather than truncate,
  -- 0041's fold G8). G11 closes it WRITER-side on the THREE MINTING PATHS, so a 65th
  -- generation can never be created -- rather than being created and then unreadable.
  -- ---------------------------------------------------------------------------------------
  -- ASSEMBLY RECONCILIATION S6-A1 (a cross-lane instrument mismatch, corrected at assembly
  -- and reported rather than relaxed). This block originally asserted the literal token
  -- `fa_lineage_too_deep` inside all SIX bodies. That is the right instrument for the three
  -- READERS -- they each carry their own inline hop counter and raise the token themselves --
  -- but the WRONG one for the three WRITERS: SECTION S5 does not inline a fourth, fifth and
  -- sixth copy of the counting law, it factors it into clara._fa_assert_lineage_mintable and
  -- `perform`s that helper at each minting path. So the writers legitimately do NOT contain
  -- the token string; the helper does. Asserting the string at the call sites would have
  -- forced three duplicated copies of the 64-edge arithmetic -- exactly the drift a shared
  -- helper exists to prevent. The writers are therefore pinned on THE CALL, and the helper is
  -- pinned on THE TOKEN, which together prove the same property the original assertion aimed
  -- at: every minting path refuses the 65th edge with CLR37 / fa_lineage_too_deep.
  -- [R14 FIX 2026-08-04 -- second re-confirming round, follow-up pass W-R14.1] THE ROSTER ASKED ONE
  -- QUESTION OF EIGHT ROWS THAT ARE TWO KINDS. The comment above already says so in words -- the
  -- readers and the helper are "pinned on THE TOKEN", the three writers "on THE CALL" -- and the
  -- loop then asked all eight the same way, with `position(marker in raw_source)`. For the five
  -- TOKEN rows that is exactly right and they do not move: the body RAISES `fa_lineage_too_deep`
  -- or `disposal_draft_outstanding` inline, the token string IS the evidence, and lexing would
  -- blank the very literal being asked about (tail 1(d)'s law, and the reason those rows keep
  -- their instrument and say so here).
  -- THE THREE CALL ROWS WERE THE LAST OF THIS WAVE'S CLASS. Asked on raw text, a call question
  -- inherits everything the round has been closing at thirteen other sites: a comment in the token
  -- gap, a quoted identifier, an upper-case respelling and a dollar-quoted message that merely
  -- NAMES the helper are each either a lawful hotfix refused or a lost call admitted -- and the
  -- three subjects are 0041/0042-installed FA minting paths, i.e. real hotfix surface. They now
  -- ask pg_temp._wdb_call_count on the lexed body, argument-blind, so the marker is the QUALIFIED
  -- NAME without its paren. The matcher itself gains nothing: it is generic by name, so a roster
  -- row is all this costs.
  for r in select * from (values
      -- readers (0041's, re-pinned: losing one re-opens a wrong-number-as-answer path).
      -- These raise the token INLINE, so the token itself is the marker -- a CONTENT question,
      -- asked on the raw body, deliberately.
      ('clara._fa_lineage_walk(uuid,date,boolean)', 'fa_lineage_too_deep', false),
      ('clara._fa_lineage_first_due_month(uuid,date)', 'fa_lineage_too_deep', false),
      ('clara._fa_disposal_stub(uuid,date)', 'fa_lineage_too_deep', false),
      -- the SHARED writer-side assertion helper: this is the one body that must carry the
      -- token, because it is the single site that raises it for all three minting paths.
      ('clara._fa_assert_lineage_mintable(uuid,text)', 'fa_lineage_too_deep', false),
      -- writers (0042's three minting paths: revise, the partial-split, the K6 replacement).
      -- Pinned on the CALL to the shared helper, not on the token (see S6-A1 above) -- so these
      -- three are CALL questions and are asked on the lexed body, blind to the argument list.
      ('clara.revise_fixed_asset_particulars(uuid,uuid,jsonb,date,text)',
        'clara._fa_assert_lineage_mintable', true),
      ('clara.dispose_fixed_asset(uuid,uuid,date,bigint,text,text,text,text,text,bigint)',
        'clara._fa_assert_lineage_mintable', true),
      ('clara._draft_opening_item_core(uuid,uuid,uuid,uuid,jsonb,jsonb,uuid,uuid,text)',
        'clara._fa_assert_lineage_mintable', true),
      -- the second-disposal guard [WDB-G10] -- a token again, and a token the SURFACE reads.
      ('clara.dispose_fixed_asset(uuid,uuid,date,bigint,text,text,text,text,text,bigint)',
        'disposal_draft_outstanding', false)
    ) as t(sig, marker, is_call) loop
    -- to_regprocedure, not the ::regprocedure cast: a body that is GONE deserves this block's
    -- named error, not a bare "function does not exist" from a cast three lines earlier.
    if to_regprocedure(r.sig) is null then
      raise exception '0042 tail 3(8): % is GONE after this migration', r.sig;
    end if;
    select coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)) into v_src from pg_proc p where p.oid = to_regprocedure(r.sig);
    if r.is_call then
      if pg_temp._wdb_call_count(pg_temp._wdb_sql_code(v_src), r.marker) = 0 then
        raise exception '0042 tail 3(8): % does not CALL % -- design SS6 requires every minting path to route the 64-edge count through the shared helper, and the call is matched by qualified name on the lexed body (blind to its arguments, and to comments, quoting and case), so only a genuinely absent call reaches this line', r.sig, r.marker;
      end if;
    elsif position(r.marker in v_src) = 0 then
      raise exception '0042 tail 3(8): % does not carry the token "%" -- design SS6 requires it at that site', r.sig, r.marker;
    end if;
  end loop;
  -- BOTH 0017 VALIDATOR SITES gain the cost-only NULL disjunct ([WDB-G12], narrowed from the
  -- round-1 over-fold: useful_life_months is already checked method-conditionally, and a
  -- global null-refusal would break method='none'). The incompleteness raise still appears
  -- TWICE (0041's own pin) -- that is what identifies the two sites -- and the cost disjunct
  -- must appear at least once per site. A LOWER bound, not an exact one: a composer may add a
  -- third cost test legitimately, and x42 owns the NULL-cost-both-doors drill.
  select lower(regexp_replace(regexp_replace(regexp_replace(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
    into v_src from pg_proc p
    where p.oid = 'clara._draft_opening_item_core(uuid,uuid,uuid,uuid,jsonb,jsonb,uuid,uuid,text)'::regprocedure;
  v_a := (length(v_src) - length(replace(v_src, 'fixed asset books-grade baseline is incomplete', '')))
         / length('fixed asset books-grade baseline is incomplete');
  if v_a <> 2 then
    raise exception '0042 tail 3(8): _draft_opening_item_core carries the baseline-incomplete raise % time(s), expected 2 -- the two K-validator sites the [WDB-G12] recut targets cannot be identified', v_a;
  end if;
  v_b := (length(v_src) - length(replace(v_src, 'v_cost is null', ''))) / length('v_cost is null');
  if v_b < 2 then
    raise exception '0042 tail 3(8): _draft_opening_item_core carries the cost-null disjunct % time(s), expected at least 2 (one per validator site, [WDB-G12]) -- with cost_cents now NOT NULL, a seed that omits a cost must be refused at BOTH doors rather than aborting on the column constraint', v_b;
  end if;

  raise notice '0042 tail 3 OK: the hook chain is ordered above the settlement early-return with all six 0041 markers intact; reverse_entry''s seventh splice sits above the mirror INSERT; revise_entry and withdraw_draft refuse below their row locks; set_client_fy_end reserves-then-rungs-then-writes and discriminates on annual cadence; the bank belt reads the shared union under the leaf; the split-month advisory is projected; all three lineage readers, all three minting paths, the second-disposal guard and both K-validator cost disjuncts are present.';
end $tail3$;

-- =====================================================================================
-- [SPLIT D-b2 2026-08-04] TAILS 4 AND 5 STAND HERE IN THE WHOLE UNIT AND ARE D-b3's (the parked
-- declaration state -- its CHECK, its set-once column and the cancel path -- and the 0040 S4.Z
-- behavioural pins re-run on the three factored cores). Both shipped with 0044.
-- =====================================================================================
-- =====================================================================================
-- TAIL 6 -- THE SS9.5 SINGLE-WRITER CENSUSES, MIRRORED FOR THE THREE D-b FLAGS KEYS
-- (design SS8 tail 6; the 0041 tail 5 idiom).
--
-- PROPOSAL AUTHENTICITY IN THIS PRODUCT IS STRUCTURAL, NOT CONVENTIONAL. A flags key is an
-- instruction the approve-time hook will execute against the books. If any body can write one,
-- then "the DB owns every number" reduces to "whoever can call a function owns every number".
-- Three counts keep it structural, and the third is the one a later migration will be tempted
-- to break: the GENERIC drafting core must stay innocent of every proposal key.
-- =====================================================================================
do $tail6$
declare
  r record; v_n int; v_names text; v_def text; v_pat text;
begin
  -- (a) ONE WRITER SET PER KEY. The writer marker is the house minting form -- either
  -- jsonb_build_object('<key>', ...) or a jsonb literal carrying "<key>": -- measured on the
  -- normalised body so a reader that merely NAMES the key (revise_entry's refusal, the hook's
  -- own arm test, the S5 sighting carve-out) is not miscounted as a minter.
  if not ($$jsonb_build_object('bank_rule_suggested', jsonb_build_object($$
            ~* 'jsonb_build_object\([[:space:]]*''bank_rule_suggested''|"bank_rule_suggested"[[:space:]]*:')
     or not ($${"bank_rule_suggested": {"rule_id": 1}}$$
            ~* 'jsonb_build_object\([[:space:]]*''bank_rule_suggested''|"bank_rule_suggested"[[:space:]]*:')
     or ($$e.flags ? 'bank_rule_suggested'$$
            ~* 'jsonb_build_object\([[:space:]]*''bank_rule_suggested''|"bank_rule_suggested"[[:space:]]*:') then
    raise exception '0042 tail 6(a): the flags-key WRITER detector no longer separates minting from reading -- a census from it would count every reader as a writer, or every writer as neither';
  end if;
  for r in select * from (values
      -- key, the exact lawful writer set, and why it is that set
      ('recurring_adjustment', '_adj_on_approve, _adj_run_occurrence_core'),
      ('staff_advance_application', 'book_staff_advance_application, resolve_and_book_bank_line'),
      ('bank_rule_suggested', 'accept_bank_rule_suggestion')
    ) as t(flagkey, want) loop
    v_pat := 'jsonb_build_object\([[:space:]]*''' || r.flagkey || '''|"' || r.flagkey || '"[[:space:]]*:';
    select coalesce(string_agg(p.proname::text, ', ' order by p.proname::text collate "C"), '')
      into v_names
      from pg_proc p
     where p.pronamespace = 'clara'::regnamespace and p.prokind = 'f'
       and lower(regexp_replace(regexp_replace(regexp_replace(
             (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g')) ~* v_pat;
    if v_names <> r.want then
      raise exception '0042 tail 6(a): the writers of the "%" proposal key are {%} -- expected exactly {%}. A key is an instruction the approve hook executes against the books; every minting site has to be an audited verb somebody adjudicated (design SS9.5, ABI SSB).', r.flagkey, v_names, r.want;
    end if;
  end loop;

  -- (b) THE GENERIC DRAFTING CORE IS INNOCENT OF ALL FIVE PROPOSAL KEYS (0041's two + D-b's
  -- three). clara._draft_entry_core is reachable from the agent lane; if it could persist a
  -- proposal key, forgery would be a matter of argument shape rather than of authority.
  select coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)) into v_def from pg_proc p
    where p.pronamespace = 'clara'::regnamespace and p.proname = '_draft_entry_core' limit 1;
  if v_def is null then
    raise exception '0042 tail 6(b): clara._draft_entry_core is GONE';
  end if;
  foreach v_names in array array['depreciation_charges', 'fa_disposal', 'recurring_adjustment',
                                 'staff_advance_application', 'bank_rule_suggested'] loop
    if position(v_names in v_def) <> 0 then
      raise exception '0042 tail 6(b): _draft_entry_core now mentions the proposal key "%" -- the generic drafting core must never be able to persist one, or proposal authenticity stops being structural', v_names;
    end if;
  end loop;

  -- (c) NO TABLE GRANTS on clara.journal_entries for any human or machine role: a proposal can
  -- only be born inside an audited SECURITY DEFINER verb (0041 tail 5(d), re-pinned).
  select count(*)::int into v_n from information_schema.role_table_grants
   where table_schema = 'clara' and table_name = 'journal_entries'
     and privilege_type in ('INSERT', 'UPDATE', 'DELETE')
     and grantee in ('clara_authenticated', 'clara_agent_ro', 'clara_runtime',
                     'clara_wake_interactive', 'clara_wake_proactive');
  if v_n <> 0 then
    raise exception '0042 tail 6(c): % write grant(s) exist on clara.journal_entries for a human or machine role -- proposal authenticity is no longer structural', v_n;
  end if;

  raise notice '0042 tail 6 OK: one adjudicated writer set per D-b flags key (2/2/1); _draft_entry_core is innocent of all five proposal keys; zero write grants on journal_entries.';
end $tail6$;
-- =====================================================================================
-- TAIL 7 -- THE NO-WAKE CENSUS (the wake-authority structural invariant, restated for D-b).
--
-- The agent never signs a template, never enrols an advance account, never approves a pair
-- correction and never resolves-and-books a bank line. That is not a policy the model is asked
-- to respect: the per-wake allowlist is the authority, and this census is what proves no D-b
-- verb slipped into it. Kept in its own block, free of pg_get_functiondef, so the ACL-shaped
-- literals here can never read as a change-of-record patch to the wiki gate.
-- =====================================================================================
do $tail7$
declare v_n int; v_names text; f text;
begin
  select count(*)::int, coalesce(string_agg(coalesce(fn_name, function_name), ', '), '')
    into v_n, v_names
    from clara.wake_fn_allowlist
   where coalesce(fn_name, function_name) like '%adjustment%'
      or coalesce(fn_name, function_name) like '%advance%'
      or coalesce(fn_name, function_name) like '%pair_reversal%'
      or coalesce(fn_name, function_name) like '%bank_rule_suggestion%'
      or coalesce(fn_name, function_name) like '%resolve_and_book%'
      or coalesce(fn_name, function_name) like '%template%';
  if v_n <> 0 then
    raise exception '0042 tail 7: % wake-allowlist row(s) name a Wave D-b verb (%) -- the agent never signs an adjustment template, enrols a staff advance, approves a pair correction or resolves-and-books a bank line', v_n, v_names;
  end if;
  -- ...and no D-b verb is reachable by a wake role or the read-only agent role by GRANT either
  -- (the allowlist and the grant are two independent gates; D-a's tail pinned both).
  foreach f in array array[
      'propose_adjustment_template', 'sign_adjustment_template', 'retire_adjustment_template',
      'run_adjustment_manual', 'adjustment_run_due', 'reverse_adjustment_pair',
      'approve_pair_reversal', 'cancel_pair_reversal', 'enrol_staff_advance_account',
      'retire_staff_advance_account', 'book_staff_advance_application',
      'complete_staff_advance_particulars', 'resolve_and_book_bank_line',
      'accept_bank_rule_suggestion'] loop
    select count(*)::int into v_n
      from pg_proc p
      cross join lateral aclexplode(coalesce(p.proacl, '{}'::aclitem[])) a
      join pg_roles rr on rr.oid = a.grantee
     where p.pronamespace = 'clara'::regnamespace and p.proname = f
       and a.privilege_type = 'EXECUTE'
       and rr.rolname in ('clara_agent_ro', 'clara_wake_interactive', 'clara_wake_proactive');
    if v_n <> 0 then
      raise exception '0042 tail 7: clara.% is granted to an agent or wake role -- every D-b act is a professional act taken by a named human', f;
    end if;
  end loop;
  -- THE ONE MACHINE VERB, and only it: the sweep's occurrence runner (design SS2.3/SS2.7).
  select count(*)::int into v_n
    from pg_proc p
    cross join lateral aclexplode(coalesce(p.proacl, '{}'::aclitem[])) a
    join pg_roles rr on rr.oid = a.grantee
   where p.pronamespace = 'clara'::regnamespace and p.proname = 'run_adjustment_occurrence'
     and a.privilege_type = 'EXECUTE' and rr.rolname = 'clara_runtime';
  if v_n = 0 then
    raise exception '0042 tail 7: clara_runtime cannot EXECUTE run_adjustment_occurrence -- the adjustment sweep would boot dead';
  end if;
  select count(*)::int into v_n
    from pg_proc p
    cross join lateral aclexplode(coalesce(p.proacl, '{}'::aclitem[])) a
    join pg_roles rr on rr.oid = a.grantee
   where p.pronamespace = 'clara'::regnamespace and p.proname = 'run_adjustment_occurrence'
     and a.privilege_type = 'EXECUTE' and rr.rolname = 'clara_authenticated';
  if v_n <> 0 then
    raise exception '0042 tail 7: the MACHINE run verb run_adjustment_occurrence is executable by clara_authenticated -- humans run an occurrence through run_adjustment_manual, which is _human_ctx-floored at bookkeeper+ (ABI SSA)';
  end if;

  raise notice '0042 tail 7 OK: no wake-allowlist row names a D-b verb; no D-b human verb is granted to an agent or wake role; the machine occurrence runner is reachable by clara_runtime and NOT by clara_authenticated.';
end $tail7$;
-- =====================================================================================
-- TAIL 8 -- THE _reserve_op RAISES-ON-MISMATCH PROBE + THE DERIVED-KEY COLLISION TOKEN
-- (design SS8 tail 8; ABI SSE's non-null rule, stated ONCE and asserted here).
--
-- THE WHOLE EAGER-RESERVATION DESIGN RESTS ON ONE PROPERTY OF _reserve_op: a key already
-- taken with DIFFERENT arguments RAISES; a key already taken with the SAME arguments REPLAYS
-- its stored result. D-b reserves derived sub-keys (`<op>:approve`, `<op>:mirror:approve`,
-- the two pair halves, the composite's draft leg) BEFORE any lock, unconditionally -- and then
-- spends them, pre-held, from a LATER approving transaction. If _reserve_op ever stopped
-- raising on mismatch, a derived key collision would silently REPLAY somebody else's receipt
-- instead of refusing, and the mirror of one occurrence could be attached to another.
--
-- The second half is the callers' obligation: a derived pre-reservation that returns non-null
-- is a COLLISION, never a replay -- because the derived key is minted from the very identity
-- the caller is about to create. ABI SSE names the token; every deriving body must carry it.
-- =====================================================================================
do $tail8$
declare v_src text; v_name text; v_n int;
  -- [R14 FIX 2026-08-04 -- N13-2] the CODE copy; `approve_key_collision` stays a token question on v_src.
  v_lex text;
begin
  select coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)) into v_src from pg_proc p
    where p.oid = 'clara._reserve_op(uuid,text,text,bytea)'::regprocedure;
  if v_src is null then
    raise exception '0042 tail 8: clara._reserve_op(uuid,text,text,bytea) is GONE -- every op-keyed act in this schema depends on it';
  end if;
  if position('v_hash is distinct from p_req_hash' in v_src) = 0 then
    raise exception '0042 tail 8: _reserve_op no longer compares the stored request hash against the caller''s -- an op key reused with different arguments would replay a foreign result instead of refusing';
  end if;
  if position('op_key reused with different args' in v_src) = 0 then
    raise exception '0042 tail 8: _reserve_op no longer RAISES on a request-hash mismatch -- the eager derived reservations of design SS2.3 and ABI SSE are built on that raise, not on a return value the caller might ignore';
  end if;
  if position('on conflict (firm_id, fn, op_key) do nothing' in v_src) = 0 then
    raise exception '0042 tail 8: _reserve_op no longer claims its receipt with an ON CONFLICT DO NOTHING insert -- the claim must be atomic, or two concurrent reservers both believe they won';
  end if;

  -- EVERY BODY THAT DERIVES A SUB-KEY NAMES THE COLLISION TOKEN (ABI SSE, the non-null rule).
  foreach v_name in array array['_adj_run_occurrence_core', '_pair_reverse_core',
                                'book_staff_advance_application', 'resolve_and_book_bank_line'] loop
    select coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)) into v_src from pg_proc p
      where p.pronamespace = 'clara'::regnamespace and p.proname = v_name;
    if v_src is null then
      raise exception '0042 tail 8: clara.% does not exist -- it is one of the four bodies that pre-reserve a DERIVED approve sub-key', v_name;
    end if;
    if position('approve_key_collision' in v_src) = 0 then
      raise exception '0042 tail 8: clara.% pre-reserves a derived approve sub-key but never raises approve_key_collision -- a non-null return from a DERIVED reservation is a collision on an identity this transaction is about to create, and treating it as a replay hands back a receipt for somebody else''s act (ABI SSE)', v_name;
    end if;
    v_lex := pg_temp._wdb_sql_code(v_src);
    if pg_temp._wdb_call_count(v_lex, 'clara._reserve_op') = 0 then
      raise exception '0042 tail 8: clara.% does not call clara._reserve_op -- its derived sub-keys are not reserved at all', v_name;
    end if;
  end loop;

  raise notice '0042 tail 8 OK: _reserve_op still claims atomically and RAISES on request-hash mismatch; all four derived-key reservers carry the approve_key_collision refusal.';
end $tail8$;
-- =====================================================================================
-- TAIL 9 -- THE fa-roles LEAF CENSUS AT ITS D-b MEMBERSHIP (design SS2.1, re-pinning 0041
-- tail 13(c) at the new set).
--
-- THE LAW IS LEAF-LAST. `client:fa-roles` is the only advisory key in this schema taken BELOW
-- the house ladder, and it is safe only because nothing that holds it goes on to take a rung.
-- D-b widens WHO takes it -- staff-advance enrolment and adjustment template propose/retire
-- now claim account roles too -- and the widening is exactly where the property could be lost.
--
-- THE MEMBERSHIP IS "EVERY DOOR THAT WRITES ROLE-CLAIMING STATE", and its complement matters
-- as much: POSTING AND APPROVE PATHS ARE NEVER TAKERS. A hook that took the leaf would acquire
-- it while already holding 203005004 (every approve path does), which is a leaf under a rung --
-- the one order this ladder has no answer for.
-- =====================================================================================
do $tail9$
declare v_n int; v_names text; v_expect text; v_src text; v_name text;
  -- [R14 FIX 2026-08-04 -- N13-2] the CODE copy; the four TABLE-NAME questions in (d) stay on v_src.
  v_lex text;
begin
  -- (a) ONE TAKER OF THE KEY ITSELF (0041 tail 13(c), unchanged).
  select count(*)::int,
         coalesce(string_agg(p.proname::text, ', ' order by p.proname::text collate "C"), '')
    into v_n, v_names
    from pg_proc p
   where p.pronamespace = 'clara'::regnamespace
     and lower(regexp_replace(regexp_replace(regexp_replace(
           (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
         like '%:fa-roles%';
  if v_n <> 1 or v_names <> '_fa_lock_roles' then
    raise exception '0042 tail 9(a): % function(s) take the fa-roles leaf key directly (%) -- expected exactly 1 (clara._fa_lock_roles). One taker is what makes the leaf auditable at all.', v_n, v_names;
  end if;

  -- (b) THE DOORS. Design SS2.1 enumerates seven; the owner ruling of 2026-08-03 (WDB-R3)
  -- adds an EIGHTH, and it is added under this census's own membership rule rather than
  -- against it. The rule is "every door that WRITES role-claiming state", and S5.17's
  -- claiming-door census found that clara._draft_opening_item_core -- the K-doc carry-down
  -- seed, publicly reachable through clara.seed_fixed_asset -- bakes all three fixed-asset
  -- account codes onto a clara.fixed_assets row straight from the seed payload. It was
  -- missing from this set for the reason this refusal names: it did its read-then-write
  -- racily, because it did no read at all. S5.17 gives it the union consult and the leaf
  -- together; taking the consult without the leaf would have made it a snapshot.
  -- [CROSS-SECTION EDIT: authored by the S5 reservation-authority lane, not the S6 lane --
  --  one identifier plus this note, forced by a change in S5. Reported, not silent.]
  v_expect := '_draft_opening_item_core, _fa_assert_code_unreserved, enrol_staff_advance_account, '
              || 'propose_adjustment_template, '
              || 'retire_adjustment_template, retire_fa_account_profile, retire_staff_advance_account, '
              || 'upsert_fa_account_profile';
  select coalesce(string_agg(p.proname::text, ', ' order by p.proname::text collate "C"), '')
    into v_names
    from pg_proc p
   where p.pronamespace = 'clara'::regnamespace
     and p.proname <> '_fa_lock_roles'
     and lower(regexp_replace(regexp_replace(regexp_replace(
           (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
         ~* '(?<![a-z0-9_.])(clara[[:space:]]*\.[[:space:]]*)?_fa_lock_roles[[:space:]]*\(';
  if v_names <> v_expect then
    raise exception '0042 tail 9(b): the fa-roles leaf doors are {%} -- expected exactly {%}. The membership is "every door that WRITES role-claiming state" (design SS2.1): the live bank belt, FA enrolment/retire, advance enrolment/retire, and adjustment template propose/retire. A door missing from this set does its read-then-write racily; a door added to it is a new opinion about where the leaf may be taken.', v_names, v_expect;
  end if;

  -- (c) THE POSTING AND APPROVE PATHS ARE NOT TAKERS. Stated as a negative because it is the
  -- half that would fail silently: a hook that takes the leaf still WORKS, right up until two
  -- ordinary approvals interleave with one enrolment.
  foreach v_name in array array['_adj_run_occurrence_core', '_adj_on_approve', '_adv_on_approve',
                                '_pair_reverse_core', 'approve_pair_reversal',
                                '_approve_entry_core', '_subledger_on_approve',
                                '_settle_from_bank_line_core', 'resolve_and_book_bank_line'] loop
    select lower(regexp_replace(regexp_replace(regexp_replace(
             coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
      into v_src from pg_proc p
      where p.pronamespace = 'clara'::regnamespace and p.proname = v_name;
    if v_src is null then
      raise exception '0042 tail 9(c): clara.% does not exist -- the non-taker census has lost a subject', v_name;
    end if;
    if position('_fa_lock_roles' in v_src) <> 0 or position(':fa-roles' in v_src) <> 0 then
      raise exception '0042 tail 9(c): clara.% takes the fa-roles LEAF -- posting and approve paths hold the 203005004 client rung, so taking the leaf there is a leaf acquired UNDER a rung, which is how this ladder deadlocks (design SS2.1, leaf-LAST)', v_name;
    end if;
  end loop;

  -- (d) THE PREDICATE ITSELF IS LOCK-FREE. _acct_role_reserved is read from inside doors that
  -- already hold the leaf AND from read-only surfaces that hold nothing; a lock inside it would
  -- make the second class acquire the leaf by accident.
  select coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)) into v_src from pg_proc p
    where p.pronamespace = 'clara'::regnamespace and p.proname = '_acct_role_reserved';
  if v_src is null then
    raise exception '0042 tail 9(d): clara._acct_role_reserved does not exist -- design SS2.1''s shared reservation reader is the one predicate FA, advances and the bank belt all read';
  end if;
  if position('pg_advisory' in v_src) <> 0 then
    raise exception '0042 tail 9(d): clara._acct_role_reserved acquires an advisory lock -- it is specified as a LOCK-FREE stable reader (design SS2.1); a lock inside it silently promotes every read-only caller into a leaf taker';
  end if;
  -- ASSEMBLY RECONCILIATION S6-A2 (a cross-lane instrument mismatch, corrected at assembly).
  -- Design SS2.1 specifies the union's four SOURCES (FA active profiles, FA register rows,
  -- ACTIVE advance enrolments, their register rows) but not how they are reached. This block
  -- originally required all four TABLE names inline. SECTION S2 reaches the FA half through
  -- the LIVE 0041 reader clara._fa_reserved_roles -- which already unions exactly
  -- fa_account_profiles (x3 shapes) and fixed_assets (x3 shapes) -- instead of re-inlining
  -- six FA reservation shapes that would then drift from the FA family's own definition. The
  -- delegated form is the stronger one: when D-a adds a seventh FA shape, the shared predicate
  -- follows automatically. The ADVANCE half has no such reader (0042 creates it), so those two
  -- tables must still be named directly. Accept EITHER the delegated FA half or both FA table
  -- names inline; require both advance sources either way.
  if position('staff_advance_accounts' in v_src) = 0
     or position('staff_advances' in v_src) = 0 then
    raise exception '0042 tail 9(d): clara._acct_role_reserved does not read BOTH advance sources (ACTIVE enrolments and their register rows) -- a partial union lets the FA family claim a code an advance already owns';
  end if;
  -- [R14 FIX 2026-08-04 -- N13-2] THE DELEGATION IS A CALL and moves; the two FA table names beside it
  -- are the alternative EVIDENCE this predicate accepts, which is a content question, so they do
  -- not. One `or` arm, two instruments -- and that is the point rather than an inconsistency.
  v_lex := pg_temp._wdb_sql_code(v_src);
  if pg_temp._wdb_call_count(v_lex, 'clara._fa_reserved_roles') = 0
     and (position('fa_account_profiles' in v_src) = 0 or position('fixed_assets' in v_src) = 0) then
    raise exception '0042 tail 9(d): clara._acct_role_reserved covers neither FA source -- it must either delegate to clara._fa_reserved_roles (the live 0041 union, preferred) or read fa_account_profiles AND fixed_assets directly; without one of those an advance enrolment can claim a code the FA register already owns';
  end if;

  raise notice '0042 tail 9 OK: one direct taker of the fa-roles leaf; exactly the seven role-claiming doors call it; no posting or approve path takes it; the shared reservation predicate is lock-free and reads all four sources.';
end $tail9$;
-- =====================================================================================
-- TAIL 10 -- THE SEVEN NEW TABLES: LIFECYCLE TRIGGERS, FORCED RLS, POLICIES AND GRANTS
-- (design SS2.1 "all seven asserted in the tail"; ABI SSD).
--
-- Asserted STRUCTURALLY -- by trigger type bits and policy shape -- rather than by trigger
-- name, because six independent lanes name their triggers, and a census keyed on names would
-- either be wrong or force a naming convention the design never stated. What is asserted is
-- what actually protects the data:
--   * FORCE row level security (without FORCE, clara_fn_owner -- the owner of every one of
--     these tables -- bypasses its own policies, which is every write path in this schema);
--   * a BEFORE TRUNCATE statement trigger bound to clara._tf_no_truncate (a TRUNCATE is the
--     one write that no append-only or transition trigger can see);
--   * at least one BEFORE ROW trigger on DELETE or UPDATE (the lifecycle guard: transition,
--     append-only, immutable, or no-delete -- which one depends on the table);
--   * an owner policy, and for the SIX firm-scoped tables a firm-predicated read policy;
--   * clara_authenticated holds SELECT and nothing else; no machine role holds anything.
-- =====================================================================================
do $tail10$
declare
  r record; v_n int; v_names text; v_qual text;
begin
  for r in select * from (values
      ('adjustment_templates', true),
      ('adjustment_runs', true),
      ('adjustment_pair_reversals', true),
      ('staff_advance_accounts', true),
      ('staff_advances', true),
      ('staff_advance_applications', true),
      -- ea1955_policy is GLOBAL reference data (the 0016 system-reference idiom): same RLS
      -- posture, NO firm predicate, and no firm_id column to write one against.
      ('ea1955_policy', false)
    ) as t(tbl, firm_scoped) loop

    if not exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
                   where n.nspname = 'clara' and c.relname = r.tbl and c.relkind = 'r') then
      raise exception '0042 tail 10: clara.% was not created (ABI SSD names all seven)', r.tbl;
    end if;
    if not exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
                   where n.nspname = 'clara' and c.relname = r.tbl
                     and c.relrowsecurity and c.relforcerowsecurity) then
      raise exception '0042 tail 10: clara.% does not carry ENABLE + FORCE row level security -- without FORCE, clara_fn_owner (which owns the table and runs every SECURITY DEFINER verb) bypasses the very policies this row is about', r.tbl;
    end if;
    -- the TRUNCATE guard, bound to the house function rather than to any function that happens
    -- to be attached to a truncate trigger
    select count(*)::int into v_n from pg_trigger t
     where t.tgrelid = ('clara.' || r.tbl)::regclass and not t.tgisinternal
       and (t.tgtype & 32) <> 0 and (t.tgtype & 1) = 0
       and t.tgfoid = 'clara._tf_no_truncate()'::regprocedure;
    if v_n < 1 then
      raise exception '0042 tail 10: clara.% has no BEFORE TRUNCATE statement trigger bound to clara._tf_no_truncate -- a TRUNCATE is the one write no row-level guard can see', r.tbl;
    end if;
    -- The lifecycle guard (transition / append-only / immutable / no-delete).
    --
    -- ASSEMBLY RECONCILIATION S6-A3 (corrected at assembly, reported not relaxed). This was
    -- originally required of ALL SEVEN tables. It is right for the six FIRM-SCOPED tables,
    -- which are written by audited SECURITY DEFINER verbs running as clara_fn_owner: for
    -- those, a row trigger is the ONLY thing standing between a verb and a rewrite, because
    -- FORCE RLS does not distinguish one owner-run body from another.
    --
    -- clara.ea1955_policy is a different kind of object and ABI SSD.7 gives it a different
    -- posture on purpose: GLOBAL statutory reference data on the 0016 system-reference idiom,
    -- written ONLY by migrations. Its protection is not a row trigger but the ABSENCE of any
    -- write path -- no role outside the owner holds INSERT/UPDATE/DELETE, and tail 19 asserts
    -- that no granted function writes it either. That combination is strictly stronger than a
    -- row trigger for reference data, and it has direct precedent: clara.sst_threshold_schedule
    -- (the SST rate schedule, the closest live analogue -- an effective-dated statutory policy
    -- table) carries exactly this shape, no row triggers and no write grants.
    --
    -- So: the six firm-scoped tables must carry the row guard; ea1955_policy must instead
    -- prove it has NO write grant to any role. The exemption is evidence-backed, not a hole.
    if r.firm_scoped then
      select count(*)::int into v_n from pg_trigger t
       where t.tgrelid = ('clara.' || r.tbl)::regclass and not t.tgisinternal
         and (t.tgtype & 1) <> 0 and (t.tgtype & 2) <> 0 and (t.tgtype & (8 | 16)) <> 0;
      if v_n < 1 then
        raise exception '0042 tail 10: clara.% has no BEFORE-ROW trigger on DELETE or UPDATE -- every firm-scoped D-b table is transition-guarded, append-only or immutable (ABI SSD); an unguarded one can be rewritten by any owner-run body that reaches it', r.tbl;
      end if;
    else
      select count(*)::int, coalesce(string_agg(distinct g.grantee || ':' || g.privilege_type, ', '), '')
        into v_n, v_names
      from information_schema.role_table_grants g
      where g.table_schema = 'clara' and g.table_name = r.tbl
        and g.privilege_type in ('INSERT', 'UPDATE', 'DELETE', 'TRUNCATE')
        and g.grantee <> 'clara_fn_owner';
      if v_n <> 0 then
        raise exception '0042 tail 10: clara.% is GLOBAL migration-written reference data (ABI SSD item 7) and carries NO row-level lifecycle trigger by design -- its ONLY protection is that nothing outside the owner may write it, but % write grant(s) exist (%). Either revoke them or give the table a row guard.', r.tbl, v_n, v_names;
      end if;
    end if;
    -- the owner policy
    select count(*)::int into v_n from pg_policies
     where schemaname = 'clara' and tablename = r.tbl and cmd = 'ALL'
       and 'clara_fn_owner' = any (roles);
    if v_n < 1 then
      raise exception '0042 tail 10: clara.% has no FOR ALL policy for clara_fn_owner -- with FORCE RLS on and no owner policy, the audited verbs cannot write their own table', r.tbl;
    end if;
    -- the read posture
    select coalesce(string_agg(distinct qual, ' | '), '') into v_qual from pg_policies
     where schemaname = 'clara' and tablename = r.tbl and 'clara_authenticated' = any (roles);
    if r.firm_scoped then
      if v_qual = '' or position('firm_id' in v_qual) = 0 then
        raise exception '0042 tail 10: clara.% has no firm-predicated read policy for clara_authenticated (qual is "%") -- a firm-scoped table without a firm predicate is a cross-tenant read', r.tbl, v_qual;
      end if;
    else
      if position('firm_id' in v_qual) <> 0 then
        raise exception '0042 tail 10: clara.ea1955_policy carries a firm predicate (qual is "%") -- it is GLOBAL reference data (ABI SSD item 7); a firm predicate there would hide the statutory notes from every firm', v_qual;
      end if;
      if exists (select 1 from information_schema.columns
                 where table_schema = 'clara' and table_name = 'ea1955_policy'
                   and column_name = 'firm_id') then
        raise exception '0042 tail 10: clara.ea1955_policy has a firm_id column -- EA 1955 is the law of Malaysia, not of a firm';
      end if;
    end if;
    -- grants: SELECT for humans, nothing else, nothing for machines
    select count(*)::int into v_n from information_schema.role_table_grants
     where table_schema = 'clara' and table_name = r.tbl
       and grantee = 'clara_authenticated' and privilege_type <> 'SELECT';
    if v_n <> 0 then
      raise exception '0042 tail 10: clara_authenticated holds % non-SELECT grant(s) on clara.% -- every write goes through an audited verb', v_n, r.tbl;
    end if;
    if not has_table_privilege('clara_authenticated', 'clara.' || r.tbl, 'SELECT') then
      raise exception '0042 tail 10: clara_authenticated cannot SELECT clara.% -- the dashboard reads these tables directly', r.tbl;
    end if;
    select count(*)::int, coalesce(string_agg(distinct grantee::text, ', '), '') into v_n, v_names
      from information_schema.role_table_grants
     where table_schema = 'clara' and table_name = r.tbl
       and grantee in ('clara_agent_ro', 'clara_runtime', 'clara_wake_interactive',
                       'clara_wake_proactive', 'PUBLIC');
    if v_n <> 0 then
      raise exception '0042 tail 10: % machine-role or PUBLIC grant(s) exist on clara.% (%) -- the agent never reads or writes a D-b register directly', v_n, r.tbl, v_names;
    end if;
  end loop;

  raise notice '0042 tail 10 OK: all seven new tables carry FORCE RLS, a _tf_no_truncate statement trigger, a BEFORE-ROW lifecycle guard, an owner policy and SELECT-only human grants with zero machine grants; the six firm-scoped tables carry a firm predicate and ea1955_policy deliberately does not.';
end $tail10$;

-- =====================================================================================
-- [SPLIT D-b2 2026-08-04] TAIL 11 STANDS HERE IN THE WHOLE UNIT AND IS D-b3's: the clara.bank_matches
-- writer census at its new four-name membership, re-pinned because the AF-2 core factoring
-- changed one of the four names. It shipped with 0044.
-- =====================================================================================
-- =====================================================================================
-- TAIL 12 -- THE K-BOUNDARY VACUITY PROBE (design SS2.4: "the K-boundary by vacuity (tail
-- probe)").
--
-- reverse_entry, revise_entry and withdraw_draft all refuse an OPENING entry outright
-- (`opening_entry_k_family_only`) -- opening balances are mutable only through the K-family.
-- The pair machine does not repeat that guard, and the design's argument for why it need not
-- is a VACUITY argument: a pair half can never be an opening entry, because the poster stamps
-- is_opening_balance FALSE, ALWAYS (design SS2.3), and the mirror copies the occurrence's
-- headers verbatim.
--
-- A vacuity argument is only as good as its premise, so the premise is asserted -- structurally
-- (both posters stamp the header explicitly rather than letting a default decide) and on the
-- data (no entry carrying the recurring_adjustment flag is an opening entry). On a fresh rig
-- the data half is vacuously true, which is the point: it becomes a real assertion the moment
-- this migration is re-applied to a world that has run occurrences.
-- =====================================================================================
do $tail12$
declare v_src text; v_n int; v_name text;
begin
  foreach v_name in array array['_adj_run_occurrence_core', '_adj_on_approve'] loop
    select lower(regexp_replace(regexp_replace(regexp_replace(
             coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
      into v_src from pg_proc p
      where p.pronamespace = 'clara'::regnamespace and p.proname = v_name;
    if v_src is null then
      raise exception '0042 tail 12: clara.% does not exist', v_name;
    end if;
    if position('is_opening_balance' in v_src) = 0
       or position('is_year_end' in v_src) = 0
       or position('tax_affecting' in v_src) = 0 then
      raise exception '0042 tail 12: clara.% does not stamp all three entry headers (is_opening_balance, is_year_end, tax_affecting) explicitly -- design SS2.3 requires them stamped, not defaulted: a defaulted header is a claim nobody made, and an occurrence that defaulted to is_opening_balance would cross the K boundary the pair machine assumes it cannot reach', v_name;
    end if;
  end loop;
  -- THE DATA HALF. Vacuous on a fresh apply; load-bearing on every later one.
  select count(*)::int into v_n from clara.journal_entries e
   where coalesce(e.flags, '{}'::jsonb) ? 'recurring_adjustment' and e.is_opening_balance;
  if v_n <> 0 then
    raise exception '0042 tail 12: % adjustment occurrence/mirror entry(ies) are flagged as OPENING balances -- the pair machine skips the K-family guard on the strength of this being impossible (design SS2.4). Those rows must be reversed through the K-family before this migration can claim the boundary holds.', v_n;
  end if;
  -- ...and the pair machine really does not carry a K guard of its own, which is what makes
  -- the vacuity argument the load-bearing one rather than a belt-and-braces remark.
  select coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)) into v_src from pg_proc p
    where p.pronamespace = 'clara'::regnamespace and p.proname = '_pair_reverse_core';
  if v_src is null then
    raise exception '0042 tail 12: clara._pair_reverse_core does not exist -- the vacuity claim has no subject';
  end if;
  if position('opening_entry_k_family_only' in v_src) <> 0 then
    raise exception '0042 tail 12: clara._pair_reverse_core carries an opening_entry_k_family_only guard -- design SS2.4 rules the boundary closed BY VACUITY. If the build decided a guard is needed after all, the design''s argument is wrong and that is an adjudication, not a silent addition.';
  end if;

  raise notice '0042 tail 12 OK: both posters stamp all three entry headers explicitly; zero flagged occurrence/mirror entries are opening balances; the pair machine carries no K guard, exactly as the vacuity argument requires.';
end $tail12$;

-- =====================================================================================
-- [SPLIT D-b2 2026-08-04] TAIL 13 STANDS HERE IN THE WHOLE UNIT AND IS D-b3's: the settled-authority
-- belt's widened arms and its open-branch predicate pin. It shipped with 0044.
-- =====================================================================================
-- =====================================================================================
-- TAIL 14 -- THE EVENT REGISTRATION + TAXONOMY COVERAGE PROBE, WITH EMISSION SITES AND
-- COUNTS PINNED (design SS2.5, ABI SSG; the 0041:978-996 CTE and the 0040-probe-6 shape,
-- extended to taxonomy coverage as SS2.5 requires).
--
-- TWO HALVES, BOTH NECESSARY. Registration in clara.event_types is a hard FK: an unregistered
-- name makes _append_event raise at emission time, so a missing row is loud. A missing
-- trigger_taxonomy row at the ACTIVE version is the opposite -- SILENT -- and it means the
-- router has no ruling for an event that is now flowing. Both new kinds decide 'ignore'
-- because the surfaces read the tables directly (the 0040/0041 reasoning, restated).
--
-- EMISSION SITES ARE PINNED BY COUNT because "one per occurrence" is an accounting statement:
-- two emitters for adjustment.posted means one posted occurrence looks like two to anything
-- that ever counts events.
-- =====================================================================================
do $tail14$
declare v_n int; v_ver int; v_src text; r record;
begin
  select count(*)::int into v_n from clara.event_types
   where name in ('adjustment.posted', 'bank.line_exception_reopened') and client_scoped;
  if v_n <> 2 then
    raise exception '0042 tail 14: expected 2 client-scoped D-b event types (adjustment.posted, bank.line_exception_reopened), found % -- an unregistered name raises at the first emission, in the middle of an approval', v_n;
  end if;
  select version into v_ver from clara.taxonomy_active;
  select count(*)::int into v_n from clara.trigger_taxonomy
   where version = v_ver and event_type in ('adjustment.posted', 'bank.line_exception_reopened')
     and decision = 'ignore';
  if v_n <> 2 then
    raise exception '0042 tail 14: expected 2 trigger_taxonomy rows at the ACTIVE version (%) with decision ignore, found % -- a registered type with no ruling at the active version is an event flowing past a router that has no opinion about it, and NOTHING raises', v_ver, v_n;
  end if;

  -- EMISSION SITES + COUNTS.
  for r in select * from (values
      ('_adj_on_approve', 'adjustment.posted', 1),
      ('unmatch_bank_match', 'bank.line_exception_reopened', 1)
    ) as t(fn, evt, want) loop
    -- Comment-stripped: an emitter's own explanatory comment routinely names the event it
    -- emits, and counting those would refuse a correct single emitter as a double one.
    select lower(regexp_replace(regexp_replace(regexp_replace(
             coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
      into v_src from pg_proc p
      where p.pronamespace = 'clara'::regnamespace and p.proname = r.fn;
    if v_src is null then
      raise exception '0042 tail 14: clara.% does not exist -- it is the named emitter of %', r.fn, r.evt;
    end if;
    v_n := (length(v_src) - length(replace(v_src, '''' || r.evt || '''', '')))
           / length('''' || r.evt || '''');
    if v_n <> r.want then
      raise exception '0042 tail 14: clara.% emits % % time(s), expected exactly % (design SS2.5 / SS4)', r.fn, r.evt, v_n, r.want;
    end if;
    -- ...and it is the ONLY emitter schema-wide.
    select count(*)::int into v_n from pg_proc p
     where p.pronamespace = 'clara'::regnamespace
       and position('''' || r.evt || '''' in lower(regexp_replace(regexp_replace(regexp_replace(
             (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))) > 0;
    if v_n <> 1 then
      raise exception '0042 tail 14: % is named by % clara body/bodies (expected exactly 1 -- clara.%) -- a second emitter makes one act look like two downstream', r.evt, v_n, r.fn;
    end if;
  end loop;

  -- PAYLOAD ALLOWLIST (ABI SSG: typed primitives only). clara.domain_events is agent-readable
  -- firm-wide, so a memo, a description or an account code in a payload is an egress of client
  -- narrative through a channel nobody reviews. Asserted on the two emitters' bodies.
  -- SCANNED IN A BOUNDED WINDOW, not over the whole body: unmatch_bank_match legitimately
  -- handles a reason and a note elsewhere (it takes p_reason as an argument), and a whole-body
  -- scan would refuse it for words it never puts on the wire. The window is the 500 characters
  -- from the event-name literal, which in the house emission form
  -- (`perform clara._append_event(firm, '<name>', ..., jsonb_build_object(...))`) contains the
  -- payload builder and little else.
  for r in select * from (values
      ('_adj_on_approve', 'adjustment.posted'),
      ('unmatch_bank_match', 'bank.line_exception_reopened')
    ) as t(fn, evt) loop
    select substr(x.norm, position('''' || r.evt || '''' in x.norm), 500) into v_src
      from (select lower(regexp_replace(regexp_replace(regexp_replace(
                     coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g')) as norm
              from pg_proc p
             where p.pronamespace = 'clara'::regnamespace and p.proname = r.fn) x;
    if v_src is null or v_src = '' then
      raise exception '0042 tail 14: could not locate the % emission window in clara.% -- the payload allowlist scan has nothing to read', r.evt, r.fn;
    end if;
    if position('''memo''' in v_src) <> 0 or position('''description''' in v_src) <> 0
       or position('''account_code''' in v_src) <> 0 or position('''note''' in v_src) <> 0
       or position('''reason''' in v_src) <> 0 then
      raise exception '0042 tail 14: clara.% names memo/description/account_code/note/reason inside its % payload -- ABI SSG payloads carry identifiers, dates and amounts only, because clara.domain_events is agent-readable firm-wide', r.fn, r.evt;
    end if;
  end loop;

  raise notice '0042 tail 14 OK: both new event types registered client-scoped, both covered at the ACTIVE taxonomy version with decision ignore, exactly one emitter each emitting exactly once, and no narrative key in either payload.';
end $tail14$;
-- =====================================================================================
-- TAIL 15 -- THE PAIR RECEIPT: FLIP-BEFORE-APPROVE, AND THE DEFERRED TRIGGER RE-QUERIES BY ID
-- (design SS2.4).
--
-- THE RECEIPT IS THE AUTHORIZATION CHANNEL. _adj_on_approve arm (1) refuses to approve a
-- pair-correction draft unless its receipt is already 'approving'. So every body that
-- approves a pair half MUST flip the receipt FIRST -- not as a bookkeeping nicety but because
-- the approval it is about to perform will read that status and refuse. A body that approves
-- first cannot work at all; a body that flips first and approves second is the only shape that
-- does. Pinning it here means the next author does not have to rediscover why.
--
-- THE DEFERRED TRIGGER MUST RE-QUERY BY ID (the 0038:3255 idiom). Its job is "no pair receipt
-- may be left in 'approving' at COMMIT" -- a statement about the FINAL committed state. A test
-- against the NEW tuple would fire on the intermediate pending->approving row that EVERY
-- lawful run writes, and refuse every pair correction ever attempted.
-- =====================================================================================
do $tail15$
declare
  v_src text; v_n int; v_a int; v_b int; v_any boolean := false; v_name text;
  v_tg record;
  -- [R14 FIX 2026-08-04 -- N13-2] the CODE copy for the ordering claim below.
  v_lex text;
begin
  -- (a) FLIP BEFORE THE CORE CALLS, in every body of the pair family that approves anything.
  foreach v_name in array array['reverse_adjustment_pair', '_pair_reverse_core',
                                'approve_pair_reversal'] loop
    select lower(regexp_replace(regexp_replace(regexp_replace(
             coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
      into v_src from pg_proc p
      where p.pronamespace = 'clara'::regnamespace and p.proname = v_name;
    if v_src is null then
      raise exception '0042 tail 15(a): clara.% does not exist -- the SS2.4 pair machine is incomplete', v_name;
    end if;
    -- [R14 FIX 2026-08-04 -- second re-confirming round, N13-2] THE ORDERING MOVES TO THE CODE COPY, AND
    -- THE FLIP IS ANCHORED ON ITS STATEMENT RATHER THAN ON ITS LITERAL. The core call is a CALL
    -- question and belongs on the matcher; `'approving'` is a string literal, which the lexer
    -- blanks, so the two cannot be compared on one text unless the flip is named by the
    -- executable statement that writes it -- the same move S5.8-b2 made when it gave up
    -- `'settlement_allocation'` for the assignment that reads it. MEASURED on the rig: each
    -- approving body carries that UPDATE exactly twice (the flip to 'approving' and the terminal
    -- flip afterwards) and the FIRST is the one that must precede the core call. The PRESENCE of
    -- the token itself stays a content question on v_src, one screen down, because "does this body
    -- name the state it writes" is not a question about code.
    select lower(regexp_replace(pg_temp._wdb_sql_code(
             coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid))), '\s+', ' ', 'g'))
      into v_lex from pg_proc p
      where p.pronamespace = 'clara'::regnamespace and p.proname = v_name;
    v_b := pg_temp._wdb_call_pos(v_lex, 'clara._approve_entry_core');
    if v_b = 0 then continue; end if;   -- this body does not approve; nothing to order
    v_any := true;
    if position('''approving''' in v_src) = 0 then
      raise exception '0042 tail 15(a): clara.% approves a pair half but never names the ''approving'' state it must write -- _adj_on_approve arm (1) refuses any pair draft whose receipt is not approving', v_name;
    end if;
    v_a := position('update clara.adjustment_pair_reversals set status =' in v_lex);
    if v_a = 0 then
      raise exception '0042 tail 15(a): clara.% approves a pair half but never flips its receipt to ''approving'' -- _adj_on_approve arm (1) refuses any pair draft whose receipt is not approving, so this path cannot succeed', v_name;
    end if;
    if v_a > v_b then
      raise exception '0042 tail 15(a): clara.% calls the approve core BEFORE flipping its receipt to ''approving'' (flip=%, approve=%) -- the receipt IS the authorization channel (design SS2.4); approving first is refused by the hook it is about to invoke', v_name, v_a, v_b;
    end if;
  end loop;
  if not v_any then
    raise exception '0042 tail 15(a): no body in the pair family calls clara._approve_entry_core -- either the low-stakes pair correction never approves its halves, or it approves them behind the core; both break CLR05 and this census would otherwise pass vacuously';
  end if;

  -- (b) THE DEFERRED RE-QUERY. Located structurally: the constraint trigger on
  -- clara.adjustment_pair_reversals that is DEFERRABLE INITIALLY DEFERRED.
  select t.tgname, p.proname, coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)) as prosrc into v_tg
    from pg_trigger t join pg_proc p on p.oid = t.tgfoid
   where t.tgrelid = 'clara.adjustment_pair_reversals'::regclass and not t.tgisinternal
     and t.tgdeferrable and t.tginitdeferred
   limit 1;
  if not found then
    raise exception '0042 tail 15(b): clara.adjustment_pair_reversals carries no DEFERRABLE INITIALLY DEFERRED trigger -- the no-commit-in-approving guard (ABI SSD item 3) is what stops a half-executed pair correction from committing with one leg approved';
  end if;
  v_src := lower(regexp_replace(regexp_replace(regexp_replace(
             v_tg.prosrc, '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'));
  if position('adjustment_pair_reversals' in v_src) = 0 or position('new.id' in v_src) = 0 then
    raise exception '0042 tail 15(b): the deferred guard % does not RE-QUERY clara.adjustment_pair_reversals by new.id -- it must judge the FINAL committed state (the 0038:3255 idiom)', v_tg.tgname;
  end if;
  if position('new.status' in v_src) <> 0 then
    raise exception '0042 tail 15(b): the deferred guard % tests new.status -- the NEW tuple is the row as it was when the trigger was QUEUED, so a NEW-tuple test fires on the intermediate pending->approving write that every lawful pair correction performs, and would refuse all of them', v_tg.tgname;
  end if;
  if position('''approving''' in v_src) = 0 then
    raise exception '0042 tail 15(b): the deferred guard % does not name the approving status it exists to forbid at commit', v_tg.tgname;
  end if;

  -- (c) THE RECEIPT'S CLOCK COLUMN IS STAMPED ON THE APPROVING->COMPLETED EDGE, not at INSERT.
  -- created_at is the PENDING moment; the ramp clock reads completed_at (design SS2.4). A
  -- receipt table whose completed_at is NOT NULL-able at birth would make every pending pair
  -- look like a completed correction to the ramp.
  if exists (select 1 from information_schema.columns
             where table_schema = 'clara' and table_name = 'adjustment_pair_reversals'
               and column_name = 'completed_at' and is_nullable = 'NO') then
    raise exception '0042 tail 15(c): clara.adjustment_pair_reversals.completed_at is NOT NULL -- it is stamped on the approving->completed edge only (ABI SSD item 3); a non-null value at INSERT makes every pending pair read as a completed correction and resets the ramp clock before anything was corrected';
  end if;
  if not exists (select 1 from information_schema.columns
                 where table_schema = 'clara' and table_name = 'adjustment_pair_reversals'
                   and column_name = 'template_id' and is_nullable = 'NO') then
    raise exception '0042 tail 15(c): clara.adjustment_pair_reversals.template_id is missing or nullable -- it is the ramp clock''s FILTER (design SS2.4); without it a correction on one template would reset every template''s ramp';
  end if;

  raise notice '0042 tail 15 OK: every pair body that approves flips its receipt to approving first; the deferred guard re-queries by id, names the approving status and never tests the NEW tuple; completed_at is nullable and template_id is not.';
end $tail15$;

-- =====================================================================================
-- [SPLIT D-b2 2026-08-04] TAIL 16 STANDS HERE IN THE WHOLE UNIT AND IS D-b0's: the
-- clara.fixed_assets.cost_cents NOT NULL post-state ([WDB-G12], S5.1). It shipped with 0042 and
-- is re-proved on every later apply by the column itself, which cannot become nullable again
-- without an explicit ALTER.
-- =====================================================================================
-- =====================================================================================
-- TAIL 17 -- THE RAMP-RESET PREDICATE: ONE UNIFIED CLOCK, BOTH CORRECTION LANES
-- (design SS2.3, the [L2/FI9] fold + the round-6 unification).
--
-- THE RAMP is what lets an occurrence AUTO-POST instead of drafting: a template earns it once
-- a human has reviewed an earlier occurrence. A reversal un-earns it -- "a reversal un-earns
-- until a fresh reviewed run passes", D-a's law at template grain. There are TWO ways to
-- correct an occurrence and they are structurally different:
--   * an AUTO-REVERSE occurrence is corrected as a PAIR, and the receipt's completed_at is the
--     moment of correction;
--   * a SOLO (non-auto-reverse) occurrence has no pair at all; plain reverse_entry is its path,
--     and the mirror's approved_at is the moment.
-- A ramp predicate that reads only one of them silently keeps auto-posting after a correction
-- made through the other -- which is the failure the sandbox's two ramp-reset cells exist to
-- catch, and which nothing else in the system would notice.
-- =====================================================================================
do $tail17$
declare v_src text; v_n int;
begin
  select lower(regexp_replace(regexp_replace(regexp_replace(
           coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
    into v_src from pg_proc p
    where p.pronamespace = 'clara'::regnamespace and p.proname = '_adj_run_occurrence_core';
  if v_src is null then
    raise exception '0042 tail 17: clara._adj_run_occurrence_core does not exist -- the occurrence poster owns the ramp derivation';
  end if;
  -- THE PAIR LANE: the completed receipt's timestamp, filtered by template.
  if position('adjustment_pair_reversals' in v_src) = 0 or position('completed_at' in v_src) = 0 then
    raise exception '0042 tail 17: the ramp predicate does not read clara.adjustment_pair_reversals.completed_at -- a completed PAIR correction would not reset the clock, so the corrected period''s re-run would AUTO-POST straight over the correction';
  end if;
  if position('''completed''' in v_src) = 0 then
    raise exception '0042 tail 17: the ramp predicate does not filter pair receipts on status=''completed'' -- a CANCELLED receipt must never reset the clock (design SS2.4), and a pending one has corrected nothing yet';
  end if;
  -- THE SOLO LANE: a plain reverse_entry mirror on an occurrence, read through reversal_of.
  if position('reversal_of' in v_src) = 0 then
    raise exception '0042 tail 17: the ramp predicate never joins on reversal_of -- a SOLO (non-auto-reverse) occurrence corrected by plain reverse_entry has no pair receipt, so without this lane the clock never moves and the next sweep auto-posts over the correction';
  end if;
  if position('approved_at' in v_src) = 0 then
    raise exception '0042 tail 17: the ramp predicate never reads approved_at -- both the earning test ("an OTHER approved occurrence whose approved_at post-dates the clock") and the solo reversal mirror''s timestamp are expressed in it';
  end if;
  -- THE UNIFICATION: one clock, taken as the LATER of the two lanes.
  if position('greatest(' in v_src) = 0 then
    raise exception '0042 tail 17: the ramp predicate takes no GREATEST over the two correction lanes -- the clock is the LATER of (newest completed pair correction, newest solo reversal mirror); reading either alone lets a correction made through the other lane pass unnoticed (design SS2.3)';
  end if;

  raise notice '0042 tail 17 OK: the ramp predicate reads the completed pair receipt AND the solo reversal mirror, filtered and unified under one GREATEST -- both correction lanes reset the same clock.';
end $tail17$;
-- =====================================================================================
-- TAIL 18 -- THE TWO HOT-LOOP PARTIAL INDEXES (ABI SSC; the D-a F10 measured law).
--
-- These are not tuning. The occurrence poster's admission law asks two questions on EVERY
-- sweep tick, per client: "is an occurrence draft outstanding?" and "has this (template,
-- period) already been met?". Both are jsonb-flag predicates over clara.journal_entries -- the
-- largest table in the schema -- and D-a measured the cost of asking them without a partial
-- index. The WHERE clauses are the load-bearing half: an index without them is an index over
-- every entry ever written, which is slower than the sequential scan it replaces.
--
-- WHY NOT BYTE-EXACT. pg_get_indexdef re-renders a parsed expression: `flags ? 'x'` comes back
-- as `(flags ? 'x'::text)` and `status='draft'` as `(status = 'draft'::text)`. Comparing the
-- design's source text byte-for-byte against ruleutils output would fail on a correct index.
-- The comparison below therefore strips whitespace, parentheses and ::text casts from BOTH
-- sides -- which is exactly as strict about MEANING and not at all strict about rendering.
-- =====================================================================================
do $tail18$
declare r record; v_def text; v_norm text;
begin
  -- The predicate is checked FRAGMENT BY FRAGMENT rather than as one joined string: `A AND B`
  -- and `B AND A` are the same predicate and the same plan, and a tail that refused one of them
  -- would be asserting a writing style, not an invariant.
  for r in select * from (values
      ('ix_je_adj_draft', 'status=''draft''', 'flags?''recurring_adjustment''', 'client_id'),
      ('ix_je_adj_occurrence', 'flags?''recurring_adjustment''', '', 'template_id')
    ) as t(idx, want_a, want_b, want_key) loop
    select pg_get_indexdef(c.oid) into v_def
      from pg_class c join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'clara' and c.relname = r.idx and c.relkind = 'i';
    if v_def is null then
      raise exception '0042 tail 18: the hot-loop partial index clara.% does not exist (ABI SSC) -- the sweep''s per-tick admission questions would scan clara.journal_entries whole', r.idx;
    end if;
    if position('journal_entries' in v_def) = 0 then
      raise exception '0042 tail 18: clara.% is not an index on clara.journal_entries (def is %)', r.idx, v_def;
    end if;
    v_norm := replace(replace(replace(replace(replace(lower(v_def),
                '::text', ''), ' ', ''), '(', ''), ')', ''), '"', '');
    if position('where' in v_norm) = 0 then
      raise exception '0042 tail 18: clara.% carries NO WHERE clause -- a full index over every journal entry ever written is slower than the scan it replaces, and ABI SSC specifies a PARTIAL index', r.idx;
    end if;
    v_norm := substr(v_norm, position('where' in v_norm));
    if position(r.want_a in v_norm) = 0
       or (r.want_b <> '' and position(r.want_b in v_norm) = 0) then
      raise exception '0042 tail 18: clara.%''s predicate does not match ABI SSC (normalised WHERE is %; expected to contain "%" and "%")', r.idx, v_norm, r.want_a, r.want_b;
    end if;
    v_norm := replace(replace(replace(replace(replace(lower(v_def),
                '::text', ''), ' ', ''), '(', ''), ')', ''), '"', '');
    if position(r.want_key in v_norm) = 0 then
      raise exception '0042 tail 18: clara.% does not key on % (normalised def is %) -- the index would not answer the question it exists for', r.idx, r.want_key, v_norm;
    end if;
  end loop;
  -- The second index must also carry the period key: the (template, period) met-ness question
  -- is two-column, and a single-column index turns an equality probe into a range scan over
  -- every period a template has ever run.
  select pg_get_indexdef(c.oid) into v_def
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'clara' and c.relname = 'ix_je_adj_occurrence';
  if position('period_start' in lower(v_def)) = 0 then
    raise exception '0042 tail 18: ix_je_adj_occurrence does not key on period_start (def is %) -- the met-ness predicate is (template_id, period_start), and half an index answers half the question', v_def;
  end if;

  raise notice '0042 tail 18 OK: both hot-loop partial indexes exist on clara.journal_entries with the ABI SSC predicates and keys.';
end $tail18$;

-- =====================================================================================
-- [SPLIT D-b2 2026-08-04] TAILS 19 AND 21 STAND HERE IN THE WHOLE UNIT AND ARE D-b1's: the
-- clara.ea1955_policy migration-written-only census and the two staff_advance entry_id indexes.
-- Both shipped with 0043.
-- =====================================================================================
-- =====================================================================================
-- TAIL 20 -- THE BOUNDARIES (design SS8 "Boundaries"; the [WDB-G16] literal).
--
-- A boundary is a thing this wave deliberately did NOT build. Absence is the hardest property
-- to keep, because nothing fails when it is lost -- so each one is asserted as an explicit
-- negative, with the reason it is a boundary rather than an omission:
--   (a) NO open_items WIDENING. Staff advances are their own register precisely so the AR/AP
--       subledger keeps meaning "amounts owed by and to third parties". An advance in
--       open_items would flow into ar/ap aging, the statements and the tie-out.
--   (b) NO EMPLOYEE COUNTERPARTY, EVER. A counterparty is a trading party; an employee is not.
--       [WDB-G7]: coding is free and ENROLMENT is the truth.
--   (c) NO NEW LISTEN CONSUMER. Both new events decide 'ignore'; nothing subscribes.
--   (d) NO NEW FROZEN WORKFLOW CLASS. Same evidence, DB-side: a taxonomy decision other than
--       'ignore' is what routes an event into workflow work.
--   (e) THE POSTERS TOUCH NEITHER journal_entries IMMUTABILITY NOR THE BELTS ([WDB-G16], the
--       literal): the immutability triggers and the movement/subledger belts know nothing
--       about D-b, and the D-b posters run under them like any other writer.
-- =====================================================================================
do $tail20$
declare v_def text; v_n int; v_names text; v_name text; v_src text;
begin
  -- (a) open_items is untouched in vocabulary and in shape. EVERY check constraint on the table
  -- is aggregated, not just "the one that mentions domain": open_items carries at least two
  -- (the domain vocabulary and the kind/sign matrix) and both name `domain`, so a single-row
  -- SELECT INTO would pick an arbitrary one and the census would be non-deterministic.
  select coalesce(string_agg(pg_get_constraintdef(c.oid), ' ~ ' order by c.conname::text collate "C"), '')
    into v_def from pg_constraint c
   where c.conrelid = 'clara.open_items'::regclass and c.contype = 'c';
  if position('''ar''' in v_def) = 0 or position('''ap''' in v_def) = 0 then
    raise exception '0042 tail 20(a): the clara.open_items CHECK set no longer names the ar/ap domain pair (defs are %)', v_def;
  end if;
  if position('advance' in v_def) <> 0 or position('adjustment_template' in v_def) <> 0 then
    raise exception '0042 tail 20(a): a clara.open_items CHECK admits a D-b concept (defs are %) -- staff advances are their own register (design SS3.2); an advance in open_items flows into ar/ap aging, the statements and the tie-out, none of which mean anything for a staff debt', v_def;
  end if;
  select coalesce(string_agg(column_name::text, ', ' order by column_name::text collate "C"), '')
    into v_names
    from information_schema.columns
   where table_schema = 'clara' and table_name = 'open_items'
     and (column_name like '%advance%' or column_name like '%template%'
          or column_name like '%adjustment%');
  if v_names <> '' then
    raise exception '0042 tail 20(a): clara.open_items gained the D-b column(s) {%} -- the subledger was not widened by this wave', v_names;
  end if;
  select coalesce(string_agg(p.proname, ', ' order by p.proname), '') into v_names
    from pg_proc p
   where p.pronamespace = 'clara'::regnamespace
     and p.proname in ('_adj_run_occurrence_core', '_adj_on_approve', '_adv_on_approve',
                       '_pair_reverse_core', 'book_staff_advance_application',
                       'enrol_staff_advance_account', 'retire_staff_advance_account',
                       'accept_bank_rule_suggestion', 'resolve_and_book_bank_line')
     and lower(regexp_replace(regexp_replace(regexp_replace(
           (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
         ~* '(insert[[:space:]]+into|update|delete[[:space:]]+from)[[:space:]]+(only[[:space:]]+)?(clara[[:space:]]*\.[[:space:]]*)?open_items(?![a-z0-9_])';
  if v_names <> '' then
    raise exception '0042 tail 20(a): {%} write clara.open_items directly -- open items are materialised by clara._subledger_on_approve from approved entries and by nothing else', v_names;
  end if;

  -- (b) no employee counterparty.
  select pg_get_constraintdef(c.oid) into v_def from pg_constraint c
   where c.conrelid = 'clara.counterparties'::regclass and c.conname = 'counterparties_kind_check';
  if v_def is null then
    raise exception '0042 tail 20(b): counterparties_kind_check is GONE -- the counterparty vocabulary is unbounded';
  end if;
  if position('employee' in v_def) <> 0 or position('staff' in v_def) <> 0 then
    raise exception '0042 tail 20(b): counterparties_kind_check admits an employee/staff kind (def is %) -- WD-R10 and [WDB-G7] put the staff relationship in the ENROLMENT, never in the counterparty master; a staff counterparty would put employee names into AR/AP aging', v_def;
  end if;
  select coalesce(string_agg(p.proname, ', ' order by p.proname), '') into v_names
    from pg_proc p
   where p.pronamespace = 'clara'::regnamespace
     and p.proname in ('_adv_on_approve', 'book_staff_advance_application',
                       'enrol_staff_advance_account', 'complete_staff_advance_particulars')
     and lower(regexp_replace(regexp_replace(regexp_replace(
           (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
         ~* '(insert[[:space:]]+into|update)[[:space:]]+(only[[:space:]]+)?(clara[[:space:]]*\.[[:space:]]*)?counterparties(?![a-z0-9_])';
  if v_names <> '' then
    raise exception '0042 tail 20(b): {%} write clara.counterparties -- the staff-advance family never mints a counterparty', v_names;
  end if;

  -- (c) no new LISTEN channel. Measured over the whole schema so a D-b body cannot introduce
  -- a third quietly; the two live channels are the event relay and the runtime control plane.
  -- (ASSEMBLY FIX: `order by m[1] collate "C"` is rejected under DISTINCT -- Postgres requires
  -- every ORDER BY expression to appear verbatim in the aggregate's argument list, and the
  -- collate clause makes it a different expression. Ordering is cosmetic here; dropped.)
  select coalesce(string_agg(distinct m[1], ', '), '') into v_names
    from pg_proc p,
         lateral regexp_matches(
           lower(regexp_replace(regexp_replace(regexp_replace(
             (coalesce(p.prosrc, '') || coalesce(pg_get_functiondef(p.oid), '')), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g')),
           'pg_notify\([[:space:]]*''([a-z0-9_]+)''', 'g') m
   where p.pronamespace = 'clara'::regnamespace;
  if v_names <> 'clara_events, clara_runtime_ctl' then
    raise exception '0042 tail 20(c): the schema notifies on {%} -- expected exactly {clara_events, clara_runtime_ctl}. Wave D-b adds NO new LISTEN consumer (design SS2.7: the adjustment sweep is a fifth due-check inside the existing leader loop, not a new subscriber).', v_names;
  end if;

  -- (d) no new frozen workflow class, in the evidence the DB can carry: both new event kinds
  -- decide 'ignore' at the ACTIVE version, so nothing routes them into workflow work. The
  -- code-side half (packages/runtime/workflows is untouched) is CI's, not this file's.
  select count(*)::int into v_n from clara.trigger_taxonomy t
    join clara.taxonomy_active a on a.version = t.version
   where t.event_type in ('adjustment.posted', 'bank.line_exception_reopened')
     and t.decision <> 'ignore';
  if v_n <> 0 then
    raise exception '0042 tail 20(d): % D-b event(s) carry a taxonomy decision other than ignore -- a routed decision is what creates workflow work, and Wave D-b ships no new frozen workflow class', v_n;
  end if;

  -- (e) THE [WDB-G16] LITERAL. The immutability triggers and the belts are innocent of D-b:
  -- the posters obey them rather than being exempted from them. A D-b marker inside any of
  -- these bodies means somebody carved out an exception instead of satisfying the rule.
  foreach v_name in array array['_tf_entry_immutable', '_tf_lines_immutable',
                                '_tf_fa_movement_belt', '_tf_subledger_entry_belt',
                                '_tf_subledger_item_belt', '_tf_subledger_alloc_belt'] loop
    -- Comment-stripped throughout (e): these bodies are allowed to EXPLAIN the boundary; what
    -- they may not do is act on it.
    select lower(regexp_replace(regexp_replace(regexp_replace(
             coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
      into v_src from pg_proc p
      where p.pronamespace = 'clara'::regnamespace and p.proname = v_name;
    if v_src is null then
      raise exception '0042 tail 20(e): clara.% is GONE -- the [WDB-G16] boundary has lost a subject', v_name;
    end if;
    if position('recurring_adjustment' in v_src) <> 0
       or position('staff_advance' in v_src) <> 0
       or position('bank_rule_suggested' in v_src) <> 0
       or position('adjustment_template' in v_src) <> 0 then
      raise exception '0042 tail 20(e): clara.% names a D-b concept -- [WDB-G16] ratifies that the two posters touch NEITHER journal_entries immutability NOR the belts. A carve-out here is the AF-2 boundary interpretation being quietly reversed.', v_name;
    end if;
  end loop;
  -- ...and the D-b posters do not disable anything either (no ALTER TABLE, no session_replication_role).
  foreach v_name in array array['_adj_run_occurrence_core', '_adj_on_approve', '_adv_on_approve',
                                '_pair_reverse_core'] loop
    select lower(regexp_replace(regexp_replace(regexp_replace(
             coalesce(nullif(p.prosrc, ''), pg_get_functiondef(p.oid)), '/\*[\s\S]*?\*/', '', 'g'), '--[^\n]*', '', 'g'), '\s+', ' ', 'g'))
      into v_src from pg_proc p
      where p.pronamespace = 'clara'::regnamespace and p.proname = v_name;
    if v_src is null then
      raise exception '0042 tail 20(e): clara.% does not exist -- the poster census has lost a subject', v_name;
    end if;
    if position('session_replication_role' in v_src) <> 0
       or position('alter table' in v_src) <> 0
       or position('disable trigger' in v_src) <> 0 then
      raise exception '0042 tail 20(e): clara.% disables a trigger or alters a table at run time -- a poster that turns a belt off to get its own write through is the one shape [WDB-G16] forbids outright', v_name;
    end if;
  end loop;

  raise notice '0042 tail 20 OK: open_items is unwidened and unwritten by D-b; no employee counterparty kind and no counterparty writes from the advance family; exactly the two pre-existing NOTIFY channels; both new events decide ignore; the immutability triggers and all four belts are innocent of D-b, and no poster disables one.';
end $tail20$;

do $tail_final$
begin
  -- [SPLIT D-b2 2026-08-04] THE CANONICAL FINAL NOTICE ENUMERATES THE WHOLE UNIT and is replaced by
  -- this one, which enumerates what THIS FILE applied and names the three slices it lands on.
  -- It is the only tail-section line this split authors rather than cuts.
  raise notice '0042 wave D-b SLICE D-b2 (recurring/reversing adjustments): APPLIED, on top of D-b0 (0042), D-b1 (0043) and D-b3 (0044). SECTION 0 (10 probes) + S1 (3 relations + 3 indexes on PRE-EXISTING tables -- the two hot-loop partials and the pair-correction lookup -- plus, on clara.adjustment_templates itself, the two fix waves'' lineage uniques: uq_adjustment_templates_one_successor and uq_adjustment_templates_one_live_leaf) + EVENTS (adjustment.posted) + S2 (the adjustment family: the period/hash primitives, the shape and correction-door authorities, the ONE re-run gate restored to full form, templates propose/sign/retire, the occurrence poster and its two twins, the due oracle, the approve-time hook and the auto-reversal pair machine, the read RPCs and the grants) + S5 (the adjustment hook line above D-b1''s advance line, revise_entry''s three proposal keys and pair lock with its re-order, withdraw_draft''s pair refusal, and set_client_fy_end''s annual-template cadence arm) + 14 tail blocks, all green. WAVE D-b IS NOW COMPLETE ACROSS ITS FOUR SLICES. This file is the HELD slice and it carries the fix wave it was held for: the round-11 findings are BUILT here -- the period-keyed lineage MEMBERSHIP WALL (admission predicate 5, refusal replaced_generation_period_standing, carried on the due oracle''s blocked[]), its propose-side period-overlap advisory, term (a) keyed on reachable periods, the parked pair asking the admission authority before it advertises a completion, fail-closed dangling ancestry, the single-live-successor law, the projected declaration and the exported wall advice. THE CONFIRMING ROUND then found more, and ITS wave is here too, marked R12 FIX in brackets at every site: the period-overlap advisory widened from RETIRED to RETIRED-OR-LIVE siblings and re-asked at SIGN (the propose-first order booked RM1,800,000 against an RM600,000 intention with warnings:[] and blocked:[]), ONE UNRETIRED LEAF PER LINEAGE ROOT (lineage_root_id + uq_adjustment_templates_one_live_leaf + the propose refusal template_lineage_root_occupied, because an edge-keyed rule let the fork move one generation up), the period-stamp GRAMMAR (clara._wdb_iso_day -- month-grain and blank stamps sorted out of the wall''s window under collate "C"), and one shared SQL-lexical stripper for ALL FOUR instruments that judge whether a live body contains a hook call (SECTION 0 probe 11, S5.8-b2 prestate+postcheck, tail 1(c), tail 3(1)) -- the last two found by running the lawful-hotfix control end to end rather than by reading the finding. THE CONFIRMING ROUND WAS THEN RE-CONFIRMED, and that round was not clean either -- its wave is here too, marked R13 FIX in brackets at every site: a CONSTRAINT TRIGGER proving that a row''s declared lineage_root_id IS its predecessor''s own root (the one-live-leaf index closed the two-live-leaf state by keying on a column nothing constrained, so the hand-written row that index exists to catch could simply lie about it and re-open the fork); clara._wdb_iso_day validating the CALENDAR and not only the shape (''2026-13-45'' passed the regex and sorts ABOVE every real day of its year, so an ancestor''s standing charge fell out of the wall''s upper bound exactly as month grain had fallen out of its lower one -- the same silent double, through the hole the fix for it left); and ONE shared token-aware, argument-blind CALL MATCHER for all four instruments that judge whether a live body calls a hook, with the stripper now marking excised comments and excised string literals with DIFFERENT non-whitespace sentinels. Both halves of that last one are deploy blockers and both were MEASURED on planted 0044 frontiers: blanking a comment to spaces made `perform clara._adj_on_approve/*hotfix*/(p_entry);` -- a real call, because a comment is whitespace -- invisible to every consumer, so the pre-fix build reported SUCCESS and left TWO executable calls to that hook in one body; and four spellings of one call let a named-notation hotfix pass probe 11 as absent and be refused by S5.8-b2 one section later, a migration dying in the middle of itself. THE THREE WAVES ARE COUNTED, NOT ESTIMATED, AND THE CONVENTION IS NAMED HERE BECAUSE THE ROUND RECORDS USED TWO OF THEM: a wave''s size in this file is the number of SOURCE LINES carrying its BRACKETED marker -- one line per delta site -- and NOT the number of diff hunks, which is numstat''s convention and merges adjacent sites into one. AND THE ROUND-13 LIST WAS RE-CONFIRMED IN TURN, which found no defect in the money core -- the lineage-root trigger held against a deferred forgery at COMMIT, against an UPDATE, and against a replica-mode extension the index caught; the calendar validation held across nine field-swap, leap-year and DateStyle combinations -- and eight defects in the INSTRUMENTS around it, marked R14 FIX in brackets at every site: the lexer learns DOUBLE-QUOTED IDENTIFIERS, because `perform "clara"."_adj_on_approve"(p_entry);` is the same call and every instrument read it as absent (MEASURED: the pre-fix build applied clean onto a body that already had the hook and left TWO independent executable calls in it) and because an apostrophe inside a lawful quoted name like "don''t" was opening a string and swallowing the executable lines after it; the sentinels become CONTROL BYTES, because `~` and `#` are legal SQL text and a body running `where clara._adj_on_approve ~ (''^x'')` -- an alias, a column and the regex-match operator, no call at all -- was counted as a call by the very gap class this file''s prose swore could not happen; the dollar-quote tag rule becomes Postgres''s own, because a non-ASCII tag was not recognised as a delimiter and its contents were read as code; SECTION 0''s probe 10 and tail 1(b), the fifth and sixth judges of "who calls this hook", join the shared question after an upper-case respelling made one read THREE callers and a comment made it read FIVE; and THIRTEEN call-shaped sites across the tails stop asking the retired round-11 regexp pair whether a body calls something -- four lawful, behaviour-identical hotfixes to clara.reverse_entry alone were refused by that one instrument. Measured on this file: 25 round-11 sites, 25 round-12 sites, 21 round-13 sites and 23 round-14 sites -- 22 from the wave itself and ONE more from its follow-up pass (W-R14.1), which split tail 3(8)''s lineage roster: five TOKEN rows keep the raw body they were always measured on, three CALL rows move to the shared matcher, and the marker census does not fork for a follow-up because the sites belong to the same wave and the same ruling. A THIRD RE-CONFIRMING ROUND then read the combined result, and its wave is here too, marked R15 FIX in brackets at every site. It found no defect in the money core -- the sweep was file-identical, W-R14.1''s roster split held 12 of 12 with every erasure arm, and tail 15(a) was verified non-vacuous on every approving body -- and it found the SAME SHAPE OF INSTRUMENT DEFECT twice more, both silent: `U&"clara".U&"_adj_on_approve"` is the same call written the other lawful way, and the round-14 lexer left the two-character prefix in code position so every instrument read a RUNNING call as absent (measured end to end: the migration APPLIED CLEAN and the body ended with TWO executable invocations per approval); and `$` is legal inside an identifier, so `x$t$` is ONE identifier that the lexer read as a dollar-quote tag -- measured on a body Postgres executes, with the call sitting between two such identifiers, the instrument read ZERO while the call ran. THEN THE FIRST FIX FOR THE FIRST OF THOSE WAS MEASURED IN ITS TURN AND FOUND INCOMPLETE, which is the same lesson a third time: refusing a U& identifier whose CONTENT is not a plain identifier catches the backslash spelling and misses a UESCAPE clause, and a UESCAPE clause redefines the escape character, so `U&''z0063lara'' UESCAPE ''z''` is clara behind a content that looks like an ordinary lowercase name -- `pg_temp.U&"z005ft4callee" UESCAPE ''z''(...)` is a body Postgres RUNS while that instrument reported its call absent, with no refusal. The question is now asked once over the WHOLE subject and fails closed, because a comment may sit between an identifier and its UESCAPE clause and no lookahead could be complete. It also repaired a regression THIS FILE introduced one wave earlier: tail 3(2)''s mirror-INSERT anchor is a phrase, not a call, and moving it onto the lexed body made a lawful comment inside it a refused deploy. WHAT THE ROUND ACTUALLY CHANGED IS THE RULE, not just the sites: the stripper now states its grammar as a NAMED SUBSET, and a construct it cannot resolve REFUSES LOUDLY with a diagnosis naming the construct, or is listed as invisible by design with the reason -- silence is the one answer it may not give, and the list now also carries the one divergence Postgres itself refuses to store. Measured on this file: 25 round-11 sites, 25 round-12 sites, 21 round-13 sites, 23 round-14 sites and 9 round-15 sites. Prose that MENTIONS a marker -- this sentence, this notice and the header -- writes it unbracketed, so no claim about the count is counted by it. Every one of them is marked at its own site, and the whole-unit twin is SUPERSEDED for this file by design: the twin carries the measured doubles these deltas close.';
end $tail_final$;

